// 2D paths — chained curve segments with baked arc-length tables, built from a
// plain-data notation. The foundation for enemy wave patterns, patrol routes,
// cutscene moves: hundreds of followers can each call `getPoint(t)` per frame
// because all the curve maths happened ONCE at construction (the bake), leaving
// a binary search over a cumulative-length table per query.
//
// A `Path` is a chain of segments — line / quad / cubic (bézier) / arc / spiral /
// wave — each optionally eased, with an optional whole-path ease on top. Without
// eases, `getPoint(t)` moves at CONSTANT SPEED along the whole path (arc-length
// parameterised), which is what makes formation flying look right.
//
// Module load is DOM-free: pure math, no canvas.
import type { Vec2 } from './util.js';
import { standardEasingFunctions } from './tween/shifty/standard-easing-functions.js';

/** An easing: the name of a standard ease (see tween's `standardEasingFunctions` —
 *  'linear', 'easeInQuad', 'easeOutCubic', 'bounce', …) or your own (t: 0..1) => 0..1. */
export type PathEase = string | ((t: number) => number);

/** A point in the data notation — `[x, y]`. */
export type PathPoint = [number, number];

/** One segment of the plain-data path notation. Every segment continues from the
 *  path's current point; coordinates are absolute (transform at parse time via
 *  {@link PathOptions}). Exactly one of the shape keys per segment. */
export interface PathSegmentData {
  /** Straight line to `[x, y]`. */
  line?: PathPoint;
  /** Quadratic bézier: `[control, to]`. */
  quad?: [PathPoint, PathPoint];
  /** Cubic bézier: `[control1, control2, to]`. */
  cubic?: [PathPoint, PathPoint, PathPoint];
  /** Elliptical arc about a centre. Starts at the current point (start angle and
   *  x-radius are derived from it); sweeps to absolute angle `to` (DEGREES —
   *  beyond ±360 keeps orbiting). `ry` defaults to the derived x-radius (circle). */
  arc?: { center: PathPoint; to: number; ry?: number };
  /** Spiral about a centre: like `arc`, but the radius glides to `endRadius`
   *  over `turns` full revolutions (positive = clockwise, negative = counter). */
  spiral?: { center: PathPoint; turns: number; endRadius: number };
  /** Sinusoidal wave: ride the straight chord to `to` while oscillating
   *  perpendicular by `amplitude` px over `cycles` full waves.
   *  `shape: 'triangle'` makes it a zigzag. */
  wave?: { to: PathPoint; amplitude: number; cycles: number; shape?: 'sine' | 'triangle' };
  /** Ease applied across THIS segment's travel (name or function). */
  ease?: PathEase;
}

/** The plain-data path notation — JSON-friendly: author it inline, in config
 *  tables, or load it with `loadJson`. */
export interface PathData {
  /** Where the path begins, `[x, y]`. */
  start: PathPoint;
  /** The chained segments, each continuing from the previous end point. */
  segments: PathSegmentData[];
  /** Ease applied across the WHOLE path's travel (on top of per-segment eases). */
  ease?: PathEase;
}

/** Parse-time options — transform the authored coordinates once, at the bake. */
export interface PathOptions {
  /** Mirror every x about this vertical axis (`flipX: W / 2` flips a wave to
   *  the other side of the screen). */
  flipX?: number;
  /** Mirror every y about this horizontal axis. */
  flipY?: number;
  /** Translate the whole path by `[dx, dy]`. */
  offset?: PathPoint;
  /** Samples baked per segment (the arc-length table resolution). Default 48 —
   *  raise for very long or very curly segments. */
  samplesPerSegment?: number;
}

const TWO_PI = Math.PI * 2;

function resolveEase(ease: PathEase | undefined): ((t: number) => number) | null {
  if (ease === undefined) return null;
  if (typeof ease === 'function') return ease;
  const fn = (standardEasingFunctions as Record<string, (t: number) => number>)[ease];
  if (!fn) {
    throw new Error(
      `Unknown path ease "${ease}" — use one of ${Object.keys(standardEasingFunctions).join(', ')}, or pass a function.`,
    );
  }
  return fn;
}

/** A segment baked to a polyline + cumulative-length table. */
interface BakedSegment {
  /** Sampled points, sample 0 = segment start. */
  xs: Float64Array;
  ys: Float64Array;
  /** Cumulative length at each sample (cum[0] = 0). */
  cum: Float64Array;
  /** Total geometric length of this segment. */
  length: number;
  ease: ((t: number) => number) | null;
}

/**
 * A 2D path: curve segments chained into one constant-speed route, baked once.
 *
 * ```ts
 * const swoop = new Path({
 *   start: [400, 40],
 *   segments: [
 *     { cubic: [[300, 40], [220, 200], [120, 200]], ease: 'easeOutQuad' },
 *     { wave: { to: [-20, 120], amplitude: 18, cycles: 2 } },
 *   ],
 * });
 * const p = swoop.getPoint(0.5);          // halfway ALONG the route (by distance)
 * sprite.x = p.x; sprite.y = p.y;
 * sprite.rot = swoop.getAngle(0.5);       // facing its direction of travel
 * ```
 *
 * `getPoint(t)` is O(log samples) — a binary search over the baked table — so
 * hundreds of followers per frame are cheap.
 */
export class Path {
  /** Total geometric length of the path, in pixels. */
  readonly length: number;

  private readonly segments: BakedSegment[];
  private readonly pathEase: ((t: number) => number) | null;

  constructor(data: PathData, options: PathOptions = {}) {
    if (!data || !Array.isArray(data.start) || !Array.isArray(data.segments) || data.segments.length === 0) {
      throw new Error('Path data needs a `start: [x, y]` and at least one entry in `segments`.');
    }
    const samples = Math.max(8, Math.floor(options.samplesPerSegment ?? 48));
    const fx = options.flipX;
    const fy = options.flipY;
    const ox = options.offset?.[0] ?? 0;
    const oy = options.offset?.[1] ?? 0;
    const tx = (x: number): number => (fx !== undefined ? fx * 2 - x : x) + ox;
    const ty = (y: number): number => (fy !== undefined ? fy * 2 - y : y) + oy;
    // Mirroring flips arc/spiral sweep direction too — count the reflections.
    const flipSweep = (fx !== undefined ? -1 : 1) * (fy !== undefined ? -1 : 1);

    this.pathEase = resolveEase(data.ease);
    this.segments = [];

    let cx = tx(data.start[0]);
    let cy = ty(data.start[1]);

    for (const seg of data.segments) {
      const startX = cx;
      const startY = cy;
      let curve: (t: number) => { x: number; y: number };

      if (seg.line) {
        const ex = tx(seg.line[0]);
        const ey = ty(seg.line[1]);
        curve = (t) => ({ x: startX + (ex - startX) * t, y: startY + (ey - startY) * t });
      } else if (seg.quad) {
        const c1x = tx(seg.quad[0][0]), c1y = ty(seg.quad[0][1]);
        const ex = tx(seg.quad[1][0]), ey = ty(seg.quad[1][1]);
        curve = (t) => {
          const u = 1 - t;
          return {
            x: u * u * startX + 2 * u * t * c1x + t * t * ex,
            y: u * u * startY + 2 * u * t * c1y + t * t * ey,
          };
        };
      } else if (seg.cubic) {
        const c1x = tx(seg.cubic[0][0]), c1y = ty(seg.cubic[0][1]);
        const c2x = tx(seg.cubic[1][0]), c2y = ty(seg.cubic[1][1]);
        const ex = tx(seg.cubic[2][0]), ey = ty(seg.cubic[2][1]);
        curve = (t) => {
          const u = 1 - t;
          return {
            x: u * u * u * startX + 3 * u * u * t * c1x + 3 * u * t * t * c2x + t * t * t * ex,
            y: u * u * u * startY + 3 * u * u * t * c1y + 3 * u * t * t * c2y + t * t * t * ey,
          };
        };
      } else if (seg.arc) {
        const ax = tx(seg.arc.center[0]);
        const ay = ty(seg.arc.center[1]);
        const rx = Math.hypot(startX - ax, startY - ay) || 0.0001;
        const ry = seg.arc.ry ?? rx;
        // the current point fixes the start angle in ellipse-PARAMETER space
        const a0 = Math.atan2((startY - ay) * (rx / ry), startX - ax);
        const a1 = (seg.arc.to * Math.PI) / 180;
        const sweep = (a1 - a0) * flipSweep;
        curve = (t) => ({
          x: ax + Math.cos(a0 + sweep * t) * rx,
          y: ay + Math.sin(a0 + sweep * t) * ry,
        });
      } else if (seg.spiral) {
        const ax = tx(seg.spiral.center[0]);
        const ay = ty(seg.spiral.center[1]);
        const r0 = Math.hypot(startX - ax, startY - ay) || 0.0001;
        const r1 = Math.max(0.0001, seg.spiral.endRadius);
        const a0 = Math.atan2(startY - ay, startX - ax);
        const sweep = seg.spiral.turns * TWO_PI * flipSweep;
        curve = (t) => {
          const r = r0 + (r1 - r0) * t;
          return { x: ax + Math.cos(a0 + sweep * t) * r, y: ay + Math.sin(a0 + sweep * t) * r };
        };
      } else if (seg.wave) {
        const ex = tx(seg.wave.to[0]);
        const ey = ty(seg.wave.to[1]);
        const amp = seg.wave.amplitude * flipSweep;
        const cycles = seg.wave.cycles;
        const triangle = seg.wave.shape === 'triangle';
        const dx = ex - startX;
        const dy = ey - startY;
        const len = Math.hypot(dx, dy) || 0.0001;
        const px = -dy / len;   // unit perpendicular to the chord
        const py = dx / len;
        curve = (t) => {
          const phase = t * cycles;
          const osc = triangle
            ? 1 - 4 * Math.abs(((phase + 0.25) % 1) - 0.5)   // triangle wave, -1..1, starts at 0 rising
            : Math.sin(phase * TWO_PI);
          return {
            x: startX + dx * t + px * amp * osc,
            y: startY + dy * t + py * amp * osc,
          };
        };
      } else {
        throw new Error('Path segment needs one of: line, quad, cubic, arc, spiral, wave.');
      }

      // The bake: sample the curve into a polyline + cumulative-length table.
      const xs = new Float64Array(samples + 1);
      const ys = new Float64Array(samples + 1);
      const cum = new Float64Array(samples + 1);
      let prevX = 0;
      let prevY = 0;
      for (let i = 0; i <= samples; i++) {
        const p = curve(i / samples);
        xs[i] = p.x;
        ys[i] = p.y;
        cum[i] = i === 0 ? 0 : cum[i - 1] + Math.hypot(p.x - prevX, p.y - prevY);
        prevX = p.x;
        prevY = p.y;
      }
      const baked: BakedSegment = { xs, ys, cum, length: cum[samples], ease: resolveEase(seg.ease) };
      this.segments.push(baked);
      cx = xs[samples];
      cy = ys[samples];
    }

    this.length = this.segments.reduce((sum, s) => sum + s.length, 0);
  }

  /** Build a Path from a JSON string or an already-parsed data object. */
  static fromJSON(json: string | PathData, options: PathOptions = {}): Path {
    return new Path(typeof json === 'string' ? (JSON.parse(json) as PathData) : json, options);
  }

  /** The point at `t` (0 = start, 1 = end) measured BY DISTANCE along the path
   *  (constant speed unless eased). Pass `out` to avoid allocating. */
  getPoint(t: number, out: Vec2 = { x: 0, y: 0 }): Vec2 {
    const tt = this.pathEase ? this.pathEase(clamp01(t)) : clamp01(t);
    let d = tt * this.length;

    // find the segment this distance falls in
    let seg = this.segments[this.segments.length - 1];
    for (let i = 0; i < this.segments.length; i++) {
      if (d <= this.segments[i].length || i === this.segments.length - 1) {
        seg = this.segments[i];
        break;
      }
      d -= this.segments[i].length;
    }

    // segment-local progress by distance, optionally eased, back to distance
    let u = seg.length > 0 ? d / seg.length : 0;
    if (seg.ease) u = seg.ease(clamp01(u));
    return sampleSegment(seg, u * seg.length, out);
  }

  /** The direction of travel at `t`, in radians (atan2 convention — feed it
   *  straight to `sprite.rot` so art faces along the path). */
  getAngle(t: number): number {
    const step = 1 / Math.max(200, this.segments.length * 50);
    const a = this.getPoint(Math.min(1 - step, Math.max(0, t)));
    const b = this.getPoint(Math.min(1, Math.max(step, t) + step));
    return Math.atan2(b.y - a.y, b.x - a.x);
  }
}

function clamp01(t: number): number {
  return t < 0 ? 0 : t > 1 ? 1 : t;
}

/** Sample a baked segment at a distance along it (binary search + lerp). */
function sampleSegment(seg: BakedSegment, dist: number, out: Vec2): Vec2 {
  const { xs, ys, cum } = seg;
  const last = cum.length - 1;
  if (dist <= 0) {
    out.x = xs[0];
    out.y = ys[0];
    return out;
  }
  if (dist >= cum[last]) {
    out.x = xs[last];
    out.y = ys[last];
    return out;
  }
  let lo = 0;
  let hi = last;
  while (lo + 1 < hi) {
    const mid = (lo + hi) >> 1;
    if (cum[mid] <= dist) lo = mid;
    else hi = mid;
  }
  const span = cum[hi] - cum[lo] || 1;
  const f = (dist - cum[lo]) / span;
  out.x = xs[lo] + (xs[hi] - xs[lo]) * f;
  out.y = ys[lo] + (ys[hi] - ys[lo]) * f;
  return out;
}

/**
 * Walks a {@link Path} at a speed in px/s — the per-frame driver for a follower.
 * Construct once, call `advance(dt)` each frame, read `t` / `done`:
 *
 * ```ts
 * const walker = new PathWalker(swoop, 120);          // 120 px/s, once through
 * // in update(dt):
 * walker.advance(dt);
 * const p = path.getPoint(walker.t);
 * this.x = p.x; this.y = p.y;
 * if (walker.done) this.kill();
 * ```
 */
export class PathWalker {
  /** Current progress 0..1 (by distance). */
  t = 0;
  /** `true` once a `'once'` walk reaches the end (never for loop/yoyo). */
  done = false;
  /** Travel speed in px/s — change it live (boosts, slow-motion). */
  speed: number;

  private dir = 1;

  constructor(
    readonly path: Path,
    speed: number,
    /** `'once'` (default) stop at the end · `'loop'` wrap to the start · `'yoyo'` bounce. */
    readonly mode: 'once' | 'loop' | 'yoyo' = 'once',
    /** Start partway along (0..1) — stagger a stream of followers. */
    startT = 0,
  ) {
    this.speed = speed;
    this.t = clamp01(startT);
  }

  /** Advance by `dt` seconds. Returns `this.done` for convenience. */
  advance(dt: number): boolean {
    if (this.done) return true;
    const step = (this.speed * dt) / Math.max(0.0001, this.path.length);
    this.t += step * this.dir;
    if (this.mode === 'once') {
      if (this.t >= 1) {
        this.t = 1;
        this.done = true;
      } else if (this.t < 0) {
        this.t = 0;
      }
    } else if (this.mode === 'loop') {
      this.t -= Math.floor(this.t);
    } else {
      // yoyo
      if (this.t > 1) {
        this.t = 2 - this.t;
        this.dir = -1;
      } else if (this.t < 0) {
        this.t = -this.t;
        this.dir = 1;
      }
    }
    return this.done;
  }

  /** Reset to the start (or `startT`), forward, not done. */
  reset(startT = 0): void {
    this.t = clamp01(startT);
    this.dir = 1;
    this.done = false;
  }
}
