// MINECRAFT CONTROLS — an OPTIONAL first-person control rig for voxel / block
// games (`world.voxels()`). Import it and you get the exact scheme a Minecraft
// player expects, on BOTH input surfaces, with zero wiring of your own:
//
//   DESKTOP (mouse + keyboard)
//     • click the canvas to LOCK the pointer — the mouse then looks freely
//       (no dragging), Esc releases it
//     • WASD / arrows move relative to where you look; double-tap W or hold
//       Ctrl to sprint
//     • Space = jump (walk) or rise (fly); Shift = sneak (walk) or sink (fly)
//     • double-tap Space toggles FLY (creative) when `canFly`
//     • LEFT mouse breaks (held = keep breaking), RIGHT mouse places (held =
//       keep placing); wheel or number keys 1–9 pick the hotbar slot
//
//   MOBILE (touch) — the Bedrock layout
//     • a floating joystick under your left thumb walks/strafes
//     • drag anywhere on the right to look; a quick TAP places, a stationary
//       HOLD breaks (continuous) — exactly like tapping vs holding a block
//     • a jump/rise button bottom-right (double-tap toggles fly when allowed);
//       a sneak/sink button beside it; tap a hotbar slot to pick it
//
// It's DOM-free at import (all listeners wire in the constructor). The rig owns
// look + input INTENT + the on-screen HUD; the helper methods
// (flyStep / walkStep / firstPerson / thirdPerson) apply that intent to a
// camera or a VoxelBody so a game never hand-rolls first-person plumbing. Each
// frame: `mc.poll()`, move (`flyStep`/`walkStep`), aim (`firstPerson`/
// `thirdPerson`), then `mc.drawHud(d, t, font)`. Read `mc.mining/placing/sel`
// and `mc.forward()` to drive raycast break/place against the voxel grid.

import { forward } from './transform3d.js';
import type { Game } from './game.js';
import type { Draw } from './draw.js';
import type { BitmapFont } from './font.js';

export interface McHotbar {
  /** Block display names, left→right (also the count of slots). */
  names: string[];
  /** A swatch colour per slot for the on-screen hotbar. */
  colors: string[];
}

export interface McOptions {
  yaw?: number;
  pitch?: number;
  /** Space/Shift meaning: 'jump' (walk — Space jumps) or 'fly' (creative —
   *  Space rises, Shift sinks). Live-mutable via `mc.fly`. Default 'fly'. */
  vertical?: 'jump' | 'fly';
  /** Allow double-tap Space / double-tap the jump button to toggle fly. When
   *  set, the rig flips `vertical` between 'jump' and 'fly'. Default false. */
  canFly?: boolean;
  /** Enable break interaction (LEFT mouse / touch hold). Default true. */
  canBreak?: boolean;
  /** Enable place interaction (RIGHT mouse / touch tap). Default false. */
  canPlace?: boolean;
  /** Hotbar to show + drive (number keys, wheel, tap). Omit for none. */
  hotbar?: McHotbar;
  /** Mouse look sensitivity, radians per pixel of movement. Default 0.0022. */
  sensitivity?: number;
}

/** Walk speeds (blocks/s) for `walkStep` — sneak/walk/run. */
export interface McWalkSpeeds { walk?: number; run?: number; sneak?: number }

/** A body the walk helper steps — `VoxelBody` satisfies this structurally. */
interface Steppable { step(dt: number, wishX: number, wishZ: number, jump: boolean): void }
/** The look-at camera the aim helpers write — `world.camera` satisfies it. */
interface AimCamera {
  x: number; y: number; z: number;
  face(yaw: number, pitch: number): void;
  lookAt(x: number, y: number, z: number): void;
}
type Vec3 = { x: number; y: number; z: number };

const HALF_PI = Math.PI / 2 - 0.02;

/** Is this a touch-first device? (coarse pointer OR a touch API present) */
function coarsePointer(): boolean {
  return (typeof matchMedia === 'function' && matchMedia('(pointer: coarse)').matches)
    || (typeof navigator !== 'undefined' && navigator.maxTouchPoints > 0)
    || (typeof window !== 'undefined' && 'ontouchstart' in window);
}

/** A round on-screen button (position resolved per-frame against the view). */
interface Btn { x: number; y: number; r: number; }

/** The 12 edges of a unit cube centred on the origin (±`h`) as polylines —
 *  feed to `world.lines()` for a Minecraft-style block outline, then set the
 *  shape's x/y/z to the target cell centre. */
export function cubeEdges(h = 0.5): Array<Array<[number, number, number]>> {
  const c: [number, number, number][] = [
    [-h, -h, -h], [h, -h, -h], [h, -h, h], [-h, -h, h],   // 0-3 bottom
    [-h, h, -h], [h, h, -h], [h, h, h], [-h, h, h],       // 4-7 top
  ];
  const e = (a: number, b: number): [[number, number, number], [number, number, number]] => [c[a], c[b]];
  return [
    e(0, 1), e(1, 2), e(2, 3), e(3, 0),                    // bottom ring
    e(4, 5), e(5, 6), e(6, 7), e(7, 4),                    // top ring
    e(0, 4), e(1, 5), e(2, 6), e(3, 7),                    // verticals
  ];
}

export class McControls {
  /** Look angles — engine `+Z`-forward convention (see forward()). Read these. */
  yaw: number;
  pitch: number;
  /** Move intent in look space, each −1..1: forward (W/joystick up) and strafe
   *  (D/joystick right). Refreshed by poll() each frame. */
  mf = 0;
  ms = 0;
  /** Vertical intent while flying, −1..1 (Space − Shift, or the touch buttons). */
  up = 0;
  /** Space held (walk-mode jump). */
  jumpHeld = false;
  /** Sprinting (Ctrl held, double-tap W, or nothing on touch). */
  sprint = false;
  /** Sneaking (Shift held on foot). */
  sneak = false;
  /** Creative flight — flips with double-tap Space / jump when `canFly`. */
  fly: boolean;
  /** Selected hotbar slot (0-based). */
  sel = 0;
  /** Break held this frame (LEFT mouse or a stationary touch-hold). */
  mining = false;
  /** Place active this frame (RIGHT mouse held, or a one-frame touch tap). */
  placing = false;
  /** Mouse/touch look sensitivity, radians per pixel. Live-mutable (a demo
   *  slider binds straight to this). */
  sensitivity: number;
  /** True once any touch has happened — switches the HUD to the mobile layout. */
  touch = coarsePointer();
  /** True while the desktop pointer is locked (mouse-look live). */
  locked = false;

  private game: Game;
  private canvas: HTMLCanvasElement;
  private o: Required<Omit<McOptions, 'hotbar' | 'yaw' | 'pitch' | 'sensitivity'>>;
  private hotbar: McHotbar | null;

  // Touch state ───────────────────────────────────────────────────────────
  private moveId: number | null = null;         // finger driving the joystick
  private moveBase = { x: 0, y: 0 };             // where it first touched
  private moveKnob = { x: 0, y: 0 };             // current finger point
  private lookId: number | null = null;          // finger driving look/actions
  private lookLast = { x: 0, y: 0 };
  private lookStart = { x: 0, y: 0 };
  private lookDown = 0;                           // ms timestamp of look touchdown
  private lookMoved = false;                      // dragged past the tap threshold
  private lookBreaking = false;                   // hold crossed into break
  private placePulse = false;                     // a tap queued a single place
  private breakPulse = false;                     // a tap queued a single break
  private jumpTouch = false;                      // jump/rise button held
  private downTouch = false;                      // sneak/sink button held
  private lastJumpTap = 0;                        // for double-tap-to-fly

  // Keyboard sprint (double-tap W) ─────────────────────────────────────────
  private lastWTap = 0;
  private sprintLatch = false;

  private un: Array<() => void> = [];

  constructor(game: Game, opts: McOptions = {}) {
    this.game = game;
    this.canvas = game.canvas;
    this.yaw = opts.yaw ?? 0;
    this.pitch = opts.pitch ?? 0.1;
    this.hotbar = opts.hotbar ?? null;
    this.fly = (opts.vertical ?? 'fly') === 'fly';
    this.sensitivity = opts.sensitivity ?? 0.0022;
    this.o = {
      vertical: opts.vertical ?? 'fly',
      canFly: opts.canFly ?? false,
      canBreak: opts.canBreak ?? true,
      canPlace: opts.canPlace ?? false,
    };
    this.wire();
  }

  /** A unit forward vector for the current look (for raycasts + camera.face). */
  forward(): { x: number; y: number; z: number } {
    return forward(this.yaw, this.pitch);
  }

  /** Horizontal wish-velocity for a move speed, from mf/ms about the yaw.
   *  Diagonals are normalised so strafing isn't faster. */
  wish(speed: number): { x: number; z: number } {
    let f = this.mf, s = this.ms;
    const l = Math.hypot(f, s);
    if (l < 1e-4) return { x: 0, z: 0 };
    if (l > 1) { f /= l; s /= l; }               // clamp joystick tilt, keep sub-full walks
    const sy = Math.sin(this.yaw), cy = Math.cos(this.yaw);
    // Right-hand-turn frame: forward=(−sin y, cos y), strafe-right=(−cos y,
    // −sin y) — so W goes where you look and D/right moves screen-right.
    return { x: (-sy * f - cy * s) * speed, z: (cy * f - sy * s) * speed };
  }

  // ── Apply helpers: turn intent into camera + body motion ────────────────────
  /** CREATIVE FLIGHT: advance a free `{x,y,z}` eye by the move intent (WASD /
   *  joystick) + vertical (Space/Shift, fly buttons). `speed` is base blocks/s;
   *  sprint doubles it. Pair with `firstPerson(cam, eye)`. */
  flyStep(eye: Vec3, dt: number, speed = 20): void {
    const s = speed * (this.sprint ? 2 : 1) * dt;
    const w = this.wish(s);
    eye.x += w.x; eye.z += w.z; eye.y += this.up * s;
  }

  /** SURVIVAL WALK: step a `VoxelBody` with the move intent + jump (gravity,
   *  collision and step-up live in the body). Speeds default to Minecraft-ish
   *  sneak 2 / walk 4.5 / run 7 blocks/s. */
  walkStep(body: Steppable, dt: number, speeds: McWalkSpeeds = {}): void {
    const spd = this.sneak ? (speeds.sneak ?? 2) : this.sprint ? (speeds.run ?? 7) : (speeds.walk ?? 4.5);
    const w = this.wish(spd);
    body.step(dt, w.x, w.z, this.jumpHeld);
  }

  /** FIRST-PERSON camera: eye = `eye`, looking along the current yaw/pitch. */
  firstPerson(cam: AimCamera, eye: Vec3): void {
    cam.x = eye.x; cam.y = eye.y; cam.z = eye.z;
    cam.face(this.yaw, this.pitch);
  }

  /** THIRD-PERSON camera: pull the eye `dist` back along the look ray from
   *  `target` (the player's head) and aim at it; `lift` raises the eye. */
  thirdPerson(cam: AimCamera, target: Vec3, dist: number, lift = 0.6): void {
    const f = this.forward();
    cam.x = target.x - f.x * dist; cam.y = target.y - f.y * dist + lift; cam.z = target.z - f.z * dist;
    cam.lookAt(target.x, target.y, target.z);
  }

  /** Read keyboard + touch into the continuous intent fields. Call once at the
   *  top of the frame BEFORE using wish()/jumpHeld/up. */
  poll(): void {
    const g = this.game;
    // Movement: joystick wins when a finger owns it, else WASD/arrows.
    if (this.moveId !== null) {
      const R = this.joyRadius();
      let dx = (this.moveKnob.x - this.moveBase.x) / R;
      let dy = (this.moveKnob.y - this.moveBase.y) / R;
      const l = Math.hypot(dx, dy);
      if (l > 1) { dx /= l; dy /= l; }
      this.ms = dx; this.mf = -dy;               // up on screen = forward
    } else {
      let f = 0, s = 0;
      if (g.input.key('KeyW', 'ArrowUp')) f += 1;
      if (g.input.key('KeyS', 'ArrowDown')) f -= 1;
      if (g.input.key('KeyD', 'ArrowRight')) s += 1;
      if (g.input.key('KeyA', 'ArrowLeft')) s -= 1;
      this.mf = f; this.ms = s;
    }

    this.sneak = g.input.key('ShiftLeft', 'ShiftRight') || (!this.fly && this.downTouch);
    // Sprint: hold Ctrl, or the double-tap-W latch (cleared when W lets go).
    if (!g.input.key('KeyW', 'ArrowUp')) this.sprintLatch = false;
    this.sprint = g.input.key('ControlLeft', 'ControlRight') || this.sprintLatch;

    if (this.fly) {
      this.up = Math.max(-1, Math.min(1,
        (g.input.key('Space') ? 1 : 0) - (g.input.key('ShiftLeft', 'ShiftRight') ? 1 : 0)
        + (this.jumpTouch ? 1 : 0) - (this.downTouch ? 1 : 0)));
      this.jumpHeld = false;
    } else {
      this.up = 0;
      this.jumpHeld = g.input.key('Space') || this.jumpTouch;
    }

    // A stationary look-finger held past the tap window starts breaking.
    if (this.lookId !== null && !this.lookMoved && this.o.canBreak
      && performance.now() - this.lookDown > 220) {
      this.lookBreaking = true;
    }
    // Break: LEFT mouse held, a touch-hold, or a one-frame tap-break.
    this.mining = (this.locked && this.mouseLeft) || this.lookBreaking || this.breakPulse;
    // Place: RIGHT mouse held, or a one-frame touch tap.
    this.placing = (this.locked && this.mouseRight) || this.placePulse;
    this.breakPulse = false;
    this.placePulse = false;
  }

  private mouseLeft = false;
  private mouseRight = false;

  // ── Wiring ────────────────────────────────────────────────────────────────
  private wire(): void {
    const cv = this.canvas;
    const on = <E extends Event>(el: EventTarget, ev: string, fn: (e: E) => void, o?: AddEventListenerOptions): void => {
      el.addEventListener(ev, fn as EventListener, o);
      this.un.push(() => el.removeEventListener(ev, fn as EventListener));
    };

    // Pointer lock (desktop mouse-look). The first click just grabs the
    // pointer; clicks AFTER that break/place.
    on(cv, 'mousedown', (e: MouseEvent) => {
      if (this.touch) return;                    // a touch device: ignore synthetic mouse
      if (!this.locked) { cv.requestPointerLock?.(); return; }
      if (e.button === 0) this.mouseLeft = true;
      if (e.button === 2) this.mouseRight = true;
    });
    on(window, 'mouseup', (e: MouseEvent) => {
      if (e.button === 0) this.mouseLeft = false;
      if (e.button === 2) this.mouseRight = false;
    });
    on(cv, 'contextmenu', (e: Event) => e.preventDefault());
    on(document, 'pointerlockchange', () => {
      this.locked = document.pointerLockElement === cv;
      if (!this.locked) { this.mouseLeft = this.mouseRight = false; }
    });
    on(document, 'mousemove', (e: MouseEvent) => {
      if (!this.locked) return;
      // Mouse RIGHT turns the view right — increasing yaw is a right turn in
      // the engine's right-hand-turn convention (see transform3d).
      this.yaw += e.movementX * this.sensitivity;
      this.pitch = Math.max(-HALF_PI, Math.min(HALF_PI, this.pitch + e.movementY * this.sensitivity));
    });
    on(cv, 'wheel', (e: WheelEvent) => {
      if (!this.hotbar) return;
      e.preventDefault();
      const n = this.hotbar.names.length;
      this.sel = (this.sel + (e.deltaY > 0 ? 1 : -1) + n) % n;
    }, { passive: false });

    // Keyboard: hotbar number keys, double-tap-W sprint, double-tap-Space fly.
    on(window, 'keydown', (e: KeyboardEvent) => {
      const t = e.target as HTMLElement | null;
      if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.tagName === 'SELECT')) return;
      if (this.hotbar) {
        const n = parseInt(e.key, 10);
        if (n >= 1 && n <= this.hotbar.names.length) this.sel = n - 1;
      }
      if (e.code === 'KeyW' && !e.repeat) {
        const now = performance.now();
        if (now - this.lastWTap < 300) this.sprintLatch = true;
        this.lastWTap = now;
      }
      if (e.code === 'Space' && !e.repeat && this.o.canFly) {
        const now = performance.now();
        if (now - this.lastSpaceTap < 300) this.fly = !this.fly;
        this.lastSpaceTap = now;
      }
    });

    // Touch: joystick, look/act, on-screen buttons + hotbar.
    on(cv, 'touchstart', (e: TouchEvent) => this.onTouchStart(e), { passive: false });
    on(cv, 'touchmove', (e: TouchEvent) => this.onTouchMove(e), { passive: false });
    on(cv, 'touchend', (e: TouchEvent) => this.onTouchEnd(e), { passive: false });
    on(cv, 'touchcancel', (e: TouchEvent) => this.onTouchEnd(e), { passive: false });
  }

  private lastSpaceTap = 0;

  // ── Touch handling ─────────────────────────────────────────────────────────
  /** Convert a Touch's page point into engine view coords (matches the HUD). */
  private toView(t: Touch): { x: number; y: number } {
    return this.game.input.toWorld({ clientX: t.clientX, clientY: t.clientY });
  }

  private joyRadius(): number { return Math.min(this.game.view.w, this.game.view.h) * 0.13; }

  private onTouchStart(e: TouchEvent): void {
    e.preventDefault();
    this.touch = true;
    const g = this.game;
    for (const t of Array.from(e.changedTouches)) {
      const p = this.toView(t);
      const btn = this.hitButton(p);
      if (btn === 'jump') {
        this.jumpTouch = true;
        const now = performance.now();
        if (this.o.canFly && now - this.lastJumpTap < 300) this.fly = !this.fly;
        this.lastJumpTap = now;
        continue;
      }
      if (btn === 'down') { this.downTouch = true; continue; }
      const slot = this.hitHotbar(p);
      if (slot >= 0) { this.sel = slot; continue; }
      // Left half → joystick (floating: base where the thumb lands).
      if (this.moveId === null && p.x < g.view.w * 0.5) {
        this.moveId = t.identifier;
        this.moveBase = { x: p.x, y: p.y };
        this.moveKnob = { x: p.x, y: p.y };
        continue;
      }
      // Otherwise → look / act finger.
      if (this.lookId === null) {
        this.lookId = t.identifier;
        this.lookLast = { x: p.x, y: p.y };
        this.lookStart = { x: p.x, y: p.y };
        this.lookDown = performance.now();
        this.lookMoved = false;
        this.lookBreaking = false;
      }
    }
  }

  private onTouchMove(e: TouchEvent): void {
    e.preventDefault();
    for (const t of Array.from(e.changedTouches)) {
      const p = this.toView(t);
      if (t.identifier === this.moveId) { this.moveKnob = { x: p.x, y: p.y }; continue; }
      if (t.identifier === this.lookId) {
        // View coords scale with the canvas; convert back to CSS px for a
        // consistent feel by using the same sensitivity as the mouse.
        const scale = this.canvas.clientHeight / Math.max(1, this.game.view.h);
        this.yaw += (p.x - this.lookLast.x) * scale * this.sensitivity;
        this.pitch = Math.max(-HALF_PI, Math.min(HALF_PI, this.pitch + (p.y - this.lookLast.y) * scale * this.sensitivity));
        this.lookLast = { x: p.x, y: p.y };
        const far = Math.hypot(p.x - this.lookStart.x, p.y - this.lookStart.y);
        if (far > this.game.view.h * 0.02) { this.lookMoved = true; this.lookBreaking = false; }
      }
    }
  }

  private onTouchEnd(e: TouchEvent): void {
    e.preventDefault();
    for (const t of Array.from(e.changedTouches)) {
      if (t.identifier === this.moveId) { this.moveId = null; this.mf = this.ms = 0; }
      else if (t.identifier === this.lookId) {
        // A quick, still tap = place (or break if no place); a drag was just
        // looking; a hold was already breaking (cleared here).
        if (!this.lookMoved && !this.lookBreaking) {
          if (this.o.canPlace) this.placePulse = true;
          else if (this.o.canBreak) this.breakPulse = true;
        }
        this.lookId = null;
        this.lookBreaking = false;
      }
      // Buttons release on any lifted finger over them (simplest + reliable).
    }
    // A lifted finger might have been a held button — clear if no touches remain.
    if (e.touches.length === 0) { this.jumpTouch = false; this.downTouch = false; }
  }

  // ── HUD ─────────────────────────────────────────────────────────────────
  // Everything below is sized as a FRACTION of view.h. A voxel game's 2D view
  // is `worldHeight` units tall — NOT pixels — so any absolute size (or a pixel
  // `Math.max` floor) blows up to a third of the screen. Text is scaled by
  // `height / font.lineHeight` for the same reason.
  /** Draw the crosshair, hotbar, and (on touch) the on-screen controls. Call
   *  inside the run() draw callback. `t` is the game clock for the crosshair pulse. */
  drawHud(d: Draw, t: number, font?: BitmapFont): void {
    const g = this.game, W = g.view.w, H = g.view.h;
    const cx = W * 0.5, cy = H * 0.5;

    // Crosshair — two thin bars with a soft pulse (reads on any block).
    const s = H * 0.016, w = H * 0.0035;
    const a = 0.65 + Math.sin(t * 4) * 0.1;
    d.rect(cx - s, cy - w, s * 2, w * 2, `rgba(255,255,255,${a})`);
    d.rect(cx - w, cy - s, w * 2, s * 2, `rgba(255,255,255,${a})`);

    if (this.hotbar) this.drawHotbar(d, font);

    if (this.touch) this.drawTouch(d);
    else if (!this.locked && font) {
      // Non-obvious on desktop: you must click to capture the mouse.
      d.text(font, 'CLICK TO LOOK', cx, H * 0.6, { align: 'center', scale: H * 0.05 / font.lineHeight, color: '#dfe6ff', alpha: 0.9 });
    }
  }

  private drawHotbar(d: Draw, font?: BitmapFont): void {
    const hb = this.hotbar!;
    const g = this.game, W = g.view.w, H = g.view.h;
    const n = hb.names.length;
    const cell = Math.min(H * 0.11, W / (n + 1));
    const pad = cell * 0.14, gap = cell * 0.06;
    const total = n * cell;
    const x0 = (W - total) / 2, y = H - cell - H * 0.03;
    d.rect(x0 - pad, y - pad, total + pad * 2, cell + pad * 2, 'rgba(12,15,29,0.72)');
    for (let i = 0; i < n; i++) {
      const x = x0 + i * cell;
      const on = i === this.sel;
      d.rect(x + gap, y + gap, cell - gap * 2, cell - gap * 2, 'rgba(0,0,0,0.35)');
      d.rect(x + pad, y + pad, cell - pad * 2, cell - pad * 2, hb.colors[i]);
      if (on) {
        // Selected slot: bright frame (four thin bars).
        const b = cell * 0.08;
        for (const [rx, ry, rw, rh] of [
          [x, y, cell, b], [x, y + cell - b, cell, b], [x, y, b, cell], [x + cell - b, y, b, cell],
        ] as const) d.rect(rx, ry, rw, rh, '#ffffff', 0.95);
      }
      if (font) d.text(font, String(i + 1), x + cell * 0.1, y + cell * 0.08, { scale: cell * 0.3 / font.lineHeight, color: '#e6ebff', alpha: 0.9 });
    }
    if (font) d.text(font, hb.names[this.sel], W / 2, y - H * 0.07, { align: 'center', scale: H * 0.045 / font.lineHeight, color: '#eef2ff' });
  }

  /** Positions for the on-screen buttons (also used for hit-testing). */
  private buttons(): { jump: Btn; down: Btn | null } {
    const W = this.game.view.w, H = this.game.view.h;
    const r = H * 0.09;
    const jump: Btn = { x: W - r * 2.2, y: H - r * 2.4, r };
    const down: Btn | null = { x: W - r * 4.6, y: H - r * 1.6, r: r * 0.82 };
    return { jump, down };
  }

  private hitButton(p: { x: number; y: number }): 'jump' | 'down' | null {
    const { jump, down } = this.buttons();
    if (Math.hypot(p.x - jump.x, p.y - jump.y) <= jump.r) return 'jump';
    if (down && Math.hypot(p.x - down.x, p.y - down.y) <= down.r) return 'down';
    return null;
  }

  private hitHotbar(p: { x: number; y: number }): number {
    if (!this.hotbar) return -1;
    const W = this.game.view.w, H = this.game.view.h;
    const n = this.hotbar.names.length;
    const cell = Math.min(H * 0.11, W / (n + 1));
    const total = n * cell, x0 = (W - total) / 2, y = H - cell - H * 0.03;
    if (p.y < y - cell * 0.3 || p.y > y + cell * 1.3) return -1;
    const i = Math.floor((p.x - x0) / cell);
    return i >= 0 && i < n ? i : -1;
  }

  private drawTouch(d: Draw): void {
    // Joystick — base ring + knob (only while a thumb owns it).
    if (this.moveId !== null) {
      const R = this.joyRadius();
      d.ring(this.moveBase.x, this.moveBase.y, R, R * 0.06, '#ffffff', 0.35);
      let dx = this.moveKnob.x - this.moveBase.x, dy = this.moveKnob.y - this.moveBase.y;
      const l = Math.hypot(dx, dy) || 1; const k = Math.min(1, l / R);
      d.circle(this.moveBase.x + dx / l * k * R, this.moveBase.y + dy / l * k * R, R * 0.42, '#ffffff', 0.5);
    } else {
      // Hint the joystick zone faintly so first-timers know where to press.
      const R = this.joyRadius();
      d.ring(this.game.view.w * 0.18, this.game.view.h - R * 1.6, R, R * 0.05, '#ffffff', 0.12);
    }

    const { jump, down } = this.buttons();
    this.drawBtn(d, jump, this.jumpTouch, true);        // jump / rise
    if (down) this.drawBtn(d, down, this.downTouch, false); // sneak / sink
  }

  private drawBtn(d: Draw, b: Btn, pressed: boolean, up: boolean): void {
    d.circle(b.x, b.y, b.r, '#0c0f1d', pressed ? 0.7 : 0.42);
    d.ring(b.x, b.y, b.r, b.r * 0.08, '#ffffff', pressed ? 0.85 : 0.45);
    // A chevron: up = jump/rise, down = sneak/sink.
    const s = b.r * 0.4, lw = b.r * 0.13;
    const yTip = up ? b.y - s * 0.5 : b.y + s * 0.5;
    const yBase = up ? b.y + s * 0.5 : b.y - s * 0.5;
    d.line(b.x - s, yBase, b.x, yTip, lw, '#ffffff', 0.9);
    d.line(b.x + s, yBase, b.x, yTip, lw, '#ffffff', 0.9);
  }

  /** Unwire every listener + release the pointer. */
  detach(): void {
    for (const fn of this.un) fn();
    this.un.length = 0;
    if (this.locked) document.exitPointerLock?.();
  }
}

/** Convenience factory mirroring the engine's `world.orbit()` call style. */
export function mcControls(game: Game, opts: McOptions = {}): McControls {
  return new McControls(game, opts);
}
