// vector-kit — the pure-math foundation of the vector games (asteroids,
// thrust, gravitar, cave-explorer, desert-golf, vector-terrain, scramble):
// polygon/segment/swept collision, surface response, point gravity, Euler
// integration, line heightfields + craters, polygon shatter fragments.
// Raster shipped these as engine modules; v2 carried them example-local
// until parity-plan Phase 2 LIFTED them here (exported namespaced as
// `vectorKit` — the gameplay half of vector games, paired with the
// `game.vector` line renderer in vector.ts).
//
// Pure, stateless functions over plain `{x, y}` data the game owns — no
// DOM, no GPU, dist-tested. The 2D world is Y-DOWN (screen convention).

import type { Vec2 } from './util.js';
import type { Draw } from './draw.js';

// ─────────────────────────────────────────────────────────────────────────────
// vector-geom — vec namespace, polygon + segment collision, surface response,
// point gravity, Euler integration, path prediction.
// ─────────────────────────────────────────────────────────────────────────────

/** A wall segment from `a` to `b` — terrain pieces, cave walls, arena edges. */
export interface Segment { a: Vec2; b: Vec2; }

/**
 * 2D vector math over plain `{x, y}` data, as a single namespace so the generic
 * names (`add`, `scale`, `dot`…) don't collide with anything in a game's scope.
 */
export const vec = {
  add(a: Vec2, b: Vec2): Vec2 { return { x: a.x + b.x, y: a.y + b.y }; },
  sub(a: Vec2, b: Vec2): Vec2 { return { x: a.x - b.x, y: a.y - b.y }; },
  scale(a: Vec2, s: number): Vec2 { return { x: a.x * s, y: a.y * s }; },
  dot(a: Vec2, b: Vec2): number { return a.x * b.x + a.y * b.y; },
  len2(a: Vec2): number { return a.x * a.x + a.y * a.y; },
  len(a: Vec2): number { return Math.sqrt(a.x * a.x + a.y * a.y); },
  dist2(a: Vec2, b: Vec2): number { const dx = a.x - b.x, dy = a.y - b.y; return dx * dx + dy * dy; },
  dist(a: Vec2, b: Vec2): number { return Math.sqrt(vec.dist2(a, b)); },

  /** Zero-safe normalize: a zero vector returns `{0,0}` rather than NaN. */
  normalize(a: Vec2): Vec2 {
    const l = Math.sqrt(a.x * a.x + a.y * a.y);
    return l > 0 ? { x: a.x / l, y: a.y / l } : { x: 0, y: 0 };
  },

  /** Clamp a vector's magnitude to at most `max` (terminal-velocity caps). */
  clampLen(a: Vec2, max: number): Vec2 {
    const l2 = a.x * a.x + a.y * a.y;
    if (l2 <= max * max) return { x: a.x, y: a.y };
    const s = max / Math.sqrt(l2);
    return { x: a.x * s, y: a.y * s };
  },

  /** A unit (or `mag`-length) vector at the given angle in radians. */
  fromAngle(rad: number, mag: number = 1): Vec2 { return { x: Math.cos(rad) * mag, y: Math.sin(rad) * mag }; },

  /** The angle of a vector in radians (-PI..PI). */
  angleOf(a: Vec2): number { return Math.atan2(a.y, a.x); },

  /** Rotate a vector by `rad` radians. */
  rotate(a: Vec2, rad: number): Vec2 {
    const c = Math.cos(rad), s = Math.sin(rad);
    return { x: a.x * c - a.y * s, y: a.x * s + a.y * c };
  },

  /** Linear interpolation between two points. */
  lerp(a: Vec2, b: Vec2, t: number): Vec2 { return { x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t }; },

  /**
   * Move `from` toward `to` by at most `maxStep`, never overshooting (it clamps
   * exactly at `to`).
   */
  stepToward(from: Vec2, to: Vec2, maxStep: number): Vec2 {
    const dx = to.x - from.x, dy = to.y - from.y;
    const d = Math.sqrt(dx * dx + dy * dy);
    if (d <= maxStep || d === 0) return { x: to.x, y: to.y };
    const s = maxStep / d;
    return { x: from.x + dx * s, y: from.y + dy * s };
  },

  /** Turn one heading toward another by at most `maxStep` radians (capped steering). */
  turnToward(fromRad: number, toRad: number, maxStep: number): number {
    let d = (toRad - fromRad) % (Math.PI * 2);
    if (d > Math.PI) d -= Math.PI * 2;
    if (d < -Math.PI) d += Math.PI * 2;
    if (d > maxStep) d = maxStep;
    if (d < -maxStep) d = -maxStep;
    return fromRad + d;
  },
};

/** Transform local-space vertices to world space by position and rotation. */
export function transformVerts(localVerts: Vec2[], pos: Vec2, rot: number = 0): Vec2[] {
  const c = Math.cos(rot), s = Math.sin(rot);
  return localVerts.map((v) => ({
    x: pos.x + v.x * c - v.y * s,
    y: pos.y + v.x * s + v.y * c,
  }));
}

/**
 * Ray-casting (even-odd) point-in-polygon test. `worldPoly` MUST be in world
 * space — call `transformVerts` first. Handles convex AND concave simple
 * polygons of either winding.
 */
export function pointInPolygon(point: Vec2, worldPoly: Vec2[]): boolean {
  let inside = false;
  for (let i = 0, j = worldPoly.length - 1; i < worldPoly.length; j = i++) {
    const vi = worldPoly[i], vj = worldPoly[j];
    if (((vi.y > point.y) !== (vj.y > point.y)) &&
        (point.x < ((vj.x - vi.x) * (point.y - vi.y)) / (vj.y - vi.y) + vi.x)) {
      inside = !inside;
    }
  }
  return inside;
}

/** Cheap bounding-circle overlap — the pragmatic default hit test for vector games. */
export function circleHit(aPos: Vec2, aRadius: number, bPos: Vec2, bRadius: number): boolean {
  const dx = aPos.x - bPos.x, dy = aPos.y - bPos.y;
  const r = aRadius + bRadius;
  return dx * dx + dy * dy < r * r;
}

/**
 * Generate an irregular asteroid-style silhouette as local-space vertices.
 * Generate ONCE at spawn, store on the entity, never per frame (it would shimmer).
 */
export function generatePolygon(
  baseRadius: number,
  vertexCount: number = 10,
  jaggedness: number = 0.4,
  rng: () => number = Math.random,
): Vec2[] {
  const verts: Vec2[] = [];
  for (let i = 0; i < vertexCount; i++) {
    const angle = (i / vertexCount) * Math.PI * 2;
    const r = baseRadius * (1 + (rng() * 2 - 1) * jaggedness);
    verts.push({ x: Math.cos(angle) * r, y: Math.sin(angle) * r });
  }
  return verts;
}

/** Signed angle from one heading to another, in radians (-PI..PI) — capped-turn steering. */
export function signedAngle(fromRad: number, toRad: number): number {
  let d = (toRad - fromRad) % (Math.PI * 2);
  if (d > Math.PI) d -= Math.PI * 2;
  if (d < -Math.PI) d += Math.PI * 2;
  return d;
}

/** Intersection point of segment p1→p2 with segment p3→p4, or null if they don't cross within both spans. */
export function segmentIntersection(p1: Vec2, p2: Vec2, p3: Vec2, p4: Vec2): Vec2 | null {
  const d1x = p2.x - p1.x, d1y = p2.y - p1.y;
  const d2x = p4.x - p3.x, d2y = p4.y - p3.y;
  const denom = d1x * d2y - d1y * d2x;
  if (denom === 0) return null;                  // parallel (or degenerate)
  const t = ((p3.x - p1.x) * d2y - (p3.y - p1.y) * d2x) / denom;
  const u = ((p3.x - p1.x) * d1y - (p3.y - p1.y) * d1x) / denom;
  if (t < 0 || t > 1 || u < 0 || u > 1) return null;
  return { x: p1.x + t * d1x, y: p1.y + t * d1y };
}

/** The earliest contact a swept point made: where, which segment, how far along the path (0..1). */
export interface SweepHit { point: Vec2; index: number; t: number; }

/**
 * Sweep a moving point's path (prev → cur) against static wall segments and return
 * the EARLIEST contact, or null. The core anti-tunnel test for bodies vs line
 * geometry (terrain, cave walls).
 */
export function sweepVsSegments(prev: Vec2, cur: Vec2, segments: Segment[]): SweepHit | null {
  const dx = cur.x - prev.x, dy = cur.y - prev.y;
  const lenPath = Math.sqrt(dx * dx + dy * dy);
  let best: SweepHit | null = null;
  for (let i = 0; i < segments.length; i++) {
    const hit = segmentIntersection(prev, cur, segments[i].a, segments[i].b);
    if (!hit) continue;
    const t = lenPath > 0 ? Math.sqrt((hit.x - prev.x) ** 2 + (hit.y - prev.y) ** 2) / lenPath : 0;
    if (!best || t < best.t) best = { point: hit, index: i, t };
  }
  return best;
}

/** Turn a terrain polyline (or any open path) into wall segments for `sweepVsSegments`. */
export function polylineSegments(points: Vec2[]): Segment[] {
  const segs: Segment[] = [];
  for (let i = 0; i < points.length - 1; i++) segs.push({ a: points[i], b: points[i + 1] });
  return segs;
}

/** Tuning for `resolveSurface` — how a body bounces, scrubs, and settles on contact. */
export interface SurfaceResponse {
  /** 0 = no bounce (pure slide), 1 = full elastic bounce. Default 0. */
  restitution?: number;
  /** 0 = frictionless, 1 = grip (kills tangential speed on contact). Default 0. */
  friction?: number;
  /** Only bounce if the approach speed exceeds this — below it the body SETTLES. Default 0. */
  bounceThreshold?: number;
}

/**
 * The general surface-collision response. Splits the velocity into normal and
 * tangential parts against the outward unit `normal`: the normal part bounces
 * back scaled by `restitution`; the tangential part is scaled by (1 - `friction`).
 * `bounceThreshold` suppresses the bounce below a minimum approach speed so a
 * resting body settles instead of jittering.
 */
export function resolveSurface(vel: Vec2, normal: Vec2, opts: SurfaceResponse = {}): Vec2 {
  const vn = vel.x * normal.x + vel.y * normal.y;          // signed normal speed (< 0 = into surface)
  if (vn >= 0) return { x: vel.x, y: vel.y };              // already separating — nothing to resolve
  const approach = -vn;
  const e = approach > (opts.bounceThreshold ?? 0) ? (opts.restitution ?? 0) : 0;
  const k = 1 - (opts.friction ?? 0);
  const tx = vel.x - vn * normal.x;                        // tangential part
  const ty = vel.y - vn * normal.y;
  const nn = e * approach;                                 // reflected normal magnitude (outward)
  return { x: tx * k + nn * normal.x, y: ty * k + nn * normal.y };
}

/**
 * Continuous ground friction for a grounded body — damps the velocity ALONG the
 * surface, scaled by how flat it is (≈ cos of the slope): full on flat ground,
 * less on a steep slope, none on a wall. Call each frame while grounded.
 */
export function surfaceFriction(
  vel: Vec2,
  normal: Vec2,
  coefficient: number,
  dt: number,
  gravityDir: Vec2 = { x: 0, y: 1 },
): Vec2 {
  const glen = Math.hypot(gravityDir.x, gravityDir.y) || 1;
  const upx = -gravityDir.x / glen, upy = -gravityDir.y / glen;     // opposite gravity, unit
  const grip = Math.max(0, normal.x * upx + normal.y * upy);        // 1 on the flat → 0 on a wall
  const damp = Math.max(0, 1 - coefficient * grip * dt);
  const vn = vel.x * normal.x + vel.y * normal.y;                   // normal part (preserved)
  const tx = vel.x - vn * normal.x, ty = vel.y - vn * normal.y;     // tangential part (damped)
  return { x: vn * normal.x + tx * damp, y: vn * normal.y + ty * damp };
}

/** A point gravity source (a star, a well) for `gravityAccel`. */
export interface GravitySource { x: number; y: number; mass: number; }

/** Tuning for `gravityAccel`. */
export interface GravityOptions {
  /** Gravitational constant — scales how deep every well feels. Default 1. */
  G?: number;
  /** Softening floor on r² (> 0) so the pull never blows up at a well's centre. Default 1. */
  minR2?: number;
}

/**
 * The summed inverse-square gravitational acceleration on a body at `pos` from
 * all `sources` (softened — no singularity at the centre). Add it to the body's
 * accel before `integrateMotion`; apply to ships AND bullets so shots curve too.
 */
export function gravityAccel(pos: Vec2, sources: GravitySource[], opts: GravityOptions = {}): Vec2 {
  const G = opts.G ?? 1;
  const minR2 = opts.minR2 ?? 1;
  let ax = 0, ay = 0;
  for (let i = 0; i < sources.length; i++) {
    const s = sources[i];
    const dx = s.x - pos.x, dy = s.y - pos.y;
    const r2 = Math.max(dx * dx + dy * dy, minR2);
    const r = Math.sqrt(r2);
    const a = (G * s.mass) / r2;
    ax += (dx / r) * a;
    ay += (dy / r) * a;
  }
  return { x: ax, y: ay };
}

/** A bare point body for `integrateMotion`/`predictPath`. */
export interface Body { x: number; y: number; vx: number; vy: number; }

/** Per-frame inputs to `integrateMotion`. */
export interface MotionOptions {
  /** Frame time in seconds. */
  delta: number;
  /** Summed acceleration this frame (thrust + any extra pulls). */
  accel?: Vec2;
  /** Optional constant gravity vector (added to accel). */
  gravity?: Vec2;
  /** Per-second linear drag coefficient (0/undefined = none). */
  drag?: number;
  /** Terminal-speed clamp (undefined = uncapped). */
  maxSpeed?: number;
}

/**
 * Advance a bare body one frame, in place — semi-implicit Euler (velocity before
 * position; stable under gravity and frame-rate independent) with a
 * terminal-speed clamp.
 */
export function integrateMotion(body: Body, opts: MotionOptions): void {
  const dt = opts.delta;
  const ax = (opts.accel?.x ?? 0) + (opts.gravity?.x ?? 0);
  const ay = (opts.accel?.y ?? 0) + (opts.gravity?.y ?? 0);

  body.vx += ax * dt;                       // integrate velocity FIRST
  body.vy += ay * dt;

  if (opts.drag) {
    const f = 1 - opts.drag * dt;
    body.vx *= f;
    body.vy *= f;
  }

  if (opts.maxSpeed !== undefined) {        // clamp terminal velocity
    const sp2 = body.vx * body.vx + body.vy * body.vy;
    const max = opts.maxSpeed;
    if (sp2 > max * max) {
      const s = max / Math.sqrt(sp2);
      body.vx *= s;
      body.vy *= s;
    }
  }

  body.x += body.vx * dt;                   // then position, with the NEW velocity
  body.y += body.vy * dt;
}

/**
 * Forward-simulate a body under an acceleration function, returning sampled
 * positions (steps + 1, starting at the current position) — aim arcs, shot
 * previews. Pass the SAME acceleration the physics uses so the prediction matches.
 */
export function predictPath(
  body: Body,
  accelFn: (state: Body) => Vec2,
  steps: number,
  dt: number,
  opts: { maxSpeed?: number; drag?: number } = {},
): Vec2[] {
  const sim: Body = { x: body.x, y: body.y, vx: body.vx, vy: body.vy };
  const points: Vec2[] = [{ x: sim.x, y: sim.y }];
  for (let i = 0; i < steps; i++) {
    integrateMotion(sim, { accel: accelFn(sim), maxSpeed: opts.maxSpeed, drag: opts.drag, delta: dt });
    points.push({ x: sim.x, y: sim.y });
  }
  return points;
}

// ─────────────────────────────────────────────────────────────────────────────
// terrain — line heightfields, craters, slope-limited driving.
// ─────────────────────────────────────────────────────────────────────────────

/** Options for `generateTerrain` — a midpoint-displacement heightfield polyline. */
export interface HeightfieldOptions {
  /** Span on x — terrain runs 0..width. */
  width: number;
  /** Average ground height (screen y; larger = lower on screen). */
  baseY: number;
  /** Initial vertical displacement. Default `baseY * 0.4`. */
  amplitude?: number;
  /** 0..1: how much amplitude survives each subdivision. Default 0.5. */
  roughness?: number;
  /** Subdivision passes (more = finer detail, 2^iterations + 1 points). Default 6. */
  iterations?: number;
  /** Clamp ceiling — the highest the ground may rise. Default 0. */
  minY?: number;
  /** Clamp floor — the lowest the ground may sink. Default `baseY * 2`. */
  maxY?: number;
  /** Injectable RNG for deterministic terrain. Default `Math.random`. */
  rng?: () => number;
}

/**
 * Midpoint-displacement terrain as a polyline, sorted left-to-right and
 * single-valued in x — ready for `heightAtX` and `polylineSegments`. Generate
 * once per level; never per frame.
 */
export function generateTerrain(opts: HeightfieldOptions): Vec2[] {
  const { width, baseY } = opts;
  const amplitude = opts.amplitude ?? baseY * 0.4;
  const roughness = opts.roughness ?? 0.5;
  const iterations = opts.iterations ?? 6;
  const minY = opts.minY ?? 0;
  const maxY = opts.maxY ?? baseY * 2;
  const rng = opts.rng ?? Math.random;

  let points: Vec2[] = [{ x: 0, y: baseY }, { x: width, y: baseY }];
  let amp = amplitude;
  for (let it = 0; it < iterations; it++) {
    const next: Vec2[] = [];
    for (let i = 0; i < points.length - 1; i++) {
      const a = points[i], b = points[i + 1];
      next.push(a);
      const my = (a.y + b.y) / 2 + (rng() * 2 - 1) * amp;
      next.push({ x: (a.x + b.x) / 2, y: Math.max(minY, Math.min(maxY, my)) });
    }
    next.push(points[points.length - 1]);
    points = next;
    amp *= roughness;
  }
  return points;
}

/**
 * Sample the y of a terrain polyline at world x, linearly interpolating between
 * the two vertices spanning x. Points must be sorted by x ascending. Returns
 * Infinity if x is outside the polyline (treat as: no ground here).
 */
export function heightAtX(polyline: Vec2[], x: number): number {
  for (let i = 0; i < polyline.length - 1; i++) {
    const a = polyline[i], b = polyline[i + 1];
    if (x >= a.x && x <= b.x) {
      const t = (x - a.x) / (b.x - a.x);
      return a.y + t * (b.y - a.y);
    }
  }
  return Infinity;
}

/**
 * Slope-limited horizontal step along a heightfield. Returns the ALLOWED x: `toX`
 * if the step's uphill slope is within `maxClimbSlope` (rise/run — ~1 is 45°),
 * otherwise `fromX` (refused). Downhill is always allowed.
 */
export function climbableX(terrain: Vec2[], fromX: number, toX: number, maxClimbSlope: number): number {
  const yHere = heightAtX(terrain, fromX);
  const yNext = heightAtX(terrain, toX);
  if (!Number.isFinite(yHere) || !Number.isFinite(yNext)) return toX;
  const run = Math.abs(toX - fromX);
  if (run === 0) return toX;
  const slope = (yHere - yNext) / run;   // screen y down: positive = ground rises ahead
  return slope > maxClimbSlope ? fromX : toX;
}

/**
 * Blow a crater into a heightfield polyline, in place — destructible terrain.
 * Lowers the surface within `radius` of (cx, cy) following a circular bowl, ONLY
 * ever pushing the ground down and clamping to `floorY`, so the surface stays
 * single-valued and `heightAtX` stays valid.
 */
export function craterHeightfield(polyline: Vec2[], cx: number, cy: number, radius: number, floorY: number): void {
  for (let i = 0; i < polyline.length; i++) {
    const p = polyline[i];
    const dx = p.x - cx;
    if (Math.abs(dx) > radius) continue;
    const bowl = cy + Math.sqrt(Math.max(0, radius * radius - dx * dx)); // crater bottom at this x
    if (bowl > p.y) p.y = Math.min(bowl, floorY);                        // only lower; clamp to floor
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// vector-fx — polygon shatter fragments (drawFragments rewritten for v2 Draw).
// ─────────────────────────────────────────────────────────────────────────────

/** One drifting line fragment of a shattered polygon. */
export interface Fragment {
  /** Segment endpoints relative to the fragment centre. */
  a: Vec2; b: Vec2;
  /** World position of the centre. */
  x: number; y: number;
  vx: number; vy: number;
  rot: number; vrot: number;
  life: number; maxLife: number;
}

/** Tuning for `shatterPolygon`. */
export interface ShatterOptions {
  /** Outward drift speed of the fragments (px/s). Default 60. */
  speed?: number;
  /** Fragment lifetime in seconds (alpha fades over it). Default 0.8. */
  life?: number;
  /** Max spin rate in rad/s (each fragment gets a random spin within ±spin/2). Default 2. */
  spin?: number;
}

/**
 * Break a WORLD-space polygon into line fragments that drift and spin apart.
 * Pass `transformVerts(entity.verts, pos, rot)` — never local vertices. Append
 * the result to a `Fragment[]` you own; advance with `updateFragments`, draw
 * with `drawFragments`.
 */
export function shatterPolygon(worldVerts: Vec2[], opts: ShatterOptions = {}): Fragment[] {
  const { speed = 60, life = 0.8, spin = 2 } = opts;
  const frags: Fragment[] = [];
  for (let i = 0; i < worldVerts.length; i++) {
    const a = worldVerts[i], b = worldVerts[(i + 1) % worldVerts.length];
    const mid = { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 };
    const ang = Math.random() * Math.PI * 2;
    frags.push({
      a: { x: a.x - mid.x, y: a.y - mid.y },
      b: { x: b.x - mid.x, y: b.y - mid.y },
      x: mid.x, y: mid.y,
      vx: Math.cos(ang) * speed, vy: Math.sin(ang) * speed,
      rot: 0, vrot: (Math.random() - 0.5) * spin,
      life, maxLife: life,
    });
  }
  return frags;
}

/** Advance line fragments and return the survivors — reassign: `this.frags = updateFragments(this.frags, dt)`. */
export function updateFragments(frags: Fragment[], dt: number): Fragment[] {
  for (let i = 0; i < frags.length; i++) {
    const f = frags[i];
    f.x += f.vx * dt; f.y += f.vy * dt;
    f.rot += f.vrot * dt;
    f.life -= dt;
  }
  return frags.filter((f) => f.life > 0);
}

/**
 * Draw line fragments through the v2 Draw verbs (world space — they scroll with
 * the camera). REWRITTEN from the raster original: each fragment is one `d.line`
 * whose alpha fades with remaining life (was `ctx.globalAlpha` + `r.drawLine`).
 */
export function drawFragments(d: Draw, frags: Fragment[], color = '#cdd', width = 1): void {
  for (let i = 0; i < frags.length; i++) {
    const f = frags[i];
    const c = Math.cos(f.rot), s = Math.sin(f.rot);
    const ax = f.x + f.a.x * c - f.a.y * s, ay = f.y + f.a.x * s + f.a.y * c;
    const bx = f.x + f.b.x * c - f.b.y * s, by = f.y + f.b.x * s + f.b.y * c;
    d.line(ax, ay, bx, by, width, color, Math.max(0, f.life / f.maxLife));
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// wrap — screen-wrap (Asteroids-style).
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Wrap a position back into `[0, width) × [0, height)` after integrating
 * movement. Mutates `position` in place. Call once per frame.
 */
export function wrapPosition(position: Vec2, width: number, height: number): void {
  if (position.x < 0) position.x += width;
  else if (position.x >= width) position.x -= width;
  if (position.y < 0) position.y += height;
  else if (position.y >= height) position.y -= height;
}

/**
 * Return every screen position at which a wrapping sprite should be drawn this
 * frame — the real position plus mirrors for each edge the sprite straddles
 * (corners yield the diagonal mirror too, so up to 4 positions).
 */
export function wrapPositions(position: Vec2, radius: number, width: number, height: number): Vec2[] {
  const xs = [position.x];
  if (position.x - radius < 0) xs.push(position.x + width);
  if (position.x + radius > width) xs.push(position.x - width);
  const ys = [position.y];
  if (position.y - radius < 0) ys.push(position.y + height);
  if (position.y + radius > height) ys.push(position.y - height);
  const out: Vec2[] = [];
  for (const x of xs) for (const y of ys) out.push({ x, y });
  return out;
}

