// Arcade joints — distance constraints that pin a sprite to a point or another sprite.
//
// Deliberately NOT the full physics-engine joint zoo: one class, two modes, built for the
// arcade tropes — a pendulum swinging on a rod, a rope that hangs slack and snaps taut, a
// grappling hook that reels in and swings (the anchor can be a moving sprite, which drags
// the body along). Solved by position projection + radial velocity removal, the classic
// stable swing: gravity supplies the pendulum motion for free.
//
// Add one with `this.physics.addJoint(new Joint({...}))`; remove with `removeJoint`.

import type { Sprite } from './sprite.js';
import type { Vec2 } from './util.js';

/** How a {@link Joint} constrains the distance: `'rope'` only pulls (slack allowed), `'rod'` is rigid. */
export type JointMode = 'rope' | 'rod';

/** Config for a {@link Joint}. */
export interface JointOptions {
  /** The body pinned on the end of the joint. */
  sprite: Sprite;
  /**
   * What the other end is pinned to: a world point `{x, y}`, or a sprite — the joint
   * follows it, so a moving platform drags the pinned body along. Reassign at runtime
   * to re-hook.
   */
  anchor: Vec2 | Sprite;
  /** Rope/rod length in world units. Default: the anchor→sprite distance at creation. Set at runtime to reel in/out. */
  length?: number;
  /**
   * `'rope'` (default): pulls only when taut — hangs slack inside `length`, snaps tight at it.
   * `'rod'`: rigid — holds the sprite at exactly `length` (a stick pendulum).
   */
  mode?: JointMode;
  /** Pin offset from an anchor SPRITE's centre (world units) — hook a specific spot (a platform's underside). Default centre. */
  offset?: Vec2;
  /** Fraction of speed shed per second while the joint is engaged — makes a swing die down. Default `0` (swings forever). */
  damping?: number;
}

/** @internal Anchor type guard without a runtime Sprite import (avoids a module cycle) — a v2 sprite always carries `vel`; a plain point never does. */
function isSprite(a: Vec2 | Sprite): a is Sprite {
  return (a as Sprite).vel !== undefined;
}

/**
 * A distance joint from a sprite's centre to an anchor — the arcade rope/rod. `'rope'` mode
 * hangs slack and only pulls when taut (grappling hooks, wrecking balls, hanging lamps on
 * chains); `'rod'` mode is rigid (stick pendulums). The anchor may be a moving sprite, which
 * drags the body along; `length` is live, so shrinking it reels the body in.
 */
export class Joint {
  /** The body pinned on the end. */
  sprite: Sprite;
  /** The other end: a world point or a sprite (live — reassign to re-hook). */
  anchor: Vec2 | Sprite;
  /** Current rope/rod length (world units). Set it to reel in or pay out. */
  length: number;
  /** `'rope'` (pull-only, slack allowed) or `'rod'` (rigid). */
  mode: JointMode;
  /** Pin offset from an anchor sprite's centre. */
  offset: Vec2;
  /** Fraction of speed shed per second while engaged. */
  damping: number;
  /** When `false`, the joint is skipped entirely (cheap on/off — release and re-grab a grapple). Default `true`. */
  enabled: boolean = true;
  /** `true` when the joint pulled this frame (rope at full stretch / rod always). Read for effects — rope tension sounds, sparks. */
  taut: boolean = false;

  /** @internal Scratch for anchorPoint() (avoids per-frame allocation). */
  private _a: Vec2 = { x: 0, y: 0 };

  constructor(opts: JointOptions) {
    this.sprite = opts.sprite;
    this.anchor = opts.anchor;
    this.mode = opts.mode ?? 'rope';
    this.offset = opts.offset ? { x: opts.offset.x, y: opts.offset.y } : { x: 0, y: 0 };
    this.damping = opts.damping ?? 0;
    if (opts.length !== undefined) {
      this.length = opts.length;
    } else {
      const a = this.anchorPoint();
      this.length = Math.hypot(this.sprite.centerX - a.x, this.sprite.centerY - a.y);
    }
  }

  /** World position of the anchored end this frame (an anchor sprite's centre plus `offset`, or the fixed point). The returned object is reused — copy it if you keep it. */
  anchorPoint(): Vec2 {
    if (isSprite(this.anchor)) {
      this._a.x = this.anchor.centerX + this.offset.x;
      this._a.y = this.anchor.centerY + this.offset.y;
    } else {
      this._a.x = this.anchor.x;
      this._a.y = this.anchor.y;
    }
    return this._a;
  }

  /** Current anchor→sprite-centre distance (world units). Compare with `length` to read the slack. */
  distance(): number {
    const a = this.anchorPoint();
    return Math.hypot(this.sprite.centerX - a.x, this.sprite.centerY - a.y);
  }

  /**
   * Solve one frame: project the sprite back onto the constraint and remove the radial
   * velocity component, relative to the anchor's own velocity, so tangential (swing)
   * motion is preserved. Called by `Physics.updateJoints` each frame between sprite
   * updates and the collision pass; call directly only if you drive the update loop
   * yourself.
   */
  update(dt: number): void {
    const s = this.sprite;
    const a = this.anchorPoint();
    const dx = s.centerX - a.x;
    const dy = s.centerY - a.y;
    const dist = Math.hypot(dx, dy);
    if (dist < 1e-6) { this.taut = false; return; }

    const over = dist - this.length;
    this.taut = over >= -1e-9;
    const engaged = this.mode === 'rod' ? Math.abs(over) > 1e-9 : over > 0;
    const nx = dx / dist;
    const ny = dy / dist;

    if (engaged) {
      // Positional projection.
      // v2: tile-collision trace lands with the tilemap port — in raster this move is
      // clipped by solid tiles, so a rope can never drag a body inside the world.
      s.x -= over * nx;
      s.y -= over * ny;

      // Radial velocity removal, relative to the anchor — a rod cancels both ways, a rope
      // only the outward pull; the tangential part survives, which is the swing.
      const av = isSprite(this.anchor) ? this.anchor.vel : null;
      const rvx = s.vel.x - (av ? av.x : 0);
      const rvy = s.vel.y - (av ? av.y : 0);
      const rad = rvx * nx + rvy * ny;
      if (this.mode === 'rod' || rad > 0) {
        s.vel.x -= nx * rad;
        s.vel.y -= ny * rad;
      }
    }

    if (this.damping > 0 && (this.mode === 'rod' || this.taut)) {
      const k = Math.max(0, 1 - this.damping * dt);
      s.vel.x *= k;
      s.vel.y *= k;
    }
  }

  // v2: raster's Joint.draw(r, ctx, style) — the sagging-rope/rod Canvas2D visual —
  // drops here; a Draw-verb equivalent lands with the v2 debug/draw helpers.
}
