/** Audio system — SFX (synthesised or sampled) and streamed music through a single WebAudio graph. Accessed as `this.game.sound` on every scene. */

/**
 * Frequency in Hz of a named note — `'C5'`, `'F#4'`, `'Bb3'` (letter, optional `#`/`b`, octave).
 * Equal temperament, A4 = 440. Returns 0 for an unrecognised name.
 */
export function noteFreq(name: string): number {
  const m = /^([a-g])([#b]?)(\d)$/i.exec(name.trim());
  if (!m) return 0;
  const offsets: Record<string, number> = { c: -9, d: -7, e: -5, f: -4, g: -2, a: 0, b: 2 };
  let semi = offsets[m[1].toLowerCase()];
  if (m[2] === '#') semi += 1;
  else if (m[2] === 'b') semi -= 1;
  semi += (parseInt(m[3], 10) - 4) * 12;
  return 440 * Math.pow(2, semi / 12);
}

/** One scheduled step of a parsed jingle: simultaneous frequencies, start and length in steps. */
interface JingleEvent {
  freqs: number[];
  start: number;
  len: number;
}

/**
 * Parse jingle notation: whitespace-separated tokens, each a note (`C5`), a chord
 * (`C4+E4+G4`), or a rest (`-`); any token takes a length multiplier (`C5:3`, `-:2`).
 * Unrecognised tokens advance time like a rest, so rhythm survives a typo.
 */
function parseJingle(notation: string): { events: JingleEvent[]; total: number } {
  const events: JingleEvent[] = [];
  let pos = 0;
  for (const token of notation.trim().split(/\s+/)) {
    if (!token) continue;
    const sep = token.indexOf(':');
    const head = sep >= 0 ? token.slice(0, sep) : token;
    const lenStr = sep >= 0 ? token.slice(sep + 1) : '';
    const parsed = parseFloat(lenStr);
    const len = lenStr && isFinite(parsed) && parsed > 0 ? parsed : 1;
    if (head !== '-' && head !== '.') {
      const freqs = head.split('+').map(noteFreq).filter((f) => f > 0);
      if (freqs.length > 0) events.push({ freqs, start: pos, len });
    }
    pos += len;
  }
  return { events, total: pos };
}

/** A filter stage in a synthesised sound. Sweep a lowpass over `'noise'` for crunchy explosions. */
export interface SoundFilter {
  /** Filter shape (`'lowpass'`, `'highpass'`, `'bandpass'`, …). Default `'lowpass'`. */
  type?: BiquadFilterType;
  /** Cutoff frequency in Hz at the start of the sound. Default 1000. */
  freq?: number;
  /** Optional cutoff sweep target in Hz — e.g. 2400 → 60 collapses a blast into a rumble. */
  freqEnd?: number;
  /** Resonance (Q). Higher = a whistly peak at the cutoff. Default 1. */
  q?: number;
}

/** Pitch wobble (LFO) for a synthesised sound — sirens, UFO drones, magic shimmer. Ignored for `'noise'`. */
export interface SoundVibrato {
  /** Wobble rate in Hz. Default 8. */
  freq?: number;
  /** Wobble depth as a fraction of the base pitch (0.1 = ±10%). Default 0.06. */
  depth?: number;
}

/** Parameters for a synthesised sound effect (SFX / beep / tone / noise). */
export interface SoundSpec {
  /** Oscillator waveform, or `'noise'` for white noise. Default `'square'`. */
  type?: OscillatorType | 'noise';
  /** Start frequency in Hz. Ignored for `'noise'`. Default 440. */
  freq?: number;
  /** Optional frequency sweep target in Hz — creates a zap/pew slide. */
  freqEnd?: number;
  /** Shape of the `freq` → `freqEnd` slide. `'exponential'` sounds pitch-linear to the ear — better lasers, jumps, falls. Default `'linear'`. */
  sweep?: 'linear' | 'exponential';
  /**
   * Pitch sequence (overrides `freq`/`freqEnd`).
   * - `number[]` — Hz steps spread evenly across `duration`, glued under one envelope (coins, power-up runs).
   * - `string` — **jingle notation**: each note gets its own envelope (real articulation — 'ta-daa!' fanfares).
   *   Tokens: notes `C5`/`F#4`/`Bb3`, chords `C4+E4+G4`, rests `-`; append `:N` to stretch (`C5:3` = 3 steps).
   *   One step lasts `step` seconds; total length comes from the notation (`duration` is ignored).
   */
  notes?: number[] | string;
  /** Seconds per notation step in jingle mode (`notes` as a string). Default 0.12. */
  step?: number;
  /** Duration in seconds. Default 0.15. */
  duration?: number;
  /** Amplitude 0→1 relative to master volume. Default 1. */
  volume?: number;
  /** Attack ramp in seconds. Default 0.005. */
  attack?: number;
  /** Release ramp in seconds. Default 0.06. */
  release?: number;
  /** Shape of the release ramp. `'exponential'` = percussive, natural die-away (explosions, thumps, plucks). Default `'linear'`. */
  curve?: 'linear' | 'exponential';
  /** Random per-play pitch variation 0→1 (0.1 = up to ±10%) — keeps rapid-fire SFX from sounding robotic. Default 0. */
  jitter?: number;
  /** Pitch wobble (LFO): `{ freq, depth }` — sirens, drones, shimmer. */
  vibrato?: SoundVibrato;
  /** Pulse width 0→0.5 for `'square'` (0.5 = even square). 0.25/0.125 give classic thin chip-tune timbres. */
  duty?: number;
  /** Filter stage: `{ type, freq, freqEnd, q }`. A swept lowpass over `'noise'` is the crunchy-explosion move. */
  filter?: SoundFilter;
  /** Distortion drive 0→1 — adds grit/crunch (explosions, heavy impacts, dirty lasers). Default 0. */
  distortion?: number;
  /** Stereo position -1 (left) → 1 (right). Default 0 (centre). */
  pan?: number;
  /** Start offset in seconds — sequence the layers of a compound sound (`play([...])`). Default 0. */
  delay?: number;
}

/** Options for `sound.music(url, opts)` — looped background music / BGM / audio track. */
export interface MusicOptions {
  /** Loop the track. Default `true`. */
  loop?: boolean;
  /** Track volume 0→1 relative to master. Default 1. */
  volume?: number;
  /** Fade-in duration in seconds. Default 0 (instant). */
  fadeIn?: number;
}

/** A sound definition: a synthesised `SoundSpec`, an array of specs played together (a layered/compound sound), or a URL string to an audio file (mp3/ogg/wav). */
export type Sound = SoundSpec | SoundSpec[] | string;

/** Audio service (SFX / music / master volume). The Game owns one as `this.sound`. The AudioContext is created lazily on the first user gesture (browser autoplay policy). All methods are no-ops where WebAudio is unavailable. */
export class Audio {
  private ctx: AudioContext | null = null;
  // Master chain split in two so a recording can tap the mix POST-volume but
  // PRE-mute: every source → volumeNode (master volume) → muteNode (0 when muted)
  // → destination. The record tap (recordDest) hangs off volumeNode, so a clip
  // captured while the game is muted locally still has sound, at the normal mix level.
  private volumeNode: GainNode | null = null;
  private muteNode: GainNode | null = null;
  // Live MediaStream tap for record() — a MediaStreamAudioDestination fed from
  // volumeNode; created on demand by captureStreamTrack(), released by stopCapture().
  private recordDest: MediaStreamAudioDestinationNode | null = null;
  private destroyed: boolean = false;
  private readonly defs: Map<string, Sound> = new Map<string, Sound>();
  private readonly buffers: Map<string, AudioBuffer> = new Map<string, AudioBuffer>();

  private musicEl: HTMLAudioElement | null = null;
  private musicGain: GainNode | null = null;
  // true when music routes through WebAudio (createMediaElementSource) — then mute
  // is handled by muteNode (keeping it in the record tap). false on the CORS
  // fallback (element plays directly), where mute must touch the element itself.
  private musicViaWebAudio: boolean = false;

  private masterVolume: number;
  private wake: (() => void) | null = null;
  private _muted: boolean = false;

  constructor(masterVolume: number = 0.25) {
    this.masterVolume = masterVolume;
    if (typeof window !== 'undefined') {
      this.wake = (): void => { this.ensure(); };
      window.addEventListener('pointerdown', this.wake, { once: true });
      window.addEventListener('keydown', this.wake, { once: true });
    }
  }

  private ensure(): AudioContext | null {
    if (this.destroyed) return null;
    try {
      if (!this.ctx) {
        this.ctx = new AudioContext();
        // volume (master level) → mute (0/1) → speakers. Splitting the two lets the
        // record tap sit after volume but before mute (see captureStreamTrack).
        this.volumeNode = this.ctx.createGain();
        this.volumeNode.gain.value = this.masterVolume;
        this.muteNode = this.ctx.createGain();
        this.muteNode.gain.value = this._muted ? 0 : 1; // honour mute set before first sound
        this.volumeNode.connect(this.muteNode);
        this.muteNode.connect(this.ctx.destination);
      }
      if (this.ctx.state === 'suspended') void this.ctx.resume();
      return this.ctx;
    } catch {
      return null;
    }
  }

  /** Pulse-shaped PeriodicWave per duty cycle (quantised), built lazily per AudioContext. */
  private readonly pulseWaves: Map<number, PeriodicWave> = new Map<number, PeriodicWave>();
  /** WaveShaper curves per distortion drive (quantised). */
  private readonly shaperCurves: Map<number, Float32Array<ArrayBuffer>> = new Map<number, Float32Array<ArrayBuffer>>();

  /** Build (and cache) a pulse wave of width `duty` from its Fourier series. */
  private pulseWave(c: AudioContext, duty: number): PeriodicWave {
    const d = Math.min(0.48, Math.max(0.02, duty));
    const key = Math.round(d * 100);
    let wave = this.pulseWaves.get(key);
    if (!wave) {
      const harmonics = 32;
      const real = new Float32Array(harmonics + 1);
      const imag = new Float32Array(harmonics + 1);
      for (let n = 1; n <= harmonics; n++) {
        real[n] = (2 / (n * Math.PI)) * Math.sin(n * Math.PI * d);
      }
      wave = c.createPeriodicWave(real, imag);
      this.pulseWaves.set(key, wave);
    }
    return wave;
  }

  /** Build (and cache) a soft-clip waveshaper curve for a 0→1 drive. */
  private distortionCurve(amount: number): Float32Array<ArrayBuffer> {
    const key = Math.round(Math.min(1, Math.max(0, amount)) * 50);
    let curve = this.shaperCurves.get(key);
    if (!curve) {
      const k = (key / 50) * 60;
      const n = 256;
      curve = new Float32Array(n);
      for (let i = 0; i < n; i++) {
        const x = (i * 2) / (n - 1) - 1;
        curve[i] = ((1 + k) * x) / (1 + k * Math.abs(x));
      }
      this.shaperCurves.set(key, curve);
    }
    return curve;
  }

  private playSpec(spec: SoundSpec): void {
    const c = this.ensure();
    if (!c || !this.volumeNode) return;
    if (typeof spec.notes === 'string') { this.playJingle(c, spec, spec.notes); return; }
    const { type = 'square', freq = 440, freqEnd, sweep = 'linear', notes,
            duration = 0.15, volume = 1, attack = 0.005, release = 0.06,
            curve = 'linear', jitter = 0, vibrato, duty, filter,
            distortion = 0, pan = 0, delay = 0 } = spec;
    if (volume <= 0 || duration <= 0) return;
    const t0 = c.currentTime + Math.max(0, delay);
    const end = t0 + duration;
    // Per-play random pitch multiplier (also varies noise playback rate).
    const jit = Math.min(1, Math.max(0, jitter));
    const pitchMul = jit > 0 ? 1 + (Math.random() * 2 - 1) * jit : 1;

    // Amplitude envelope: attack → hold → release (linear or exponential die-away).
    const gain = c.createGain();
    gain.connect(this.volumeNode);
    gain.gain.setValueAtTime(0, t0);
    gain.gain.linearRampToValueAtTime(volume, t0 + attack);
    gain.gain.setValueAtTime(volume, t0 + Math.max(attack, duration - release));
    if (curve === 'exponential') {
      gain.gain.exponentialRampToValueAtTime(Math.max(0.0001, volume * 0.001), end);
      gain.gain.setValueAtTime(0, end);
    } else {
      gain.gain.linearRampToValueAtTime(0, end);
    }

    let src: AudioScheduledSourceNode;
    if (type === 'noise') {
      const frames = Math.max(1, Math.floor(c.sampleRate * duration * Math.max(1, pitchMul)));
      const buffer = c.createBuffer(1, frames, c.sampleRate);
      const data = buffer.getChannelData(0);
      for (let i = 0; i < frames; i++) data[i] = Math.random() * 2 - 1;
      const node = c.createBufferSource();
      node.buffer = buffer;
      if (pitchMul !== 1) node.playbackRate.setValueAtTime(pitchMul, t0);
      src = node;
    } else {
      const osc = c.createOscillator();
      if (type === 'square' && duty !== undefined && duty > 0 && duty < 0.5) {
        osc.setPeriodicWave(this.pulseWave(c, duty));
      } else {
        osc.type = type;
      }
      if (Array.isArray(notes) && notes.length > 0) {
        const step = duration / notes.length;
        for (let i = 0; i < notes.length; i++) {
          osc.frequency.setValueAtTime(Math.max(1, notes[i] * pitchMul), t0 + i * step);
        }
      } else {
        osc.frequency.setValueAtTime(Math.max(1, freq * pitchMul), t0);
        if (freqEnd !== undefined) {
          if (sweep === 'exponential') {
            osc.frequency.exponentialRampToValueAtTime(Math.max(1, freqEnd * pitchMul), end);
          } else {
            osc.frequency.linearRampToValueAtTime(Math.max(1, freqEnd * pitchMul), end);
          }
        }
      }
      if (vibrato) {
        const lfo = c.createOscillator();
        lfo.frequency.setValueAtTime(vibrato.freq ?? 8, t0);
        const lfoGain = c.createGain();
        const base = (Array.isArray(notes) && notes.length > 0 ? notes[0] : freq) * pitchMul;
        lfoGain.gain.setValueAtTime((vibrato.depth ?? 0.06) * base, t0);
        lfo.connect(lfoGain);
        lfoGain.connect(osc.frequency);
        lfo.start(t0);
        lfo.stop(end);
      }
      src = osc;
    }

    // Tone chain: source → filter → distortion → pan → envelope → master.
    let node: AudioNode = src;
    if (filter) {
      const f = c.createBiquadFilter();
      f.type = filter.type ?? 'lowpass';
      f.Q.setValueAtTime(filter.q ?? 1, t0);
      f.frequency.setValueAtTime(Math.max(10, filter.freq ?? 1000), t0);
      if (filter.freqEnd !== undefined) {
        f.frequency.exponentialRampToValueAtTime(Math.max(10, filter.freqEnd), end);
      }
      node.connect(f);
      node = f;
    }
    if (distortion > 0) {
      const shaper = c.createWaveShaper();
      shaper.curve = this.distortionCurve(distortion);
      node.connect(shaper);
      node = shaper;
    }
    if (pan !== 0 && typeof c.createStereoPanner === 'function') {
      const p = c.createStereoPanner();
      p.pan.setValueAtTime(Math.max(-1, Math.min(1, pan)), t0);
      node.connect(p);
      node = p;
    }
    node.connect(gain);
    src.start(t0);
    src.stop(end);
  }

  /**
   * Play a jingle (`notes` as notation string): every note/chord is its own enveloped
   * voice — real articulation between notes — all feeding one shared
   * filter → distortion → pan → volume chain into the master.
   */
  private playJingle(c: AudioContext, spec: SoundSpec, notation: string): void {
    if (!this.volumeNode) return;
    const { type = 'square', volume = 1, attack = 0.005, release,
            curve = 'linear', jitter = 0, vibrato, duty, filter,
            distortion = 0, pan = 0, delay = 0, step = 0.12 } = spec;
    if (volume <= 0 || step <= 0) return;
    const { events, total } = parseJingle(notation);
    if (events.length === 0) return;
    const t0 = c.currentTime + Math.max(0, delay);
    const end = t0 + total * step;
    const jit = Math.min(1, Math.max(0, jitter));

    // Shared tone chain (same order as a single SFX, minus the per-note envelopes).
    const volGain = c.createGain();
    volGain.gain.setValueAtTime(volume, t0);
    volGain.connect(this.volumeNode);
    let chainIn: AudioNode = volGain;
    if (pan !== 0 && typeof c.createStereoPanner === 'function') {
      const p = c.createStereoPanner();
      p.pan.setValueAtTime(Math.max(-1, Math.min(1, pan)), t0);
      p.connect(chainIn);
      chainIn = p;
    }
    if (distortion > 0) {
      const shaper = c.createWaveShaper();
      shaper.curve = this.distortionCurve(distortion);
      shaper.connect(chainIn);
      chainIn = shaper;
    }
    if (filter) {
      const f = c.createBiquadFilter();
      f.type = filter.type ?? 'lowpass';
      f.Q.setValueAtTime(filter.q ?? 1, t0);
      f.frequency.setValueAtTime(Math.max(10, filter.freq ?? 1000), t0);
      if (filter.freqEnd !== undefined) {
        f.frequency.exponentialRampToValueAtTime(Math.max(10, filter.freqEnd), end);
      }
      f.connect(chainIn);
      chainIn = f;
    }

    for (const ev of events) {
      const nStart = t0 + ev.start * step;
      // Sound 92% of the slot so consecutive notes articulate instead of slurring.
      const nDur = ev.len * step * 0.92;
      const nEnd = nStart + nDur;
      const att = Math.min(attack, nDur * 0.3);
      const rel = Math.min(release ?? Math.max(0.02, nDur * 0.35), nDur * 0.8);
      const peak = 1 / Math.sqrt(ev.freqs.length); // chords share headroom
      const env = c.createGain();
      env.connect(chainIn);
      env.gain.setValueAtTime(0, nStart);
      env.gain.linearRampToValueAtTime(peak, nStart + att);
      env.gain.setValueAtTime(peak, nStart + Math.max(att, nDur - rel));
      if (curve === 'exponential') {
        env.gain.exponentialRampToValueAtTime(0.0001, nEnd);
        env.gain.setValueAtTime(0, nEnd);
      } else {
        env.gain.linearRampToValueAtTime(0, nEnd);
      }
      const pitchMul = jit > 0 ? 1 + (Math.random() * 2 - 1) * jit : 1;
      for (const f of ev.freqs) {
        const osc = c.createOscillator();
        if (type === 'square' && duty !== undefined && duty > 0 && duty < 0.5) {
          osc.setPeriodicWave(this.pulseWave(c, duty));
        } else if (type !== 'noise') {
          osc.type = type;
        }
        osc.frequency.setValueAtTime(Math.max(1, f * pitchMul), nStart);
        if (vibrato) {
          const lfo = c.createOscillator();
          lfo.frequency.setValueAtTime(vibrato.freq ?? 8, nStart);
          const lfoGain = c.createGain();
          lfoGain.gain.setValueAtTime((vibrato.depth ?? 0.06) * f * pitchMul, nStart);
          lfo.connect(lfoGain);
          lfoGain.connect(osc.frequency);
          lfo.start(nStart);
          lfo.stop(nEnd);
        }
        osc.connect(env);
        osc.start(nStart);
        osc.stop(nEnd);
      }
    }
  }

  private loadSample(url: string): Promise<void> {
    if (this.buffers.has(url)) return Promise.resolve();
    const c = this.ensure();
    if (!c || typeof fetch === 'undefined') return Promise.resolve();
    return (async () => {
      try {
        const data = await (await fetch(url)).arrayBuffer();
        this.buffers.set(url, await c.decodeAudioData(data));
      } catch {
        /* unreachable file / decode failure — stays unloaded, plays silently */
      }
    })();
  }

  private playSample(url: string): void {
    const c = this.ensure();
    if (!c || !this.volumeNode) return;
    const buf = this.buffers.get(url);
    if (!buf) { this.loadSample(url); return; }
    const gain = c.createGain();
    gain.connect(this.volumeNode);
    const node = c.createBufferSource();
    node.buffer = buf;
    node.connect(gain);
    node.start();
  }

  private playSound(sound: Sound): void {
    if (typeof sound === 'string') this.playSample(sound);
    else if (Array.isArray(sound)) for (const layer of sound) this.playSpec(layer);
    else this.playSpec(sound);
  }

  /** Play a named sound (registered with `define`), an inline `SoundSpec`, or an array of specs fired together (layer a compound sound — stagger layers with `delay`). Use for one-shot SFX / audio cues. */
  play(sound: string | SoundSpec | SoundSpec[]): void {
    if (typeof sound === 'string') {
      const def = this.defs.get(sound);
      if (def !== undefined) this.playSound(def);
    } else {
      this.playSound(sound);
    }
  }

  /** Register a reusable sound under a name — a `SoundSpec`, an array of specs (a layered sound), or a URL to an audio file (mp3/ogg/wav). Audio files are preloaded immediately. Call during scene `preload` or `setup`. */
  define(name: string, sound: Sound): void {
    this.defs.set(name, sound);
    if (typeof sound === 'string') this.loadSample(sound);
  }

  /** Preload an audio file by URL so the first `play` is gapless. Resolves when the file is decoded and cached. */
  load(url: string): Promise<void> {
    return this.loadSample(url);
  }

  /** `true` if `url`'s sample has already been decoded and cached — so re-queuing it needs no load. */
  isLoaded(url: string): boolean {
    return this.buffers.has(url);
  }

  /** `true` when all audio is silenced (master gain forced to 0). */
  get muted(): boolean { return this._muted; }

  /** Silence (`on = true`, the default) or restore all audio by forcing/relaxing the master gain. Music keeps playing (muted), so unmuting never restarts the track. Persists if set before the first sound plays. */
  mute(on: boolean = true): void {
    this._muted = on;
    if (this.muteNode) this.muteNode.gain.value = on ? 0 : 1;
    // On the CORS fallback the music element plays directly (not through muteNode),
    // so mute it at the element. On the WebAudio path leave it audible into the
    // graph — muteNode silences playback while the pre-mute record tap still gets it.
    if (this.musicEl && !this.musicViaWebAudio) this.musicEl.muted = on;
  }

  /** Flip the mute state and return it — handy for a mute button. */
  toggleMute(): boolean {
    this.mute(!this._muted);
    return this._muted;
  }

  /**
   * @internal Begin tapping the master mix (post-volume, pre-mute) as a live
   * MediaStream for {@link Game.record}, returning the audio track to add to the
   * recorder's stream — or null if no audio graph exists yet (a game that has made
   * no sound records video only). The tap is independent of mute, so a clip has
   * sound even when the game is muted locally.
   */
  captureStreamTrack(): MediaStreamTrack | null {
    if (!this.ctx || !this.volumeNode) return null; // nothing has played → no audio to capture
    if (this.ctx.state === 'suspended') void this.ctx.resume();
    if (!this.recordDest) {
      this.recordDest = this.ctx.createMediaStreamDestination();
      this.volumeNode.connect(this.recordDest);
    }
    return this.recordDest.stream.getAudioTracks()[0] ?? null;
  }

  /** @internal Stop the record tap started by {@link captureStreamTrack} and release it. */
  stopCapture(): void {
    if (this.recordDest && this.volumeNode) {
      try { this.volumeNode.disconnect(this.recordDest); } catch { /* already disconnected */ }
    }
    this.recordDest = null;
  }

  /** Stream and loop a music track from a URL (BGM / background music / chiptune). Replaces any currently playing track. */
  music(url: string, opts: MusicOptions = {}): void {
    const c = this.ensure();
    if (!c || !this.volumeNode || typeof globalThis.Audio === 'undefined') return;
    const { loop = true, volume = 1, fadeIn = 0 } = opts;
    if (this.musicEl) { this.musicEl.pause(); this.musicEl = null; }
    const el = new globalThis.Audio(url);
    el.crossOrigin = 'anonymous';
    el.loop = loop;
    const gain = c.createGain();
    gain.connect(this.volumeNode);
    try {
      c.createMediaElementSource(el).connect(gain);
      this.musicViaWebAudio = true; // through muteNode → silenced by mute, still captured pre-mute
    } catch {
      // CORS-tainted: the element plays directly, bypassing muteNode — mute it here.
      this.musicViaWebAudio = false;
      el.volume = volume * this.masterVolume;
      el.muted = this._muted;
    }
    const now = c.currentTime;
    gain.gain.setValueAtTime(fadeIn > 0 ? 0 : volume, now);
    if (fadeIn > 0) gain.gain.linearRampToValueAtTime(volume, now + fadeIn);
    this.musicEl = el;
    this.musicGain = gain;
    void el.play().catch(() => {});
  }

  /** Stop the currently playing music track. Pass `{ fadeOut: seconds }` for a smooth fade. */
  stopMusic(opts: { fadeOut?: number } = {}): void {
    const el = this.musicEl;
    const gain = this.musicGain;
    if (!el) return;
    const fade = opts.fadeOut ?? 0;
    if (fade > 0 && gain && this.ctx) {
      const now = this.ctx.currentTime;
      gain.gain.linearRampToValueAtTime(0, now + fade);
      setTimeout(() => el.pause(), fade * 1000);
    } else {
      el.pause();
    }
    this.musicEl = null;
    this.musicGain = null;
  }

  /** Master volume 0→1. Affects all SFX and music simultaneously. Default 0.25. */
  get volume(): number {
    return this.masterVolume;
  }
  set volume(v: number) {
    this.masterVolume = Math.max(0, Math.min(1, v));
    // Volume is its own node now — set it live; muteNode independently handles
    // silence, so a change while muted simply takes audible effect on unmute.
    if (this.volumeNode) this.volumeNode.gain.value = this.masterVolume;
  }

  /** Suspend all audio output (SFX + music) — use when showing a pause overlay. */
  pause(): void {
    if (this.musicEl) this.musicEl.pause();
    if (this.ctx && this.ctx.state !== 'suspended') void this.ctx.suspend();
  }

  /** Resume audio after `pause()` or after the browser's autoplay-suspended boot. */
  resume(): void {
    this.ensure();
    if (this.musicEl) void this.musicEl.play().catch(() => {});
  }

  /** Tear down the audio system: stop music, close the AudioContext, remove event listeners. After this every method is a no-op. Called automatically by `Game.destroy()`. */
  destroy(): void {
    this.destroyed = true;
    if (this.wake && typeof window !== 'undefined') {
      window.removeEventListener('pointerdown', this.wake);
      window.removeEventListener('keydown', this.wake);
    }
    this.wake = null;
    if (this.musicEl) this.musicEl.pause();
    this.musicEl = null;
    this.musicGain = null;
    if (this.ctx) void this.ctx.close().catch(() => {});
    this.ctx = null;
    this.volumeNode = null;
    this.muteNode = null;
    this.recordDest = null;
    this.defs.clear();
    this.buffers.clear();
    this.pulseWaves.clear();
    this.shaperCurves.clear();
  }
}
