// MsdfText — a retained, styled block of MSDF text. Lays out ONCE on change
// (word-wrap, kerning, alignment, rich-text runs, decorations) and re-submits
// cheaply every frame. Draw it with `d.msdfText(text, x, y)`.
//
// The style surface ports Antriel's phaser4-msdf-text: per-object and per-run
// colour (+ vertical gradient), alpha, faux-bold weight, outline (width / colour
// / softness / rounded / inner-colour / layered), drop shadow (offset / softness
// / spread / rounded / inner-colour), skew (faux italic), and underline /
// strikethrough / highlight decorations. Edge-distance channels (weight, outline
// width, shadow spread) are normalised by the atlas distanceRange, so a value
// means the same on any font. SOFTNESS is a direct field fraction (NOT divided
// by distanceRange): dividing it made the blur a sub-pixel no-op on fonts with a
// wide distanceRange, so softness passes straight through to the field.
//
// Module load is DOM-free (pure layout math + submission).

import type { MsdfFont, MsdfGlyph } from './msdf-font.js';
import {
  MsdfRenderer, packColor, packParams, packSolidParams, packDashParams, SOLID_PARAMS,
} from './msdf.js';
import { transformedBounds, type TextBounds, type TextTransform } from './text-bounds.js';

export type MsdfAlign = 'left' | 'center' | 'right';

/** A colour: `0xRRGGBB`, a CSS-ish `#rgb`/`#rrggbb`/`rgb(r,g,b)` string, or a top→bottom gradient. */
export type MsdfColor = number | string | { top: number | string; bottom: number | string };

export interface MsdfOutline {
  /** Outline width in distance-field units (bounded near 0.5). `0` disables it (unless softness > 0). */
  width?: number;
  color?: number | string;
  alpha?: number;
  /** Blur the outer edge (MTSDF only). With width 0 the outline IS a glow hugging the letters. */
  softness?: number;
  /** Round the outer corners off the true SDF, 0 sharp → 1 round (MTSDF only). */
  rounded?: number | boolean;
  /** Colour at the outline's inner edge — ramps from `color`; forces layered. */
  innerColor?: number | string;
  /** Draw the outline as a separate silhouette pass so a thick outline never covers a neighbour. */
  layered?: boolean;
}

export interface MsdfShadow {
  x?: number;
  y?: number;
  color?: number | string;
  alpha?: number;
  /** Blur (MTSDF only). */
  softness?: number;
  /** Dilate the silhouette before blurring — a fat hard shadow. Works on plain MSDF. */
  spread?: number;
  rounded?: number | boolean;
  innerColor?: number | string;
}

/** An underline / strikethrough rule (`true` inherits everything). */
export interface MsdfRule {
  color?: number | string;
  alpha?: number;
  /** Multiplier on the font's underline thickness. Default 1. */
  thickness?: number;
  /** Em-relative shift from the default position (positive = down). */
  offset?: number;
  /** Cut into dashes: `true` for defaults, or `{ length, gap, radius }` (em-relative). */
  dash?: boolean | { length?: number; gap?: number; radius?: number; softness?: number };
}

/** A highlight pill painted behind a run (`true` = marker yellow). */
export interface MsdfHighlight {
  color?: number | string;
  alpha?: number;
  /** Corner radius 0 (square) → 1 (stadium). */
  radius?: number;
  /** Edge blur 0 → 1 (fades inward). */
  softness?: number;
  /** Border ring width 0 → 1. */
  borderWidth?: number;
  borderColor?: number | string;
  /** Em-relative padding (× fontSize). */
  padding?: number;
}

/** A per-run style override (rich text). Every field optional. */
export interface MsdfStyle {
  color?: MsdfColor;
  alpha?: number;
  weight?: number;
  outline?: MsdfOutline;
  shadow?: MsdfShadow;
  skew?: number;
  underline?: boolean | MsdfRule;
  strikethrough?: boolean | MsdfRule;
  highlight?: boolean | MsdfHighlight;
  /** Per-run font-size multiplier (structural — relayout). */
  fontScale?: number;
  /** Per-run font: another loaded MsdfFont, or a face name in a merged atlas. */
  font?: MsdfFont | string;
}

/** A rich-text segment: a bare string (unstyled) or styled text. */
export type MsdfSegment = string | (MsdfStyle & { text: string });

export interface MsdfTextOptions extends MsdfStyle {
  fontSize?: number;
  align?: MsdfAlign;
  lineSpacing?: number;
  letterSpacing?: number;
  /** Word-wrap width in pixels (0 = no wrap). */
  maxWidth?: number;
}

export interface MsdfDrawOptions {
  /** Uniform scale of the whole block about its origin. */
  scale?: number;
  /** Rotation of the whole block about its origin, in radians. */
  rotation?: number;
  /** Extra alpha multiplier on the whole block. */
  alpha?: number;
  /** Anchor as a fraction of the block (0,0 = top-left, 0.5,0.5 = centre). Default 0,0. */
  origin?: { x?: number; y?: number };
  /** Depth 0..1 (0 = frontmost). Text tests-never, so this only orders text vs text. */
  z?: number;
}

// ── Colour parsing → 0xRRGGBB ────────────────────────────────────────────────

function toRGB(c: number | string): number {
  if (typeof c === 'number') return c & 0xffffff;
  const s = c.trim();
  if (s[0] === '#') {
    let h = s.slice(1);
    if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
    return parseInt(h.slice(0, 6), 16) & 0xffffff;
  }
  const m = s.match(/rgba?\(([^)]+)\)/i);
  if (m) {
    const p = m[1].split(',').map((v) => parseFloat(v));
    return ((Math.round(p[0]) & 0xff) << 16) | ((Math.round(p[1]) & 0xff) << 8) | (Math.round(p[2]) & 0xff);
  }
  return 0xffffff;
}

// ── Resolved per-character style (structural + appearance) ───────────────────

interface Resolved {
  face: MsdfFont;
  sizeMul: number;
  colTop: number; colBottom: number; alpha: number;
  weight: number;
  oWidth: number; oColor: number; oAlpha: number; oSoft: number; oRound: number; oInner: number; oLayered: boolean;
  sX: number; sY: number; sColor: number; sAlpha: number; sSoft: number; sSpread: number; sRound: number; sInner: number;
  skew: number;
  underline: MsdfRule | null;
  strike: MsdfRule | null;
  highlight: MsdfHighlight | null;
}

interface LaidGlyph {
  g: MsdfGlyph;
  face: MsdfFont;
  size: number;      // fontSize * sizeMul (px)
  penX: number;      // pen origin x (block space)
  baselineY: number; // baseline y (block space)
  st: Resolved;
}

interface Rect {
  x: number; y: number; w: number; h: number;
  face: MsdfFont;
  color: number; alpha: number;
  // solid params
  radius: number; border: number; soft: number; borderColor: number; borderAlpha: number;
  dashCount: number; dashDuty: number;
  pass: number; // 0 highlight, 1 underline, 2 strike
}

const roundedNorm = (v: number | boolean | undefined): number => v === true ? 1 : v === false || v == null ? 0 : v;

/**
 * A styled, laid-out block of MSDF text. Create with `game.assets.msdfText(font, str,
 * opts)`; mutate with the chainable setters; draw with `d.msdfText(text, x, y)`.
 */
export class MsdfText {
  private _text = '';
  private _segments: MsdfSegment[] | null = null;
  private _overlays: { start: number; length: number; style: MsdfStyle }[] = [];

  fontSize: number;
  align: MsdfAlign = 'left';
  lineSpacing = 0;
  letterSpacing = 0;
  maxWidth = 0;

  // Object-level style (the base every run inherits).
  private base: MsdfStyle;

  private laid: LaidGlyph[] = [];
  private rects: Rect[] = [];
  private lineTops: number[] = [];
  private _width = 0;
  private _height = 0;
  private dirty = true;

  constructor(
    public font: MsdfFont,
    text: string | string[] = '',
    opts: MsdfTextOptions = {},
  ) {
    this.fontSize = opts.fontSize ?? 48;
    this.align = opts.align ?? 'left';
    this.lineSpacing = opts.lineSpacing ?? 0;
    this.letterSpacing = opts.letterSpacing ?? 0;
    this.maxWidth = opts.maxWidth ?? 0;
    this.base = {
      color: opts.color ?? 0xffffff,
      alpha: opts.alpha ?? 1,
      weight: opts.weight ?? 0,
      outline: opts.outline,
      shadow: opts.shadow,
      skew: opts.skew ?? 0,
      underline: opts.underline,
      strikethrough: opts.strikethrough,
      highlight: opts.highlight,
    };
    this._text = Array.isArray(text) ? text.join('\n') : text;
  }

  get width(): number { this.ensure(); return this._width; }
  get height(): number { this.ensure(); return this._height; }
  get text(): string { return this._text; }

  /**
   * The box this block PAINTS when drawn at (x, y) with `opts` — the text box
   * grown by outline / shadow ink, through origin / scale / rotation. Use it to
   * space HUD furniture, and `textOverlaps()` to check a whole layout;
   * `width`/`height` are the tighter text box you align to. See text-layout.md.
   *
   * The ink margin is an ESTIMATE that errs generous: outline width and shadow
   * spread are distance-FIELD fractions, whose pixel size depends on the atlas's
   * distanceRange as well as the font size.
   */
  bounds(x: number, y: number, opts?: TextTransform): TextBounds {
    this.ensure();
    let m = 0;                                   // symmetric ink margin
    let sx = 0, sy = 0;                          // directional shadow offset
    const grow = (s: MsdfStyle | undefined): void => {
      if (!s) return;
      const o = s.outline;
      if (o) m = Math.max(m, ((o.width ?? 0) + (o.softness ?? 0)) * this.fontSize);
      const sh = s.shadow;
      if (sh) {
        m = Math.max(m, ((sh.spread ?? 0) + (sh.softness ?? 0)) * this.fontSize);
        sx = Math.max(sx, Math.abs(sh.x ?? 0));
        sy = Math.max(sy, Math.abs(sh.y ?? 0));
      }
    };
    grow(this.base);
    for (const seg of this._segments ?? []) if (typeof seg !== 'string') grow(seg);
    for (const ov of this._overlays) grow(ov.style);
    const l = m + sx, t = m + sy;
    return transformedBounds(
      this._width + (m + sx) * 2, this._height + (m + sy) * 2,
      x, y, opts, l, t, this._width, this._height,
    );
  }

  // ── Chainable setters ──
  setText(text: string | string[]): this { this._text = Array.isArray(text) ? text.join('\n') : text; this._segments = null; return this.mark(); }
  setFont(font: MsdfFont): this { this.font = font; return this.mark(); }
  setFontSize(size: number): this { this.fontSize = size; return this.mark(); }
  setAlign(a: MsdfAlign): this { this.align = a; return this.mark(); }
  setLineSpacing(v: number): this { this.lineSpacing = v; return this.mark(); }
  setLetterSpacing(v: number): this { this.letterSpacing = v; return this.mark(); }
  setMaxWidth(v: number): this { this.maxWidth = v; return this.mark(); }
  setColor(c: MsdfColor, alpha?: number): this { this.base.color = c; if (alpha != null) this.base.alpha = alpha; return this.mark(); }
  setAlpha(a: number): this { this.base.alpha = a; return this.mark(); }
  setWeight(w: number): this { this.base.weight = w; return this.mark(); }
  setOutline(o: MsdfOutline | null): this { this.base.outline = o ?? undefined; return this.mark(); }
  setShadow(s: MsdfShadow | null): this { this.base.shadow = s ?? undefined; return this.mark(); }
  setSkew(k: number): this { this.base.skew = k; return this.mark(); }
  setUnderline(u: boolean | MsdfRule): this { this.base.underline = u; return this.mark(); }
  setStrikethrough(s: boolean | MsdfRule): this { this.base.strikethrough = s; return this.mark(); }
  setHighlight(h: boolean | MsdfHighlight): this { this.base.highlight = h; return this.mark(); }

  /** Set styled text from segments (their text is concatenated into `text`). */
  setRichText(segments: MsdfSegment[]): this {
    this._segments = segments;
    this._text = segments.map((s) => (typeof s === 'string' ? s : s.text)).join('');
    return this.mark();
  }

  /** Overlay a style onto matching spans: a substring, a RegExp, or `{ start, length }`. */
  addStyle(target: string | RegExp | { start: number; length: number }, style: MsdfStyle): this {
    if (typeof target === 'object' && 'start' in target) {
      this._overlays.push({ start: target.start, length: target.length, style });
    } else if (typeof target === 'string') {
      let i = 0;
      while ((i = this._text.indexOf(target, i)) !== -1) { this._overlays.push({ start: i, length: target.length, style }); i += target.length || 1; }
    } else {
      const re = new RegExp(target.source, target.flags.includes('g') ? target.flags : target.flags + 'g');
      for (const m of this._text.matchAll(re)) { if (m[0].length) this._overlays.push({ start: m.index!, length: m[0].length, style }); }
    }
    return this.mark();
  }

  /** Remove every `addStyle` overlay. */
  clearStyles(): this { this._overlays.length = 0; return this.mark(); }

  private mark(): this { this.dirty = true; return this; }

  /**
   * Shrink `fontSize` (binary search) so the word-wrapped text fits `w`×`h`.
   * Permanently sets `fontSize` and `maxWidth`. Shrink-only unless `maxSize` given.
   */
  fitInside(w: number, h: number, opts: { maxSize?: number; minSize?: number; precision?: number } = {}): this {
    let lo = opts.minSize ?? 1, hi = opts.maxSize ?? this.fontSize;
    const prec = opts.precision ?? 0.25;
    this.maxWidth = w;
    while (hi - lo > prec) {
      const mid = (lo + hi) / 2;
      this.fontSize = mid; this.dirty = true; this.ensure();
      if (this._width <= w && this._height <= h) lo = mid; else hi = mid;
    }
    this.fontSize = lo; this.dirty = true;
    return this;
  }

  // ── Style resolution ──────────────────────────────────────────────────────

  private resolveFace(f: MsdfFont | string | undefined): MsdfFont {
    if (!f) return this.font;
    if (typeof f === 'string') return this.font.face(f) ?? this.font;
    return f;
  }

  /** Merge a layer's style keys onto a resolved char state. */
  private apply(r: Resolved, s: MsdfStyle): void {
    if (s.color != null) {
      if (typeof s.color === 'object') { r.colTop = toRGB(s.color.top); r.colBottom = toRGB(s.color.bottom); }
      else { r.colTop = r.colBottom = toRGB(s.color); }
    }
    if (s.alpha != null) r.alpha = s.alpha;
    if (s.weight != null) r.weight = s.weight;
    if (s.skew != null) r.skew = s.skew;
    if (s.fontScale != null && s.fontScale > 0) r.sizeMul = s.fontScale;
    if (s.font != null) r.face = this.resolveFace(s.font);
    if (s.outline) {
      const o = s.outline;
      if (o.width != null) r.oWidth = o.width;
      if (o.color != null) r.oColor = toRGB(o.color);
      if (o.alpha != null) r.oAlpha = o.alpha;
      if (o.softness != null) r.oSoft = o.softness;
      if (o.rounded != null) r.oRound = roundedNorm(o.rounded);
      if (o.innerColor != null) r.oInner = toRGB(o.innerColor);
      if (o.layered != null) r.oLayered = o.layered;
    }
    if (s.shadow) {
      const sh = s.shadow;
      if (sh.x != null) r.sX = sh.x;
      if (sh.y != null) r.sY = sh.y;
      if (sh.color != null) r.sColor = toRGB(sh.color);
      if (sh.alpha != null) r.sAlpha = sh.alpha;
      if (sh.softness != null) r.sSoft = sh.softness;
      if (sh.spread != null) r.sSpread = sh.spread;
      if (sh.rounded != null) r.sRound = roundedNorm(sh.rounded);
      if (sh.innerColor != null) r.sInner = toRGB(sh.innerColor);
    }
    if (s.underline != null) r.underline = s.underline === false ? null : (s.underline === true ? {} : s.underline);
    if (s.strikethrough != null) r.strike = s.strikethrough === false ? null : (s.strikethrough === true ? {} : s.strikethrough);
    if (s.highlight != null) r.highlight = s.highlight === false ? null : (s.highlight === true ? {} : s.highlight);
  }

  /** Build the per-source-character resolved-style array. */
  private resolveChars(): Resolved[] {
    const n = this._text.length;
    const out: Resolved[] = new Array(n);
    const base = this.base;
    const baseCol = base.color ?? 0xffffff;
    const baseTop = typeof baseCol === 'object' ? toRGB(baseCol.top) : toRGB(baseCol);
    const baseBottom = typeof baseCol === 'object' ? toRGB(baseCol.bottom) : baseTop;

    // Segment run boundaries (from setRichText).
    const runStyle: (MsdfStyle | null)[] = new Array(n).fill(null);
    if (this._segments) {
      let i = 0;
      for (const seg of this._segments) {
        const t = typeof seg === 'string' ? seg : seg.text;
        if (typeof seg !== 'string') for (let k = 0; k < t.length; k++) runStyle[i + k] = seg;
        i += t.length;
      }
    }

    for (let i = 0; i < n; i++) {
      const r: Resolved = {
        face: this.font, sizeMul: 1,
        colTop: baseTop, colBottom: baseBottom, alpha: base.alpha ?? 1,
        weight: base.weight ?? 0,
        oWidth: 0, oColor: 0, oAlpha: 1, oSoft: 0, oRound: 0, oInner: -1, oLayered: false,
        sX: 0, sY: 0, sColor: 0, sAlpha: 0, sSoft: 0, sSpread: 0, sRound: 1, sInner: -1,
        skew: base.skew ?? 0,
        underline: null, strike: null, highlight: null,
      };
      if (base.outline) this.apply(r, { outline: base.outline });
      if (base.shadow) { r.sAlpha = base.shadow.alpha ?? 1; this.apply(r, { shadow: base.shadow }); }
      if (base.underline != null) this.apply(r, { underline: base.underline });
      if (base.strikethrough != null) this.apply(r, { strikethrough: base.strikethrough });
      if (base.highlight != null) this.apply(r, { highlight: base.highlight });
      if (runStyle[i]) { const s = runStyle[i]!; if (s.shadow && s.shadow.alpha == null && !base.shadow) r.sAlpha = 1; this.apply(r, s); }
      out[i] = r;
    }
    // Overlays last (in add order).
    for (const ov of this._overlays) {
      const end = Math.min(n, ov.start + ov.length);
      for (let i = Math.max(0, ov.start); i < end; i++) {
        if (ov.style.shadow && ov.style.shadow.alpha == null && (out[i].sAlpha === 0)) out[i].sAlpha = 1;
        this.apply(out[i], ov.style);
      }
    }
    return out;
  }

  // ── Layout ────────────────────────────────────────────────────────────────

  private ensure(): void { if (this.dirty) this.rebuild(); }

  private charAdvance(r: Resolved, code: number): number {
    const g = r.face.glyph(code);
    return g ? g.advance * this.fontSize * r.sizeMul : 0;
  }

  private rebuild(): void {
    this.dirty = false;
    this.laid = [];
    this.rects = [];
    this.lineTops = [];
    const chars = this.resolveChars();
    const src = this._text;
    const fs = this.fontSize;
    const ls = this.letterSpacing;

    // 1. Word wrap → wrapped code/srcIndex arrays (srcIndex -1 = soft break).
    const wrapped = this.wrap(src, chars);
    const codes = wrapped.codes;
    const srcIdx = wrapped.srcIdx;

    // 2. Walk lines: compute per-line width + metrics, then place glyphs.
    // Split into lines on '\n' (code 10).
    const lineStart: number[] = [0];
    for (let i = 0; i < codes.length; i++) if (codes[i] === 10) lineStart.push(i + 1);

    // First pass: line widths + metrics.
    const lineWidth: number[] = [];
    const lineAscent: number[] = [];
    const lineHeight: number[] = [];
    for (let li = 0; li < lineStart.length; li++) {
      const from = lineStart[li];
      const to = li + 1 < lineStart.length ? lineStart[li + 1] - 1 : codes.length;
      let w = 0, prev = 0, count = 0, ascent = 0, height = 0;
      let prevR: Resolved | null = null;
      for (let i = from; i < to; i++) {
        const si = srcIdx[i];
        const r = si >= 0 ? chars[si] : chars[chars.length - 1] ?? this.baseResolved();
        const code = codes[i];
        const g = r.face.glyph(code);
        const size = fs * r.sizeMul;
        // metrics from every char (largest ascent/lineHeight on the line)
        const a = r.face.data.ascent * size;
        const lh = r.face.data.lineHeight * size;
        if (a > ascent) ascent = a;
        if (lh > height) height = lh;
        if (!g) { prev = 0; continue; }
        if (prev !== 0 && prevR === r) w += (r.face.glyph(prev)?.kerning.get(code) ?? 0) * size;
        w += g.advance * size;
        prev = code; prevR = r; count++;
      }
      if (to <= from) { ascent = this.font.data.ascent * fs; height = this.font.data.lineHeight * fs; }
      if (ls !== 0 && count > 0) w += ls * count;
      lineWidth.push(w); lineAscent.push(ascent); lineHeight.push(height);
    }

    const blockW = Math.max(0, ...lineWidth);

    // Second pass: place glyphs on each line.
    let top = 0;
    for (let li = 0; li < lineStart.length; li++) {
      const from = lineStart[li];
      const to = li + 1 < lineStart.length ? lineStart[li + 1] - 1 : codes.length;
      const baseline = top + lineAscent[li];
      this.lineTops.push(top);
      const inset = this.align === 'center' ? (blockW - lineWidth[li]) / 2 : this.align === 'right' ? blockW - lineWidth[li] : 0;
      let pen = inset, prev = 0;
      let prevR: Resolved | null = null;
      const lineGlyphStart = this.laid.length;
      for (let i = from; i < to; i++) {
        const si = srcIdx[i];
        const r = si >= 0 ? chars[si] : (this.baseResolved());
        const code = codes[i];
        const g = r.face.glyph(code);
        const size = fs * r.sizeMul;
        if (!g) { prev = 0; continue; }
        if (prev !== 0 && prevR === r) pen += (r.face.glyph(prev)?.kerning.get(code) ?? 0) * size;
        this.laid.push({ g, face: r.face, size, penX: pen, baselineY: baseline, st: r });
        pen += g.advance * size + (ls !== 0 ? ls : 0);
        prev = code; prevR = r;
      }
      // Decoration rects for this line (contiguous runs sharing a decoration).
      this.buildLineRects(lineGlyphStart, this.laid.length, top, lineHeight[li], baseline);
      top += lineHeight[li] + this.lineSpacing;
    }

    this._width = blockW;
    this._height = Math.max(0, top - this.lineSpacing);
  }

  private baseResolved(): Resolved {
    // Fallback style for soft-break-inserted positions (no source char).
    return {
      face: this.font, sizeMul: 1, colTop: 0xffffff, colBottom: 0xffffff, alpha: 1, weight: 0,
      oWidth: 0, oColor: 0, oAlpha: 1, oSoft: 0, oRound: 0, oInner: -1, oLayered: false,
      sX: 0, sY: 0, sColor: 0, sAlpha: 0, sSoft: 0, sSpread: 0, sRound: 1, sInner: -1,
      skew: 0, underline: null, strike: null, highlight: null,
    };
  }

  /** Merge contiguous same-decoration glyph spans on one line into rects. */
  private buildLineRects(from: number, to: number, lineTop: number, lineH: number, baseline: number): void {
    const kinds: [keyof Resolved, number][] = [['highlight', 0], ['underline', 1], ['strike', 2]];
    for (const [key, pass] of kinds) {
      let i = from;
      while (i < to) {
        const st = this.laid[i].st;
        const spec = (st as any)[key] as MsdfRule | MsdfHighlight | null;
        if (!spec) { i++; continue; }
        // extend while same spec object
        let j = i + 1;
        while (j < to && (this.laid[j].st as any)[key] === spec) j++;
        this.emitRect(key, spec, this.laid[i], this.laid[j - 1], lineTop, lineH, baseline, pass);
        i = j;
      }
    }
  }

  private emitRect(
    key: keyof Resolved, spec: MsdfRule | MsdfHighlight,
    first: LaidGlyph, last: LaidGlyph, lineTop: number, lineH: number, baseline: number, pass: number,
  ): void {
    const st = first.st;
    const x0 = first.penX;
    const x1 = last.penX + last.g.advance * last.size;
    const size = first.size;
    if (key === 'highlight') {
      const h = spec as MsdfHighlight;
      const pad = (h.padding ?? 0) * size;
      this.rects.push({
        x: x0 - pad, y: lineTop - pad, w: (x1 - x0) + pad * 2, h: lineH + pad * 2,
        face: first.face,
        color: toRGB(h.color ?? 0xffe14d), alpha: h.alpha ?? 1,
        radius: h.radius ?? 0, border: h.borderWidth ?? 0, soft: h.softness ?? 0,
        borderColor: toRGB(h.borderColor ?? 0x000000), borderAlpha: 1,
        dashCount: 0, dashDuty: 0, pass,
      });
      return;
    }
    const rule = spec as MsdfRule;
    const face = first.face.data;
    const thick = face.underlineThickness * size * (rule.thickness ?? 1);
    const y = key === 'strike'
      ? baseline - 0.25 * size + (rule.offset ?? 0) * size - thick / 2
      : baseline + face.underlineOffset * size + (rule.offset ?? 0) * size - thick / 2;
    let dashCount = 0, dashDuty = 0, radius = 0, soft = 0;
    if (rule.dash) {
      const d = rule.dash === true ? {} : rule.dash;
      const len = (d.length ?? 0.14) * size;
      const gap = (d.gap ?? 0.09) * size;
      const period = len + gap;
      const w = x1 - x0;
      dashCount = Math.max(1, Math.round(w / period));
      dashDuty = Math.min(0.98, Math.max(0.02, len / period));
      radius = d.radius ?? 0;
      soft = d.softness ?? 0;
    }
    this.rects.push({
      x: x0, y, w: x1 - x0, h: thick, face: first.face,
      color: toRGB(rule.color ?? st.colTop), alpha: rule.alpha ?? st.alpha,
      radius, border: 0, soft, borderColor: 0, borderAlpha: 0, dashCount, dashDuty, pass,
    });
  }

  // ── Word wrap (port of MSDFTextWrap.wrapLines, single-run-aware) ────────────

  private wrap(src: string, chars: Resolved[]): { codes: number[]; srcIdx: number[] } {
    const codes: number[] = [];
    const srcIdx: number[] = [];
    const max = this.maxWidth;
    const fs = this.fontSize, ls = this.letterSpacing;
    if (max <= 0) {
      for (let i = 0; i < src.length; i++) { codes.push(src.charCodeAt(i)); srcIdx.push(i); }
      return { codes, srcIdx };
    }
    let lineC: number[] = [], lineS: number[] = [], wordC: number[] = [], wordS: number[] = [];
    const measure = (extraCode: number, extraSrc: number): number => {
      let w = 0, prev = 0, count = 0; let prevR: Resolved | null = null;
      const add = (code: number, s: number): void => {
        const r = chars[s]; const g = r.face.glyph(code); if (!g) { prev = 0; return; }
        const size = fs * r.sizeMul;
        if (prev !== 0 && prevR === r) w += (r.face.glyph(prev)?.kerning.get(code) ?? 0) * size;
        w += g.advance * size; prev = code; prevR = r; count++;
      };
      for (let k = 0; k < lineC.length; k++) add(lineC[k], lineS[k]);
      for (let k = 0; k < wordC.length; k++) add(wordC[k], wordS[k]);
      if (extraCode >= 0) add(extraCode, extraSrc);
      if (ls !== 0 && count > 0) w += ls * count;
      return w;
    };
    const commit = (breakSrc: number | null): void => {
      let end = lineC.length;
      if (breakSrc === -1) while (end > 0 && lineC[end - 1] === 32) end--;
      for (let k = 0; k < end; k++) { codes.push(lineC[k]); srcIdx.push(lineS[k]); }
      if (breakSrc !== null) { codes.push(10); srcIdx.push(breakSrc); }
      lineC = []; lineS = [];
    };
    const finishWord = (): void => {
      if (!wordC.length) return;
      if (measure(-1, 0) > max && lineC.length > 0) { commit(-1); lineC = wordC; lineS = wordS; }
      else { for (let k = 0; k < wordC.length; k++) { lineC.push(wordC[k]); lineS.push(wordS[k]); } }
      wordC = []; wordS = [];
    };
    for (let i = 0; i < src.length; i++) {
      const code = src.charCodeAt(i);
      if (code === 10) { finishWord(); commit(i); continue; }
      if (code === 32) {
        if (measure(code, i) > max && lineC.length > 0) { commit(-1); lineC = wordC; lineS = wordS; lineC.push(code); lineS.push(i); }
        else { for (let k = 0; k < wordC.length; k++) { lineC.push(wordC[k]); lineS.push(wordS[k]); } lineC.push(code); lineS.push(i); }
        wordC = []; wordS = [];
      } else { wordC.push(code); wordS.push(i); }
    }
    finishWord(); commit(null);
    return { codes, srcIdx };
  }

  // ── Submit (called by d.msdfText) ───────────────────────────────────────────

  /**
   * @internal Push this text's quads into `r` at (x, y). The DRAW SURFACE
   * passes its own renderer, so one block can be drawn in world space and on
   * the HUD.
   */
  submit(r: MsdfRenderer, x: number, y: number, opts: MsdfDrawOptions = {}): void {
    this.ensure();
    const scale = opts.scale ?? 1;
    const rot = opts.rotation ?? 0;
    const objA = opts.alpha ?? 1;
    const ox = (opts.origin?.x ?? 0) * this._width;
    const oy = (opts.origin?.y ?? 0) * this._height;
    const depth = opts.z ?? 0;
    const cos = Math.cos(rot), sin = Math.sin(rot);

    // Text-space point → world (origin, scale, rotation, translate).
    const wx = (lx: number, ly: number): number => { const sx = (lx - ox) * scale, sy = (ly - oy) * scale; return x + (sx * cos - sy * sin); };
    const wy = (lx: number, ly: number): number => { const sx = (lx - ox) * scale, sy = (ly - oy) * scale; return y + (sx * sin + sy * cos); };

    // ── highlight rects (behind everything) ──
    for (const rc of this.rects) if (rc.pass === 0) this.pushRect(r, rc, wx, wy, objA, depth);

    // ── shadow pass ──
    for (const lg of this.laid) {
      const st = lg.st;
      if (st.sAlpha <= 0 && st.sColor === 0 && st.sX === 0 && st.sY === 0) continue;
      if (st.sAlpha <= 0) continue;
      const mt = lg.face.isMtsdf;
      const inv = lg.face.invRange;
      const par = packParams(st.weight * inv, mt ? st.sRound : 0, st.sSpread * inv, mt ? st.sSoft : 0);
      const inner = packColor(st.sInner >= 0 ? st.sInner : st.sColor, 0);
      const outl = packColor(st.sColor, st.sAlpha * objA);
      this.pushGlyph(r, lg, st.sX, st.sY, wx, wy, inner, inner, outl, par, depth);
    }

    // ── layered outline silhouette pass ──
    for (const lg of this.laid) {
      const st = lg.st;
      const layered = (st.oLayered || st.oInner >= 0) && (st.oWidth > 0 || st.oSoft > 0);
      if (!layered) continue;
      const mt = lg.face.isMtsdf;
      const inv = lg.face.invRange;
      const par = packParams(st.weight * inv, mt ? st.oRound : 0, st.oWidth * inv, mt ? st.oSoft : 0);
      const inner = packColor(st.oInner >= 0 ? st.oInner : st.oColor, 0);
      const outl = packColor(st.oColor, st.oAlpha * objA);
      this.pushGlyph(r, lg, 0, 0, wx, wy, inner, inner, outl, par, depth);
    }

    // ── underline rects ──
    for (const rc of this.rects) if (rc.pass === 1) this.pushRect(r, rc, wx, wy, objA, depth);

    // ── fill pass ──
    for (const lg of this.laid) {
      const st = lg.st;
      const mt = lg.face.isMtsdf;
      const inv = lg.face.invRange;
      const layered = (st.oLayered || st.oInner >= 0) && (st.oWidth > 0 || st.oSoft > 0);
      const hasOutline = !layered && (st.oWidth > 0 || st.oSoft > 0);
      const par = packParams(st.weight * inv, mt ? st.oRound : 0, hasOutline ? st.oWidth * inv : 0, mt && hasOutline ? st.oSoft : 0);
      const colTop = packColor(st.alpha * objA > 0 ? st.colTop : st.oColor, st.alpha * objA);
      const colBottom = packColor(st.alpha * objA > 0 ? st.colBottom : st.oColor, st.alpha * objA);
      const outl = hasOutline ? packColor(st.oColor, st.oAlpha * objA) : 0;
      this.pushGlyph(r, lg, 0, 0, wx, wy, colTop, colBottom, outl, par, depth);
    }

    // ── strikethrough rects ──
    for (const rc of this.rects) if (rc.pass === 2) this.pushRect(r, rc, wx, wy, objA, depth);
  }

  private pushGlyph(
    r: MsdfRenderer, lg: LaidGlyph, offX: number, offY: number,
    wx: (a: number, b: number) => number, wy: (a: number, b: number) => number,
    colTop: number, colBottom: number, outl: number, par: number, depth: number,
  ): void {
    const g = lg.g;
    if (g.w === 0 || g.h === 0) return;
    const size = lg.size;
    const qx = lg.penX + g.xOffset * size + offX;
    const qy = lg.baselineY + g.yOffset * size + offY;
    const qw = g.w * size, qh = g.h * size;
    const k = lg.st.skew;
    // skew shears x by -k*(y - baseline)
    const shear = (ly: number): number => -k * (ly - lg.baselineY);
    const tlx = qx + shear(qy), trx = qx + qw + shear(qy);
    const blx = qx + shear(qy + qh), brx = qx + qw + shear(qy + qh);
    const view = lg.face.view;
    const [ux, uy] = lg.face.unitRange;
    const o = r.alloc(view);
    const f = r.f32, u = r.u32;
    // corners TL, TR, BL, BR
    f[o] = wx(tlx, qy); f[o + 1] = wy(tlx, qy);
    f[o + 2] = wx(trx, qy); f[o + 3] = wy(trx, qy);
    f[o + 4] = wx(blx, qy + qh); f[o + 5] = wy(blx, qy + qh);
    f[o + 6] = wx(brx, qy + qh); f[o + 7] = wy(brx, qy + qh);
    f[o + 8] = g.uMin; f[o + 9] = g.vTop; f[o + 10] = g.uMax; f[o + 11] = g.vBottom;
    u[o + 12] = colTop; u[o + 13] = colTop; u[o + 14] = colBottom; u[o + 15] = colBottom;
    u[o + 16] = outl; u[o + 17] = outl; u[o + 18] = outl; u[o + 19] = outl;
    u[o + 20] = par; u[o + 21] = par; u[o + 22] = par; u[o + 23] = par;
    f[o + 24] = ux; f[o + 25] = uy; f[o + 26] = depth; f[o + 27] = 0;
  }

  private pushRect(
    r: MsdfRenderer, rc: Rect,
    wx: (a: number, b: number) => number, wy: (a: number, b: number) => number, objA: number, depth: number,
  ): void {
    if (rc.w <= 0 || rc.h <= 0) return;
    const x0 = rc.x, y0 = rc.y, x1 = rc.x + rc.w, y1 = rc.y + rc.h;
    const view = rc.face.view;
    const [ux, uy] = rc.face.unitRange;
    const col = packColor(rc.color, rc.alpha * objA);
    const border = rc.border > 0 ? packColor(rc.borderColor, rc.borderAlpha * objA) : 0;
    const par = rc.dashCount > 0 ? packDashParams(rc.radius, rc.dashDuty, rc.soft)
      : (rc.radius > 0 || rc.border > 0 || rc.soft > 0) ? packSolidParams(rc.radius, rc.border, rc.soft) : SOLID_PARAMS;
    const uMax = rc.dashCount > 0 ? rc.dashCount : 1;
    const o = r.alloc(view);
    const f = r.f32, u = r.u32;
    f[o] = wx(x0, y0); f[o + 1] = wy(x0, y0);
    f[o + 2] = wx(x1, y0); f[o + 3] = wy(x1, y0);
    f[o + 4] = wx(x0, y1); f[o + 5] = wy(x0, y1);
    f[o + 6] = wx(x1, y1); f[o + 7] = wy(x1, y1);
    f[o + 8] = 0; f[o + 9] = 0; f[o + 10] = uMax; f[o + 11] = 1;
    u[o + 12] = col; u[o + 13] = col; u[o + 14] = col; u[o + 15] = col;
    u[o + 16] = border; u[o + 17] = border; u[o + 18] = border; u[o + 19] = border;
    u[o + 20] = par; u[o + 21] = par; u[o + 22] = par; u[o + 23] = par;
    f[o + 24] = ux; f[o + 25] = uy; f[o + 26] = depth; f[o + 27] = 0;
  }
}
