/**
 * Roguelike DUNGEON generator — rooms joined by corridors, with doors and
 * tagged rooms. Pure CPU math, zero engine dependency; import it directly
 * (`import { Dungeon } from '../engine/webgpu.js'`). NOT wired into `Game`.
 *
 * The sibling to `Maze`: where a maze is wall-per-edge corridors, a dungeon is
 * open ROOMS connected by tunnels — the Rogue/Nethack/Zelda layout. It works
 * straight in tile space (one cell = one floor tile you walk on), so the output
 * is a thick 0/1 grid ready for a `Tilemap` / `CollisionGrid` / wall-box build,
 * or to seed a `FlowGrid`'s obstacles. Rooms are placed, connected into one
 * network (plus optional extra loops), doorways are detected, and rooms are
 * TAGGED (start / boss / treasure / junction) so a game can place the player,
 * the objective, and loot without post-analysis.
 */

import { makeRng, hashCode } from './util.js';
import type { Cell } from './util.js';

const WALL = 1;
const FLOOR = 0;
const DOOR = 2;

/** How a room reads in the layout — for placing the player, objective and loot. */
export type RoomTag = 'start' | 'boss' | 'treasure' | 'junction' | 'normal';

/** One generated room (a rectangle of floor), in tile coordinates. */
export interface DungeonRoom {
  /** Stable room index. */
  id: number;
  /** Left column (inclusive). */
  col: number;
  /** Top row (inclusive). */
  row: number;
  /** Width in tiles. */
  w: number;
  /** Height in tiles. */
  h: number;
  /** Centre column (floored). */
  cx: number;
  /** Centre row (floored). */
  cy: number;
  /** Role in the layout (see {@link RoomTag}). */
  tag: RoomTag;
}

/** Configuration for a new {@link Dungeon}. `cols`/`rows` are required. */
export interface DungeonOptions {
  /** Grid width in tiles. */
  cols: number;
  /** Grid height in tiles. */
  rows: number;
  /** Seed for reproducible dungeons (string is hashed). Omit for random. */
  seed?: number | string;
  /** How many times to try placing a room. Default scales with area. */
  roomAttempts?: number;
  /** Minimum room side in tiles. Default `4`. */
  minRoom?: number;
  /** Maximum room side in tiles. Default `9`. */
  maxRoom?: number;
  /** Minimum wall gap kept between rooms. Default `1`. */
  roomMargin?: number;
  /** Extra corridors beyond the connecting tree, for loops. Default `2`. */
  extraConnections?: number;
  /** Corridor width in tiles. Default `1` (doors are only detected at width 1). */
  corridorWidth?: number;
}

/** Options for {@link Dungeon.tiles} — the 0/1(/door) grid. */
export interface DungeonTileOptions {
  /** Value for wall tiles. Default `1`. */
  wall?: number;
  /** Value for floor tiles. Default `0`. */
  floor?: number;
  /** Value for door tiles. Default = `floor` (doors read as walkable floor). */
  door?: number;
}

/**
 * A generated dungeon: the tile grid plus room/door metadata and the queries a
 * game needs. Construct once (generation runs in the constructor); read from it
 * every frame.
 *
 * ```ts
 * const dungeon = new Dungeon({ cols: 60, rows: 40, seed: 'level-1', extraConnections: 3 });
 * const grid = dungeon.tiles();                        // 0 floor / 1 wall → CollisionGrid
 * const start = dungeon.roomsByTag('start')[0];        // where to drop the player
 * const boss = dungeon.roomsByTag('boss')[0];          // the objective room
 * ```
 */
export class Dungeon {
  /** Grid width in tiles. */
  readonly cols: number;
  /** Grid height in tiles. */
  readonly rows: number;
  /** The numeric seed actually used. */
  readonly seed: number;
  /** Per-tile data, row-major: `1` wall, `0` floor, `2` door. Prefer
   *  {@link isWall} / {@link tiles}, but exposed for custom exporters. */
  readonly grid: Uint8Array;
  /** Every placed room. */
  readonly rooms: DungeonRoom[] = [];
  /** Detected doorway tiles (1-wide thresholds into rooms). */
  readonly doors: Cell[] = [];
  /** Room-graph edges as `[roomId, roomId]` pairs (which rooms are joined). */
  readonly connections: Array<[number, number]> = [];

  constructor(opts: DungeonOptions) {
    this.cols = Math.max(5, Math.floor(opts.cols));
    this.rows = Math.max(5, Math.floor(opts.rows));
    this.seed = typeof opts.seed === 'string' ? hashCode(opts.seed) : (opts.seed ?? ((Math.random() * 0xffffffff) >>> 0));
    const rng = makeRng(this.seed);
    this.grid = new Uint8Array(this.cols * this.rows).fill(WALL);

    const minR = Math.max(3, opts.minRoom ?? 4);
    const maxR = Math.max(minR, opts.maxRoom ?? 9);
    const margin = Math.max(0, opts.roomMargin ?? 1);
    const attempts = opts.roomAttempts ?? Math.floor((this.cols * this.rows) / 45) + 4;
    const width = Math.max(1, Math.floor(opts.corridorWidth ?? 1));

    this._placeRooms(rng, attempts, minR, maxR, margin);
    this._connectRooms(rng, opts.extraConnections ?? 2, width);
    if (width === 1) this._detectDoors();
    this._tagRooms();
  }

  // ── Grid basics ────────────────────────────────────────────────────────────

  /** Row-major tile index for `(col, row)`. No bounds check. */
  index(col: number, row: number): number {
    return row * this.cols + col;
  }

  /** Is `(col, row)` inside the grid? */
  inBounds(col: number, row: number): boolean {
    return col >= 0 && col < this.cols && row >= 0 && row < this.rows;
  }

  /** Is the tile solid wall? Out-of-bounds reads as wall. */
  isWall(col: number, row: number): boolean {
    return !this.inBounds(col, row) || this.grid[this.index(col, row)] === WALL;
  }

  /** Is the tile walkable (floor or door)? */
  isFloor(col: number, row: number): boolean {
    return this.inBounds(col, row) && this.grid[this.index(col, row)] !== WALL;
  }

  /** Which cell contains world/pixel position `(x, y)` at `cellSize` units per
   *  tile from `(originX, originY)`. `null` when outside the grid. */
  cellAt(x: number, y: number, cellSize = 1, originX = 0, originY = 0): Cell | null {
    const col = Math.floor((x - originX) / cellSize);
    const row = Math.floor((y - originY) / cellSize);
    return this.inBounds(col, row) ? { col, row } : null;
  }

  // ── Queries ────────────────────────────────────────────────────────────────

  /** The room whose rectangle contains `(col, row)`, or `null` (a corridor / wall). */
  roomAt(col: number, row: number): DungeonRoom | null {
    for (const r of this.rooms) {
      if (col >= r.col && col < r.col + r.w && row >= r.row && row < r.row + r.h) return r;
    }
    return null;
  }

  /** All rooms carrying a given {@link RoomTag}. */
  roomsByTag(tag: RoomTag): DungeonRoom[] {
    return this.rooms.filter((r) => r.tag === tag);
  }

  /** Every walkable (floor or door) cell — for scattering pickups / spawns. */
  floors(): Cell[] {
    const out: Cell[] = [];
    for (let r = 0; r < this.rows; r++) {
      for (let c = 0; c < this.cols; c++) if (this.grid[this.index(c, r)] !== WALL) out.push({ col: c, row: r });
    }
    return out;
  }

  /** Shortest walkable path from `from` to `to` (4-dir BFS through floor +
   *  doors), inclusive; `[]` if unreachable. */
  path(from: Cell, to: Cell): Cell[] {
    if (!this.isFloor(from.col, from.row) || !this.isFloor(to.col, to.row)) return [];
    const n = this.cols * this.rows;
    const prev = new Int32Array(n).fill(-2);
    const start = this.index(from.col, from.row);
    prev[start] = -1;
    let frontier = [start];
    const goal = this.index(to.col, to.row);
    const DX = [0, 1, 0, -1], DY = [-1, 0, 1, 0];
    while (frontier.length) {
      const next: number[] = [];
      for (const i of frontier) {
        if (i === goal) { frontier = []; break; }
        const c = i % this.cols, r = (i / this.cols) | 0;
        for (let d = 0; d < 4; d++) {
          const nc = c + DX[d], nr = r + DY[d];
          if (!this.inBounds(nc, nr) || this.grid[this.index(nc, nr)] === WALL) continue;
          const j = this.index(nc, nr);
          if (prev[j] === -2) { prev[j] = i; next.push(j); }
        }
      }
      if (frontier.length) frontier = next;
    }
    if (prev[goal] === -2) return [];
    const out: Cell[] = [];
    for (let i = goal; i !== -1; i = prev[i]) out.push({ col: i % this.cols, row: (i / this.cols) | 0 });
    return out.reverse();
  }

  // ── Exporters ──────────────────────────────────────────────────────────────

  /** The dungeon as a THICK 0/1 tile grid (`grid[y][x]`), ready for a `Tilemap`
   *  / `CollisionGrid` / wall-box build. Doors default to the floor value. */
  tiles(opts: DungeonTileOptions = {}): number[][] {
    const wall = opts.wall ?? 1;
    const floor = opts.floor ?? 0;
    const door = opts.door ?? floor;
    const out: number[][] = [];
    for (let r = 0; r < this.rows; r++) {
      const row = new Array<number>(this.cols);
      for (let c = 0; c < this.cols; c++) {
        const t = this.grid[this.index(c, r)];
        row[c] = t === WALL ? wall : t === DOOR ? door : floor;
      }
      out.push(row);
    }
    return out;
  }

  /** ASCII rendering (`#` wall, `+` door, `.` floor) — tests + console. */
  toString(): string {
    let s = '';
    for (let r = 0; r < this.rows; r++) {
      for (let c = 0; c < this.cols; c++) {
        const t = this.grid[this.index(c, r)];
        s += t === WALL ? '#' : t === DOOR ? '+' : '.';
      }
      s += '\n';
    }
    return s;
  }

  // ── Generation internals ───────────────────────────────────────────────────

  private _setFloor(col: number, row: number): void {
    if (this.inBounds(col, row) && this.grid[this.index(col, row)] === WALL) this.grid[this.index(col, row)] = FLOOR;
  }

  private _placeRooms(rng: () => number, attempts: number, minR: number, maxR: number, margin: number): void {
    const fits = (col: number, row: number, w: number, h: number): boolean => {
      for (const r of this.rooms) {
        if (col - margin < r.col + r.w && col + w + margin > r.col &&
            row - margin < r.row + r.h && row + h + margin > r.row) return false;
      }
      return true;
    };
    for (let i = 0; i < attempts; i++) {
      const w = minR + ((rng() * (maxR - minR + 1)) | 0);
      const h = minR + ((rng() * (maxR - minR + 1)) | 0);
      if (w >= this.cols - 2 || h >= this.rows - 2) continue;
      const col = 1 + ((rng() * (this.cols - w - 2)) | 0);
      const row = 1 + ((rng() * (this.rows - h - 2)) | 0);
      if (!fits(col, row, w, h)) continue;
      const room: DungeonRoom = { id: this.rooms.length, col, row, w, h, cx: col + (w >> 1), cy: row + (h >> 1), tag: 'normal' };
      for (let r = row; r < row + h; r++) for (let c = col; c < col + w; c++) this.grid[this.index(c, r)] = FLOOR;
      this.rooms.push(room);
    }
    // Guarantee at least one room so the dungeon is never solid.
    if (this.rooms.length === 0) {
      const w = Math.min(maxR, this.cols - 2), h = Math.min(maxR, this.rows - 2);
      const col = ((this.cols - w) / 2) | 0, row = ((this.rows - h) / 2) | 0;
      for (let r = row; r < row + h; r++) for (let c = col; c < col + w; c++) this.grid[this.index(c, r)] = FLOOR;
      this.rooms.push({ id: 0, col, row, w, h, cx: col + (w >> 1), cy: row + (h >> 1), tag: 'normal' });
    }
  }

  private _carveH(x0: number, x1: number, y: number, width: number): void {
    const lo = Math.min(x0, x1), hi = Math.max(x0, x1);
    for (let x = lo; x <= hi; x++) for (let w = 0; w < width; w++) this._setFloor(x, y + w);
  }

  private _carveV(y0: number, y1: number, x: number, width: number): void {
    const lo = Math.min(y0, y1), hi = Math.max(y0, y1);
    for (let y = lo; y <= hi; y++) for (let w = 0; w < width; w++) this._setFloor(x + w, y);
  }

  private _corridor(a: DungeonRoom, b: DungeonRoom, rng: () => number, width: number): void {
    if (rng() < 0.5) { this._carveH(a.cx, b.cx, a.cy, width); this._carveV(a.cy, b.cy, b.cx, width); }
    else { this._carveV(a.cy, b.cy, a.cx, width); this._carveH(a.cx, b.cx, b.cy, width); }
  }

  private _connectRooms(rng: () => number, extra: number, width: number): void {
    // Connecting tree: each room joins its nearest already-placed room.
    for (let i = 1; i < this.rooms.length; i++) {
      let best = 0, bd = Infinity;
      for (let j = 0; j < i; j++) {
        const dx = this.rooms[i].cx - this.rooms[j].cx, dy = this.rooms[i].cy - this.rooms[j].cy;
        const d = dx * dx + dy * dy;
        if (d < bd) { bd = d; best = j; }
      }
      this._corridor(this.rooms[i], this.rooms[best], rng, width);
      this.connections.push([i, best]);
    }
    // Extra loops between random room pairs (multiple routes).
    for (let k = 0; k < extra && this.rooms.length > 2; k++) {
      const a = (rng() * this.rooms.length) | 0;
      let b = (rng() * this.rooms.length) | 0;
      if (a === b) b = (b + 1) % this.rooms.length;
      this._corridor(this.rooms[a], this.rooms[b], rng, width);
      this.connections.push([a, b]);
    }
  }

  /** Mark 1-wide corridor tiles that thread into a room as doors. */
  private _detectDoors(): void {
    for (let r = 1; r < this.rows - 1; r++) {
      for (let c = 1; c < this.cols - 1; c++) {
        const i = this.index(c, r);
        if (this.grid[i] !== FLOOR || this.roomAt(c, r)) continue;   // door sits in the corridor, outside the room
        const wallV = this.grid[this.index(c, r - 1)] === WALL && this.grid[this.index(c, r + 1)] === WALL;
        const wallH = this.grid[this.index(c - 1, r)] === WALL && this.grid[this.index(c + 1, r)] === WALL;
        // Horizontal pinch touching a room on one side → doorway.
        if (wallV && (this.roomAt(c - 1, r) || this.roomAt(c + 1, r))) { this.grid[i] = DOOR; this.doors.push({ col: c, row: r }); }
        else if (wallH && (this.roomAt(c, r - 1) || this.roomAt(c, r + 1))) { this.grid[i] = DOOR; this.doors.push({ col: c, row: r }); }
      }
    }
  }

  private _tagRooms(): void {
    if (this.rooms.length === 1) { this.rooms[0].tag = 'start'; return; }
    // Adjacency + degree from the corridor graph.
    const adj = new Map<number, number[]>();
    const deg = new Int32Array(this.rooms.length);
    for (const r of this.rooms) adj.set(r.id, []);
    for (const [a, b] of this.connections) {
      if (a === b) continue;
      adj.get(a)!.push(b); adj.get(b)!.push(a);
      deg[a]++; deg[b]++;
    }
    // Start = the most top-left room; boss = the graph-farthest room from it.
    let start = 0;
    for (let i = 1; i < this.rooms.length; i++) {
      if (this.rooms[i].cx + this.rooms[i].cy < this.rooms[start].cx + this.rooms[start].cy) start = i;
    }
    const dist = new Int32Array(this.rooms.length).fill(-1);
    dist[start] = 0;
    let frontier = [start], boss = start;
    while (frontier.length) {
      const next: number[] = [];
      for (const i of frontier) {
        if (dist[i] > dist[boss]) boss = i;
        for (const j of adj.get(i)!) if (dist[j] === -1) { dist[j] = dist[i] + 1; next.push(j); }
      }
      frontier = next;
    }
    for (const r of this.rooms) {
      if (r.id === start) r.tag = 'start';
      else if (r.id === boss) r.tag = 'boss';
      else if (deg[r.id] >= 3) r.tag = 'junction';
      else if (deg[r.id] <= 1) r.tag = 'treasure';
      else r.tag = 'normal';
    }
  }
}
