// Built-in fallback scenes (ported from raster's default-scenes): used when a
// game's roster doesn't register its own 'title' / 'gameOver'. A bare
// { play } roster is still a complete game — title in, game over out.

import { Scene } from './scene.js';
import type { Draw } from './draw.js';
import type { BitmapFont } from './font.js';

/** Fallback title: "PRESS SPACE TO START" → 'play'. Register your own `title` to replace. */
export class DefaultTitle extends Scene {
  private font!: BitmapFont;

  override setup(): void {
    this.font = this.game.assets.font({ font: 'bold 26px monospace' });
  }

  override update(dt: number): void {
    super.update(dt);
    if (this.game.input.keyPressed('Space', 'Enter')) this.gotoPlay();
  }

  override drawHud(d: Draw): void {
    d.text(this.font, 'PRESS SPACE TO START', this.game.view.w / 2, this.game.view.h / 2 - 13, {
      align: 'center', color: '#e6e9f5',
    });
  }
}

/** Fallback game-over: "YOU WIN!" / "GAME OVER" (from `{ win }` in the payload) → 'title'. */
export class DefaultGameOver extends Scene {
  private font!: BitmapFont;
  private won = false;

  override setup(data?: unknown): void {
    this.won = !!(data as { win?: boolean } | undefined)?.win;
    this.font = this.game.assets.font({ font: 'bold 26px monospace' });
  }

  override update(dt: number): void {
    super.update(dt);
    if (this.game.input.keyPressed('Space', 'Enter')) this.gotoTitle();
  }

  override drawHud(d: Draw): void {
    const cx = this.game.view.w / 2, cy = this.game.view.h / 2;
    d.text(this.font, this.won ? 'YOU WIN!' : 'GAME OVER', cx, cy - 30, { align: 'center', color: '#e6e9f5' });
    d.text(this.font, 'PRESS SPACE', cx, cy + 8, { align: 'center', scale: 0.6, color: '#8a93b5' });
  }
}
