// MSDF fonts: crisp, scalable text from a multi-channel signed-distance-field
// atlas (msdf-atlas-gen format — a .json layout + a .png atlas). Unlike the
// baked bitmap font (font.ts), an MSDF glyph stays razor-sharp at ANY scale and
// carries a distance field the shader reads for faux-bold weight, outlines,
// glows and soft shadows — see msdf.ts for the renderer.
//
// This module is the DATA layer: it parses the atlas JSON into a flat runtime
// glyph table (kerning, metrics, UVs) and uploads the PNG to a GPU texture.
// Module load is DOM-free; every texture/DOM touch is inside a function.
//
// The JSON schema is msdf-atlas-gen's own (NOT AngelCode/BMFont): an `atlas`
// block (type, distanceRange, size, yOrigin), top-level `metrics`/`glyphs`/
// `kerning`, OR a `variants` array (one entry per `-and`-merged font sharing one
// texture). Generate a pair with msdf-atlas-gen or snowb.org — see msdf.md.

// ── msdf-atlas-gen JSON shapes ──────────────────────────────────────────────

interface AtlasJSON {
  type: 'msdf' | 'mtsdf' | 'sdf';
  distanceRange: number;
  size: number;
  width: number;
  height: number;
  yOrigin: 'top' | 'bottom';
}
interface MetricsJSON {
  emSize: number;
  lineHeight: number;
  ascender: number;
  descender: number;
  underlineY: number;
  underlineThickness: number;
}
interface BoundsJSON { left: number; top: number; right: number; bottom: number }
interface GlyphJSON {
  unicode: number;
  advance: number;
  planeBounds?: BoundsJSON;
  atlasBounds?: BoundsJSON;
}
interface KerningJSON { unicode1: number; unicode2: number; advance: number }
interface VariantJSON {
  name?: string;
  metrics: MetricsJSON;
  glyphs: GlyphJSON[];
  kerning?: KerningJSON[];
}
/** Root msdf-atlas-gen JSON (single font, or a merged `variants` atlas). */
export interface MsdfFontJSON {
  atlas: AtlasJSON;
  metrics?: MetricsJSON;
  glyphs?: GlyphJSON[];
  kerning?: KerningJSON[];
  variants?: VariantJSON[];
}

// ── Runtime glyph/metrics data (flat, em-normalized, y-down) ─────────────────

/**
 * One glyph, laid out in the **y-down, em-normalized** convention (multiply by
 * font size for pixels). `xOffset`/`yOffset` position the quad's top-left from
 * the pen (yOffset negative = above the baseline); `w`/`h` are the quad size;
 * UVs are in image space (v grows downward, `vTop < vBottom`).
 */
export interface MsdfGlyph {
  code: number;
  advance: number;     // pen advance after this glyph (em)
  xOffset: number;     // quad left from pen (em)
  yOffset: number;     // quad top from baseline (em, negative above)
  w: number;           // quad width (em)
  h: number;           // quad height (em)
  uMin: number; uMax: number; vTop: number; vBottom: number;
  kerning: Map<number, number>; // next-code -> extra advance (em)
}

/** Parsed, renderer-ready data for one font face (one texture, one field). */
export interface MsdfFontData {
  name: string;
  fieldType: 'msdf' | 'mtsdf' | 'sdf';
  distanceRange: number;
  atlasWidth: number;
  atlasHeight: number;
  /** Em metrics, y-down: ascent/descent positive, underline offset positive-down. */
  ascent: number;
  descent: number;
  lineHeight: number;
  underlineOffset: number;
  underlineThickness: number;
  glyphs: Map<number, MsdfGlyph>;
}

function parseVariant(atlas: AtlasJSON, v: VariantJSON, name: string): MsdfFontData {
  const yUp = atlas.yOrigin === 'bottom';
  const W = atlas.width, Hh = atlas.height;
  const glyphs = new Map<number, MsdfGlyph>();

  for (const g of v.glyphs) {
    const pb = g.planeBounds, ab = g.atlasBounds;
    if (!pb || !ab) {
      // Whitespace: advance only, no quad.
      glyphs.set(g.unicode, {
        code: g.unicode, advance: g.advance, xOffset: 0, yOffset: 0, w: 0, h: 0,
        uMin: 0, uMax: 0, vTop: 0, vBottom: 0, kerning: new Map(),
      });
      continue;
    }
    // Plane bounds → quad size + top-left, normalized to y-down.
    const w = pb.right - pb.left;
    const h = yUp ? pb.top - pb.bottom : pb.bottom - pb.top;
    const yOffset = yUp ? -pb.top : pb.top;
    // Atlas pixel bounds → image-space UVs (v=0 at the top image row).
    const uMin = Math.min(ab.left, ab.right) / W;
    const uMax = Math.max(ab.left, ab.right) / W;
    let vTop: number, vBottom: number;
    if (yUp) {
      // yOrigin bottom: atlas Y grows up; image row = H - atlasY. top edge has
      // the larger atlas Y, so it maps to the smaller image row (nearer v=0).
      vTop = (Hh - Math.max(ab.top, ab.bottom)) / Hh;
      vBottom = (Hh - Math.min(ab.top, ab.bottom)) / Hh;
    } else {
      vTop = Math.min(ab.top, ab.bottom) / Hh;
      vBottom = Math.max(ab.top, ab.bottom) / Hh;
    }
    glyphs.set(g.unicode, {
      code: g.unicode, advance: g.advance, xOffset: pb.left, yOffset, w, h,
      uMin, uMax, vTop, vBottom, kerning: new Map(),
    });
  }

  for (const k of v.kerning ?? []) {
    glyphs.get(k.unicode1)?.kerning.set(k.unicode2, k.advance);
  }

  const m = v.metrics;
  return {
    name,
    fieldType: atlas.type,
    distanceRange: atlas.distanceRange,
    atlasWidth: W,
    atlasHeight: Hh,
    ascent: Math.abs(m.ascender),
    descent: Math.abs(m.descender),
    lineHeight: m.lineHeight,
    // underlineY is signed baseline-relative; store as a positive-down offset.
    underlineOffset: yUp ? -m.underlineY : m.underlineY,
    underlineThickness: m.underlineThickness,
    glyphs,
  };
}

/**
 * Parse an msdf-atlas-gen JSON into one entry per font face. A single-font JSON
 * yields one entry; a merged (`-and`) atlas yields one per variant, all sharing
 * the same texture. Pure — no DOM/GPU.
 */
export function parseMsdfFont(json: MsdfFontJSON, baseName = 'MSDF'): MsdfFontData[] {
  if (json.variants) {
    return json.variants.map((v, i) => parseVariant(json.atlas, v, v.name || `${baseName}#${i}`));
  }
  return [parseVariant(json.atlas, { metrics: json.metrics!, glyphs: json.glyphs!, kerning: json.kerning }, baseName)];
}

// ── The GPU-backed font handle ──────────────────────────────────────────────

/**
 * A loaded MSDF font: parsed metrics/glyphs + a GPU atlas texture. Faces sharing
 * a merged atlas share one `texture`. Get a glyph with `glyph(code)`; measure a
 * line with `measure(text, size)`. Draw with `game.assets.msdfText(...)` / `d.msdfText`.
 */
export class MsdfFont {
  constructor(
    readonly data: MsdfFontData,
    /** The atlas texture view (shared across faces of a merged atlas). */
    readonly view: GPUTextureView,
    /** Faces packed in the same texture, keyed by name (single-font: just this). */
    readonly faces: Map<string, MsdfFont> = new Map(),
  ) {}

  get name(): string { return this.data.name; }
  get isMtsdf(): boolean { return this.data.fieldType === 'mtsdf'; }
  /** distanceRange / atlasSize — the shader's per-texture AA unit (x, y). */
  get unitRange(): [number, number] {
    return [this.data.distanceRange / this.data.atlasWidth, this.data.distanceRange / this.data.atlasHeight];
  }
  /** 1 / distanceRange — normalises weight/outline/shadow into field fractions. */
  get invRange(): number { return 1 / this.data.distanceRange; }

  glyph(code: number): MsdfGlyph | undefined { return this.data.glyphs.get(code); }

  /** Another face packed in the same merged atlas, or `undefined`. */
  face(name: string): MsdfFont | undefined { return this.faces.get(name); }

  /** Rendered width of a single line (no newlines), in pixels at `fontSize`. */
  measure(text: string, fontSize = 48, letterSpacing = 0): number {
    let w = 0, prev = 0, count = 0;
    for (let i = 0; i < text.length; i++) {
      const code = text.charCodeAt(i);
      const g = this.data.glyphs.get(code);
      if (!g) { prev = 0; continue; }
      if (prev !== 0) w += (this.data.glyphs.get(prev)?.kerning.get(code) ?? 0) * fontSize;
      w += g.advance * fontSize;
      prev = code; count++;
    }
    if (letterSpacing !== 0 && count > 0) w += letterSpacing * count;
    return w;
  }
}

/**
 * Upload an MSDF atlas image to a sampleable texture. MSDF/MTSDF values are raw
 * distances, so the copy must NOT premultiply alpha (the MTSDF alpha channel is
 * a true SDF, not opacity) — `copyExternalImageToTexture` leaves it unpremult
 * by default, which is exactly what we want. Linear filtering (set on the
 * renderer's sampler) is mandatory for MSDF.
 */
export function msdfTextureFrom(device: GPUDevice, img: TexImageSource, w: number, h: number): GPUTexture {
  const texture = device.createTexture({
    size: { width: w, height: h },
    format: 'rgba8unorm',
    usage: 0x4 /* TEXTURE_BINDING */ | 0x2 /* COPY_DST */ | 0x10 /* RENDER_ATTACHMENT */,
  });
  device.queue.copyExternalImageToTexture({ source: img }, { texture, premultipliedAlpha: false }, { width: w, height: h });
  return texture;
}
