// The UI panel style layer — the DATA half of the procedural UI system.
//
// A panel is never an image. It is a rounded-box SIGNED DISTANCE FIELD plus a
// MATERIAL, and every part of that material — rim, bevel, gloss, inner shadow,
// drop shadow — is a function of the distance to the silhouette edge. That is
// the whole reason this beats nine-slice: nine-slice STRETCHES pixels, so a rim
// authored at 200px wide becomes a fat smear at 800px. An SDF panel EVALUATES
// its rim at the width you asked for, at every size, at every resolution, with
// no source art at all.
//
// A UiStyle is plain JSON — no code, no shader, no asset. Named styles live in
// `UI_STYLES` and new ones arrive through `defineUiStyle()`, exactly as effects
// arrive as EffectDef data (see effects.ts): that is how the look-and-feel
// library grows without an engine release.
//
// Pure + DOM-free: this module only turns a style into numbers. ui.ts owns the
// GPU side and webgl/ui.ts its GL twin.

import { rgba, type Rgba } from './color.js';

/** Corner radii: one value for all four, `'pill'` (fully round ends), or
 *  `[topLeft, topRight, bottomRight, bottomLeft]`. */
export type UiRadius = number | 'pill' | [number, number, number, number];

/**
 * A panel's look. **Every field is optional** — a style states only what it
 * changes, and `base` inherits the rest from a named style, so the common case
 * is one line: `{ base: 'glossy', fill: '#e6408f' }`.
 *
 * Lengths (`border`, `bevelWidth`, `radius`, `shadowBlur`, …) are in the
 * SURFACE's own units — world units on `game.draw`, CSS pixels on `game.hud` —
 * the same units the panel's own width and height are in. Angles are DEGREES.
 */
export interface UiStyle {
  /** Named style to inherit from (see `UI_STYLES`). Unknown names resolve to the defaults. */
  base?: string;

  // ── Silhouette ──
  /** Corner rounding. `'pill'` rounds the short axis fully. Default 12. */
  radius?: UiRadius;

  // ── Body ──
  /** Fill colour (gradient START). Default '#5a6bb8'. */
  fill?: string;
  /** Gradient END colour. Omit for a flat fill. */
  fillTo?: string;
  /** Gradient direction in degrees: 0 = top→bottom, 90 = left→right. Default 0. */
  fillAngle?: number;

  // ── Rim ──
  /** Border/rim thickness, drawn INSIDE the silhouette. 0 disables it. Default 0. */
  border?: number;
  /** Rim colour (gradient START, along `fillAngle`). Default '#ffffff'. */
  borderColor?: string;
  /** Rim gradient END colour. Omit for a flat rim. */
  borderColorTo?: string;

  // ── Relief: the bevel is what makes a flat rounded rect read as an OBJECT ──
  /** Bevel strength 0..1 — how hard the lit/shaded edge reads. 0 disables it. Default 0. */
  bevel?: number;
  /** How far the bevel reaches in from the edge. Default: the border width, or 6. */
  bevelWidth?: number;
  /** Where the light comes FROM, degrees clockwise from straight up. Default 0 (above). */
  light?: number;

  // ── Gloss: the bright cap across the top — the "candy" cue ──
  /** Gloss strength 0..1. 0 disables it. Default 0. */
  gloss?: number;
  /** Fraction of the panel's height the gloss covers. Default 0.45. */
  glossHeight?: number;
  /** How far the gloss is inset from the sides. Default 6. */
  glossInset?: number;
  /** Gloss colour. Default '#ffffff'. */
  glossColor?: string;

  // ── Inner shadow: contact darkening on the side away from the light ──
  /** Inner shadow strength 0..1. 0 disables it. Default 0. */
  innerShadow?: number;
  /** How far the inner shadow reaches in from the edge. Default 10. */
  innerShadowWidth?: number;
  /** Inner shadow colour. Default '#000000'. */
  innerShadowColor?: string;

  // ── Drop shadow: lifts the panel off whatever is behind it ──
  /** Drop shadow strength 0..1. 0 disables it. Default 0. */
  shadow?: number;
  /** Shadow offset. Default x 0, y 4. */
  shadowX?: number;
  shadowY?: number;
  /** Shadow blur radius. Default 10. */
  shadowBlur?: number;
  /** Grow the shadow's silhouette before blurring. Default 0. */
  shadowSpread?: number;
  /** Shadow colour. Default '#000000'. */
  shadowColor?: string;

  // ── Whole-panel ──
  /**
   * Lighten (> 0) or darken (< 0) the body and rim, -1..1. This is the RELATIVE
   * knob the state styles want: `tint` can only multiply, so it can darken but
   * never brighten, and a hover that brightens has to work without knowing what
   * colour the panel is. Default 0.
   */
  brightness?: number;
  /** Multiply tint over the finished panel — disabled/greyed states. Default '#ffffff'. */
  tint?: string;
  /** Overall opacity. Default 1. */
  alpha?: number;
  /** Shift the whole panel. A pressed button sinking is `offsetY: 2`. Default 0. */
  offsetX?: number;
  offsetY?: number;

  // ── Interaction (see UiStateStyle) ──
  /**
   * The look while the pointer is over the panel. `true` uses the engine
   * default (a brighten). **Setting this makes the panel interactive.**
   */
  hover?: boolean | UiStateStyle;
  /**
   * The look while the pointer is held down on it. `true` uses the engine
   * default (darken + sink). Also makes the panel interactive.
   */
  pressed?: boolean | UiStateStyle;
  /** Hit-test with no look change — for `panel().clicked` on a flat design. */
  interactive?: boolean;
  /** Show the hand cursor while hovered. Default `true` for interactive panels. */
  cursor?: boolean;
}

/**
 * A hover / pressed look: every APPEARANCE key of {@link UiStyle}, each
 * optional and each falling back to the panel's base look. States cannot
 * nest — a hover style has no `hover` of its own.
 */
export type UiStateStyle = Omit<UiStyle, 'base' | 'hover' | 'pressed' | 'interactive' | 'cursor'>;

/** Which look a panel is drawing this frame. */
export type UiState = 'base' | 'hover' | 'pressed';

/** A style with every field decided — what `UiRenderer.push` packs. Produced by
 *  `resolveUiStyle`; games use {@link UiStyle} and never build one by hand. */
export interface ResolvedUiStyle {
  radius: [number, number, number, number];
  fill: Rgba; fillTo: Rgba; fillAngle: number;      // radians
  border: number; borderColor: Rgba; borderColorTo: Rgba;
  bevel: number; bevelWidth: number; light: number; // radians
  gloss: number; glossHeight: number; glossInset: number; glossColor: Rgba;
  innerShadow: number; innerShadowWidth: number; innerShadowColor: Rgba;
  shadow: number; shadowX: number; shadowY: number;
  shadowBlur: number; shadowSpread: number; shadowColor: Rgba;
  tint: Rgba; alpha: number; offsetX: number; offsetY: number;
  // Interaction, decided once from the merged style so the draw verb can read
  // it without merging again.
  interactive: boolean; cursor: boolean;
  hasHover: boolean; hasPressed: boolean;
}

/** The radius sentinel meaning "round the short axis fully" — the shader clamps
 *  every radius to half the shortest side, so any huge number is a pill. */
const PILL = 1e5;

const DEG = Math.PI / 180;

/** Fall back to `d` when `v` is undefined (0 and '' are real values). */
const or = <T>(v: T | undefined, d: T): T => (v === undefined ? d : v);

function radii(r: UiRadius | undefined, fallback: UiRadius): [number, number, number, number] {
  const v = r === undefined ? fallback : r;
  if (v === 'pill') return [PILL, PILL, PILL, PILL];
  if (typeof v === 'number') return [v, v, v, v];
  return [v[0], v[1], v[2], v[3]];
}

// ── The built-in styles ────────────────────────────────────────────────────
//
// Deliberately GENERIC, not a copy of any one art pack: each names a MATERIAL
// (glossy, glass, metal, inset…), and the colours are just defaults you
// override. `{ base: 'glossy', fill: '#7ac74f', fillTo: '#4e9b2c' }` is a green
// candy button; nothing else has to change.

/** The built-in named styles. Extend with `defineUiStyle()`. */
export const UI_STYLES: Record<string, UiStyle> = {
  /** A flat rounded rect — the neutral starting point. */
  flat: {
    radius: 10,
    fill: '#5a6bb8',
  },

  /** The candy/casual button: fat rim, vertical gradient, bevel and a gloss cap. */
  glossy: {
    radius: 16,
    fill: '#8f5bd8', fillTo: '#5f2fa8', fillAngle: 0,
    border: 5, borderColor: '#ffb340', borderColorTo: '#e07a1c',
    bevel: 0.45, bevelWidth: 10,
    gloss: 0.5, glossHeight: 0.42, glossInset: 9,
    innerShadow: 0.35, innerShadowWidth: 14,
    shadow: 0.35, shadowY: 5, shadowBlur: 12,
  },

  /** A container/frame: soft body, clear rim, sits under other UI. */
  panel: {
    radius: 18,
    fill: '#2b2f4a', fillTo: '#1d2036',
    border: 3, borderColor: '#5b628f',
    bevel: 0.2, bevelWidth: 6,
    innerShadow: 0.25, innerShadowWidth: 20,
    shadow: 0.45, shadowY: 8, shadowBlur: 22,
  },

  /** Translucent frosted card with a bright top rim. */
  glass: {
    radius: 14,
    fill: '#ffffff', fillTo: '#ffffff', alpha: 0.16,
    border: 1.5, borderColor: '#ffffff',
    bevel: 0.3, bevelWidth: 4,
    gloss: 0.25, glossHeight: 0.5, glossInset: 2,
  },

  /** Brushed-metal chip: cool gradient, tight bevel, thin bright rim. */
  metal: {
    radius: 8,
    fill: '#9aa3b2', fillTo: '#59616f',
    border: 2, borderColor: '#cfd6e2', borderColorTo: '#3c424e',
    bevel: 0.6, bevelWidth: 5,
    gloss: 0.22, glossHeight: 0.5, glossInset: 3,
    shadow: 0.3, shadowY: 3, shadowBlur: 8,
  },

  /** A SUNKEN well — slider tracks, progress-bar backgrounds, empty slots.
   *  Same material with the light flipped to BELOW, so the relief carves in. */
  inset: {
    radius: 'pill',
    fill: '#1a1c2e', fillTo: '#2a2d47',
    border: 2, borderColor: '#11131f',
    bevel: 0.5, bevelWidth: 7, light: 180,
    innerShadow: 0.6, innerShadowWidth: 10,
  },

  /** The FILL that rides inside an `inset` track — bars, meters, XP. */
  bar: {
    radius: 'pill',
    fill: '#5ce1a0', fillTo: '#2ea56c',
    bevel: 0.3, bevelWidth: 5,
    gloss: 0.4, glossHeight: 0.5, glossInset: 2,
  },
};

/**
 * Register a named style (or replace one). Styles are plain data, so a content
 * pack — or the game-building agent — can ship a whole UI theme without any
 * engine change: `defineUiStyle('rune', { base: 'panel', fill: '#26324a', … })`.
 */
export function defineUiStyle(name: string, def: UiStyle): void {
  UI_STYLES[name] = def;
}

const DEFAULTS: Required<Pick<UiStyle,
  'radius' | 'fill' | 'fillAngle' | 'border' | 'borderColor' | 'bevel' | 'light' |
  'gloss' | 'glossHeight' | 'glossInset' | 'glossColor' | 'innerShadow' |
  'innerShadowWidth' | 'innerShadowColor' | 'shadow' | 'shadowX' | 'shadowY' |
  'shadowBlur' | 'shadowSpread' | 'shadowColor' | 'tint' | 'alpha' |
  'brightness' | 'offsetX' | 'offsetY'>> = {
  radius: 12,
  fill: '#5a6bb8', fillAngle: 0,
  border: 0, borderColor: '#ffffff',
  bevel: 0, light: 0,
  gloss: 0, glossHeight: 0.45, glossInset: 6, glossColor: '#ffffff',
  innerShadow: 0, innerShadowWidth: 10, innerShadowColor: '#000000',
  shadow: 0, shadowX: 0, shadowY: 4, shadowBlur: 10, shadowSpread: 0, shadowColor: '#000000',
  tint: '#ffffff', alpha: 1,
  brightness: 0, offsetX: 0, offsetY: 0,
};

// The looks `hover: true` / `pressed: true` stand for. They are deliberately
// RELATIVE (brightness, an offset) rather than absolute colours, so they read
// correctly on every material and every palette without knowing either — which
// is what lets a button be interactive without authoring two more styles.
const DEFAULT_HOVER: UiStateStyle = { brightness: 0.15 };
const DEFAULT_PRESSED: UiStateStyle = { brightness: -0.12, offsetY: 2 };

/** Mix a colour toward white (b > 0) or black (b < 0); alpha untouched. */
function brighten(c: Rgba, b: number): Rgba {
  if (!b) return c;
  const k = b < 0 ? -b : b;
  const to = b > 0 ? 1 : 0;
  return [c[0] + (to - c[0]) * k, c[1] + (to - c[1]) * k, c[2] + (to - c[2]) * k, c[3]];
}

const stateStyle = (v: boolean | UiStateStyle | undefined, dflt: UiStateStyle): UiStateStyle | null =>
  v === true ? dflt : v === false || v == null ? null : v;

/**
 * Flatten a style (name, object, or object with `base`) into decided numbers,
 * optionally overlaid with its `hover` / `pressed` look.
 *
 * Pure — a shallow merge plus cached colour parses, cheap enough to call per
 * panel per frame, so animating a style field just works. Nothing is memoised
 * on the style object precisely so that a MUTATED style takes effect at once.
 */
export function resolveUiStyle(style?: string | UiStyle, state: UiState = 'base'): ResolvedUiStyle {
  const own: UiStyle = typeof style === 'string' ? (UI_STYLES[style] ?? {}) : (style ?? {});
  const base: UiStyle = own.base ? (UI_STYLES[own.base] ?? {}) : {};
  // One merged view: own field wins, else the named base, else the default. The
  // state overlay goes on top, so it only has to state what it CHANGES.
  const hover = stateStyle(own.hover ?? base.hover, DEFAULT_HOVER);
  const pressed = stateStyle(own.pressed ?? base.pressed, DEFAULT_PRESSED);
  const overlay = (state === 'hover' ? hover : state === 'pressed' ? pressed : null) ?? {};
  const s = { ...DEFAULTS, ...base, ...own, ...overlay } as Required<UiStyle> & UiStyle;

  // `radius` and `bevelWidth` need the raw layers, not the defaulted view: a
  // number and "absent" are different, and DEFAULTS would mask the difference.
  const rawRadius = overlay.radius ?? own.radius ?? base.radius;
  const rawBevelW = overlay.bevelWidth ?? own.bevelWidth ?? base.bevelWidth;

  const b = s.brightness;
  const fill = brighten(rgba(s.fill), b);
  const borderColor = brighten(rgba(s.borderColor), b);
  return {
    radius: radii(rawRadius, DEFAULTS.radius),
    fill,
    // A gradient with no end colour is a flat fill — reuse the start colour.
    fillTo: s.fillTo ? brighten(rgba(s.fillTo), b) : fill,
    fillAngle: s.fillAngle * DEG,
    border: s.border,
    borderColor,
    borderColorTo: s.borderColorTo ? brighten(rgba(s.borderColorTo), b) : borderColor,
    bevel: s.bevel,
    // A bevel with no width tracks the rim it is shading, so `border` alone reads right.
    bevelWidth: or(rawBevelW, s.border > 0 ? s.border * 2 : 6),
    light: s.light * DEG,
    gloss: s.gloss, glossHeight: s.glossHeight, glossInset: s.glossInset,
    glossColor: rgba(s.glossColor),
    innerShadow: s.innerShadow, innerShadowWidth: s.innerShadowWidth,
    innerShadowColor: rgba(s.innerShadowColor),
    shadow: s.shadow, shadowX: s.shadowX, shadowY: s.shadowY,
    shadowBlur: s.shadowBlur, shadowSpread: s.shadowSpread,
    // The shadow is CAST, not lit — brightening the panel must not brighten it.
    shadowColor: rgba(s.shadowColor),
    tint: rgba(s.tint), alpha: s.alpha,
    offsetX: s.offsetX, offsetY: s.offsetY,
    interactive: !!(own.interactive ?? base.interactive) || !!hover || !!pressed,
    cursor: (own.cursor ?? base.cursor) ?? true,
    hasHover: !!hover, hasPressed: !!pressed,
  };
}
