// Bitmap fonts: glyphs are baked ONCE (runtime, shelf-packed into the shared
// atlas) and drawn as ordinary batched quads — per-frame changing text costs
// nothing but instance pushes. Glyphs bake WHITE so per-instance tint colours
// text for free.
//
// Module load is DOM-free; baking happens inside bakeFont() (canvas 2D).

import type { Atlas } from './atlas.js';

export interface Glyph {
  /** Atlas frame index. */
  frame: number;
  /** Draw size in pixels (== world units at scale 1). */
  w: number;
  h: number;
  /** Horizontal pen advance after this glyph. */
  advance: number;
}

export interface FontOptions {
  /** CSS font shorthand (default 'bold 16px monospace'). */
  font?: string;
  /** Characters to bake (default printable ASCII). */
  charset?: string;
}

const ASCII = (() => {
  let s = '';
  for (let c = 33; c <= 126; c++) s += String.fromCharCode(c);
  return s;
})();

/** A baked glyph set. Pure data after baking — measure() is headless math. */
export class BitmapFont {
  constructor(
    readonly glyphs: ReadonlyMap<string, Glyph>,
    readonly lineHeight: number,
    /** Pen advance for characters without a glyph (space, unknown). */
    readonly spaceAdvance: number,
  ) {}

  /** Rendered width of a single line, in world units. */
  measure(text: string, scale = 1): number {
    let w = 0;
    for (const ch of text) w += (this.glyphs.get(ch)?.advance ?? this.spaceAdvance) * scale;
    return w;
  }
}

/** Rasterize a charset into white glyphs on the atlas (called by game.assets.font()). */
export function bakeFont(atlas: Atlas, opts: FontOptions = {}): BitmapFont {
  const font = opts.font ?? 'bold 16px monospace';
  const charset = opts.charset ?? ASCII;
  const probe = document.createElement('canvas').getContext('2d')!;
  probe.font = font;
  // Probe the WHOLE charset for extents (a single-char probe clips tall
  // ascenders/deep descenders) and take the font's own bounding box where the
  // browser reports it — whichever is taller wins, plus a pixel of headroom.
  const pm = probe.measureText(charset);
  const ascent = Math.ceil(Math.max(pm.actualBoundingBoxAscent || 0, pm.fontBoundingBoxAscent || 0, 8)) + 1;
  const descent = Math.ceil(Math.max(pm.actualBoundingBoxDescent || 0, pm.fontBoundingBoxDescent || 0, 2)) + 1;
  const lineHeight = ascent + descent + 2;

  const glyphs = new Map<string, Glyph>();
  for (const ch of charset) {
    const m = probe.measureText(ch);
    const adv = Math.ceil(m.width);
    if (adv <= 0) continue;
    // Ink can overhang the advance on both sides (italics, serifs) — size the
    // cell to the ink, keep the pen advance separate.
    const left = Math.ceil(Math.max(0, m.actualBoundingBoxLeft || 0));
    const right = Math.ceil(Math.max(adv, m.actualBoundingBoxRight || 0));
    const c = document.createElement('canvas');
    c.width = left + right + 2;
    c.height = lineHeight;
    const ctx = c.getContext('2d')!;
    ctx.font = font;
    ctx.fillStyle = '#ffffff'; // white: per-instance tint colours the text
    ctx.textBaseline = 'alphabetic';
    ctx.fillText(ch, 1 + left, ascent);
    const frame = atlas.add(c);
    glyphs.set(ch, { frame, w: c.width, h: c.height, advance: adv + 1 });
  }
  const spaceAdvance = Math.max(2, Math.ceil(probe.measureText(' ').width));
  return new BitmapFont(glyphs, lineHeight, spaceAdvance);
}
