// UnicodeText — text for EVERY writing system: Chinese, Japanese, Korean,
// Arabic, Hebrew, Thai, Devanagari, Cyrillic, Greek, emoji… as well as Latin.
//
// WHY THIS EXISTS. The bitmap (`d.text`) and MSDF (`d.msdfText`) paths both key
// glyphs off a FIXED, pre-baked character set and advance a pen one code unit at
// a time, left to right. That model simply cannot express the scripts most of
// the world reads:
//   • CJK has tens of thousands of glyphs — no atlas bakes them all.
//   • Arabic glyphs CHANGE SHAPE by position (isolated / initial / medial /
//     final) and join to their neighbours; one codepoint is not one glyph.
//   • Arabic and Hebrew run RIGHT TO LEFT, and mix with LTR digits/names, so
//     the visual order is not the string order (the Unicode bidi algorithm).
//   • Devanagari/Thai/Khmer reorder and stack marks around their base glyph.
//
// The browser already ships a complete implementation of all of that. So this
// path hands the string to Canvas 2D — which shapes it, applies bidi, and does
// per-character SYSTEM FONT FALLBACK — rasterizes the finished block ONCE into
// its own texture, and draws it as a single textured quad through the text
// renderer's bitmap lane. One quad per block, whatever the script.
//
// The styling is the canvas's: gradient fills, outer strokes, layered drop
// shadows, glow, underlines, rounded background plates — all baked into the
// raster, so they cost nothing per frame. HOVER and PRESSED styles are baked as
// their own rasters up front, so lighting a menu item up is a texture swap, not
// a re-rasterize.
//
// Module load is DOM-free: the measuring context and every raster are created
// lazily inside layout()/raster().

import { rgba } from './color.js';
import { BITMAP_PARAMS, packColor, type MsdfRenderer } from './msdf.js';
import { transformedBounds, type TextBounds, type TextTransform } from './text-bounds.js';

// ── Public option types ──────────────────────────────────────────────────────

export type UnicodeAlign = 'left' | 'center' | 'right';
/** `'auto'` picks RTL when the first strong character is Arabic/Hebrew/… */
export type UnicodeDirection = 'ltr' | 'rtl' | 'auto';

/** A multi-stop gradient. `stops` are CSS colours, or `[offset, colour]` pairs. */
export interface TextGradient {
  stops: Array<string | [number, string]>;
  /** Degrees: 90 (default) = top→bottom, 0 = left→right. */
  angle?: number;
}

/** A solid colour, a top→bottom pair, or a full gradient. */
export type TextFill = string | { top: string; bottom: string } | TextGradient;

export interface TextStroke {
  color?: string;
  /** Stroke width in px (default 4). */
  width?: number;
  /** `'outer'` (default) keeps the letterform's inside clean; `'center'` straddles the edge. */
  align?: 'outer' | 'center';
  join?: 'round' | 'bevel' | 'miter';
}

export interface TextShadow {
  x?: number;
  y?: number;
  blur?: number;
  color?: string;
}

/** A halo hugging the letters (a blurred, un-offset shadow, stacked for punch). */
export interface TextGlow {
  color?: string;
  /** Blur radius in px (default 12). */
  blur?: number;
  /** How many times the halo is stacked, 1..6 — brightness/tightness (default 3). */
  strength?: number;
}

/** An underline / strikethrough rule (`true` inherits the fill colour). */
export interface TextRule {
  color?: string;
  /** Line thickness in px (default ~6% of the font size). */
  thickness?: number;
  /** Shift from the default position, px (positive = down). */
  offset?: number;
}

/** A plate painted behind the text (dialogue boxes, name tags, menu buttons). */
export interface TextBackground {
  color?: string;
  /** Extra px around the text block (default 12). */
  padding?: number;
  /** Corner radius in px (default 0). */
  radius?: number;
  borderColor?: string;
  borderWidth?: number;
}

/** Everything a state (base / hover / pressed) can paint. */
export interface TextAppearance {
  color?: TextFill;
  stroke?: TextStroke | null;
  shadow?: TextShadow | TextShadow[] | null;
  glow?: TextGlow | null;
  background?: TextBackground | null;
  underline?: boolean | TextRule;
  strikethrough?: boolean | TextRule;
}

/**
 * A hover / pressed look. Every key is OPTIONAL and falls back to the base
 * style, so `{ color: '#fff', underline: true }` is a complete hyperlink hover.
 *
 * APPEARANCE ONLY — there is deliberately no `fontSize`/`maxWidth` here: a
 * hover that reflows the text would shift everything around it. Use `scale` for
 * a grow-on-hover (draw-time, no re-raster).
 */
export interface TextStateStyle extends TextAppearance {
  /** Uniform scale while in this state (default 1). */
  scale?: number;
  /** Alpha multiplier while in this state (default 1). */
  alpha?: number;
}

export interface UnicodeTextOptions extends TextAppearance {
  /**
   * A full CSS font shorthand — wins over the parts below.
   * e.g. `'700 48px "Noto Sans JP", sans-serif'`.
   */
  font?: string;
  /** Default `'sans-serif'` — the system stack, which falls back per character. */
  fontFamily?: string;
  /** Px (default 48). In world space this is world units; on the HUD, CSS px. */
  fontSize?: number;
  fontWeight?: string | number;
  fontStyle?: 'normal' | 'italic' | 'oblique';
  /** Default: `'left'` for LTR text, `'right'` for RTL. */
  align?: UnicodeAlign;
  /** Base paragraph direction. Default `'auto'`. */
  direction?: UnicodeDirection;
  /** Line box as a multiple of fontSize (default 1.3). */
  lineHeight?: number;
  /** Extra px between characters. TRAP: breaks Arabic joining — leave 0 for Arabic. */
  letterSpacing?: number;
  /** Word-wrap width in px (0 = no wrap). In vertical mode this caps COLUMN length. */
  maxWidth?: number;
  /** Transparent margin around the block in px (default 0). */
  padding?: number;
  /** CJK vertical writing (tategaki): columns stack downward, right to left. */
  vertical?: boolean;
  /**
   * Pin the raster supersample factor. Omit (the default) and the block
   * re-rasterizes itself to stay crisp at whatever size it's drawn.
   */
  resolution?: number;
  /** BCP-47 tag steering line breaking (default: the document's). */
  locale?: string;

  // ── Interaction ──
  /** The look while the pointer is over it. Setting this makes the block interactive. */
  hover?: TextStateStyle;
  /** The look while the pointer is held down on it. Also makes it interactive. */
  pressed?: TextStateStyle;
  /** Hit-test without a style change (for `text.hovered` / `onClick`). */
  interactive?: boolean;
  /** Grow the clickable area by this many px on every side (fat-finger targets). */
  hitPadding?: number;
  /** Show the hand cursor while hovered. Default `true` for interactive blocks. */
  cursor?: boolean;
}

export interface UnicodeDrawOptions extends TextTransform {
  /** Uniform scale about the origin. */
  scale?: number;
  /** Rotation about the origin, radians. */
  rotation?: number;
  alpha?: number;
  /** Multiply-tint the whole block, hex (`'#ff8080'`). */
  tint?: string;
  /** Anchor as a fraction of the block (0,0 = top-left, 0.5,0.5 = centre). */
  origin?: { x?: number; y?: number };
  /** Depth 0..1 (0 = frontmost). Text tests-never, so this only orders text vs text. */
  z?: number;
}

/** @internal The pointer, in the drawing surface's own units, plus the cursor hook. */
export interface TextPointer {
  x: number;
  y: number;
  down: boolean;
  /** Called by a hovered interactive block that wants the hand cursor. */
  wantCursor?: () => void;
  /**
   * When the current/last press began (the tracker's `downTime`). `down` alone
   * is POLLED once a frame, so a press and release that both land between two
   * frames are invisible to it — a fast tap, or any click while the frame rate
   * dips. A changed `pressedAt` is the press EDGE, and survives that gap.
   */
  pressedAt?: number;
  /** Where that press began, in this surface's units — a click must be judged
   *  by where the press LANDED, not where the pointer drifted to. */
  pressX?: number;
  pressY?: number;
}

// ── Pure helpers (headless — exported for tests) ─────────────────────────────

// Strong right-to-left blocks: Hebrew, Arabic, Syriac, Thaana, NKo, Samaritan,
// Mandaic, Arabic Extended + the presentation forms, and the RTL SMP scripts.
const RTL_RANGES: ReadonlyArray<readonly [number, number]> = [
  [0x0590, 0x05ff], [0x0600, 0x07bf], [0x07c0, 0x08ff],
  [0xfb1d, 0xfdff], [0xfe70, 0xfeff],
  [0x10800, 0x10cff], [0x10d40, 0x10ebf], [0x1e800, 0x1efff],
];

/** True when this codepoint is a strong right-to-left character. */
export function isRtlCodePoint(cp: number): boolean {
  for (const [lo, hi] of RTL_RANGES) if (cp >= lo && cp <= hi) return true;
  return false;
}

/**
 * The base paragraph direction of a string, by the Unicode "first strong
 * character" rule: leading digits, spaces and punctuation are skipped, then the
 * first letter decides. `'مرحبا 42'` → rtl, `'42 مرحبا'` → rtl, `'Hi مرحبا'` → ltr.
 */
export function detectDirection(text: string): 'ltr' | 'rtl' {
  for (const ch of text) {
    const cp = ch.codePointAt(0)!;
    if (isRtlCodePoint(cp)) return 'rtl';
    // Strong LTR: any letter outside the RTL blocks. Cheap test — skip the
    // ASCII neutrals/digits and anything below the Latin letters.
    if ((cp >= 0x41 && cp <= 0x5a) || (cp >= 0x61 && cp <= 0x7a) || cp >= 0x00c0) return 'ltr';
  }
  return 'ltr';
}

// CJK ideographs, kana, Hangul and the full-width forms — scripts that break
// between ANY two characters rather than at spaces.
function isCjk(cp: number): boolean {
  return (cp >= 0x2e80 && cp <= 0x9fff)     // radicals, kana, CJK unified
    || (cp >= 0xa960 && cp <= 0xa97f)       // Hangul Jamo Extended-A
    || (cp >= 0xac00 && cp <= 0xd7ff)       // Hangul syllables
    || (cp >= 0xf900 && cp <= 0xfaff)       // compatibility ideographs
    || (cp >= 0xfe30 && cp <= 0xfe4f)       // CJK compatibility forms
    || (cp >= 0xff00 && cp <= 0xff60)       // full-width forms
    || (cp >= 0x20000 && cp <= 0x3ffff);    // extensions B..
}

/** Kinsoku: characters that may never START a line (closers, small kana, marks). */
const NO_LINE_START = '）］｝〕〉》」』】〙〗〟’”｠»、。，．：；！？!?,.:;ー々〜〜ぁぃぅぇぉっゃゅょゎァィゥェォッャュョヮヵヶ・ゝゞヽヾ';
/** Kinsoku: characters that may never END a line (openers). */
const NO_LINE_END = '（［｛〔〈《「『【〘〖〝‘“｟«';

/**
 * Indices at which a line may be broken (a break happens BEFORE the index).
 * Uses `Intl.Segmenter` word segmentation where available — that is what gets
 * Thai and Khmer (which have no spaces) right — plus per-character breaking for
 * CJK. Kinsoku rules then veto the ugly breaks.
 */
export function breakOpportunities(text: string, locale?: string): number[] {
  const at = new Set<number>();
  const seg = segmenter('word', locale);
  if (seg) {
    // Dictionary word boundaries — the ONLY thing that wraps Thai and Khmer,
    // which have no spaces and no per-character breaking either.
    for (const s of seg.segment(text)) if (s.index > 0) at.add(s.index);
  } else {
    for (let i = 1; i < text.length; i++) if (text.charCodeAt(i - 1) === 32 || text.charCodeAt(i - 1) === 9) at.add(i);
  }
  // CJK breaks between (nearly) ANY two characters, so add those on top — word
  // boundaries alone leave a long Japanese run unwrappable.
  for (let i = 1; i < text.length; i++) {
    if (isCjk(text.codePointAt(i - 1)!) || isCjk(text.codePointAt(i)!)) at.add(i);
  }
  // Kinsoku veto: never leave a closer stranded at the head of a line, and
  // never end a line on an opener.
  return [...at].sort((a, b) => a - b)
    .filter((i) => !NO_LINE_START.includes(text[i]) && !NO_LINE_END.includes(text[i - 1]));
}

interface SegLike { segment(s: string): Iterable<{ index: number; segment: string }> }
type SegCtor = new (l?: string, o?: object) => SegLike;

// Building an Intl.Segmenter is expensive enough to matter when a wrap hard-
// breaks or a vertical column re-lays-out — cache one per (granularity, locale).
const segCache = new Map<string, SegLike | null>();
function segmenter(granularity: 'word' | 'grapheme', locale?: string): SegLike | null {
  const key = `${granularity}|${locale ?? ''}`;
  let seg = segCache.get(key);
  if (seg === undefined) {
    seg = null;
    try {
      const I = Intl as unknown as { Segmenter?: SegCtor };
      if (I.Segmenter) seg = new I.Segmenter(locale, { granularity });
    } catch { seg = null; }
    segCache.set(key, seg);
  }
  return seg;
}

/** Split into user-perceived characters (grapheme clusters) — emoji and marks stay whole. */
export function graphemes(text: string, locale?: string): string[] {
  const seg = segmenter('grapheme', locale);
  if (!seg) return [...text];
  const out: string[] = [];
  for (const s of seg.segment(text)) out.push(s.segment);
  return out;
}

/** Characters rotated a quarter turn when set vertically (tategaki). */
const VERTICAL_ROTATE = 'ー〜～－—–‐−(){}[]（）｛｝〔〕〈〉《》「」『』【】〘〙〖〗:;=~<>≪≫';
/** Characters nudged to the cell's top-right when set vertically. */
const VERTICAL_NUDGE = '、。，．';

// ── Layout + raster ──────────────────────────────────────────────────────────

interface Line { text: string; width: number }

/** Ink spill beyond the text box, per side, in px. */
interface Bleed { l: number; t: number; r: number; b: number }

const NO_BLEED: Bleed = { l: 0, t: 0, r: 0, b: 0 };
function unionBleed(a: Bleed, b: Bleed): Bleed {
  return { l: Math.max(a.l, b.l), t: Math.max(a.t, b.t), r: Math.max(a.r, b.r), b: Math.max(a.b, b.b) };
}

type TextState = 'base' | 'hover' | 'pressed';

/** One baked state: its own raster, texture and ink extents. */
interface Variant {
  canvas: HTMLCanvasElement;
  tex: TextTexture | null;
  res: number;
  capRes: number;
  bleed: Bleed;
  epoch: number;
}

let measureCtx: CanvasRenderingContext2D | null = null;
function measurer(): CanvasRenderingContext2D {
  if (!measureCtx) measureCtx = document.createElement('canvas').getContext('2d')!;
  return measureCtx;
}

/** Whether this browser honours `ctx.letterSpacing` (Chrome 99+, Safari 17+, FF 126+). */
let letterSpacingOk: boolean | null = null;
function hasLetterSpacing(): boolean {
  if (letterSpacingOk === null) letterSpacingOk = 'letterSpacing' in measurer();
  return letterSpacingOk;
}

/** @internal The texture handle the host hands back for a rasterized block. */
export interface TextTexture {
  view: GPUTextureView;
  destroy(): void;
}

/** @internal What a UnicodeText needs from the Game that owns it. */
export interface UnicodeTextHost {
  /** Upload a rasterized block as a premultiplied texture. */
  textTexture(src: HTMLCanvasElement): TextTexture;
  /** Bumped whenever the GPU device is rebuilt — every texture is then stale. */
  epoch(): number;
}

const MAX_TEX = 4096;

/**
 * A retained, styled block of text in ANY writing system. Create it with
 * `game.assets.unicodeText(str, opts)`, mutate it with the chainable setters,
 * and draw it with `d.unicodeText(text, x, y)` — on the world surface or the
 * HUD.
 *
 * The block lays out and rasterizes lazily: change nothing and a frame costs
 * one quad push.
 */
export class UnicodeText {
  private _text: string;
  private o: Required<Pick<UnicodeTextOptions,
    'fontFamily' | 'fontSize' | 'fontWeight' | 'fontStyle' | 'lineHeight' |
    'letterSpacing' | 'maxWidth' | 'padding' | 'vertical' | 'direction'>> & UnicodeTextOptions;

  private _lines: Line[] = [];
  private _width = 0;
  private _height = 0;
  private dirty = true;
  private variants = new Map<TextState, Variant>();

  // ── Interaction state ──
  private _hovered = false;
  private _down = false;
  private _clicked = false;
  /** The press started ON this block — a drag that began elsewhere can't click it. */
  private armed = false;
  private prevDown = false;
  private clickFns: Array<(t: UnicodeText) => void> = [];

  /** @internal Built by `game.assets.unicodeText()` — never construct one directly. */
  constructor(private host: UnicodeTextHost, text: string | string[] = '', opts: UnicodeTextOptions = {}) {
    this._text = Array.isArray(text) ? text.join('\n') : text;
    // Defaults LAST — an explicit `{ fontSize: undefined }` must not win.
    this.o = {
      ...opts,
      fontFamily: opts.fontFamily ?? 'sans-serif',
      fontSize: opts.fontSize ?? 48,
      fontWeight: opts.fontWeight ?? 400,
      fontStyle: opts.fontStyle ?? 'normal',
      lineHeight: opts.lineHeight ?? 1.3,
      letterSpacing: opts.letterSpacing ?? 0,
      maxWidth: opts.maxWidth ?? 0,
      padding: opts.padding ?? 0,
      vertical: opts.vertical ?? false,
      direction: opts.direction ?? 'auto',
    };
  }

  get text(): string { return this._text; }
  /** TEXT-box width in px (== draw units at scale 1) — what you ALIGN to. For the
   *  box it actually paints (stroke/glow/shadow/plate) use {@link bounds}. */
  get width(): number { this.ensureLayout(); return this._width; }
  /** TEXT-box height in px — see {@link width}. */
  get height(): number { this.ensureLayout(); return this._height; }
  /** The wrapped lines (or columns, when vertical). */
  get lines(): readonly string[] { this.ensureLayout(); return this._lines.map((l) => l.text); }
  /** The resolved base direction — useful when `direction: 'auto'`. */
  get resolvedDirection(): 'ltr' | 'rtl' {
    return this.o.direction === 'auto' ? detectDirection(this._text) : this.o.direction;
  }

  // ── Interaction (valid after the block has been drawn at least once) ──

  /** `true` while the pointer is over this block. */
  get hovered(): boolean { return this._hovered; }
  /** `true` while the pointer is held down on this block. */
  get held(): boolean { return this._hovered && this._down && this.armed; }
  /** `true` for the ONE frame a click completed on this block (press AND release on it). */
  get clicked(): boolean { return this._clicked; }
  /** `true` when this block hit-tests the pointer at all. */
  get isInteractive(): boolean {
    return this.o.interactive === true || !!this.o.hover || !!this.o.pressed || this.clickFns.length > 0;
  }

  /** Run `fn` when the block is clicked. Returns an unsubscribe function. */
  onClick(fn: (text: UnicodeText) => void): () => void {
    this.clickFns.push(fn);
    return () => { const i = this.clickFns.indexOf(fn); if (i >= 0) this.clickFns.splice(i, 1); };
  }

  // ── Chainable setters ──
  setText(text: string | string[]): this {
    const next = Array.isArray(text) ? text.join('\n') : text;
    if (next === this._text) return this;               // no-op: never re-raster for free
    this._text = next;
    return this.mark();
  }
  setFont(css: string): this { this.o.font = css; return this.mark(); }
  setFontFamily(family: string): this { this.o.fontFamily = family; this.o.font = undefined; return this.mark(); }
  setFontSize(px: number): this { this.o.fontSize = px; this.o.font = undefined; return this.mark(); }
  setFontWeight(w: string | number): this { this.o.fontWeight = w; this.o.font = undefined; return this.mark(); }
  setColor(c: TextFill): this { this.o.color = c; return this.mark(); }
  setStroke(s: TextStroke | null): this { this.o.stroke = s; return this.mark(); }
  setShadow(s: TextShadow | TextShadow[] | null): this { this.o.shadow = s; return this.mark(); }
  setGlow(g: TextGlow | null): this { this.o.glow = g; return this.mark(); }
  setBackground(b: TextBackground | null): this { this.o.background = b; return this.mark(); }
  setUnderline(u: boolean | TextRule): this { this.o.underline = u; return this.mark(); }
  setStrikethrough(s: boolean | TextRule): this { this.o.strikethrough = s; return this.mark(); }
  setAlign(a: UnicodeAlign): this { this.o.align = a; return this.mark(); }
  setDirection(d: UnicodeDirection): this { this.o.direction = d; return this.mark(); }
  setLineHeight(m: number): this { this.o.lineHeight = m; return this.mark(); }
  setLetterSpacing(px: number): this { this.o.letterSpacing = px; return this.mark(); }
  setMaxWidth(px: number): this { this.o.maxWidth = px; return this.mark(); }
  setVertical(on: boolean): this { this.o.vertical = on; return this.mark(); }
  setPadding(px: number): this { this.o.padding = px; return this.mark(); }
  /** The look while hovered (`null` removes it). Appearance keys only — see {@link TextStateStyle}. */
  setHoverStyle(s: TextStateStyle | null): this { this.o.hover = s ?? undefined; return this.mark(); }
  /** The look while held down (`null` removes it). */
  setPressedStyle(s: TextStateStyle | null): this { this.o.pressed = s ?? undefined; return this.mark(); }

  private mark(): this {
    this.dirty = true;
    for (const v of this.variants.values()) v.tex?.destroy();
    this.variants.clear();
    return this;
  }

  /** Shrink `fontSize` (binary search) until the wrapped block fits `w`×`h` px. */
  fitInside(w: number, h: number, opts: { minSize?: number; maxSize?: number; precision?: number } = {}): this {
    let lo = opts.minSize ?? 4, hi = opts.maxSize ?? this.o.fontSize;
    const prec = opts.precision ?? 0.5;
    this.o.maxWidth = w;
    this.o.font = undefined;
    while (hi - lo > prec) {
      const mid = (lo + hi) / 2;
      this.o.fontSize = mid; this.dirty = true; this.ensureLayout();
      if (this._width <= w && this._height <= h) lo = mid; else hi = mid;
    }
    this.o.fontSize = lo;
    return this.mark();
  }

  /** Free every GPU texture. The block re-rasterizes if drawn again. */
  destroy(): void {
    for (const v of this.variants.values()) v.tex?.destroy();
    this.variants.clear();
    this.dirty = true;
  }

  // ── Bounds ────────────────────────────────────────────────────────────────

  /**
   * The box this block actually PAINTS when drawn at (x, y) with `opts` — the
   * text box grown by stroke, glow, shadow and background-plate ink, then put
   * through origin / scale / rotation. **This is what you space layout against**;
   * `width`/`height` are the tighter text box you ALIGN to.
   *
   * Reserved worst case: the bounds cover the largest of the base, hover and
   * pressed states, so a menu spaced by this cannot collide when an item lights
   * up or grows on hover.
   *
   * ```ts
   * const b = score.bounds(16, 12);
   * timer.setMaxWidth(...); d.unicodeText(timer, 16, b.bottom + 8);   // never overlaps
   * ```
   */
  bounds(x: number, y: number, opts?: TextTransform): TextBounds {
    this.ensureLayout();
    const b = this.maxBleed();
    const scale = (opts?.scale ?? 1) * this.maxStateScale();
    return transformedBounds(
      this._width + b.l + b.r, this._height + b.t + b.b,
      x, y, { ...opts, scale }, b.l, b.t, this._width, this._height,
    );
  }

  /**
   * The CLICKABLE box — the text box plus the background plate's padding and
   * `hitPadding`. Deliberately NOT the painted box: a soft glow should not
   * swallow the pointer twenty pixels away from any letter.
   */
  hitBounds(x: number, y: number, opts?: TextTransform): TextBounds {
    this.ensureLayout();
    const p = this.hitPad();
    return transformedBounds(
      this._width + p * 2, this._height + p * 2,
      x, y, opts, p, p, this._width, this._height,
    );
  }

  private hitPad(): number {
    let plate = 0;
    for (const s of this.states()) {
      const bg = this.styleFor(s).background;
      if (bg) plate = Math.max(plate, bg.padding ?? 12);
    }
    return (this.o.hitPadding ?? 0) + plate;
  }

  /** Which states this block can be in — only those actually styled. */
  private states(): TextState[] {
    const out: TextState[] = ['base'];
    if (this.o.hover) out.push('hover');
    if (this.o.pressed) out.push('pressed');
    return out;
  }

  private maxBleed(): Bleed {
    let b = NO_BLEED;
    for (const s of this.states()) b = unionBleed(b, this.inkBleed(s));
    return b;
  }

  private maxStateScale(): number {
    return Math.max(1, this.o.hover?.scale ?? 1, this.o.pressed?.scale ?? 1);
  }

  /** The appearance of one state: its own keys over the base ones. */
  private styleFor(state: TextState): TextAppearance {
    if (state === 'base') return this.o;
    const s = state === 'hover' ? this.o.hover : this.o.pressed;
    if (!s) return this.o;
    return {
      color: s.color ?? this.o.color,
      stroke: s.stroke !== undefined ? s.stroke : this.o.stroke,
      shadow: s.shadow !== undefined ? s.shadow : this.o.shadow,
      glow: s.glow !== undefined ? s.glow : this.o.glow,
      background: s.background !== undefined ? s.background : this.o.background,
      underline: s.underline !== undefined ? s.underline : this.o.underline,
      strikethrough: s.strikethrough !== undefined ? s.strikethrough : this.o.strikethrough,
    };
  }

  // ── Font resolution ──

  private cssFont(): string {
    if (this.o.font) return this.o.font;
    const style = this.o.fontStyle === 'normal' ? '' : `${this.o.fontStyle} `;
    return `${style}${this.o.fontWeight} ${this.o.fontSize}px ${this.o.fontFamily}`;
  }

  /** The em size the layout uses — parsed out of a `font` shorthand when given. */
  private emSize(): number {
    if (!this.o.font) return this.o.fontSize;
    const m = /(\d*\.?\d+)px/.exec(this.o.font);
    return m ? parseFloat(m[1]) : this.o.fontSize;
  }

  private applyFont(ctx: CanvasRenderingContext2D): void {
    ctx.font = this.cssFont();
    if (hasLetterSpacing()) ctx.letterSpacing = `${this.o.letterSpacing}px`;
    ctx.direction = this.resolvedDirection;
  }

  // ── Layout ──

  private ensureLayout(): void { if (this.dirty) this.layout(); }

  private layout(): void {
    const ctx = measurer();
    ctx.save();
    this.applyFont(ctx);
    const em = this.emSize();
    const lh = em * this.o.lineHeight;
    const pad = this.o.padding;

    if (this.o.vertical) {
      // Tategaki: `maxWidth` caps a COLUMN's length; columns are one em wide.
      const cols = this.layoutVertical(em);
      this._lines = cols;
      this._width = cols.length * lh + pad * 2;
      this._height = (cols.length ? Math.max(...cols.map((c) => c.width)) : 0) + pad * 2;
    } else {
      const lines: Line[] = [];
      for (const para of this._text.split('\n')) {
        if (!this.o.maxWidth) { lines.push({ text: para, width: ctx.measureText(para).width }); continue; }
        for (const l of this.wrap(ctx, para, this.o.maxWidth)) lines.push(l);
      }
      this._lines = lines;
      this._width = (lines.length ? Math.max(...lines.map((l) => l.width)) : 0) + pad * 2;
      this._height = lines.length * lh + pad * 2;
    }
    ctx.restore();
    this.dirty = false;
  }

  /**
   * Greedy wrap at the script-correct break opportunities: take the LAST
   * opportunity that still fits, and hard-break by grapheme when even the first
   * one overflows (a long URL, or CJK with no opportunities at all).
   */
  private wrap(ctx: CanvasRenderingContext2D, para: string, max: number): Line[] {
    if (!para) return [{ text: '', width: 0 }];
    const ends = breakOpportunities(para, this.o.locale).filter((i) => i > 0 && i < para.length);
    ends.push(para.length);
    const out: Line[] = [];
    const trimEnd = (s: string): string => s.replace(/\s+$/, '');
    let start = 0;
    let i = 0;
    while (start < para.length) {
      while (i < ends.length && ends[i] <= start) i++;
      let fit = -1, j = i;
      while (j < ends.length) {
        const t = trimEnd(para.slice(start, ends[j]));
        if (ctx.measureText(t).width > max) break;
        fit = ends[j];
        j++;
      }
      if (fit < 0) {
        // Even the first opportunity overflows — consume as many graphemes as fit.
        const chunk = para.slice(start, ends[i] ?? para.length);
        let buf = '';
        for (const g of graphemes(chunk, this.o.locale)) {
          if (buf && ctx.measureText(buf + g).width > max) break;
          buf += g;
        }
        if (!buf) buf = chunk.slice(0, 1) || para.slice(start, start + 1);   // always progress
        out.push({ text: buf, width: ctx.measureText(buf).width });
        start += buf.length;
        continue;
      }
      const line = trimEnd(para.slice(start, fit));
      out.push({ text: line, width: ctx.measureText(line).width });
      start = fit;
      while (para[start] === ' ') start++;
      i = j;
    }
    return out.length ? out : [{ text: '', width: 0 }];
  }

  /** Vertical columns: graphemes stack downward, `maxWidth` caps the run length. */
  private layoutVertical(em: number): Line[] {
    const step = em * this.o.lineHeight;
    const capacity = this.o.maxWidth > 0 ? Math.max(1, Math.floor(this.o.maxWidth / step)) : Infinity;
    const cols: Line[] = [];
    for (const para of this._text.split('\n')) {
      const gs = graphemes(para, this.o.locale);
      let buf: string[] = [];
      for (const g of gs) {
        if (buf.length >= capacity && !NO_LINE_START.includes(g)) {
          cols.push({ text: buf.join(''), width: buf.length * step });
          buf = [];
        }
        buf.push(g);
      }
      cols.push({ text: buf.join(''), width: buf.length * step });
    }
    return cols;
  }

  // ── Raster ──

  /** Per-side px of canvas the stroke/shadow/glow/plate ink needs beyond the text box. */
  private inkBleed(state: TextState): Bleed {
    const s = this.styleFor(state);
    let l = 2, t = 2, r = 2, b = 2;
    const grow = (n: number): void => { l = Math.max(l, n); t = Math.max(t, n); r = Math.max(r, n); b = Math.max(b, n); };

    if (s.stroke) grow((s.stroke.width ?? 4) * (s.stroke.align === 'center' ? 0.5 : 1) + 1);
    if (s.glow) grow((s.glow.blur ?? 12) + 2);
    if (s.background) grow((s.background.padding ?? 12) + (s.background.borderWidth ?? 0) + 2);
    // Shadows are DIRECTIONAL — a shadow at +4/+5 spills right and down only.
    for (const sh of shadowList(s.shadow)) {
      const x = sh.x ?? 0, y = sh.y ?? 0, blur = (sh.blur ?? 0) + 2;
      l = Math.max(l, blur - x);
      r = Math.max(r, blur + x);
      t = Math.max(t, blur - y);
      b = Math.max(b, blur + y);
    }
    // A rule under the last line can sit below the line box on a tight lineHeight.
    if (s.underline) b = Math.max(b, this.emSize() * 0.25);
    return { l: Math.ceil(l), t: Math.ceil(t), r: Math.ceil(r), b: Math.ceil(b) };
  }

  /** Paint one state's block into a fresh canvas at `res`× supersampling. */
  private raster(state: TextState, res: number): Variant {
    this.ensureLayout();
    const s = this.styleFor(state);
    const em = this.emSize();
    const lh = em * this.o.lineHeight;
    const pad = this.o.padding;
    const bleed = this.inkBleed(state);
    const boxW = this._width - pad * 2;
    const boxH = this._height - pad * 2;

    // Never exceed the texture limit — coarsen the raster instead (and remember
    // the ceiling, so ensureRaster doesn't retry a bigger one every frame).
    const spanW = this._width + bleed.l + bleed.r;
    const spanH = this._height + bleed.t + bleed.b;
    let r = res;
    let capRes = Infinity;
    if (spanW * r > MAX_TEX || spanH * r > MAX_TEX) {
      r = Math.max(0.05, Math.min(MAX_TEX / Math.max(1, spanW), MAX_TEX / Math.max(1, spanH)));
      capRes = r;
    }
    const cw = Math.min(MAX_TEX, Math.max(1, Math.ceil(spanW * r)));
    const ch = Math.min(MAX_TEX, Math.max(1, Math.ceil(spanH * r)));

    const c = document.createElement('canvas');
    c.width = cw;
    c.height = ch;
    const ctx = c.getContext('2d')!;
    ctx.scale(r, r);
    this.applyFont(ctx);
    ctx.textBaseline = 'alphabetic';

    // Where the TEXT starts inside the raster: past the ink bleed, then the pad.
    const ox = bleed.l + pad;
    const oy = bleed.t + pad;

    this.paintBackground(ctx, s, ox, oy, boxW, boxH);
    const fill = this.makeFill(ctx, s, ox, oy, boxW, boxH);

    if (this.o.vertical) this.paintVertical(ctx, s, ox, oy, lh, em, fill);
    else this.paintHorizontal(ctx, s, ox, oy, boxW, lh, em, fill);

    return { canvas: c, tex: null, res: r, capRes, bleed, epoch: -1 };
  }

  private paintBackground(
    ctx: CanvasRenderingContext2D, s: TextAppearance, ox: number, oy: number, w: number, h: number,
  ): void {
    const bg = s.background;
    if (!bg) return;
    const p = bg.padding ?? 12;
    const rad = bg.radius ?? 0;
    const x = ox - p, y = oy - p, bw = w + p * 2, bh = h + p * 2;
    ctx.beginPath();
    if (rad > 0 && typeof ctx.roundRect === 'function') ctx.roundRect(x, y, bw, bh, rad);
    else ctx.rect(x, y, bw, bh);
    if (bg.color) { ctx.fillStyle = bg.color; ctx.fill(); }
    if (bg.borderWidth) {
      ctx.lineWidth = bg.borderWidth;
      ctx.strokeStyle = bg.borderColor ?? '#ffffff';
      ctx.stroke();
    }
  }

  /** The fill style: a colour string, or a gradient built across the block. */
  private makeFill(
    ctx: CanvasRenderingContext2D, s: TextAppearance,
    ox: number, oy: number, boxW: number, boxH: number,
  ): string | CanvasGradient {
    const col = s.color ?? '#ffffff';
    if (typeof col === 'string') return col;
    const stops: Array<[number, string]> = 'stops' in col
      ? col.stops.map((v, i, a): [number, string] => (typeof v === 'string' ? [a.length === 1 ? 0 : i / (a.length - 1), v] : v))
      : [[0, col.top], [1, col.bottom]];
    const angle = ('stops' in col ? col.angle : undefined) ?? 90;
    const rad = (angle * Math.PI) / 180;
    // A gradient spanning the block, so a multi-line title ramps as one piece.
    const cx = ox + boxW / 2, cy = oy + boxH / 2;
    const len = Math.abs(Math.cos(rad)) * boxW + Math.abs(Math.sin(rad)) * boxH;
    const g = ctx.createLinearGradient(
      cx - (Math.cos(rad) * len) / 2, cy - (Math.sin(rad) * len) / 2,
      cx + (Math.cos(rad) * len) / 2, cy + (Math.sin(rad) * len) / 2,
    );
    for (const [at, c] of stops) g.addColorStop(Math.max(0, Math.min(1, at)), c);
    return g;
  }

  /** Where a line's anchor x sits, and which canvas textAlign to use for it. */
  private anchor(ox: number, boxW: number): { x: number; align: CanvasTextAlign } {
    const rtl = this.resolvedDirection === 'rtl';
    const a = this.o.align ?? (rtl ? 'right' : 'left');
    if (a === 'center') return { x: ox + boxW / 2, align: 'center' };
    if (a === 'right') return { x: ox + boxW, align: 'right' };
    return { x: ox, align: 'left' };
  }

  private paintHorizontal(
    ctx: CanvasRenderingContext2D, s: TextAppearance, ox: number, oy: number, boxW: number,
    lh: number, em: number, fill: string | CanvasGradient,
  ): void {
    const { x, align } = this.anchor(ox, boxW);
    ctx.textAlign = align;
    // Sit the first baseline sensibly inside its line box.
    const baseline = oy + em * 0.82 + (lh - em) / 2;
    for (let i = 0; i < this._lines.length; i++) {
      const line = this._lines[i];
      const y = baseline + i * lh;
      this.paintOne(ctx, s, line.text, x, y, fill);
      this.paintRules(ctx, s, line, x, y, em, fill);
    }
  }

  /** Underline / strikethrough for one laid-out line. */
  private paintRules(
    ctx: CanvasRenderingContext2D, s: TextAppearance, line: Line,
    anchorX: number, baseline: number, em: number, fill: string | CanvasGradient,
  ): void {
    if (!s.underline && !s.strikethrough) return;
    if (!line.width) return;
    const a = ctx.textAlign;
    const x0 = a === 'center' ? anchorX - line.width / 2 : a === 'right' ? anchorX - line.width : anchorX;
    const rule = (spec: boolean | TextRule, dy: number): void => {
      const r = spec === true ? {} : spec as TextRule;
      const th = r.thickness ?? Math.max(1, em * 0.06);
      ctx.fillStyle = r.color ?? fill;
      ctx.fillRect(x0, baseline + dy + (r.offset ?? 0) - th / 2, line.width, th);
    };
    if (s.underline) rule(s.underline, em * 0.14);
    if (s.strikethrough) rule(s.strikethrough, -em * 0.28);
  }

  private paintVertical(
    ctx: CanvasRenderingContext2D, s: TextAppearance, ox: number, oy: number,
    lh: number, em: number, fill: string | CanvasGradient,
  ): void {
    ctx.textAlign = 'center';
    const cols = this._lines;
    for (let ci = 0; ci < cols.length; ci++) {
      // Columns run RIGHT to LEFT — the first column is the rightmost.
      const cx = ox + (cols.length - 1 - ci) * lh + lh / 2;
      const gs = graphemes(cols[ci].text, this.o.locale);
      for (let gi = 0; gi < gs.length; gi++) {
        const g = gs[gi];
        const cy = oy + gi * lh + em * 0.82 + (lh - em) / 2;
        if (VERTICAL_ROTATE.includes(g)) {
          ctx.save();
          ctx.translate(cx, cy - em * 0.32);
          ctx.rotate(Math.PI / 2);
          this.paintOne(ctx, s, g, 0, em * 0.32, fill);
          ctx.restore();
        } else if (VERTICAL_NUDGE.includes(g)) {
          this.paintOne(ctx, s, g, cx + em * 0.4, cy - em * 0.55, fill);
        } else {
          this.paintOne(ctx, s, g, cx, cy, fill);
        }
      }
    }
  }

  /** One run of text: shadows → glow → stroke → fill, in that order. */
  private paintOne(
    ctx: CanvasRenderingContext2D, s: TextAppearance,
    str: string, x: number, y: number, fill: string | CanvasGradient,
  ): void {
    if (!str) return;
    const st = s.stroke;
    const strokeW = st ? (st.width ?? 4) * (st.align === 'center' ? 1 : 2) : 0;

    // Shadows: cast by the SILHOUETTE (stroke + fill), so an outlined title
    // throws the outline's shadow, not a thin inner one.
    for (const sh of shadowList(s.shadow)) {
      ctx.save();
      ctx.shadowOffsetX = sh.x ?? 0;
      ctx.shadowOffsetY = sh.y ?? 0;
      ctx.shadowBlur = sh.blur ?? 0;
      ctx.shadowColor = sh.color ?? 'rgba(0,0,0,0.6)';
      ctx.fillStyle = '#000';
      if (strokeW > 0) {
        ctx.lineWidth = strokeW;
        ctx.lineJoin = st!.join ?? 'round';
        ctx.strokeStyle = '#000';
        ctx.strokeText(str, x, y);
      }
      ctx.fillText(str, x, y);
      ctx.restore();
    }

    // Glow: an un-offset blurred halo, stacked to build intensity.
    const gl = s.glow;
    if (gl) {
      ctx.save();
      ctx.shadowOffsetX = 0;
      ctx.shadowOffsetY = 0;
      ctx.shadowBlur = gl.blur ?? 12;
      ctx.shadowColor = gl.color ?? '#ffffff';
      ctx.fillStyle = gl.color ?? '#ffffff';
      const n = Math.max(1, Math.min(6, Math.round(gl.strength ?? 3)));
      for (let i = 0; i < n; i++) ctx.fillText(str, x, y);
      ctx.restore();
    }

    if (strokeW > 0) {
      ctx.lineWidth = strokeW;
      ctx.lineJoin = st!.join ?? 'round';
      ctx.miterLimit = 2;
      ctx.strokeStyle = st!.color ?? '#000000';
      ctx.strokeText(str, x, y);
    }
    ctx.fillStyle = fill;
    ctx.fillText(str, x, y);
  }

  // ── Submission ───────────────────────────────────────────────────────────

  /**
   * @internal Push this block's quad into `r` at (x, y). Called by
   * `d.unicodeText()`; the surface passes its own renderer (which is why the
   * SAME object can be drawn in world space and on the HUD) and its pointer.
   */
  submit(
    r: MsdfRenderer, x: number, y: number, opts: UnicodeDrawOptions = {},
    pointer?: (() => TextPointer | null) | null,
  ): void {
    const state = this.updateInput(x, y, opts, pointer);
    const stateStyle = state === 'hover' ? this.o.hover : state === 'pressed' ? this.o.pressed : undefined;
    const scale = (opts.scale ?? 1) * (stateStyle?.scale ?? 1);

    const v = this.ensureRaster(state, r.pxPerUnit * Math.abs(scale));
    const view = v.tex?.view;
    if (!view) return;

    const rot = opts.rotation ?? 0;
    const a = (opts.alpha ?? 1) * (stateStyle?.alpha ?? 1);
    const col = packColor(tintRGB(opts.tint), a);
    const depth = opts.z ?? 0;

    // Quad size in draw units: the raster back at 1× (it includes the bleed).
    const qw = v.canvas.width / v.res;
    const qh = v.canvas.height / v.res;
    // The ORIGIN is the text BLOCK's, not the raster's — bleed must not shift it.
    const ox = (opts.origin?.x ?? 0) * this._width + v.bleed.l;
    const oy = (opts.origin?.y ?? 0) * this._height + v.bleed.t;
    const cos = Math.cos(rot), sin = Math.sin(rot);
    const wx = (lx: number, ly: number): number => {
      const sx = (lx - ox) * scale, sy = (ly - oy) * scale;
      return x + (sx * cos - sy * sin);
    };
    const wy = (lx: number, ly: number): number => {
      const sx = (lx - ox) * scale, sy = (ly - oy) * scale;
      return y + (sx * sin + sy * cos);
    };

    const o = r.alloc(view);
    const f = r.f32, u = r.u32;
    f[o] = wx(0, 0); f[o + 1] = wy(0, 0);
    f[o + 2] = wx(qw, 0); f[o + 3] = wy(qw, 0);
    f[o + 4] = wx(0, qh); f[o + 5] = wy(0, qh);
    f[o + 6] = wx(qw, qh); f[o + 7] = wy(qw, qh);
    f[o + 8] = 0; f[o + 9] = 0; f[o + 10] = 1; f[o + 11] = 1;
    u[o + 12] = col; u[o + 13] = col; u[o + 14] = col; u[o + 15] = col;
    u[o + 16] = 0; u[o + 17] = 0; u[o + 18] = 0; u[o + 19] = 0;
    u[o + 20] = BITMAP_PARAMS; u[o + 21] = BITMAP_PARAMS; u[o + 22] = BITMAP_PARAMS; u[o + 23] = BITMAP_PARAMS;
    f[o + 24] = 0; f[o + 25] = 0; f[o + 26] = depth; f[o + 27] = 0;
  }

  /**
   * Hit-test the pointer and advance the press/click edge machine. Returns the
   * state to draw. A click needs the press AND the release on this block, so a
   * drag that began elsewhere can't trigger it.
   */
  private updateInput(
    x: number, y: number, opts: UnicodeDrawOptions,
    read?: (() => TextPointer | null) | null,
  ): TextState {
    this._clicked = false;
    // The getter is called ONLY for an interactive block: reading it is what
    // makes the surface attach its pointer listeners, and a game full of static
    // labels should not pay for that.
    if (!this.isInteractive) return 'base';
    const pointer = read?.() ?? null;
    if (!pointer) { this._hovered = false; this._down = false; this.armed = false; this.prevDown = false; return 'base'; }

    const box = this.hitBounds(x, y, opts);
    const over = pointer.x >= box.x && pointer.x <= box.right && pointer.y >= box.y && pointer.y <= box.bottom;
    this._hovered = over;
    this._down = pointer.down;

    if (pointer.down && !this.prevDown) this.armed = over;         // press started here?
    if (!pointer.down && this.prevDown && this.armed && over) {
      this._clicked = true;
      for (const fn of this.clickFns) fn(this);
    }
    if (!pointer.down) this.armed = false;
    this.prevDown = pointer.down;

    if (over && (this.o.cursor ?? true)) pointer.wantCursor?.();
    if (over && pointer.down && this.armed && this.o.pressed) return 'pressed';
    if (over && this.o.hover) return 'hover';
    return 'base';
  }

  /**
   * Rasterize + upload this state if needed. `wanted` is how many device pixels
   * one draw unit covers this frame: the block re-rasterizes when it would
   * otherwise be drawn blurry. Quantised to half-steps and RAISE-ONLY (below
   * the cap), so a zooming camera can't churn a fresh texture every frame.
   */
  private ensureRaster(state: TextState, wanted: number): Variant {
    this.ensureLayout();
    const pinned = this.o.resolution;
    // Quantise to half-steps, tolerating ~10% under-sampling before stepping up:
    // without the slack a 1.04 hover scale would jump straight to a 1.5× raster
    // (2.25× the texture) for a difference nobody can see.
    const auto = Math.max(1, Math.min(4, Math.ceil((wanted / 1.1) * 2) / 2));
    const have = this.variants.get(state);
    const target = Math.min(pinned ?? auto, have?.capRes ?? Infinity);
    const epoch = this.host.epoch();
    if (have && have.epoch === epoch && have.res >= target) return have;

    const v = this.raster(state, Math.max(target, have && have.epoch !== epoch ? have.res : 0));
    have?.tex?.destroy();
    v.tex = this.host.textTexture(v.canvas);
    v.epoch = epoch;
    this.variants.set(state, v);
    return v;
  }
}

function shadowList(s: TextShadow | TextShadow[] | null | undefined): TextShadow[] {
  return !s ? [] : Array.isArray(s) ? s : [s];
}

/** A hex tint → 0xRRGGBB (white when absent). */
function tintRGB(hex: string | undefined): number {
  if (!hex) return 0xffffff;
  const [r, g, b] = rgba(hex);
  return ((r * 255) << 16) | ((g * 255) << 8) | (b * 255) | 0;
}
