/** Tween / motion / animation system. The Game owns one as `this.tween`. Animate / ease / interpolate any numeric or colour-string property with `this.tween.to(sprite, { x: 200 })`. Driven by the game clock — tweens freeze automatically when the game pauses. */

import {
  Tweenable,
  processTweens,
  interpolate as shiftyInterpolate,
  standardEasingFunctions,
} from './shifty/index.js';
import type { TweenState, RenderFunction, Easing } from './shifty/index.js';

const EASE_ALIASES: Record<string, string> = {
  linear: 'linear',
  quad: 'easeInOutQuad',
  cubic: 'easeInOutCubic',
  quart: 'easeInOutQuart',
  quint: 'easeInOutQuint',
  sine: 'easeInOutSine',
  expo: 'easeInOutExpo',
  circ: 'easeInOutCirc',
  back: 'easeOutBack',
  bounce: 'easeOutBounce',
};

/** An easing curve: a named standard curve (e.g. `'easeOutBounce'`), a short alias (`'bounce'`/`'quad'`/`'linear'`), a custom `(pos) => value` function, or a CSS cubic-bezier `[x1,y1,x2,y2]` array. See `EASING` for all accepted names. */
export type Ease = string | ((pos: number) => number) | number[];

const resolveEase = (ease?: Ease): Ease => {
  if (ease == null) return 'easeInOutQuad';
  if (typeof ease === 'string') return EASE_ALIASES[ease] ?? ease;
  return ease;
};

/** All easing curve names accepted by `TweenOptions.ease` — standard shifty curves plus the short aliases. */
export const EASING: string[] = [
  ...Object.keys(standardEasingFunctions),
  ...Object.keys(EASE_ALIASES),
];

/** Options for `tween.to / from / fromTo`. All fields are optional. */
export interface TweenOptions<T = object> {
  /** Duration in seconds. Default 0.5. */
  duration?: number;
  /** Easing curve name, function, or cubic-bezier array. Default `'easeInOutQuad'`. See `Ease` / `EASING`. */
  ease?: Ease;
  /** Delay in seconds before the animation starts. Default 0. */
  delay?: number;
  /** Called once when the tween begins (after any delay). */
  onStart?: (target: T) => void;
  /** Called every frame with the mutated target and progress 0→1 through the current run. */
  onUpdate?: (target: T, progress: number) => void;
  /** Called once when the tween (and all loops) finish. */
  onComplete?: (target: T) => void;
  /** Repeat the tween: `true` = loop forever, a number = that many additional repeats. Default none. */
  loop?: boolean | number;
  /** With `loop` — reverse direction on each repeat (ping-pong / yo-yo). */
  yoyo?: boolean;
}

/**
 * A running tween handle. Returned by `tween.to` / `tween.from` / `tween.fromTo`. Supports `pause`, `resume`, `stop`, `seek`, and `await` (resolves when the tween finishes; never resolves for infinite loops).
 */
export class TweenHandle {
  private readonly _owner: Tween;
  private _tw: Tweenable;
  private _target: Record<string, number | string>;
  private _from: TweenState;
  private _to: TweenState;
  private _opts: TweenOptions;
  private _loopsLeft: number;
  private _yoyo: boolean;
  private _done = false;
  private _started = false;
  private _progress = 0;
  private _resolve: (() => void) | null = null;
  private _promise: Promise<void> | null = null;

  /** @ignore — construct via `tween.to / from / fromTo`, not directly. */
  constructor(
    owner: Tween,
    target: object,
    from: TweenState,
    to: TweenState,
    opts: TweenOptions,
  ) {
    this._owner = owner;
    this._target = target as Record<string, number | string>;
    this._from = from;
    this._to = to;
    this._opts = opts;
    this._yoyo = !!opts.yoyo;
    this._loopsLeft =
      opts.loop === true
        ? Infinity
        : typeof opts.loop === 'number'
          ? opts.loop
          : 0;
    this._tw = new Tweenable();
    owner._active.add(this);
    this._run();
  }

  private _run(): void {
    const durationMs = (this._opts.duration ?? 0.5) * 1000;
    const render: RenderFunction = (state, elapsedMs) => {
      Object.assign(this._target, state);
      this._progress = durationMs > 0 ? Math.min(1, Math.max(0, elapsedMs / durationMs)) : 1;
      this._opts.onUpdate?.(this._target, this._progress);
    };
    this._tw.tween({
      from: { ...this._from },
      to: { ...this._to },
      duration: durationMs,
      delay: (this._opts.delay ?? 0) * 1000,
      easing: resolveEase(this._opts.ease) as Easing,
      start: () => {
        if (this._started) return;
        this._started = true;
        this._opts.onStart?.(this._target);
      },
      render,
      finish: () => this._onFinish(),
    });
  }

  private _onFinish(): void {
    if (this._loopsLeft > 0) {
      this._loopsLeft--;
      if (this._yoyo) {
        const t = this._from;
        this._from = this._to;
        this._to = t;
      }
      this._run();
      return;
    }
    if (this._done) return;
    this._done = true;
    this._owner._active.delete(this);
    this._opts.onComplete?.(this._target);
    this._resolve?.();
  }

  /** Pause this tween. Resume with `resume()`. */
  pause(): this {
    this._tw.pause();
    return this;
  }

  /** Resume this tween from where `pause()` left it. */
  resume(): this {
    this._tw.resume();
    return this;
  }

  /** Stop this tween immediately. Pass `jumpToEnd = true` to snap the target to its end values first. Cancels any remaining loop repeats. */
  stop(jumpToEnd = false): this {
    if (this._done) return this;
    this._loopsLeft = 0;
    if (jumpToEnd) {
      Object.assign(this._target, this._to);
      this._progress = 1;
    }
    this._tw.stop();
    if (!this._done) this._onFinish();
    return this;
  }

  /** Jump the tween's playhead to `seconds` from its start (scrub / seek). */
  seek(seconds: number): this {
    this._tw.seek(seconds * 1000);
    return this;
  }

  /** `true` while the tween is advancing (not paused, not finished). */
  get isPlaying(): boolean {
    return this._tw.isPlaying;
  }

  /** `true` once the tween (and all loop repeats) have finished. */
  get isDone(): boolean {
    return this._done;
  }

  /** Normalised progress through the current run, 0→1. Poll this instead of tracking elapsed time yourself. */
  get progress(): number {
    return this._progress;
  }

  /** Makes the handle thenable — `await handle` resolves when the tween finishes. Never resolves for infinite loops. */
  then<R = void>(
    onFulfilled?: (() => R | PromiseLike<R>) | null,
    onRejected?: ((reason: unknown) => R | PromiseLike<R>) | null,
  ): Promise<R> {
    if (!this._promise) {
      this._promise = this._done
        ? Promise.resolve()
        : new Promise<void>((res) => {
            this._resolve = res;
          });
    }
    return this._promise.then(onFulfilled ?? undefined, onRejected ?? undefined);
  }
}

/** A batch handle over several `TweenHandle` instances — pause, resume, stop, or await all of them together. Returned by `tween.group(...)`. */
export interface TweenGroup {
  /** Pause all handles in the group. */
  pause(): void;
  /** Resume all handles in the group. */
  resume(): void;
  /** Stop all handles in the group. Pass `true` to jump each to its end values. */
  stop(jumpToEnd?: boolean): void;
  /** Resolves when every handle in the group has finished. */
  then<R = void>(onFulfilled?: () => R | PromiseLike<R>): Promise<R>;
}

const pick = (
  target: Record<string, number | string>,
  props: Record<string, number | string>,
): TweenState => {
  const out: TweenState = {};
  for (const k in props) out[k] = target[k];
  return out;
};

/** @internal Keys already warned about, so a misused tween in a loop warns once, not every frame. */
const _warnedTweenKeys = new Set<string>();

/**
 * @internal Dev guard: a tween only interpolates numbers and colour strings. If a
 * target property is a `Vec2` (`scale`/`position`/`velocity`/`size`/…), tweening the
 * field itself overwrites the `{x,y}` object with a number and the sprite renders at
 * `NaN` — silently. Point the caller at the working pattern instead of failing quietly.
 */
const warnIfObjectProps = (target: object, keys: TweenState): void => {
  if (typeof console === 'undefined') return;
  const t = target as Record<string, unknown>;
  for (const k in keys) {
    const v = t[k];
    if (typeof v === 'object' && v !== null && !_warnedTweenKeys.has(k)) {
      _warnedTweenKeys.add(k);
      console.warn(
        `[tween] "${k}" is an object (a Vec2 like scale/position?), not a number — ` +
          `tween its axes instead: tween.to(obj.${k}, { x, y }). ` +
          `Tweening the object itself overwrites it and renders at NaN.`,
      );
    }
  }
};

/**
 * The motion / animation / tween system. The Game owns one as `this.tween` (accessed on any scene as `this.tween`). The Game advances it every frame — call `this.tween.to(sprite, { x: 200 })` and the rest is automatic.
 */
export class Tween {
  private clockMs = 0;
  private _paused = false;

  /** @internal Active tween handles. Used for `count` / `stopAll`. */
  readonly _active = new Set<TweenHandle>();

  constructor() {
    Tweenable.setScheduleFunction(() => {});
    Tweenable.now = () => this.clockMs;
  }

  /** Animate `target`'s properties FROM their current values TO `props`. The most common tween call — e.g. `tween.to(sprite, { x: 200, alpha: 0 }, { duration: 0.4 })`. */
  to<T extends object>(
    target: T,
    props: Partial<Record<keyof T & string, number | string>>,
    opts: TweenOptions<T> = {},
  ): TweenHandle {
    const t = target as Record<string, number | string>;
    const to = props as Record<string, number | string>;
    warnIfObjectProps(target, to);
    return new TweenHandle(this, target, pick(t, to), { ...to }, opts as TweenOptions);
  }

  /** Animate `target`'s properties FROM `props` TO their current values — use to animate / slide / fade something in from a starting position. */
  from<T extends object>(
    target: T,
    props: Partial<Record<keyof T & string, number | string>>,
    opts: TweenOptions<T> = {},
  ): TweenHandle {
    const t = target as Record<string, number | string>;
    const from = props as Record<string, number | string>;
    warnIfObjectProps(target, from);
    return new TweenHandle(this, target, { ...from }, pick(t, from), opts as TweenOptions);
  }

  /** Animate `target`'s properties from `fromProps` to `toProps` with full explicit control over both endpoints. */
  fromTo<T extends object>(
    target: T,
    fromProps: Partial<Record<keyof T & string, number | string>>,
    toProps: Partial<Record<keyof T & string, number | string>>,
    opts: TweenOptions<T> = {},
  ): TweenHandle {
    warnIfObjectProps(target, toProps as Record<string, number | string>);
    return new TweenHandle(
      this,
      target,
      { ...(fromProps as Record<string, number | string>) },
      { ...(toProps as Record<string, number | string>) },
      opts as TweenOptions,
    );
  }

  /**
   * Run tween steps one after another in a chain — each step starts when the previous one finishes. Each element is a function that returns a `TweenHandle` or any `Promise`. Returns a promise that resolves when the whole sequence is done.
   */
  sequence(steps: Array<() => TweenHandle | Promise<unknown> | void>): Promise<void> {
    let p: Promise<unknown> = Promise.resolve();
    for (const step of steps) p = p.then(() => step() ?? undefined);
    return p.then(() => undefined);
  }

  /** Group several `TweenHandle` instances for unified pause/resume/stop/await. */
  group(...handles: TweenHandle[]): TweenGroup {
    return {
      pause: () => handles.forEach((h) => h.pause()),
      resume: () => handles.forEach((h) => h.resume()),
      stop: (jumpToEnd = false) => handles.forEach((h) => h.stop(jumpToEnd)),
      then: <R = void>(onFulfilled?: () => R | PromiseLike<R>) =>
        Promise.all(handles.map((h) => h.then())).then(() =>
          onFulfilled ? onFulfilled() : (undefined as R),
        ),
    };
  }

  /**
   * Compute a one-off interpolated / lerped snapshot (no animation, no handle). Works on numbers and colour strings: `tween.interpolate({ v: 0 }, { v: 10 }, 0.5).v === 5`.
   */
  interpolate: typeof shiftyInterpolate = shiftyInterpolate;

  /** All easing curve names accepted by `TweenOptions.ease`. */
  get EASING(): string[] {
    return EASING;
  }

  /** Advance the clock by `deltaSeconds` and step all active tweens. Called automatically by the Game loop — do not call this yourself. */
  update(deltaSeconds: number): void {
    if (this._paused) return;
    this.clockMs += deltaSeconds * 1000;
    processTweens();
  }

  /** Freeze every active tween WITHOUT stopping the game loop — use when displaying a pause overlay. */
  pauseAll(): void {
    this._paused = true;
  }

  /** Unfreeze every tween after `pauseAll()`. */
  resumeAll(): void {
    this._paused = false;
  }

  /** Alias of `pauseAll()` — the hook a state machine's suspend calls. */
  pause(): void {
    this._paused = true;
  }

  /** Alias of `resumeAll()`. */
  resume(): void {
    this._paused = false;
  }

  /** Stop every active tween (e.g. on a level reset). Pass `true` to snap each tween to its end values. */
  stopAll(jumpToEnd = false): void {
    for (const h of [...this._active]) h.stop(jumpToEnd);
  }

  /** Number of currently active (running or paused) tweens. */
  get count(): number {
    return this._active.size;
  }

  /** `true` when the whole system is frozen by `pauseAll()`. */
  get isPaused(): boolean {
    return this._paused;
  }

  /** Stop all tweens and tear down the system. Called automatically by `Game.destroy()`. */
  destroy(): void {
    this.stopAll();
  }
}
