// TRUE per-object glow — the Godot/Photoshop outer-glow look. In-shader tap
// rings can never reach that width and smoothness, so this is the real
// technique: every glowing sprite stamps its TINTED SILHOUETTE (alpha ×
// colour, additive so overlaps sum) into a HALF-RESOLUTION target; the
// target gets a separable gaussian blur (H→V, two iterations, spread scaled
// by the largest requested glow size); the result composites ADDITIVELY over
// the scene — wide, luminous, perfectly smooth halos, and the half-res
// upsample smooths it further for free.
//
// Cost when no sprite glows: zero (no passes run). With glows: one stamp
// pass + 4 blur passes at half res + 1 fullscreen composite.

import { BITS } from './gpu.js';
import { DEPTH_FORMAT } from './batch.js';
import type { Frame } from './atlas.js';

const FLOATS = 16; // posSize | rot+flip+pad2 | color | uvRect

const STAMP_WGSL = /* wgsl */ `
struct U { view: vec4f }
struct Inst { posSize: vec4f, misc: vec4f, color: vec4f, uv: vec4f }
struct VSOut { @builtin(position) pos: vec4f, @location(0) uv: vec2f, @location(1) color: vec4f }
@group(0) @binding(0) var<uniform> u: U;
@group(0) @binding(1) var<storage, read> inst: array<Inst>;
@group(0) @binding(2) var samp: sampler;
@group(0) @binding(3) var tex: texture_2d<f32>;

@vertex
fn vs(@builtin(vertex_index) vi: u32, @builtin(instance_index) ii: u32) -> VSOut {
  let d = inst[ii];
  let c01 = vec2f(f32(vi & 1u), f32(vi >> 1u));
  let centre = d.posSize.xy + d.posSize.zw * 0.5;
  let off = (c01 - 0.5) * d.posSize.zw;
  let sn = sin(d.misc.x);
  let cn = cos(d.misc.x);
  let world = centre + vec2f(off.x * cn - off.y * sn, off.x * sn + off.y * cn);
  let ndc = (world - u.view.xy) / u.view.zw * 2.0 - 1.0;
  var out: VSOut;
  out.pos = vec4f(ndc.x, -ndc.y, 0.0, 1.0);
  var ux = c01.x;
  if (d.misc.y > 0.5) { ux = 1.0 - ux; }
  out.uv = vec2f(mix(d.uv.x, d.uv.z, ux), mix(d.uv.y, d.uv.w, c01.y));
  out.color = d.color;
  return out;
}

@fragment
fn fs(in: VSOut) -> @location(0) vec4f {
  let a = textureSample(tex, samp, in.uv).a * in.color.a;
  return vec4f(in.color.rgb * a, a);   // tinted silhouette, additive-summed
}
`;

const BLUR_WGSL = /* wgsl */ `
struct U { dir: vec4f }   // xy = step (texel * spread * axis), zw unused
@group(0) @binding(0) var<uniform> u: U;
@group(0) @binding(1) var samp: sampler;
@group(0) @binding(2) var src: texture_2d<f32>;
struct VSOut { @builtin(position) pos: vec4f, @location(0) uv: vec2f }

@vertex
fn vs(@builtin(vertex_index) vi: u32) -> VSOut {
  var out: VSOut;
  let x = f32((vi << 1u) & 2u);
  let y = f32(vi & 2u);
  out.pos = vec4f(x * 2.0 - 1.0, 1.0 - y * 2.0, 0.0, 1.0);
  out.uv = vec2f(x, y);
  return out;
}

const W = array<f32, 7>(0.199, 0.176, 0.121, 0.065, 0.0275, 0.009, 0.0022);

@fragment
fn fs(in: VSOut) -> @location(0) vec4f {
  var acc = textureSample(src, samp, in.uv) * W[0];
  for (var i = 1u; i < 7u; i++) {
    let o = u.dir.xy * f32(i);
    acc += textureSample(src, samp, clamp(in.uv + o, vec2f(0.0), vec2f(1.0))) * W[i];
    acc += textureSample(src, samp, clamp(in.uv - o, vec2f(0.0), vec2f(1.0))) * W[i];
  }
  return acc;
}
`;

const COMPOSITE_WGSL = /* wgsl */ `
struct U { strength: vec4f }
@group(0) @binding(0) var<uniform> u: U;
@group(0) @binding(1) var samp: sampler;
@group(0) @binding(2) var src: texture_2d<f32>;
struct VSOut { @builtin(position) pos: vec4f, @location(0) uv: vec2f }

@vertex
fn vs(@builtin(vertex_index) vi: u32) -> VSOut {
  var out: VSOut;
  let x = f32((vi << 1u) & 2u);
  let y = f32(vi & 2u);
  out.pos = vec4f(x * 2.0 - 1.0, 1.0 - y * 2.0, 0.0, 1.0);
  out.uv = vec2f(x, y);
  return out;
}

@fragment
fn fs(in: VSOut) -> @location(0) vec4f {
  let g = textureSample(src, samp, in.uv);
  return vec4f(g.rgb * u.strength.x, 0.0);   // additive: pure light
}
`;

export class GlowPass {
  private data: Float32Array<ArrayBuffer> = new Float32Array(256 * FLOATS);
  private count = 0;
  private maxSize = 0;
  private extraActive = false;
  private view = new Float32Array(4);

  private device!: GPUDevice;
  private stampPipeline!: GPURenderPipeline;
  private blurPipeline!: GPURenderPipeline;
  private compositePipeline!: GPURenderPipeline;
  private stampLayout!: GPUBindGroupLayout;
  private fsLayout!: GPUBindGroupLayout;
  private sampler!: GPUSampler;
  private stampUniforms!: GPUBuffer;
  private blurUniformsH!: GPUBuffer;
  private blurUniformsV!: GPUBuffer;
  private compUniforms!: GPUBuffer;
  private instances!: GPUBuffer;
  private capacity = 256;
  private targets: [GPUTexture, GPUTexture] | null = null;
  private atlasView: GPUTextureView | null = null;
  private compBind: GPUBindGroup | null = null;

  constructor(device: GPUDevice, private format: GPUTextureFormat) {
    this.rebuild(device);
  }

  get active(): boolean {
    return this.count > 0 || this.extraActive;
  }

  /** @internal Another system (the vector layer) wants the blur this frame
   * even if no sprite stamps: mark active and feed its glow size into the
   * blur-spread measure. */
  wake(size: number): void {
    this.extraActive = true;
    this.maxSize = Math.max(this.maxSize, size);
  }

  /** @internal Start a frame with the world view rect. */
  begin(x: number, y: number, w: number, h: number): void {
    this.count = 0;
    this.maxSize = 0;
    this.extraActive = false;
    this.view.set([x, y, w, h]);
  }

  /** @internal Queue one glowing sprite's tinted silhouette (world coords). */
  stamp(
    x: number, y: number, w: number, h: number, f: Frame,
    rot: number, flipX: boolean,
    r: number, g: number, b: number, a: number, size: number,
  ): void {
    if (this.count === this.capacity) {
      this.capacity *= 2;
      const next = new Float32Array(this.capacity * FLOATS);
      next.set(this.data);
      this.data = next;
      this.instances.destroy();
      this.instances = this.device.createBuffer({ size: this.capacity * FLOATS * 4, usage: BITS.STORAGE | BITS.COPY_DST });
    }
    const o = this.count * FLOATS;
    const d = this.data;
    d[o] = x; d[o + 1] = y; d[o + 2] = w; d[o + 3] = h;
    d[o + 4] = rot; d[o + 5] = flipX ? 1 : 0; d[o + 6] = 0; d[o + 7] = 0;
    d[o + 8] = r; d[o + 9] = g; d[o + 10] = b; d[o + 11] = a;
    d[o + 12] = f.u0; d[o + 13] = f.v0; d[o + 14] = f.u1; d[o + 15] = f.v1;
    this.count++;
    this.maxSize = Math.max(this.maxSize, size);
  }

  /** @internal Render silhouette + blur chain (before the main 2D pass).
   * `extra` draws additional stamps into the same half-res pass (the vector
   * layer's soft line cores) — one blur serves every glowing thing. */
  render(encoder: GPUCommandEncoder, canvasW: number, canvasH: number, extra?: (pass: GPURenderPassEncoder) => void): void {
    const spriteStamps = this.count > 0 && !!this.atlasView;
    if (!spriteStamps && !this.extraActive) return;
    const w = Math.max(1, canvasW >> 1), h = Math.max(1, canvasH >> 1);
    if (!this.targets || this.targets[0].width !== w || this.targets[0].height !== h) {
      this.targets?.forEach((t) => t.destroy());
      const make = (): GPUTexture => this.device.createTexture({
        size: { width: w, height: h },
        format: this.format,
        usage: BITS.RENDER_ATTACHMENT | BITS.TEXTURE_BINDING,
      });
      this.targets = [make(), make()];
      this.compBind = null;
    }
    const [A, B] = this.targets;
    this.device.queue.writeBuffer(this.stampUniforms, 0, this.view);
    if (spriteStamps) {
      this.device.queue.writeBuffer(this.instances, 0, this.data.buffer, 0, this.count * FLOATS * 4);
    }

    // 1. stamp silhouettes into A (additive — overlapping glows sum)
    const p1 = encoder.beginRenderPass({
      colorAttachments: [{ view: A.createView(), loadOp: 'clear', clearValue: { r: 0, g: 0, b: 0, a: 0 }, storeOp: 'store' }],
    });
    if (spriteStamps) {
      const stampBind = this.device.createBindGroup({
        layout: this.stampLayout,
        entries: [
          { binding: 0, resource: { buffer: this.stampUniforms } },
          { binding: 1, resource: { buffer: this.instances } },
          { binding: 2, resource: this.sampler },
          { binding: 3, resource: this.atlasView! },
        ],
      });
      p1.setPipeline(this.stampPipeline);
      p1.setBindGroup(0, stampBind);
      p1.draw(4, this.count);
    }
    extra?.(p1);
    p1.end();

    // 2. separable blur, two iterations; spread follows the largest glow size
    const spread = Math.min(3, Math.max(0.6, this.maxSize / 10));
    this.device.queue.writeBuffer(this.blurUniformsH, 0, new Float32Array([spread / w, 0, 0, 0]));
    this.device.queue.writeBuffer(this.blurUniformsV, 0, new Float32Array([0, spread / h, 0, 0]));
    for (let i = 0; i < 2; i++) {
      this.blurTo(encoder, A, B, this.blurUniformsH);
      this.blurTo(encoder, B, A, this.blurUniformsV);
    }

  }

  private blurTo(encoder: GPUCommandEncoder, from: GPUTexture, to: GPUTexture, uniforms: GPUBuffer): void {
    const bind = this.device.createBindGroup({
      layout: this.fsLayout,
      entries: [
        { binding: 0, resource: { buffer: uniforms } },
        { binding: 1, resource: this.sampler },
        { binding: 2, resource: from.createView() },
      ],
    });
    const pass = encoder.beginRenderPass({
      colorAttachments: [{ view: to.createView(), loadOp: 'clear', clearValue: { r: 0, g: 0, b: 0, a: 0 }, storeOp: 'store' }],
    });
    pass.setPipeline(this.blurPipeline);
    pass.setBindGroup(0, bind);
    pass.draw(3);
    pass.end();
  }

  /** @internal Additively composite the blurred glow into the open scene pass. */
  composite(pass: GPURenderPassEncoder): void {
    if (!this.active || !this.targets) return;
    if (!this.compBind) {
      this.device.queue.writeBuffer(this.compUniforms, 0, new Float32Array([1.15, 0, 0, 0]));
      this.compBind = this.device.createBindGroup({
        layout: this.fsLayout,
        entries: [
          { binding: 0, resource: { buffer: this.compUniforms } },
          { binding: 1, resource: this.sampler },
          { binding: 2, resource: this.targets[0].createView() },
        ],
      });
    }
    pass.setPipeline(this.compositePipeline);
    pass.setBindGroup(0, this.compBind);
    pass.draw(3);
  }

  setTexture(view: GPUTextureView): void {
    this.atlasView = view;
  }

  rebuild(device: GPUDevice): void {
    this.device = device;
    this.targets = null;
    this.compBind = null;
    this.atlasView = null;
    this.sampler = device.createSampler({ magFilter: 'linear', minFilter: 'linear' });
    this.stampLayout = device.createBindGroupLayout({
      entries: [
        { binding: 0, visibility: BITS.STAGE_VERTEX, buffer: { type: 'uniform' } },
        { binding: 1, visibility: BITS.STAGE_VERTEX, buffer: { type: 'read-only-storage' } },
        { binding: 2, visibility: BITS.STAGE_FRAGMENT, sampler: {} },
        { binding: 3, visibility: BITS.STAGE_FRAGMENT, texture: {} },
      ],
    });
    this.fsLayout = device.createBindGroupLayout({
      entries: [
        { binding: 0, visibility: BITS.STAGE_FRAGMENT, buffer: { type: 'uniform' } },
        { binding: 1, visibility: BITS.STAGE_FRAGMENT, sampler: {} },
        { binding: 2, visibility: BITS.STAGE_FRAGMENT, texture: {} },
      ],
    });
    const mk = (code: string): GPUShaderModule => {
      const m = device.createShaderModule({ code });
      void m.getCompilationInfo().then((info) => {
        for (const msg of info.messages) {
          if (msg.type === 'error') console.error(`GlowPass WGSL ${msg.lineNum}:${msg.linePos} ${msg.message}`);
        }
      });
      return m;
    };
    const stampMod = mk(STAMP_WGSL);
    this.stampPipeline = device.createRenderPipeline({
      layout: device.createPipelineLayout({ bindGroupLayouts: [this.stampLayout] }),
      vertex: { module: stampMod, entryPoint: 'vs' },
      fragment: {
        module: stampMod, entryPoint: 'fs',
        targets: [{ format: this.format, blend: { color: { srcFactor: 'one', dstFactor: 'one' }, alpha: { srcFactor: 'one', dstFactor: 'one' } } }],
      },
      primitive: { topology: 'triangle-strip' },
    });
    const blurMod = mk(BLUR_WGSL);
    this.blurPipeline = device.createRenderPipeline({
      layout: device.createPipelineLayout({ bindGroupLayouts: [this.fsLayout] }),
      vertex: { module: blurMod, entryPoint: 'vs' },
      fragment: { module: blurMod, entryPoint: 'fs', targets: [{ format: this.format }] },
      primitive: { topology: 'triangle-list' },
    });
    const compMod = mk(COMPOSITE_WGSL);
    this.compositePipeline = device.createRenderPipeline({
      layout: device.createPipelineLayout({ bindGroupLayouts: [this.fsLayout] }),
      vertex: { module: compMod, entryPoint: 'vs' },
      fragment: {
        module: compMod, entryPoint: 'fs',
        targets: [{ format: this.format, blend: { color: { srcFactor: 'one', dstFactor: 'one' }, alpha: { srcFactor: 'one', dstFactor: 'one' } } }],
      },
      // lives inside the depth-attached scene pass; ignores depth entirely
      depthStencil: { format: DEPTH_FORMAT, depthWriteEnabled: false, depthCompare: 'always' },
      primitive: { topology: 'triangle-list' },
    });
    this.stampUniforms = device.createBuffer({ size: 16, usage: BITS.UNIFORM | BITS.COPY_DST });
    this.blurUniformsH = device.createBuffer({ size: 16, usage: BITS.UNIFORM | BITS.COPY_DST });
    this.blurUniformsV = device.createBuffer({ size: 16, usage: BITS.UNIFORM | BITS.COPY_DST });
    this.compUniforms = device.createBuffer({ size: 16, usage: BITS.UNIFORM | BITS.COPY_DST });
    this.instances = device.createBuffer({ size: this.capacity * FLOATS * 4, usage: BITS.STORAGE | BITS.COPY_DST });
  }
}
