// THE DEBUG OVERLAY — ships in every game, disabled by default (Rich: this
// is for END USERS too, not just dev). The agent's diagnostic tool: when a
// player says "the sprite doesn't hit properly!", the agent flips
// `game.debug = true` (or `{ hitboxes: true }`) and the player can SEE the
// misaligned hitbox and say so. Everything draws through the existing
// verbs — zero cost while disabled, no new GPU code.
//
//   game.debug = true;                       // everything sensible
//   game.debug = { hitboxes: true };         // just the boxes
//   game.debug = false;                      // off (the default)

import type { Draw } from './draw.js';
import type { Scene } from './scene.js';
import type { Sprite } from './sprite.js';
import { CollisionGrid } from './collision-grid.js';
import type { BitmapFont } from './font.js';

export interface DebugOptions {
  /** Sprite hitboxes, colour-coded by body type (dynamic green, static blue,
   * kinematic orange, sensor purple, none grey). Default true. */
  hitboxes?: boolean;
  /** Velocity vectors from each moving sprite's centre. Default true. */
  velocity?: boolean;
  /** Red markers on edges with active `touching` contacts. Default true. */
  touching?: boolean;
  /** Collision-grid cells in view: solid outlines + slope surface lines. Default true. */
  tiles?: boolean;
  /** The HUD stats line: fps, sprites, particles, 3D counts. Default true. */
  stats?: boolean;
  /**
   * The box every text block PAINTS (ink and all) — green normally, **RED where
   * two of them collide**. Turn this on the moment a HUD or menu looks crowded:
   * it shows the real extents, which include stroke/glow/shadow/plate and the
   * hover state, not the tighter text box. Default true.
   */
  textBounds?: boolean;
}

const BODY_COLORS: Record<string, string> = {
  dynamic: '#46e08a',
  static: '#59a1ff',
  kinematic: '#ffb347',
  sensor: '#c58bff',
  none: '#8a93b5',
};

/**
 * Normalise the public `game.debug` value. Exported from the barrel (and so
 * from the shipped `.d.ts`) because the dist tests exercise it directly — set
 * `game.debug` rather than calling this.
 */
export function normalizeDebug(v: boolean | DebugOptions): Required<DebugOptions> | null {
  if (v === false) return null;
  const o = v === true ? {} : v;
  return {
    hitboxes: o.hitboxes ?? true,
    velocity: o.velocity ?? true,
    touching: o.touching ?? true,
    tiles: o.tiles ?? true,
    stats: o.stats ?? true,
    textBounds: o.textBounds ?? true,
  };
}

/** Renders the overlay each frame — constructed once by Game; drive it with `game.debug`. */
export class DebugOverlay {
  private font: BitmapFont | null = null;
  private fps = 60;

  draw(
    d: Draw,
    hud: Draw,
    scene: Scene,
    opts: Required<DebugOptions>,
    ctx: {
      dt: number;
      view: { x: number; y: number; w: number; h: number };
      particles: number;
      counts3d: { meshes: number; billboards: number; draws: number } | null;
      font: () => BitmapFont;
    },
  ): void {
    if (ctx.dt > 0) this.fps += (1 / ctx.dt - this.fps) * 0.05; // smoothed

    if (opts.tiles) this.drawTiles(d, scene, ctx.view);
    if (opts.textBounds) { this.drawTextBounds(d); this.drawTextBounds(hud); }

    for (const s of scene.sprites) {
      if (s.dead) continue;
      if (opts.hitboxes) this.outline(d, s);
      if (opts.velocity && (s.vel.x !== 0 || s.vel.y !== 0)) {
        d.line(s.centerX, s.centerY, s.centerX + s.vel.x * 0.15, s.centerY + s.vel.y * 0.15, 1, '#ffd147', 0.9);
        d.circle(s.centerX + s.vel.x * 0.15, s.centerY + s.vel.y * 0.15, 1.6, '#ffd147', 0.9);
      }
      if (opts.touching) this.contacts(d, s);
    }

    if (opts.stats) {
      this.font ??= ctx.font();
      const parts = [
        `FPS ${Math.round(this.fps)}`,
        `SPRITES ${scene.sprites.length}`,
        `PARTICLES ${ctx.particles}`,
      ];
      if (ctx.counts3d) parts.push(`3D ${ctx.counts3d.meshes}m/${ctx.counts3d.billboards}b/${ctx.counts3d.draws}dc`);
      // A backing bar keeps the line legible over any game HUD/scene. Uses the
      // HUD surface's OWN dimensions (unzoomed) — `ctx.view` is the zoomed world
      // rect, so under camera.zoom the bar would otherwise mis-size.
      hud.rect(0, hud.h - 20, hud.w, 20, '#000000', 0.55);
      hud.text(this.font, parts.join('  '), 6, hud.h - 16, { color: '#5cd9b3' });
    }
  }

  /**
   * Outline every text block drawn on this surface, reddening any that collide.
   * The boxes are the PAINTED extents (stroke/glow/shadow/plate + the hover
   * state), which is why a HUD that looks fine by text size can still clash.
   */
  private drawTextBounds(d: Draw): void {
    const boxes = d.textBoxes;
    if (!boxes.length) return;
    for (let i = 0; i < boxes.length; i++) {
      const a = boxes[i];
      let clash = false;
      for (let j = 0; j < boxes.length && !clash; j++) {
        if (j === i) continue;
        const b = boxes[j];
        clash = a.x < b.right && b.x < a.right && a.y < b.bottom && b.y < a.bottom;
      }
      const c = clash ? '#ff4d6d' : '#46e08a';
      const t = clash ? 2 : 1;
      d.line(a.x, a.y, a.right, a.y, t, c, 0.95);
      d.line(a.right, a.y, a.right, a.bottom, t, c, 0.95);
      d.line(a.right, a.bottom, a.x, a.bottom, t, c, 0.95);
      d.line(a.x, a.bottom, a.x, a.y, t, c, 0.95);
      if (clash) d.rect(a.x, a.y, a.w, a.h, '#ff4d6d', 0.12);
    }
  }

  private outline(d: Draw, s: Sprite): void {
    const c = BODY_COLORS[s.body] ?? '#ffffff';
    d.line(s.x, s.y, s.x + s.w, s.y, 1, c, 0.9);
    d.line(s.x + s.w, s.y, s.x + s.w, s.y + s.h, 1, c, 0.9);
    d.line(s.x + s.w, s.y + s.h, s.x, s.y + s.h, 1, c, 0.9);
    d.line(s.x, s.y + s.h, s.x, s.y, 1, c, 0.9);
  }

  private contacts(d: Draw, s: Sprite): void {
    const t = s.touching;
    const T = 2.5;
    if (t.down) d.rect(s.x + 1, s.y + s.h - T, s.w - 2, T, '#ff5c5c', 0.85);
    if (t.up) d.rect(s.x + 1, s.y, s.w - 2, T, '#ff5c5c', 0.85);
    if (t.left) d.rect(s.x, s.y + 1, T, s.h - 2, '#ff5c5c', 0.85);
    if (t.right) d.rect(s.x + s.w - T, s.y + 1, T, s.h - 2, '#ff5c5c', 0.85);
  }

  private drawTiles(d: Draw, scene: Scene, view: { x: number; y: number; w: number; h: number }): void {
    const map = scene.collisionMap;
    if (!(map instanceof CollisionGrid)) return; // the no-op grid has nothing to show
    const ts = map.tilesize;
    const x0 = Math.max(0, Math.floor(view.x / ts));
    const y0 = Math.max(0, Math.floor(view.y / ts));
    const x1 = Math.min((map.data[0]?.length ?? 0) - 1, Math.ceil((view.x + view.w) / ts));
    const y1 = Math.min(map.data.length - 1, Math.ceil((view.y + view.h) / ts));
    for (let ty = y0; ty <= y1; ty++) {
      for (let tx = x0; tx <= x1; tx++) {
        const t = map.data[ty]?.[tx] ?? 0;
        if (t === 0) continue;
        const wx = tx * ts, wy = ty * ts;
        const def = map.tiledef[t];
        if (def) {
          // A slope: draw its surface line (tiledef = [x1, y1, x2, y2, solid] in tile fractions).
          d.line(wx + def[0] * ts, wy + def[1] * ts, wx + def[2] * ts, wy + def[3] * ts, 1.2, '#ff9de2', 0.9);
        } else {
          // A full solid cell: faint fill + outline.
          d.rect(wx, wy, ts, ts, '#59a1ff', 0.10);
          d.line(wx, wy, wx + ts, wy, 0.8, '#59a1ff', 0.45);
          d.line(wx, wy + ts, wx + ts, wy + ts, 0.8, '#59a1ff', 0.45);
          d.line(wx, wy, wx, wy + ts, 0.8, '#59a1ff', 0.45);
          d.line(wx + ts, wy, wx + ts, wy + ts, 0.8, '#59a1ff', 0.45);
        }
      }
    }
  }
}
