/**
 * hull3d — pure convex-hull math for 3D model colliders (no DOM, no GPU, no
 * deps). Loaded OBJ/GLB models are arbitrary triangle soups; physics wants a
 * small CONVEX wrap of them. `quickhull` computes the hull of a point cloud,
 * `hullOfVerts` runs it over the engine's stride-8 vertex format and samples
 * the result down to a physics-friendly point count. Both run once per model
 * at load time — clarity over speed (meshes are ≤ ~30k verts).
 */

/** Relative epsilon: scaled by the cloud's largest axis extent. */
const EPS_REL = 1e-7;

// ─── quickhull ───────────────────────────────────────────────────────────────

/**
 * 3D quickhull over a point cloud. Input: flat xyz triples. Output: the
 * hull's unique vertices as flat xyz triples (order unspecified). Handles
 * degenerate inputs by returning what it can (≤3 points / coplanar sets
 * return the input's unique extreme points — Box3D accepts them).
 */
export function quickhull(points: Float32Array | number[]): Float32Array {
  const P = points;
  const n = Math.floor(P.length / 3);

  // Unique points only — duplicates would fake extreme pairs and stall faces.
  const idx: number[] = [];
  const seen = new Set<string>();
  for (let i = 0; i < n; i++) {
    const key = P[i * 3] + ',' + P[i * 3 + 1] + ',' + P[i * 3 + 2];
    if (!seen.has(key)) {
      seen.add(key);
      idx.push(i);
    }
  }
  if (idx.length <= 3) return gather(P, idx);

  const X = (i: number): number => P[i * 3];
  const Y = (i: number): number => P[i * 3 + 1];
  const Z = (i: number): number => P[i * 3 + 2];

  // Cloud extent → the absolute epsilon every "is it off the surface?" uses.
  let iMinX = idx[0], iMaxX = idx[0], iMinY = idx[0], iMaxY = idx[0], iMinZ = idx[0], iMaxZ = idx[0];
  for (const i of idx) {
    if (X(i) < X(iMinX)) iMinX = i;
    if (X(i) > X(iMaxX)) iMaxX = i;
    if (Y(i) < Y(iMinY)) iMinY = i;
    if (Y(i) > Y(iMaxY)) iMaxY = i;
    if (Z(i) < Z(iMinZ)) iMinZ = i;
    if (Z(i) > Z(iMaxZ)) iMaxZ = i;
  }
  const extent = Math.max(X(iMaxX) - X(iMinX), Y(iMaxY) - Y(iMinY), Z(iMaxZ) - Z(iMinZ));
  const eps = Math.max(extent * EPS_REL, 1e-12);

  // ── Initial simplex: farthest pair of the 6 axis extremes… ──
  const ext = [iMinX, iMaxX, iMinY, iMaxY, iMinZ, iMaxZ];
  let s0 = ext[0], s1 = ext[1], bestD2 = -1;
  for (let a = 0; a < 6; a++) {
    for (let b = a + 1; b < 6; b++) {
      const dx = X(ext[a]) - X(ext[b]), dy = Y(ext[a]) - Y(ext[b]), dz = Z(ext[a]) - Z(ext[b]);
      const d2 = dx * dx + dy * dy + dz * dz;
      if (d2 > bestD2) { bestD2 = d2; s0 = ext[a]; s1 = ext[b]; }
    }
  }
  if (bestD2 <= eps * eps) return gather(P, [idx[0]]); // the whole cloud is one point

  // …plus the point farthest from that line…
  const lx = X(s1) - X(s0), ly = Y(s1) - Y(s0), lz = Z(s1) - Z(s0);
  const lLen = Math.hypot(lx, ly, lz);
  let s2 = -1, d2best = eps;
  for (const i of idx) {
    const px = X(i) - X(s0), py = Y(i) - Y(s0), pz = Z(i) - Z(s0);
    const cx = ly * pz - lz * py, cy = lz * px - lx * pz, cz = lx * py - ly * px;
    const d = Math.hypot(cx, cy, cz) / lLen;
    if (d > d2best) { d2best = d; s2 = i; }
  }
  if (s2 < 0) {
    // Collinear cloud: the two extreme points along the line ARE the hull.
    let lo = idx[0], hi = idx[0];
    for (const i of idx) {
      const t = (X(i) - X(s0)) * lx + (Y(i) - Y(s0)) * ly + (Z(i) - Z(s0)) * lz;
      if (t < (X(lo) - X(s0)) * lx + (Y(lo) - Y(s0)) * ly + (Z(lo) - Z(s0)) * lz) lo = i;
      if (t > (X(hi) - X(s0)) * lx + (Y(hi) - Y(s0)) * ly + (Z(hi) - Z(s0)) * lz) hi = i;
    }
    return gather(P, lo === hi ? [lo] : [lo, hi]);
  }

  // …plus the point farthest from that plane.
  const p2x = X(s2) - X(s0), p2y = Y(s2) - Y(s0), p2z = Z(s2) - Z(s0);
  let nx = ly * p2z - lz * p2y, ny = lz * p2x - lx * p2z, nz = lx * p2y - ly * p2x;
  const nLen = Math.hypot(nx, ny, nz) || 1;
  nx /= nLen; ny /= nLen; nz /= nLen;
  const off = nx * X(s0) + ny * Y(s0) + nz * Z(s0);
  let s3 = -1, d3best = eps;
  for (const i of idx) {
    const d = Math.abs(nx * X(i) + ny * Y(i) + nz * Z(i) - off);
    if (d > d3best) { d3best = d; s3 = i; }
  }
  if (s3 < 0) {
    // Coplanar cloud: 2D hull in the plane's own basis (the square's corners
    // come back, its interior points don't).
    return hull2d(P, idx, s0, lx / lLen, ly / lLen, lz / lLen, nx, ny, nz, eps, extent);
  }

  // ── Faces + directed-edge adjacency. ──
  interface Face {
    a: number; b: number; c: number;
    nx: number; ny: number; nz: number; off: number;
    pts: number[]; far: number; farD: number;
    dead: boolean; mark: number;
  }
  const faces: Face[] = [];
  // Directed edge (a→b) → the face that owns it. Neighbor across = (b→a).
  const edges = new Map<number, Face>();
  const EK = 0x400000; // supports point indices < 4.2M with exact float keys
  const ekey = (a: number, b: number): number => a * EK + b;

  const makeFace = (a: number, b: number, c: number): Face => {
    const abx = X(b) - X(a), aby = Y(b) - Y(a), abz = Z(b) - Z(a);
    const acx = X(c) - X(a), acy = Y(c) - Y(a), acz = Z(c) - Z(a);
    let fnx = aby * acz - abz * acy, fny = abz * acx - abx * acz, fnz = abx * acy - aby * acx;
    const len = Math.hypot(fnx, fny, fnz) || 1e-30;
    fnx /= len; fny /= len; fnz /= len;
    return {
      a, b, c, nx: fnx, ny: fny, nz: fnz,
      off: fnx * X(a) + fny * Y(a) + fnz * Z(a),
      pts: [], far: -1, farD: eps, dead: false, mark: 0,
    };
  };
  const dist = (f: Face, i: number): number => f.nx * X(i) + f.ny * Y(i) + f.nz * Z(i) - f.off;
  const addFace = (f: Face): void => {
    faces.push(f);
    edges.set(ekey(f.a, f.b), f);
    edges.set(ekey(f.b, f.c), f);
    edges.set(ekey(f.c, f.a), f);
  };

  // The simplex centroid is strictly inside — the orientation referee forever.
  const cx = (X(s0) + X(s1) + X(s2) + X(s3)) / 4;
  const cy = (Y(s0) + Y(s1) + Y(s2) + Y(s3)) / 4;
  const cz = (Z(s0) + Z(s1) + Z(s2) + Z(s3)) / 4;
  const outward = (f: Face): Face =>
    (f.nx * cx + f.ny * cy + f.nz * cz - f.off > 0) ? makeFace(f.a, f.c, f.b) : f;

  addFace(outward(makeFace(s0, s1, s2)));
  addFace(outward(makeFace(s0, s1, s3)));
  addFace(outward(makeFace(s0, s2, s3)));
  addFace(outward(makeFace(s1, s2, s3)));

  // Assign every remaining point to ONE face it lies outside of.
  const claim = (i: number, candidates: Face[]): void => {
    let best: Face | null = null, bestDist = eps;
    for (const f of candidates) {
      if (f.dead) continue;
      const d = dist(f, i);
      if (d > bestDist) { bestDist = d; best = f; }
    }
    if (best) {
      best.pts.push(i);
      if (bestDist > best.farD) { best.farD = bestDist; best.far = i; }
    }
  };
  for (const i of idx) {
    if (i === s0 || i === s1 || i === s2 || i === s3) continue;
    claim(i, faces);
  }

  // ── Expand: pull each face's farthest outside point onto the hull. ──
  const queue: Face[] = faces.filter((f) => f.pts.length > 0);
  let markGen = 0;
  let guard = idx.length * 12 + 64; // termination belt-and-braces
  while (queue.length > 0 && guard-- > 0) {
    const f = queue.pop()!;
    if (f.dead || f.pts.length === 0) continue;
    const apex = f.far;

    // Flood-fill the faces visible from the apex; hidden neighbors mark the horizon.
    markGen++;
    f.mark = markGen;
    const visible: Face[] = [f];
    const stack: Face[] = [f];
    const horizon: number[] = []; // directed (a,b) pairs, visible-face winding
    while (stack.length > 0) {
      const g = stack.pop()!;
      const va = [g.a, g.b, g.c];
      for (let k = 0; k < 3; k++) {
        const a = va[k], b = va[(k + 1) % 3];
        const nb = edges.get(ekey(b, a));
        if (!nb || nb.dead || nb.mark === markGen) continue;
        if (dist(nb, apex) > eps) {
          nb.mark = markGen;
          visible.push(nb);
          stack.push(nb);
        } else {
          horizon.push(a, b);
        }
      }
    }

    // Retire the visible faces; their outside points go back in the pool.
    const orphans: number[] = [];
    for (const g of visible) {
      g.dead = true;
      edges.delete(ekey(g.a, g.b));
      edges.delete(ekey(g.b, g.c));
      edges.delete(ekey(g.c, g.a));
      for (const i of g.pts) if (i !== apex) orphans.push(i);
    }

    // New faces: horizon edge → apex (winding inherited = outward), then
    // re-home the orphans onto them (or drop the ones now inside).
    const fresh: Face[] = [];
    for (let k = 0; k < horizon.length; k += 2) {
      const nf = outward(makeFace(horizon[k], horizon[k + 1], apex));
      addFace(nf);
      fresh.push(nf);
    }
    for (const i of orphans) claim(i, fresh);
    for (const nf of fresh) if (nf.pts.length > 0) queue.push(nf);
  }

  // The hull's vertices = every vertex still referenced by a live face.
  const out = new Set<number>();
  for (const f of faces) {
    if (f.dead) continue;
    out.add(f.a); out.add(f.b); out.add(f.c);
  }
  return gather(P, [...out]);
}

/** @internal Coplanar fallback: Andrew monotone chain in the plane's (u,v) basis. */
function hull2d(
  P: Float32Array | number[], idx: number[], origin: number,
  ux: number, uy: number, uz: number,
  vxn: number, vyn: number, vzn: number,
  eps: number, extent: number,
): Float32Array {
  // v = n × u completes the in-plane basis.
  const vx = vyn * uz - vzn * uy, vy = vzn * ux - vxn * uz, vz = vxn * uy - vyn * ux;
  const ox = P[origin * 3], oy = P[origin * 3 + 1], oz = P[origin * 3 + 2];
  const pts = idx.map((i) => {
    const px = P[i * 3] - ox, py = P[i * 3 + 1] - oy, pz = P[i * 3 + 2] - oz;
    return { x: px * ux + py * uy + pz * uz, y: px * vx + py * vy + pz * vz, i };
  });
  pts.sort((a, b) => (a.x - b.x) || (a.y - b.y));
  const eps2 = eps * Math.max(extent, 1); // cross products carry area units
  const cross = (o: { x: number; y: number }, a: { x: number; y: number }, b: { x: number; y: number }): number =>
    (a.x - o.x) * (b.y - o.y) - (a.y - o.y) * (b.x - o.x);
  const half = (list: typeof pts): typeof pts => {
    const h: typeof pts = [];
    for (const p of list) {
      while (h.length >= 2 && cross(h[h.length - 2], h[h.length - 1], p) <= eps2) h.pop();
      h.push(p);
    }
    return h;
  };
  const lower = half(pts);
  const upper = half([...pts].reverse());
  const ring = [...lower.slice(0, -1), ...upper.slice(0, -1)];
  return gather(P, ring.map((p) => p.i));
}

/** @internal Flat xyz triples for a list of point indices. */
function gather(P: Float32Array | number[], ids: number[]): Float32Array {
  const out = new Float32Array(ids.length * 3);
  for (let k = 0; k < ids.length; k++) {
    out[k * 3] = P[ids[k] * 3];
    out[k * 3 + 1] = P[ids[k] * 3 + 1];
    out[k * 3 + 2] = P[ids[k] * 3 + 2];
  }
  return out;
}

// ─── hullOfVerts ─────────────────────────────────────────────────────────────

/**
 * Convex hull of a stride-8 vertex soup (pos+normal+uv — the engine's
 * geometry format): dedupes positions (1e-5 grid), runs quickhull, and if
 * the hull has more than `maxPoints` vertices, SIMPLIFIES by greedy
 * farthest-point sampling down to `maxPoints` (physics cores want small
 * hulls; 32–64 is plenty).
 */
export function hullOfVerts(verts: Float32Array, maxPoints: number = 48): Float32Array {
  const pts: number[] = [];
  const seen = new Set<string>();
  for (let i = 0; i + 2 < verts.length; i += 8) {
    const x = verts[i], y = verts[i + 1], z = verts[i + 2];
    const key = Math.round(x * 1e5) + ':' + Math.round(y * 1e5) + ':' + Math.round(z * 1e5);
    if (!seen.has(key)) {
      seen.add(key);
      pts.push(x, y, z);
    }
  }
  const hull = quickhull(pts);
  if (hull.length / 3 <= maxPoints) return hull;
  return farthestPoints(hull, maxPoints);
}

/** @internal Greedy farthest-point sampling: keep the `k` most spread-out points. */
function farthestPoints(P: Float32Array, k: number): Float32Array {
  const n = P.length / 3;
  // Seed with the point farthest from the centroid (an extreme, never a middle).
  let cx = 0, cy = 0, cz = 0;
  for (let i = 0; i < n; i++) { cx += P[i * 3]; cy += P[i * 3 + 1]; cz += P[i * 3 + 2]; }
  cx /= n; cy /= n; cz /= n;
  let seed = 0, seedD = -1;
  for (let i = 0; i < n; i++) {
    const d = (P[i * 3] - cx) ** 2 + (P[i * 3 + 1] - cy) ** 2 + (P[i * 3 + 2] - cz) ** 2;
    if (d > seedD) { seedD = d; seed = i; }
  }
  const chosen = [seed];
  // minD[i] = squared distance from point i to the nearest chosen point.
  const minD = new Float64Array(n);
  const relax = (j: number): void => {
    const jx = P[j * 3], jy = P[j * 3 + 1], jz = P[j * 3 + 2];
    for (let i = 0; i < n; i++) {
      const d = (P[i * 3] - jx) ** 2 + (P[i * 3 + 1] - jy) ** 2 + (P[i * 3 + 2] - jz) ** 2;
      if (d < minD[i]) minD[i] = d;
    }
  };
  minD.fill(Infinity);
  relax(seed);
  while (chosen.length < k) {
    let next = -1, nextD = -1;
    for (let i = 0; i < n; i++) {
      if (minD[i] > nextD) { nextD = minD[i]; next = i; }
    }
    if (next < 0 || nextD <= 0) break; // fewer unique points than k
    chosen.push(next);
    relax(next);
  }
  const out = new Float32Array(chosen.length * 3);
  for (let m = 0; m < chosen.length; m++) {
    out[m * 3] = P[chosen[m] * 3];
    out[m * 3 + 1] = P[chosen[m] * 3 + 1];
    out[m * 3 + 2] = P[chosen[m] * 3 + 2];
  }
  return out;
}
