// Flat filled TRIANGLES — the primitive the quad batch can't do. Backs the
// `d.fill(points, color)` verb: an arbitrary polygon is ear-clipped on the CPU
// and each triangle is pushed as one instance (3 corners + colour). Alpha
// blended, drawn in the 2D pass alongside the other shapes.
//
// Same instanced pattern as batch.ts: a view uniform maps the world rect to the
// canvas; a storage buffer holds per-triangle instances; GPU objects rebuild
// from CPU state on device loss. draw(3, count) — one triangle per instance.

import { BITS } from './gpu.js';
import { DEPTH_FORMAT, SRC_TRI, type DrawOrder } from './batch.js';
import type { Vec2 } from './util.js';

const FLOATS = 12; // per triangle: tri(4: ax,ay,bx,by) c(4: cx,cy,_,_) color(4: rgba)

/** Ear-clip a simple polygon into triangles (flat index triples: `[a,b,c, …]`).
 *  Self-contained so the 2D draw path never imports the 3D geometry module. */
export function triangulate(pts: ReadonlyArray<Vec2>): number[] {
  const n = pts.length;
  if (n < 3) return [];
  const idx: number[] = pts.map((_, i) => i);
  const cross = (a: number, b: number, c: number): number =>
    (pts[b].x - pts[a].x) * (pts[c].y - pts[a].y) - (pts[b].y - pts[a].y) * (pts[c].x - pts[a].x);
  // Wind counter-clockwise so "ears" have positive cross product.
  let area = 0;
  for (let i = 0; i < n; i++) { const j = (i + 1) % n; area += pts[i].x * pts[j].y - pts[j].x * pts[i].y; }
  if (area < 0) idx.reverse();
  const inTri = (a: number, b: number, c: number, p: number): boolean => {
    const d1 = cross2(pts[p], pts[a], pts[b]), d2 = cross2(pts[p], pts[b], pts[c]), d3 = cross2(pts[p], pts[c], pts[a]);
    const neg = d1 < 0 || d2 < 0 || d3 < 0, pos = d1 > 0 || d2 > 0 || d3 > 0;
    return !(neg && pos);
  };
  const out: number[] = [];
  let guard = n * n;
  while (idx.length > 3 && guard-- > 0) {
    let clipped = false;
    for (let i = 0; i < idx.length; i++) {
      const a = idx[(i - 1 + idx.length) % idx.length], b = idx[i], c = idx[(i + 1) % idx.length];
      if (cross(a, b, c) <= 0) continue;                 // reflex vertex — not an ear
      let ear = true;
      for (const p of idx) { if (p !== a && p !== b && p !== c && inTri(a, b, c, p)) { ear = false; break; } }
      if (!ear) continue;
      out.push(a, b, c); idx.splice(i, 1); clipped = true; break;
    }
    if (!clipped) break;                                 // degenerate — stop
  }
  if (idx.length === 3) out.push(idx[0], idx[1], idx[2]);
  return out;
}
function cross2(p: Vec2, a: Vec2, b: Vec2): number {
  return (b.x - a.x) * (p.y - a.y) - (b.y - a.y) * (p.x - a.x);
}

const wgsl = /* wgsl */ `
struct U { view: vec4f }
struct Inst { tri: vec4f, c: vec4f, color: vec4f }
struct VSOut { @builtin(position) pos: vec4f, @location(0) color: vec4f }
@group(0) @binding(0) var<uniform> u: U;
@group(0) @binding(1) var<storage, read> inst: array<Inst>;
@vertex
fn vs(@builtin(vertex_index) vi: u32, @builtin(instance_index) ii: u32) -> VSOut {
  let d = inst[ii];
  var p = d.c.xy;
  if (vi == 0u) { p = d.tri.xy; } else if (vi == 1u) { p = d.tri.zw; }
  let ndc = (p - u.view.xy) / u.view.zw * 2.0 - 1.0;
  var o: VSOut;
  o.pos = vec4f(ndc.x, -ndc.y, 0.0, 1.0);
  o.color = d.color;
  return o;
}
@fragment
fn fs(in: VSOut) -> @location(0) vec4f {
  return vec4f(in.color.rgb * in.color.a, in.color.a);   // premultiplied
}
`;

/** An instanced flat-triangle batch (alpha blend). One per Draw surface. */
export class TriBatch {
  /** The surface's submission-order log — see batch.ts's DrawOrder. */
  private order: DrawOrder | null = null;
  private uploaded = false;
  /** Layer cursor — moved with the surface's other passes by Draw.setUiLayer. */
  private layer = 0;
  private data: Float32Array;
  private count = 0;
  private capacity = 2048;
  private uniformData = new Float32Array(4);

  private device!: GPUDevice;
  private pipeline!: GPURenderPipeline;
  private layout!: GPUBindGroupLayout;
  private uniforms!: GPUBuffer;
  private instances!: GPUBuffer;
  private bind!: GPUBindGroup;

  constructor(device: GPUDevice, private format: GPUTextureFormat) {
    this.data = new Float32Array(this.capacity * FLOATS);
    this.rebuild(device);
  }

  rebuild(device: GPUDevice): void {
    this.device = device;
    this.layout = device.createBindGroupLayout({
      entries: [
        { binding: 0, visibility: BITS.STAGE_VERTEX, buffer: { type: 'uniform' } },
        { binding: 1, visibility: BITS.STAGE_VERTEX, buffer: { type: 'read-only-storage' } },
      ],
    });
    const module = device.createShaderModule({ code: wgsl });
    void module.getCompilationInfo().then((info) => {
      for (const m of info.messages) if (m.type === 'error') console.error(`TriBatch WGSL ${m.lineNum}:${m.linePos} ${m.message}`);
    });
    this.pipeline = device.createRenderPipeline({
      layout: device.createPipelineLayout({ bindGroupLayouts: [this.layout] }),
      vertex: { module, entryPoint: 'vs' },
      fragment: {
        module, entryPoint: 'fs',
        targets: [{
          format: this.format,
          blend: {
            color: { srcFactor: 'one', dstFactor: 'one-minus-src-alpha' },
            alpha: { srcFactor: 'one', dstFactor: 'one-minus-src-alpha' },
          },
        }],
      },
      depthStencil: { format: DEPTH_FORMAT, depthWriteEnabled: false, depthCompare: 'always' },
      primitive: { topology: 'triangle-list' },
    });
    this.uniforms = device.createBuffer({ size: 16, usage: BITS.UNIFORM | BITS.COPY_DST });
    this.instances = device.createBuffer({ size: this.capacity * FLOATS * 4, usage: BITS.STORAGE | BITS.COPY_DST });
    this.makeBind();
  }

  private makeBind(): void {
    this.bind = this.device.createBindGroup({
      layout: this.layout,
      entries: [
        { binding: 0, resource: { buffer: this.uniforms } },
        { binding: 1, resource: { buffer: this.instances } },
      ],
    });
  }

  begin(viewX: number, viewY: number, viewW: number, viewH: number): void {
    this.uniformData[0] = viewX; this.uniformData[1] = viewY;
    this.uniformData[2] = viewW; this.uniformData[3] = viewH;
    this.count = 0;
    this.layer = 0;
    this.uploaded = false;
  }

  /** @see QuadBatch.setLayer */
  setLayer(n: number): void { this.layer = n; }

  /** Push one triangle `(ax,ay)-(bx,by)-(cx,cy)` in colour `(r,g,b,a)` (0..1). */
  push(ax: number, ay: number, bx: number, by: number, cx: number, cy: number, r: number, g: number, b: number, a: number): void {
    this.order?.put(SRC_TRI, this.count, this.layer);
    if (this.count >= this.capacity) this.grow();
    const o = this.count * FLOATS, d = this.data;
    d[o] = ax; d[o + 1] = ay; d[o + 2] = bx; d[o + 3] = by;
    d[o + 4] = cx; d[o + 5] = cy; d[o + 6] = 0; d[o + 7] = 0;
    d[o + 8] = r; d[o + 9] = g; d[o + 10] = b; d[o + 11] = a;
    this.count++;
  }

  private grow(): void {
    this.capacity *= 2;
    const next = new Float32Array(this.capacity * FLOATS);
    next.set(this.data);
    this.data = next;
    this.instances.destroy();
    this.instances = this.device.createBuffer({ size: this.capacity * FLOATS * 4, usage: BITS.STORAGE | BITS.COPY_DST });
    this.makeBind();
  }

  flush(pass: GPURenderPassEncoder): void {
    if (!this.upload()) return;
    pass.setPipeline(this.pipeline);
    pass.setBindGroup(0, this.bind);
    pass.draw(3, this.count);
  }

  /** @internal Take part in a surface's submission order (see batch.ts). */
  joinOrder(order: DrawOrder): void { this.order = order; }

  private upload(): boolean {
    if (this.count === 0) return false;
    if (!this.uploaded) {
      this.device.queue.writeBuffer(this.uniforms, 0, this.uniformData);
      this.device.queue.writeBuffer(this.instances, 0, this.data.buffer, 0, this.count * FLOATS * 4);
      this.uploaded = true;
    }
    return true;
  }

  /** @internal Draw ONE contiguous span — the submission-order walk's unit. */
  drawRange(pass: GPURenderPassEncoder, first: number, n: number): void {
    if (n <= 0 || !this.upload()) return;
    pass.setPipeline(this.pipeline);
    pass.setBindGroup(0, this.bind);
    pass.draw(3, n, 0, first);
  }
}
