/**
 * Flow-field pathfinding on a grid — pure CPU math, zero engine dependency.
 * Import it directly (`import { FlowGrid } from '../engine/webgpu.js'`); it is
 * NOT wired into `Game` or any scene.
 *
 * The tower-defense pattern (after redblobgames.com/pathfinding/tower-defense):
 * instead of running A* once PER enemy, run ONE search from the goal(s) across
 * the whole grid to get an **integration field** (distance-to-goal per cell),
 * then take its negative gradient to get a **flow field** (each cell's step
 * direction toward the goal). Every enemy just reads the flow at its position —
 * hundreds of units, one search. When a tower is built the field is recomputed
 * once and everyone re-routes.
 *
 * The grid is mutable: block/unblock cells (towers, walls), weight cells (mud,
 * roads), move the goals — the field rebuilds lazily on the next query. It
 * feeds either engine dimension: `steer(x, y)` returns a smooth
 * (interpolated) direction vector for an enemy at any world position;
 * `flowVec(col, row)` / `distance(col, row)` are the raw per-cell values for a
 * tile render or a 3D build. `canBuild(col, row)` is the placement guard that
 * refuses a tower which would fully wall spawns off from the goal.
 */

import type { Vec2, Cell } from './util.js';

// ── 8-way directions ─────────────────────────────────────────────────────────
// Clockwise from East. Even indices are orthogonal, odd are diagonal.

/** A flow direction as an 8-way index (0=E, 1=SE, 2=S, 3=SW, 4=W, 5=NW, 6=N,
 *  7=NE), or `-1` for "no flow" (a goal cell, a blocked cell, or unreachable). */
export type FlowDir = -1 | 0 | 1 | 2 | 3 | 4 | 5 | 6 | 7;

const DX8: number[] = [1, 1, 0, -1, -1, -1, 0, 1];
const DY8: number[] = [0, 1, 1, 1, 0, -1, -1, -1];
const SQRT2 = Math.SQRT2;
// Per-direction cost multiplier and normalised unit vector.
const DCOST: number[] = DX8.map((_, d) => (d & 1 ? SQRT2 : 1));
const UVX: number[] = DX8.map((x, d) => x / (d & 1 ? SQRT2 : 1));
const UVY: number[] = DY8.map((y, d) => y / (d & 1 ? SQRT2 : 1));

/** Configuration for a new {@link FlowGrid}. `cols`/`rows` are required. */
export interface FlowGridOptions {
  /** Grid width in cells. */
  cols: number;
  /** Grid height in cells. */
  rows: number;
  /** Goal cell(s) — the field flows toward the NEAREST of these (multi-goal is
   *  the "supernode" trick, seeded for free). At least one is needed for a
   *  useful field. */
  goals?: Cell[];
  /** Spawn cell(s). Only used by {@link FlowGrid.canBuild} to guarantee a
   *  tower never fully walls a spawn off from the goal. */
  spawns?: Cell[];
  /** Allow 8-way (diagonal) movement. Default `true`. */
  diagonal?: boolean;
  /** Let diagonal moves slip between two blocked cells at a corner. Default
   *  `false` (units won't squeeze between two towers placed corner-to-corner). */
  cutCorners?: boolean;
}

/**
 * A mutable grid carrying a flow field toward one or more goals. Build it, set
 * goals + obstacles, then read `steer()` / `flowVec()` / `distance()` every
 * frame. Edits (block, weight, goals) mark the field dirty; it rebuilds itself
 * on the next query — call {@link update} up front if you want the cost paid at
 * a known time.
 *
 * ```ts
 * const grid = new FlowGrid({ cols: 40, rows: 30, goals: [{ col: 39, row: 15 }], spawns: [{ col: 0, row: 15 }] });
 * if (grid.canBuild(c, r)) grid.build(c, r);          // place a tower
 * enemy.vel = scale(grid.steer(enemy.x, enemy.y, TILE), speed);  // follow the flow
 * ```
 */
export class FlowGrid {
  /** Grid width in cells. */
  readonly cols: number;
  /** Grid height in cells. */
  readonly rows: number;
  /** Whether diagonal movement is allowed. */
  diagonal: boolean;
  /** Whether diagonal moves may cut blocked corners. */
  cutCorners: boolean;
  /** The current goal cells (flow points toward the nearest). */
  goals: Cell[];
  /** The current spawn cells (used by {@link canBuild}). */
  spawns: Cell[];

  /** `1` where a cell is blocked (tower/wall), else `0`. Row-major. */
  readonly blocked: Uint8Array;
  /** Per-cell entry cost (terrain weight); `1` is normal, higher is slower. */
  readonly weight: Float32Array;

  /** Integration field: distance to the nearest goal per cell, `Infinity` when
   *  unreachable. Row-major. Rebuilt by {@link update}. `@internal`-ish —
   *  prefer {@link distance}. */
  readonly dist: Float32Array;
  /** Flow field: the {@link FlowDir} each cell steps toward its goal. */
  readonly flow: Int8Array;

  private _dirty = true;

  constructor(opts: FlowGridOptions) {
    this.cols = Math.max(1, Math.floor(opts.cols));
    this.rows = Math.max(1, Math.floor(opts.rows));
    this.diagonal = opts.diagonal ?? true;
    this.cutCorners = opts.cutCorners ?? false;
    this.goals = (opts.goals ?? []).map((g) => ({ col: g.col, row: g.row }));
    this.spawns = (opts.spawns ?? []).map((s) => ({ col: s.col, row: s.row }));
    const n = this.cols * this.rows;
    this.blocked = new Uint8Array(n);
    this.weight = new Float32Array(n).fill(1);
    this.dist = new Float32Array(n).fill(Infinity);
    this.flow = new Int8Array(n).fill(-1);
  }

  // ── Grid basics ────────────────────────────────────────────────────────────

  /** Row-major cell index for `(col, row)`. No bounds check. */
  index(col: number, row: number): number {
    return row * this.cols + col;
  }

  /** Is `(col, row)` inside the grid? */
  inBounds(col: number, row: number): boolean {
    return col >= 0 && col < this.cols && row >= 0 && row < this.rows;
  }

  /** Which cell contains world/pixel position `(x, y)`, at `cellSize` units per
   *  cell from `(originX, originY)`. `null` when outside the grid. */
  cellAt(x: number, y: number, cellSize = 1, originX = 0, originY = 0): Cell | null {
    const col = Math.floor((x - originX) / cellSize);
    const row = Math.floor((y - originY) / cellSize);
    return this.inBounds(col, row) ? { col, row } : null;
  }

  // ── Mutation (marks the field dirty) ───────────────────────────────────────

  /** Is the cell an obstacle (tower/wall)? Out-of-bounds reads as blocked. */
  isBlocked(col: number, row: number): boolean {
    return !this.inBounds(col, row) || this.blocked[this.index(col, row)] === 1;
  }

  /** Block or unblock a cell (place/remove a tower or wall). */
  setBlocked(col: number, row: number, on: boolean): void {
    if (!this.inBounds(col, row)) return;
    const v = on ? 1 : 0;
    if (this.blocked[this.index(col, row)] !== v) { this.blocked[this.index(col, row)] = v; this._dirty = true; }
  }

  /** Place a tower/wall at `(col, row)` (alias for `setBlocked(…, true)`). */
  build(col: number, row: number): void { this.setBlocked(col, row, true); }
  /** Remove a tower/wall at `(col, row)` (alias for `setBlocked(…, false)`). */
  unbuild(col: number, row: number): void { this.setBlocked(col, row, false); }

  /** Clear every obstacle. */
  clearBlocked(): void { this.blocked.fill(0); this._dirty = true; }

  /** Set a cell's terrain entry cost (`1` normal; `>1` slow mud; `<1` fast
   *  road). Cells stay passable; block with {@link setBlocked} instead. */
  setWeight(col: number, row: number, w: number): void {
    if (!this.inBounds(col, row)) return;
    this.weight[this.index(col, row)] = Math.max(0.0001, w);
    this._dirty = true;
  }

  /** Replace the goal cells and mark the field dirty. */
  setGoals(goals: Cell[]): void {
    this.goals = goals.map((g) => ({ col: g.col, row: g.row }));
    this._dirty = true;
  }

  /** Replace the spawn cells (used only by {@link canBuild}). */
  setSpawns(spawns: Cell[]): void {
    this.spawns = spawns.map((s) => ({ col: s.col, row: s.row }));
  }

  // ── Field build ────────────────────────────────────────────────────────────

  /**
   * Rebuild the integration + flow fields (Dijkstra from all goals). Called
   * automatically by the queries when the grid is dirty; call it yourself to
   * pay the cost at a controlled time. Orthogonal steps cost `weight`,
   * diagonal steps `weight · √2`.
   */
  update(): void {
    const n = this.cols * this.rows;
    this.dist.fill(Infinity);
    this.flow.fill(-1);
    const heapId: number[] = [];
    const heapKey: number[] = [];
    const push = (id: number, k: number): void => {
      heapId.push(id); heapKey.push(k);
      let i = heapId.length - 1;
      while (i > 0) {
        const p = (i - 1) >> 1;
        if (heapKey[p] <= heapKey[i]) break;
        [heapKey[p], heapKey[i]] = [heapKey[i], heapKey[p]];
        [heapId[p], heapId[i]] = [heapId[i], heapId[p]];
        i = p;
      }
    };
    const pop = (): number => {
      const top = heapId[0], last = heapId.length - 1;
      heapId[0] = heapId[last]; heapKey[0] = heapKey[last];
      heapId.pop(); heapKey.pop();
      let i = 0;
      const len = heapId.length;
      for (;;) {
        const l = i * 2 + 1, r = l + 1;
        let m = i;
        if (l < len && heapKey[l] < heapKey[m]) m = l;
        if (r < len && heapKey[r] < heapKey[m]) m = r;
        if (m === i) break;
        [heapKey[m], heapKey[i]] = [heapKey[i], heapKey[m]];
        [heapId[m], heapId[i]] = [heapId[i], heapId[m]];
        i = m;
      }
      return top;
    };
    const dirCount = this.diagonal ? 8 : 4;
    const dstep = this.diagonal ? 1 : 2;   // step by 2 over DX8 to hit only orthogonals

    for (const g of this.goals) {
      if (this.inBounds(g.col, g.row) && this.blocked[this.index(g.col, g.row)] === 0) {
        const i = this.index(g.col, g.row);
        if (this.dist[i] !== 0) { this.dist[i] = 0; push(i, 0); }
      }
    }
    while (heapId.length) {
      const i = pop();
      const col = i % this.cols, row = (i / this.cols) | 0;
      const base = this.dist[i];
      for (let s = 0; s < dirCount; s++) {
        const d = this.diagonal ? s : s * dstep;
        if (!this._canStep(col, row, d)) continue;
        const c = col + DX8[d], r = row + DY8[d], j = this.index(c, r);
        const nd = base + DCOST[d] * this.weight[j];
        if (nd < this.dist[j]) { this.dist[j] = nd; push(j, nd); }
      }
    }

    // Flow = negative gradient: each reachable non-goal cell steps to its
    // lowest-distance corner-safe neighbour.
    for (let row = 0; row < this.rows; row++) {
      for (let col = 0; col < this.cols; col++) {
        const i = this.index(col, row);
        if (this.dist[i] === Infinity || this.dist[i] === 0) continue;
        let best: FlowDir = -1, bestDist = this.dist[i];
        for (let s = 0; s < dirCount; s++) {
          const d = (this.diagonal ? s : s * dstep) as FlowDir;
          if (!this._canStep(col, row, d)) continue;
          const nd = this.dist[this.index(col + DX8[d], row + DY8[d])];
          if (nd < bestDist) { bestDist = nd; best = d; }
        }
        this.flow[i] = best;
      }
    }
    this._dirty = false;
  }

  /** @internal Can we step direction `d` from `(col,row)` — target in-bounds &
   *  passable, and (for diagonals, unless cutCorners) both orthogonal sides open. */
  private _canStep(col: number, row: number, d: number): boolean {
    const c = col + DX8[d], r = row + DY8[d];
    if (!this.inBounds(c, r) || this.blocked[this.index(c, r)] === 1) return false;
    if ((d & 1) && !this.cutCorners) {
      // Diagonal: both orthogonal neighbours must be open.
      if (this.isBlocked(col + DX8[d], row) || this.isBlocked(col, row + DY8[d])) return false;
    }
    return true;
  }

  private _ensure(): void { if (this._dirty) this.update(); }

  // ── Queries ────────────────────────────────────────────────────────────────

  /** Distance (field cost) from `(col, row)` to the nearest goal, or
   *  `Infinity` if blocked/unreachable. */
  distance(col: number, row: number): number {
    this._ensure();
    return this.inBounds(col, row) ? this.dist[this.index(col, row)] : Infinity;
  }

  /** Can an enemy at `(col, row)` reach a goal? */
  reachable(col: number, row: number): boolean {
    return this.distance(col, row) !== Infinity;
  }

  /** The {@link FlowDir} `(col, row)` flows toward its goal (`-1` at a goal /
   *  blocked / unreachable cell). */
  flowDir(col: number, row: number): FlowDir {
    this._ensure();
    return this.inBounds(col, row) ? (this.flow[this.index(col, row)] as FlowDir) : -1;
  }

  /** The unit flow VECTOR at cell `(col, row)` — the direction to move, as a
   *  `{x, y}` (zero when there's no flow). */
  flowVec(col: number, row: number): Vec2 {
    const d = this.flowDir(col, row);
    return d === -1 ? { x: 0, y: 0 } : { x: UVX[d], y: UVY[d] };
  }

  /**
   * The smooth steering direction for an enemy at world position `(x, y)` —
   * bilinearly interpolates the flow arrows of the four surrounding cells so
   * units off the cell centre don't jerk between headings. Returns a
   * unit-length `{x, y}` (zero at the goal / in a dead pocket). `cellSize` +
   * `origin` map world units to the grid (same convention as {@link cellAt}).
   */
  steer(x: number, y: number, cellSize = 1, originX = 0, originY = 0): Vec2 {
    this._ensure();
    // Continuous cell-space position, with integer coords at cell CENTRES.
    const fx = (x - originX) / cellSize - 0.5;
    const fy = (y - originY) / cellSize - 0.5;
    const c0 = Math.floor(fx), r0 = Math.floor(fy);
    const tx = fx - c0, ty = fy - r0;
    let vx = 0, vy = 0;
    const add = (c: number, r: number, wgt: number): void => {
      if (wgt <= 0 || !this.inBounds(c, r)) return;
      const d = this.flow[this.index(c, r)];
      if (d === -1) return;
      vx += UVX[d] * wgt; vy += UVY[d] * wgt;
    };
    add(c0, r0, (1 - tx) * (1 - ty));
    add(c0 + 1, r0, tx * (1 - ty));
    add(c0, r0 + 1, (1 - tx) * ty);
    add(c0 + 1, r0 + 1, tx * ty);
    const len = Math.hypot(vx, vy);
    if (len > 1e-4) return { x: vx / len, y: vy / len };
    // Fallback: the containing cell's own arrow (interp landed on blocked cells).
    return this.flowVec(Math.round(fx), Math.round(fy));
  }

  /**
   * Would blocking `(col, row)` still leave EVERY spawn able to reach a goal?
   * The tower-placement guard: returns `false` for a build that would fully
   * wall a spawn off (or that isn't a legal, currently-open cell). Runs a
   * connectivity check with the same movement rules — it does not mutate the
   * grid.
   */
  canBuild(col: number, row: number): boolean {
    if (!this.inBounds(col, row) || this.blocked[this.index(col, row)] === 1) return false;
    // Building on a goal or spawn is never allowed.
    const at = (list: Cell[]): boolean => list.some((p) => p.col === col && p.row === row);
    if (at(this.goals) || at(this.spawns)) return false;
    if (this.spawns.length === 0) return true;   // nothing to protect

    // Reachability BFS from all goals with this cell temporarily blocked.
    const bi = this.index(col, row);
    this.blocked[bi] = 1;
    const seen = new Uint8Array(this.cols * this.rows);
    let frontier: number[] = [];
    for (const g of this.goals) {
      if (this.inBounds(g.col, g.row) && this.blocked[this.index(g.col, g.row)] === 0) {
        const gi = this.index(g.col, g.row);
        if (!seen[gi]) { seen[gi] = 1; frontier.push(gi); }
      }
    }
    const dirCount = this.diagonal ? 8 : 4;
    const dstep = this.diagonal ? 1 : 2;
    while (frontier.length) {
      const next: number[] = [];
      for (const i of frontier) {
        const c = i % this.cols, r = (i / this.cols) | 0;
        for (let s = 0; s < dirCount; s++) {
          const d = this.diagonal ? s : s * dstep;
          if (!this._canStep(c, r, d)) continue;
          const j = this.index(c + DX8[d], r + DY8[d]);
          if (!seen[j]) { seen[j] = 1; next.push(j); }
        }
      }
      frontier = next;
    }
    this.blocked[bi] = 0;   // restore
    return this.spawns.every((s) => this.inBounds(s.col, s.row) && seen[this.index(s.col, s.row)] === 1);
  }

  /**
   * Trace the route from `(col, row)` by following the flow field to a goal —
   * an inclusive list of cells, for drawing a preview path or a debug overlay.
   * Empty when unreachable; capped so a broken field can't loop forever.
   */
  path(from: Cell, maxSteps = this.cols * this.rows): Cell[] {
    this._ensure();
    if (!this.reachable(from.col, from.row)) return [];
    const out: Cell[] = [{ col: from.col, row: from.row }];
    let col = from.col, row = from.row;
    for (let i = 0; i < maxSteps; i++) {
      const d = this.flow[this.index(col, row)];
      if (d === -1) break;   // reached a goal
      col += DX8[d]; row += DY8[d];
      out.push({ col, row });
    }
    return out;
  }
}
