// The Scene — a GAME STATE (Title, Play, GameOver…) and the common-access
// root for gameplay code, ported from the raster engine's proven model.
// Register a roster with Game.create({ scenes: { title, play, gameOver } })
// and transition with this.gotoPlay() / this.game.go(role, data); each
// transition tears the old scene down (its sprites die with it) and builds
// the next via setup(data).
//
// WITHIN a scene: a flat list of sprites + arcade motion + the declarative
// collision solver. NO scene graph, no display hierarchy (the research
// verdict: nobody puts transform trees on the GPU) — just sprites in
// add-order, class-pair collision rules, and a per-scene camera.
//
//   this.solid(Player, Wall)          — they can't pass through each other
//   this.on(Player, Coin, (p, c) ...) — overlap callback (pickups, hits)
//
// Lifecycle (all optional overrides): setup(data) builds the world;
// update(dt) is per-frame logic (call super.update(dt) — it advances
// sprites, physics and collisions); draw(d) adds world-space verbs on top
// of the auto-drawn sprites (call super.draw(d) first); drawHud(d) is the
// screen-space UI pass.
//
// Module load is DOM/GPU-free: everything here is data + math, headlessly
// testable against the built bundle.

import { Sprite } from './sprite.js';
import { Camera } from './camera.js';
import { CollisionGrid, type CollisionGridLike } from './collision-grid.js';
import type { Tilemap } from './tilemap.js';
import { SceneInput } from './scene-input.js';
import { SpritePool } from './sprite-pool.js';
import { VfxSystem } from './vfx.js';
import { Physics } from './physics.js';
import type { Contact } from './physics.js';
import type { Physics2d } from './physics2d.js';
import type { Draw } from './draw.js';
import type { Game } from './game.js';
import type { Preload } from './preload.js';
import type { Audio } from './audio.js';
import type { Tween } from './tween/index.js';
import type { EventDescriptor, EventFn, HitFn } from './glue.js';

/** Constructor type for a sprite class used in collision rules (`solid` / `on`). */
export type SpriteClass = abstract new (...args: never[]) => Sprite;

/** Constructor type for a Scene subclass — the roster holds these. */
export type SceneClass = new () => Scene;

/** The scene roster for Game.create: `play` is required; `title`, `gameOver`,
 * `intro` or any custom role key is optional (title/gameOver have built-in
 * fallbacks for goto targets). */
export type SceneRoster = { play: SceneClass } & Partial<Record<string, SceneClass>>;

/** @internal A `solid(A, B)` registration, consumed by `Physics.checkOverlaps`. */
export interface SolidRule { a: SpriteClass; b: SpriteClass; cb?: HitFn }
/** @internal An `on(A, B)` registration, consumed by `Physics.checkOverlaps`. */
export interface OnRule { a: SpriteClass; b: SpriteClass; cb: (a: Sprite, b: Sprite, contact: Contact) => void }

export class Scene {
  /** The owning Game — set before setup(). Global services + game.go() live here. */
  game!: Game;
  /** This scene's camera: follow a sprite, set bounds, shake(), or write x/y. */
  readonly camera = new Camera();
  /**
   * Typed keyboard + pointer input for this scene. Bind actions with `this.input.bind({...})`,
   * then read `this.input.keys.<name>.held` / `.pressed` in `update()`.
   */
  readonly input: SceneInput = new SceneInput(this);
  /**
   * The motion + collision system: gravity, worldBounds, effectors, joints, the
   * `solid(A, B)` solve and the `on(A, B)` overlap detection. Configure with
   * `this.physics.gravity = 360` and `this.physics.worldBounds = { x, y, w, h }`.
   */
  readonly physics: Physics = new Physics(this);
  /**
   * Optional full-body physics world (Box2D v3). Assign one from
   * `await Physics2d.create(...)` in `setup()` and the scene steps and syncs it
   * for you each frame. Bound sprites are driven by the simulation; unbound
   * sprites keep using the arcade `physics`. `null` = no full-body physics (the
   * default — nothing is loaded).
   */
  physics2d: Physics2d | null = null;
  /** Downward acceleration in world units/s² applied to dynamic bodies (× sprite.gravity). Alias of `physics.gravity`. */
  get gravity(): number { return this.physics.gravity; }
  set gravity(v: number) { this.physics.gravity = v; }
  readonly sprites: Sprite[] = [];
  /** The tile-based static collision map traced by physics. Defaults to the no-op grid (nothing blocks). */
  collisionMap: CollisionGridLike = CollisionGrid.staticNoCollision;
  /** Tilemap layers drawn as the scrolling background (and optional foreground layers). */
  backgroundMaps: Tilemap[] = [];
  /** Object pool for recycling frequently-spawned sprites — `this.pool.spawn(Bullet, x, y)`. */
  readonly pool: SpritePool = new SpritePool(this);
  /**
   * Object VFX — trails and one-shot bursts, all data: `sprite.vfx =
   * 'flameTrail'`, `this.vfx.burst('shockwave', x, y)`, or a manual
   * `this.vfx.trail(def)` you feed with point(). See vfx.md.
   */
  readonly vfx: VfxSystem = new VfxSystem();
  /** Declarative collision pairs and event listeners, set by the subclass from its `events/` folder. */
  events: EventDescriptor[] = [];

  private solids: SolidRule[] = [];
  private ons: OnRule[] = [];
  /** @internal Solid pairs from `solid(A, B)`, resolved by `Physics.checkOverlaps` before the detection pass. */
  get _solids(): SolidRule[] { return this.solids; }
  /** @internal Collision pairs from `on(A, B)`, consumed by `Physics.checkOverlaps`. */
  get _hits(): OnRule[] { return this.ons; }
  private _listeners: Map<string, EventFn[]> = new Map();
  /** Resolves a sprite's default size from its first frame (wired by Game). */
  frameSizer: ((frame: number) => { w: number; h: number }) | null = null;
  /** Wired by Game: the current view rect, for '%' config placement. */
  viewRect: (() => { x: number; y: number; w: number; h: number }) | null = null;

  /** Add a sprite (returns it). Default w/h resolve from its first frame. */
  add<T extends Sprite>(sprite: T): T {
    // '%' config dims resolve ONCE against the view at add-time (placement
    // sugar — after this the sprite is plain world units, physics and all).
    if (sprite.pct && this.viewRect) {
      const v = this.viewRect();
      if (sprite.pct.x !== undefined) sprite.x = v.x + sprite.pct.x * v.w;
      if (sprite.pct.y !== undefined) sprite.y = v.y + sprite.pct.y * v.h;
      if (sprite.pct.w !== undefined) sprite.w = sprite.pct.w * v.w;
      if (sprite.pct.h !== undefined) sprite.h = sprite.pct.h * v.h;
      sprite.pct = undefined;
    }
    sprite.last.x = sprite.x; // keep `last` honest through '%' placement, so the
    sprite.last.y = sprite.y; // first frame's CCD never sees a phantom teleport

    if ((sprite.w === 0 || sprite.h === 0) && this.frameSizer) {
      const s = this.frameSizer(sprite.frames + sprite.frame);
      if (sprite.w === 0) sprite.w = s.w;
      if (sprite.h === 0) sprite.h = s.h;
    }
    this.sprites.push(sprite);
    return sprite;
  }

  /** Declare that instances of A and B can never overlap (walls, floors, crates).
   *  Pass `cb` to also react to each resolved contact (damage, sound, …). */
  solid(a: SpriteClass, b: SpriteClass, cb?: HitFn): void {
    this.solids.push({ a, b, cb });
  }

  /** Declare an overlap callback between instances of A and B (pickups, bullets, hits).
   *  The handler also receives the minimal-penetration `Contact` (side + overlap) —
   *  ignore it, or feed it to `this.physics.reflect(sprite, contact)`. */
  on(a: SpriteClass, b: SpriteClass, cb: (a: Sprite, b: Sprite, contact: Contact) => void): void;
  /** Listen for a named game event emitted by `emit()`. Typically declared via `on('name', fn)` in `events/`. */
  on(name: string, fn: EventFn): void;
  on(
    aOrName: SpriteClass | string,
    bOrFn: SpriteClass | EventFn,
    cb?: (a: Sprite, b: Sprite, contact: Contact) => void,
  ): void {
    if (typeof aOrName === 'string') {
      const fn = bOrFn as EventFn;
      const ls = this._listeners.get(aOrName);
      if (ls) ls.push(fn);
      else this._listeners.set(aOrName, [fn]);
      return;
    }
    this.ons.push({ a: aOrName, b: bOrFn as SpriteClass, cb: cb as (a: Sprite, b: Sprite, contact: Contact) => void });
  }

  /** Fire a named game event — every listener registered for `name` runs synchronously with the scene and optional payload. */
  emit(name: string, payload?: unknown): void {
    const ls = this._listeners.get(name);
    if (ls) for (let i = 0; i < ls.length; i++) ls[i](this, payload);
  }

  // ── Lifecycle (override any; all base implementations are the machinery) ──

  /**
   * Declare assets to load BEFORE the scene runs — queue them on `load`
   * (`load.image(url)`, `load.json(url)`, `load.audio(url)`…); the engine
   * shows a progress bar while anything genuinely loads, then calls
   * `setup()`. Return a Promise to await custom async work. Skip entirely
   * for procedural (asset-free) scenes. Base is a no-op.
   */
  preload(_load: Preload): void | Promise<void> {}

  /**
   * Build the scene — called once on transition, with any go() payload.
   * May be async: return a Promise (e.g. `await game.assets.msdfFont(...)`,
   * `await game.world3d(...)`, `await Physics2d.create(...)`) and the engine
   * keeps the loading screen up and awaits it before the scene first renders.
   */
  setup(_data?: unknown): void | Promise<void> {}

  /**
   * Wire the declarative `events` list and pointer→sprite gesture dispatch for this scene
   * (raster calls this after `setup()`, so `this.game` is set).
   * TODO(wire): call from game.go() on the incoming scene, after setup() completes.
   * @internal
   */
  _activate(): void {
    this.input.attach();
    for (const reg of this.events) {
      if (reg.kind === 'hit') this.on(reg.a, reg.b, (a, b) => reg.fn(a, b, this));
      else if (reg.kind === 'solid') this.solid(reg.a, reg.b, reg.fn);
      else this.on(reg.name, reg.fn);
    }
  }

  /**
   * Tear down the scene when a transition replaces it: removes every pointer/gesture/text
   * subscription this scene registered on the game's input (scene-wide `on*` handlers and the
   * internal sprite-dispatch hooks), so handlers from dead scenes never fire again.
   * TODO(wire): call from game.go() on the outgoing scene, before the new one is built. Idempotent.
   * @internal
   */
  _deactivate(): void {
    this.input.detach();
  }

  /** Screen-space UI — called every frame with the HUD draw surface. */
  drawHud(_d: Draw): void {}

  // ── Common-access helpers ──────────────────────────────────────────────

  /** Audio service — play synth SFX with `this.sound.play('hit')` or music with `this.sound.music(url)`. */
  get sound(): Audio {
    return this.game.sound;
  }

  /** Tween service — animate any object property, e.g. `this.tween.to(sprite, { x: 200 }, { duration: 0.4 })`. */
  get tween(): Tween {
    return this.game.tween;
  }

  /** All live sprites that are instances of `type`. */
  getSpritesByType<T extends Sprite>(type: abstract new (...args: never[]) => T): T[] {
    const out: T[] = [];
    for (const s of this.sprites) if (s instanceof type && !s.dead) out.push(s);
    return out;
  }

  /** A world X at fraction f across this frame's view (0 = left, 1 = right). */
  vw(f: number): number {
    const v = this.viewRect?.();
    return v ? v.x + f * v.w : 0;
  }

  /** A world Y at fraction f down this frame's view (0 = top, 1 = bottom). */
  vh(f: number): number {
    const v = this.viewRect?.();
    return v ? v.y + f * v.h : 0;
  }

  /** This frame's view width in world units. */
  get width(): number { return this.viewRect?.().w ?? 0; }
  /** This frame's view height in world units. */
  get height(): number { return this.viewRect?.().h ?? 0; }
  /** Horizontal centre of the view (world X). */
  get centerX(): number { return this.vw(0.5); }
  /** Vertical centre of the view (world Y). */
  get centerY(): number { return this.vh(0.5); }

  // ── Transitions (payload arrives in the target scene's setup(data)) ─────

  /** Transition to the scene registered as 'intro'. */
  gotoIntro(data?: unknown): void { this.game.go('intro', data); }
  /** Transition to the scene registered as 'title' (built-in fallback exists). */
  gotoTitle(data?: unknown): void { this.game.go('title', data); }
  /** Transition to the scene registered as 'play'. */
  gotoPlay(data?: unknown): void { this.game.go('play', data); }
  /** Transition to 'gameOver' — pass a result, e.g. { win: true, score } (built-in fallback exists). */
  gotoGameOver(result?: unknown): void { this.game.go('gameOver', result); }

  /** One update: behaviour → motion (physics) → joints → solids → overlaps → sweep dead. */
  update(dt: number): void {
    // Advance the tilemap layers' per-tile animation clocks (raster ticked each
    // layer's Animation objects here; v2 maps own a single shared clock).
    for (const m of this.backgroundMaps) m.update(dt);
    for (const s of this.sprites) {
      // NOTE: touching flags are NOT reset here — sprite.update() reads LAST
      // frame's contacts (the raster contract: `if (this.touching.down &&
      // jump)` works). Physics resets them at the top of updateBody; 'none'
      // bodies reset here since physics never sees them.
      if (s.body === 'none') {
        s.touching.up = s.touching.down = s.touching.left = s.touching.right = false;
      }
      s.update(dt);
      s.stepAnim(dt);
      // Timed fx self-clear (flash/shake with duration, squash with cycles).
      const fx = s.fx;
      if (fx) {
        if (fx.flash?.duration !== undefined) {
          fx.flash._left = (fx.flash._left ?? fx.flash.duration) - dt;
          if (fx.flash._left <= 0) delete fx.flash;
        }
        if (fx.shake?.duration !== undefined) {
          fx.shake._left = (fx.shake._left ?? fx.shake.duration) - dt;
          if (fx.shake._left <= 0) delete fx.shake;
        }
        if (fx.squash) {
          fx.squash._t = (fx.squash._t ?? 0) + dt;
          if (fx.squash.cycles && fx.squash._t * (fx.squash.speed ?? 2) >= fx.squash.cycles) delete fx.squash;
        }
        if (Object.keys(fx).length === 0) s.fx = undefined;
      }
    }
    // Motion: gravity + velocity integration, effectors, world bounds — per body,
    // owned by Physics. 'none' bodies are user-moved and skipped entirely.
    for (const s of this.sprites) {
      if (s.body === 'none') { s.last.x = s.x; s.last.y = s.y; continue; }
      this.physics.updateBody(s, dt);
    }
    this.physics2d?.update(dt);     // full-body (Box2D) step + sync, before joints/collision see positions
    this.physics.updateJoints(dt);  // ropes/rods solve before collision sees the positions
    this.physics.checkOverlaps();   // declarative solid(A, B) solve + on(A, B) detection glue
    // Object VFX: feed sprite-bound trails from FINAL positions, then tick.
    this.vfx.particles = this.game?.fx ?? null;
    for (const s of this.sprites) {
      if (s.vfx && !s.dead) this.vfx.feed(s, s.vfx);
    }
    this.vfx.update(dt);

    for (let i = this.sprites.length - 1; i >= 0; i--) {
      if (this.sprites[i].dead) {
        const [s] = this.sprites.splice(i, 1);
        this.pool.tryReturn(s); // pooled classes recycle; others just drop
      }
    }
  }

  /**
   * Push the frame: background tilemaps → every sprite (scene order = paint order
   * unless z set) → foreground tilemaps. Raster's layer order preserved: maps draw
   * in `backgroundMaps` order, breaking to the sprite pass at the first
   * `foreground` map, which draws (with the rest) after the sprites.
   */
  draw(d: Draw): void {
    const view = this.viewRect?.() ?? { x: 0, y: 0, w: 0, h: 0 };

    let mapIndex = 0;
    for (; mapIndex < this.backgroundMaps.length; mapIndex++) {
      const map = this.backgroundMaps[mapIndex];
      if (map.foreground) {
        break; // foreground layers draw after sprites
      }
      map.draw(d, view);
    }

    this.vfx.drawUnder(d);   // trails stream BEHIND the bodies
    for (const s of this.sprites) {
      d.sprite(s.drawFrame, s.x, s.y, {
        w: s.w, h: s.h, rot: s.rot, flipX: s.flipX,
        tint: s.tint, alpha: s.alpha, z: s.z, blend: s.blend, fx: s.fx,
        uvRepeat: s.uvRepeat, uvScroll: s.uvScroll, deform: s.deform,
      });
    }

    for (; mapIndex < this.backgroundMaps.length; mapIndex++) {
      this.backgroundMaps[mapIndex].draw(d, view);
    }
    this.vfx.drawOver(d);    // burst rings + flashes pop over the world
  }

}

/**
 * Separate two overlapping AABBs along the axis of least penetration.
 * static/none bodies never move; two dynamics split the correction.
 * Exported for tests.
 */
export function separate(a: Sprite, b: Sprite): void {
  const px = Math.min(a.x + a.w - b.x, b.x + b.w - a.x); // x penetration
  const py = Math.min(a.y + a.h - b.y, b.y + b.h - a.y); // y penetration
  if (px <= 0 || py <= 0) return;
  const aMoves = a.body === 'dynamic';
  const bMoves = b.body === 'dynamic';
  if (!aMoves && !bMoves) return;
  const share = aMoves && bMoves ? 0.5 : 1;
  if (px < py) {
    const dir = a.centerX < b.centerX ? -1 : 1; // push a left or right
    if (aMoves) {
      a.x += dir * px * share;
      if (dir < 0) a.touching.right = true; else a.touching.left = true;
      if (a.vel.x * dir < 0) a.vel.x = -a.vel.x * a.bounce || 0;
    }
    if (bMoves) {
      b.x -= dir * px * share;
      if (dir < 0) b.touching.left = true; else b.touching.right = true;
      if (b.vel.x * dir > 0) b.vel.x = -b.vel.x * b.bounce || 0;
    }
  } else {
    const dir = a.centerY < b.centerY ? -1 : 1; // push a up or down
    if (aMoves) {
      a.y += dir * py * share;
      if (dir < 0) a.touching.down = true; else a.touching.up = true;
      if (a.vel.y * dir < 0) a.vel.y = -a.vel.y * a.bounce || 0;
    }
    if (bMoves) {
      b.y -= dir * py * share;
      if (dir < 0) b.touching.up = true; else b.touching.down = true;
      if (b.vel.y * dir > 0) b.vel.y = -b.vel.y * b.bounce || 0;
    }
  }
}
