// The engine-owned fixed-timestep clock. Physics, verlet ropes, and any other
// simulation all step through THIS — never their own accumulator — so bursty
// dt (backgrounded tabs, GC pauses) can never outrun a constraint solver.
// Render code interpolates with `alpha` for smooth motion on 120 Hz+ displays.

export class FixedClock {
  /** Fraction [0..1) of a step elapsed since the last consumed step — lerp render poses with this. */
  alpha = 0;
  private acc = 0;

  constructor(
    /** Simulation step in seconds (default 60 Hz). */
    readonly step = 1 / 60,
    /** Max steps consumed per advance — excess time is DROPPED (no spiral of death). */
    readonly maxSteps = 5,
  ) {}

  /** Feed a frame's dt; returns how many fixed steps to run right now. */
  advance(dt: number): number {
    this.acc += Math.max(0, dt);
    let steps = Math.floor(this.acc / this.step);
    if (steps > this.maxSteps) {
      this.acc -= (steps - this.maxSteps) * this.step; // drop the excess time
      steps = this.maxSteps;
    }
    this.acc -= steps * this.step;
    this.alpha = this.acc / this.step;
    return steps;
  }
}
