// The Game — the engine's front door. Owns the device (with loss recovery),
// the atlas, the batchers + depth buffer, the fixed-step clock, the scene,
// the camera and the frame loop, and hands game code a Draw surface each
// frame.
//
// THE LAYOUT MODEL (Resolution 2.0, dissolved): the game authors ONE number —
// `worldHeight`, the logical height of its world — and draws in those units.
// Every frame the visible world rect is `worldHeight` tall and as wide as the
// window's aspect makes it; the projection maps that rect to the full canvas.
// There is no resize event, no safe area, no pinning: read `game.view` for
// this frame's rect and derive layout from it. Rotate or resize the window
// mid-game and everything just re-fits.
//
// THE FRAME (two draw calls): scene sprites + verb pushes are routed to an
// opaque CUTOUT batch (depth write — early-Z kills overdraw) and a BLEND
// batch (shapes, translucency; depth-tested against the cutout content).
// See batch.ts for the architecture.

import { Gpu, installErrorOverlay } from './gpu.js';
import type { GlRenderer } from './webgl/renderer.js';
import type { GlWorld3d } from './webgl3d/world.js';
import { Atlas, textureFromCanvas } from './atlas.js';
import { DrawOrder, SRC_QUADS, SRC_LABELS, SRC_CUTOUT, SRC_ADD, SRC_TRI, QuadBatch, DEPTH_FORMAT } from './batch.js';
import { Draw } from './draw.js';
import type { TextPointer } from './unicode-text.js';
import { FixedClock } from './clock.js';
import { rgba } from './color.js';
import { Scene, type SceneRoster } from './scene.js';
import type { Camera } from './camera.js';
import { DefaultTitle, DefaultGameOver } from './defaults.js';
import { BitmapFont } from './font.js';
import { Particles } from './particles.js';
import type { World3d, World3dOptions, World3dFxHook } from './world3d.js';
import { VectorLayer } from './vector.js';
import { Lights2d } from './lights2d.js';
import { PostChain } from './post.js';
import { FxBatch } from './fxbatch.js';
import { GridBatch } from './gridbatch.js';
import { TriBatch } from './tribatch.js';
import { GlowPass } from './glowpass.js';
import type { SsaoPass, SsaoOptions } from './ssao.js';
import type { RaysPass, RaysOptions } from './rays.js';
import type { EffectDef } from './effects.js';
import { Input } from './input.js';
import type { Pointer } from './pointer.js';
import { Preload, LoadingScene, LOADING_MIN_MS } from './preload.js';
import { BackdropChain } from './backdrop.js';
import { DebugOverlay, normalizeDebug, type DebugOptions } from './debug.js';
import { clearAssetCaches, fontsSettled } from './assets.js';
import { MsdfRenderer } from './msdf.js';
import { UiRenderer } from './ui.js';
import { msdfTextureFrom, type MsdfFont } from './msdf-font.js';
import { Audio } from './audio.js';
import { Tween } from './tween/index.js';
import { Screen } from './screen.js';
import { Assets } from './game-assets.js';
import { PostLayer } from './post.js';
import { BackdropLayer } from './backdrop.js';

export interface GameOptions {
  /**
   * Where to mount the game. Pass a host element or a selector for one — the
   * engine ALWAYS creates its own `<canvas>` inside it (guaranteeing a WebGPU
   * context, never a stray WebGL one). Omit to fill the viewport (a fullscreen
   * canvas appended to `<body>`).
   */
  container?: HTMLElement | string;
  /** Logical world height — the ONE authored dimension (default 768). */
  worldHeight?: number;
  /** Clear colour, hex (default '#0b0e1a'). */
  background?: string;
  /** Fixed simulation step in seconds for onStep callbacks (default 1/60). */
  fixedStep?: number;
  /**
   * THE art axis. false (default): smooth — linear sampling, high-res art
   * scales cleanly. true: pixel art — sprites render at NATIVE resolution
   * but sample their texels BLOCKY (snapped to texel centres, one-screen-
   * pixel AA seams): fat crisp pixels with float-smooth motion, rotation
   * and scaling. Pick per game, never per sprite.
   */
  pixelArt?: boolean;
  /**
   * The scene roster: `{ play }` required, `title` / `gameOver` / `intro` /
   * custom roles optional (title and gameOver have built-in fallbacks as
   * go() targets). Boot order: intro → title → play, first registered wins.
   * Omit entirely for the single-scene shorthand (game.run(frame) drives an
   * implicit scene — fine for demos and toys).
   */
  scenes?: SceneRoster;
  /** Replace the built-in loading bar: draws on the HUD surface with the eased 0..1 progress. */
  drawLoading?: (d: Draw, progress: number) => void;
  /** Show the dev error overlay for GPU/page errors (default true). */
  overlay?: boolean;
}

/** The world rect on screen this frame, in world units. */
export interface ViewRect { x: number; y: number; w: number; h: number }

export class Game {
  /** Engine version string, stamped at build time. */
  readonly version: string = typeof __ENGINE_VERSION__ !== 'undefined' ? __ENGINE_VERSION__ : 'Phaser AE v2 (dev)';
  /** The draw verbs — valid inside the run() callback. WORLD space (scrolls with the camera). */
  readonly draw: Draw;
  /** The same verbs in SCREEN space: origin (0,0) top-left of the window, camera-proof,
   * always on top of the world. Score, health bars, prompts go here. */
  readonly hud: Draw;
  /** The ACTIVE scene (an implicit one when no roster was given). */
  current: Scene;
  /** Alias for the active scene — `game.scene.add(...)` etc. */
  get scene(): Scene { return this.current; }
  /** The active scene's camera (each scene owns its own). */
  get camera(): Camera { return this.current.camera; }
  /** The particle system — emit() bursts/streams; updated + drawn automatically (over the scene). */
  readonly fx = new Particles();
  /** This frame's visible world rect (camera origin + worldHeight fit). */
  readonly view: ViewRect = { x: 0, y: 0, w: 0, h: 0 };
  /** Keyboard and pointer input. Read key/mouse state from scenes via `this.input`. */
  readonly input: Input;
  /** Audio / SFX / music system. Play sounds with `this.game.sound.play('hit')` or stream music with `.music(url)`. */
  readonly sound: Audio;
  /** Motion / animation system (tween / ease / interpolate). Animate sprite properties with `this.tween.to(sprite, { x: 200 })`. Advanced by the run loop — tweens freeze when the game pauses. */
  readonly tween: Tween;
  /**
   * The PRESENTATION SURFACE — the canvas as a display, and what you capture off
   * it: `game.screen.fullscreen()`, `.screenshot(cb)`, `.record(60, 10, cb)`.
   * Host-shell API (a page's fullscreen / share button), not game API — nothing
   * here touches the simulation. To freeze the game use `game.pause()`.
   */
  readonly screen: Screen;
  /**
   * THE ASSET REGISTRY — bake or load something once, get the handle the draw
   * verbs take: `game.assets.loadFrames(url)`, `.font()`, `.msdfFont(png, json)`,
   * `.deformer(def)`. Every call is idempotent, so setup() can re-run for free.
   */
  readonly assets: Assets;
  /**
   * THE POST CHAIN — full-screen effects OVER the finished frame:
   * `game.post.add('bloom')`, `game.post.clear()`. For fire/smoke/sparks IN the
   * world you want `game.fx` (particles), not this.
   */
  readonly post: PostLayer;
  /**
   * THE BACKDROP STACK — full-screen layers BEHIND the world, camera-aware:
   * `game.backdrop.add('stars')`, `.clear()`, `.background(img)`.
   */
  readonly backdrop: BackdropLayer;
  /** HUD stays crisp above post effects (default). false = effects apply to the HUD too. */
  hudAboveFx = true;
  /**
   * Seconds of input GRACE after every scene transition (default 0.5 =
   * 500 ms): all keys and gestures read as inactive, so a player frantically
   * tapping fire when they die can't instantly dismiss the game-over screen.
   * Set 0 to disable.
   */
  inputGrace = 0.5;
  /**
   * The DEBUG OVERLAY — ships in every game, off by default. Set `true` for
   * everything (hitboxes, velocity vectors, contacts, tile collision,
   * stats) or pick: `game.debug = { hitboxes: true }`. For players AND
   * agents: when a hitbox looks wrong, turn this on so they can SEE it.
   */
  get debug(): boolean | DebugOptions { return this.debugOpts ?? false; }
  set debug(v: boolean | DebugOptions) { this.debugOpts = normalizeDebug(v); }
  /** Seconds since run() started. */
  time = 0;
  readonly canvas: HTMLCanvasElement;
  /** Which backend this game runs on: 'webgpu', or 'webgl' (the fallback). */
  readonly renderer: 'webgpu' | 'webgl';

  private gpu: Gpu | null;
  /** The WebGL fallback backend (null on the WebGPU path). */
  private glr: GlRenderer | null;
  /** The GL 3D world when the fallback carries one (this.world stays the
   *  public-typed handle; this is the concretely-typed twin reference). */
  private glWorld: GlWorld3d | null = null;

  private atlas = new Atlas();
  private cutoutBatch: QuadBatch;
  private blendBatch: QuadBatch;
  /** Bitmap labels for the WORLD surface's UI — flushed in the UI band, over panels. */
  private textBatch: QuadBatch;
  /**
   * Submission order for each surface's SCENE content: its quads and its text
   * pass, interleaved. A sign drawn before a wall goes behind it — the frame
   * breaks the quad batch, draws the text, and resumes. See DrawOrder.
   */
  private sceneOrder: DrawOrder;
  private hudOrder: DrawOrder;
  /** The WORLD text pass (MSDF + Unicode blocks) — over the lit scene, under the HUD. */
  private msdf: MsdfRenderer;
  private ui: UiRenderer;
  /** The SCREEN-SPACE twin: the same text verbs on `game.hud`, in CSS pixels, over the HUD sprites. */
  private msdfHud: MsdfRenderer;
  private uiHud: UiRenderer;
  /** Bumped on every device/context rebuild — UnicodeText re-uploads when it changes. */
  private texEpoch = 0;
  /** Set by a hovered interactive text block each frame; drives the hand cursor. */
  private cursorWanted = false;
  /** The cursor currently applied to the canvas, so we only touch style on change. */
  private cursorNow = '';
  private addBatch: QuadBatch;
  private fxBatch: FxBatch;
  private gridBatch: GridBatch;
  private triBatch: TriBatch;
  /**
   * THE VECTOR LAYER — first-class line art (retained VectorShapes with
   * per-shape transforms, shatter(), deformable polylines, immediate
   * seg()/poly()): `game.vector.shape(points, { glow: 0.8 })`. Drawn in the
   * scene pass between the blend and grid batches; pair with bloom for the
   * full vector-monitor look. See skills/vector.md.
   */
  readonly vector: VectorLayer;
  private glowPass: GlowPass;
  private _lights2d: Lights2d | null = null;
  /**
   * The 2D LIGHT layer — additive point/spot lights with hard shadows off
   * scenery (`lights2d.occluders`), colour mixing and flicker. Created on first
   * access (games that don't light pay nothing). Draw your scene, drop a dark
   * ambient overlay, then this adds the lights back. See skills/lights2d.md.
   */
  get lights2d(): Lights2d {
    if (!this._lights2d) {
      if (this.gpu) {
        this._lights2d = new Lights2d(this.gpu.device, this.gpu.format);
        this.gpu.onRebuild((device) => this._lights2d?.rebuild(device));
      } else {
        // The GL twin shares the surface; the renderer owns its rebuild.
        this._lights2d = this.glr!.createLights2d() as unknown as Lights2d;
      }
    }
    return this._lights2d;
  }
  // The 3D core (world3d-core.js) is a LAZY chunk — nothing 3D exists until
  // the first `await game.world3d()`. ssao/rays passes ride the same chunk.
  private core3d: Promise<typeof import('./core3d.js')> | null = null;
  private worldP: Promise<World3d> | null = null;
  private ssaoPass: SsaoPass | null = null;
  private raysPass: RaysPass | null = null;
  private pendingSsao: boolean | SsaoOptions | null = null;
  private pendingRays: boolean | RaysOptions | null = null;
  private hudBatch: QuadBatch;
  /** `d.text()` glyphs for the HUD surface — flushed in the text slot, over panels. */
  private hudTextBatch: QuadBatch;
  private world: World3d | null = null;
  private postChain: PostChain;
  private backdrops: BackdropChain;
  private atlasView: GPUTextureView | null = null;
  private msaaColor: GPUTexture | null = null;
  private worldDepth: GPUTexture | null = null;
  private worldDepthView: GPUTextureView | null = null;
  private clock: FixedClock;
  private stepFns: Array<(step: number) => void> = [];
  private bg: readonly [number, number, number, number];
  private worldHeight: number;
  private debugOpts: Required<DebugOptions> | null = null;
  private debugOverlay = new DebugOverlay();
  private roster: SceneRoster | null;
  private booted = false;
  private drawLoading?: (d: Draw, progress: number) => void;
  /** Registered frames per url|frameW|frameH — loadFrames/framesOf are idempotent. */
  private frameCache = new Map<string, number>();
  /** Baked bitmap fonts per font|charset — font() is idempotent (see below). */
  private fontCache = new Map<string, BitmapFont>();
  private raf = 0;
  private last = -1;
  private textureReady = false;
  /** atlas.generation last uploaded to the GPU — re-upload when it falls behind. */
  private uploadedGen = -1;
  private depth: GPUTexture | null = null;
  private pixelArt = false;

  private filter: GPUFilterMode;

  /** The boot banner logs once per page, however many Games are constructed. */
  private static bannerShown = false;

  // Run-loop state for the host controls: pause/resume freeze the loop without
  // losing the frame callback, so the last frame stays on screen.
  private running = false;
  private destroyed = false;
  /** @internal Window listeners added at create() — held so destroy() removes them. */
  private winListeners: Array<[string, EventListener]> = [];
  /** @internal The rAF closure built by run(), re-scheduled by resume(). */
  private tickFn: ((now: number) => void) | null = null;
  /** @internal Mute state of `sound` before pause() silenced it, so resume() restores the user's choice. */
  private soundMutedBeforePause = false;

  /**
   * @internal Guards the one-shot `window.PhaserGameReady()` callback so it fires
   * exactly once — after the first real scene is built — and never again.
   */
  private _readyFired = false;
  /**
   * @internal Guards the one-shot `window.PhaserGamePlaying()` callback so it
   * fires exactly once — the first time the `'play'` scene is built.
   */
  private _playingFired = false;

  private constructor(gpu: Gpu | null, glr: GlRenderer | null, opts: GameOptions) {
    this.gpu = gpu;
    this.glr = glr;
    this.renderer = gpu ? 'webgpu' : 'webgl';
    this.banner();
    this.canvas = gpu ? gpu.canvas : glr!.ctx.canvas;
    this.worldHeight = opts.worldHeight ?? 768;
    this.bg = rgba(opts.background ?? '#0b0e1a');
    this.clock = new FixedClock(opts.fixedStep ?? 1 / 60);
    // pixelArt = blocky sampling at native resolution (see batch.ts).
    const blocky = opts.pixelArt === true;
    this.pixelArt = blocky;
    this.filter = 'linear';
    const filter = this.filter;
    if (gpu) {
      this.cutoutBatch = new QuadBatch(gpu.device, gpu.format, { cutout: true, filter, blocky });
      this.blendBatch = new QuadBatch(gpu.device, gpu.format, { cutout: false, filter, blocky });
      this.msdf = new MsdfRenderer(gpu.device, gpu.format);
      this.msdfHud = new MsdfRenderer(gpu.device, gpu.format, 1024);
      this.ui = new UiRenderer(gpu.device, gpu.format);
      this.uiHud = new UiRenderer(gpu.device, gpu.format);
      this.addBatch = new QuadBatch(gpu.device, gpu.format, { cutout: false, blend: 'add', filter, blocky });
      // Per-object fx keep nearest under pixelArt (their tap rings aren't blocky-aware).
      this.fxBatch = new FxBatch(gpu.device, gpu.format, { filter: opts.pixelArt ? 'nearest' : 'linear' });
      this.glowPass = new GlowPass(gpu.device, gpu.format);
      this.gridBatch = new GridBatch(gpu.device, gpu.format, { filter, blocky });
      this.vector = new VectorLayer(gpu.device, gpu.format);
      this.triBatch = new TriBatch(gpu.device, gpu.format);
      // HUD: one blend batch, no depth test — screen space paints in push order.
      this.hudBatch = new QuadBatch(gpu.device, gpu.format, { cutout: false, depthTest: false, capacity: 4096, filter, blocky });
      // Bitmap text rides in the TEXT slot (after the panel pass), so it never
      // depth-tests against the scene — same rule the MSDF pass follows.
      this.textBatch = new QuadBatch(gpu.device, gpu.format, { cutout: false, depthTest: false, filter, blocky });
      this.hudTextBatch = new QuadBatch(gpu.device, gpu.format, { cutout: false, depthTest: false, capacity: 4096, filter, blocky });
      this.postChain = new PostChain(gpu.device, gpu.format);
      this.backdrops = new BackdropChain(gpu.device, gpu.format);
      this.sceneOrder = new DrawOrder();
      this.hudOrder = new DrawOrder();
    } else {
      // The WebGL backend: the renderer constructed the full twin set (same
      // begin/push/flush surface, same instance packing — see webgl/). The
      // casts are the backend seam: shared code drives the twins duck-typed;
      // the WebGPU-only members are only reached inside `if (this.gpu)` arms.
      const r = glr!;
      this.cutoutBatch = r.cutoutBatch as unknown as QuadBatch;
      this.blendBatch = r.blendBatch as unknown as QuadBatch;
      this.msdf = r.msdf as unknown as MsdfRenderer;
      this.msdfHud = r.msdfHud as unknown as MsdfRenderer;
      this.ui = r.ui as unknown as UiRenderer;
      this.uiHud = r.uiHud as unknown as UiRenderer;
      this.addBatch = r.addBatch as unknown as QuadBatch;
      this.fxBatch = r.fxBatch as unknown as FxBatch;
      this.glowPass = r.glowPass as unknown as GlowPass;
      this.gridBatch = r.gridBatch as unknown as GridBatch;
      this.vector = r.vector as unknown as VectorLayer;
      this.triBatch = r.triBatch as unknown as TriBatch;
      this.hudBatch = r.hudBatch as unknown as QuadBatch;
      this.textBatch = r.textBatch as unknown as QuadBatch;
      this.hudTextBatch = r.hudTextBatch as unknown as QuadBatch;
      this.postChain = r.postChain as unknown as PostChain;
      this.backdrops = r.backdrops as unknown as BackdropChain;
      // The GL renderer runs the ordered walk itself, so both halves must share
      // ONE order log per surface — adopt the renderer's rather than making our own.
      this.sceneOrder = r.sceneOrder;
      this.hudOrder = r.hudOrder;
    }
    // Interactive text hit-tests the pointer in its OWN surface's units. The
    // tracker reports world coordinates, so the HUD closure maps them back
    // through this frame's view — the one screen↔world mapping, reused.
    const wantCursor = (): void => { this.cursorWanted = true; };
    // The tracker's DOM listeners are lazy: without this a game whose only
    // pointer use is interactive TEXT (no mouse binding, no gesture handler)
    // would never see a pointer at all, and hover would silently never fire.
    // Only interactive blocks read these closures, so static labels cost nothing.
    const pointer = (): Pointer | null => {
      this.input.pointerTracker.attach();
      return this.input.ignoring ? null : this.input.pointer;
    };
    const worldPointer = (): TextPointer | null => {
      const p = pointer();
      return p ? {
        x: p.x, y: p.y, down: p.isDown, wantCursor,
        // The press EDGE and where it landed — see TextPointer. The tracker
        // reports both in world units already.
        pressedAt: p.downTime, pressX: p.startX, pressY: p.startY,
      } : null;
    };
    const hudPointer = (): TextPointer | null => {
      const p = pointer();
      if (!p) return null;
      const v = this.view;
      const toHudX = (wx: number): number => ((wx - v.x) / Math.max(1e-6, v.w)) * this.hud.w;
      const toHudY = (wy: number): number => ((wy - v.y) / Math.max(1e-6, v.h)) * this.hud.h;
      return {
        x: toHudX(p.x),
        y: toHudY(p.y),
        down: p.isDown,
        wantCursor,
        pressedAt: p.downTime, pressX: toHudX(p.startX), pressY: toHudY(p.startY),
      };
    };
    this.blendBatch.joinOrder(this.sceneOrder, SRC_QUADS);
    this.msdf.joinOrder(this.sceneOrder);
    this.ui.joinOrder(this.sceneOrder);
    this.textBatch.joinOrder(this.sceneOrder, SRC_LABELS);
    this.cutoutBatch.joinOrder(this.sceneOrder, SRC_CUTOUT);
    this.addBatch.joinOrder(this.sceneOrder, SRC_ADD);
    this.triBatch.joinOrder(this.sceneOrder);
    this.gridBatch.joinOrder(this.sceneOrder);
    this.fxBatch.joinOrder(this.sceneOrder);
    this.hudBatch.joinOrder(this.hudOrder, SRC_QUADS);
    this.msdfHud.joinOrder(this.hudOrder);
    this.uiHud.joinOrder(this.hudOrder);
    this.hudTextBatch.joinOrder(this.hudOrder, SRC_LABELS);
    this.draw = new Draw(this.cutoutBatch, this.blendBatch, this.atlas, this.addBatch, this.fxBatch, this.glowPass, this.gridBatch, this.triBatch, this.msdf, worldPointer, this.ui, this.textBatch);
    this.hud = new Draw(this.hudBatch, this.hudBatch, this.atlas, this.hudBatch, null, null, null, null, this.msdfHud, hudPointer, this.uiHud, this.hudTextBatch);
    // Keyboard + pointer input service (ported from the raster engine). The
    // PointerTracker maps client coords to world units through this frame's
    // view via input.toWorld, so CSS layout and input can never disagree.
    const mobile = typeof navigator !== 'undefined' && /mobile|android|iphone|ipad|ipod/i.test(navigator.userAgent);
    const touchDevice = typeof window !== 'undefined' && 'ontouchstart' in window;
    this.input = new Input(this.canvas, touchDevice, mobile);
    // Audio + tween services (ported from the raster engine). The Audio
    // constructor installs its own once-only user-gesture unlock listeners
    // (pointerdown/keydown) — raster's pattern, mirrored verbatim.
    this.sound = new Audio();
    this.tween = new Tween();
    // The widget layer's dependencies: input and the zero-setup fallback font
    // are both built AFTER the Draw surfaces, so they arrive by attachment
    // rather than through Draw's constructor. The font bakes on first use, so a
    // game that never draws a widget never pays for it.
    let uiFont: BitmapFont | null = null;
    const uiDeps = {
      input: () => this.input,
      bitmapFont: () => uiFont ?? (uiFont = this.assets.font({ font: 'bold 20px system-ui, sans-serif' })),
      msdfText: (font: MsdfFont, str: string, size: number, color: string, wrap: number, align: 'left' | 'center' | 'right', bold: boolean) =>
        // MSDF bold is FAUX — a field-weight offset, not a second font file.
        this.assets.msdfText(font, str, { fontSize: size, color, maxWidth: wrap, align, weight: bold ? 0.09 : 0 }),
      unicodeText: (str: string, size: number, color: string, wrap: number, align: 'left' | 'center' | 'right', bold: boolean) =>
        this.assets.unicodeText(str, { fontSize: size, color, maxWidth: wrap, align, fontWeight: bold ? 700 : 400 }),
    };
    this.draw.attachUi(uiDeps);
    this.hud.attachUi(uiDeps);
    // The presentation surface owns its own state (fullscreen mode, pending shot,
    // recorder) and reads what it needs from here through closures, so nothing
    // private has to become public to serve it.
    this.screen = new Screen({
      canvas: this.canvas,
      sound: this.sound,
      isPixelArt: () => this.pixelArt,
      isRunning: () => this.running,
      isDestroyed: () => this.destroyed,
      markDirty: () => (this.gpu ?? this.glr)!.markDirty(),
    });
    // Same closure-host pattern: the renderer-owned pieces (atlas, msdf, grid
    // batch) are assigned per backend just above, so they're read lazily.
    this.assets = new Assets({
      atlas: () => this.atlas,
      msdfTexture: (src, w, h) => (this.gpu
        ? msdfTextureFrom(this.gpu.device, src, w, h).createView()
        // The GL msdf twin keys its texture runs on this handle opaquely.
        : this.glr!.msdfTexture(src) as unknown as GPUTextureView),
      textTexture: (canvas) => {
        // Both text passes cache a bind group per view, so a re-rasterized
        // block must evict BOTH or the cache grows for the life of the game.
        const forget = (v: GPUTextureView): void => { this.msdf.release(v); this.msdfHud.release(v); };
        if (this.gpu) {
          // PREMULTIPLIED: the text pass blends premultiplied, and linear
          // filtering on unpremultiplied ink fringes every antialiased edge.
          const tex = textureFromCanvas(this.gpu.device, canvas, true);
          const view = tex.createView();
          return { view, destroy: () => { forget(view); tex.destroy(); } };
        }
        const gl = this.glr!;
        const tex = gl.textTexture(canvas);
        const view = tex as unknown as GPUTextureView;
        return { view, destroy: () => { forget(view); gl.deleteTexture(tex); } };
      },
      textureEpoch: () => this.texEpoch,
      registerDeform: (def) => this.gridBatch.register(def),
    });
    this.post = new PostLayer(() => this.postChain);
    this.backdrop = new BackdropLayer(() => this.backdrops);
    // The one screen→world mapping in the engine: the pointer tracker AND
    // input.toWorld() both read it, so a gesture and a raw DOM event always
    // agree about where the player touched.
    this.input.pointerTracker.mapToWorld = (clientX, clientY) => {
      const r = this.canvas.getBoundingClientRect();
      return {
        x: this.view.x + ((clientX - r.left) / Math.max(1, r.width)) * this.view.w,
        y: this.view.y + ((clientY - r.top) / Math.max(1, r.height)) * this.view.h,
      };
    };
    this.roster = opts.scenes ?? null;
    this.drawLoading = opts.drawLoading;
    // The pre-boot scene: the implicit single scene (shorthand mode), or a
    // placeholder the roster's first scene replaces when run() starts.
    this.current = this.attach(new Scene());
    // The view is valid from CREATION (not just the first frame) so load-time
    // scene.add() can resolve '%' placements. The canvas can be 0-sized
    // mid-load — fall back to the window's aspect.
    const view = this.view as { w: number; h: number };
    view.h = this.worldHeight;
    view.w = this.worldHeight * ((this.canvas.width || window.innerWidth) / Math.max(1, this.canvas.height || window.innerHeight));
    // Device-loss recovery: recreate pipelines/buffers/depth, re-upload the atlas.
    if (gpu) gpu.onRebuild((device) => {
      this.cutoutBatch.rebuild(device);
      this.blendBatch.rebuild(device);
      this.msdf.rebuild(device);
      this.msdfHud.rebuild(device);
      this.ui.rebuild(device);
      this.uiHud.rebuild(device);
      this.texEpoch++;               // every UnicodeText texture died with the device
      this.addBatch.rebuild(device);
      this.fxBatch.rebuild(device);
      this.gridBatch.rebuild(device);
      this.triBatch.rebuild(device);
      this.vector.rebuild(device);
      this.glowPass.rebuild(device);
      this.ssaoPass?.rebuild(device);
      this.raysPass?.rebuild(device);
      this.hudBatch.rebuild(device);
      this.textBatch.rebuild(device);
      this.hudTextBatch.rebuild(device);
      this.world?.rebuild(device);
      this.postChain.rebuild(device);
      this.backdrops.rebuild(device);
      this.depth = null;
      this.msaaColor = null;
      this.worldDepth = null;
      this.worldDepthView = null;
      this.textureReady = false;
    });
    // Context-restore recovery on the GL backend: the renderer rebuilds its
    // own twins; the game just re-uploads the atlas on the next frame.
    if (glr) glr.onRebuild(() => { this.textureReady = false; this.texEpoch++; });

    // Expose the running game on the window for the host page (its pause / mute
    // controls call `window.game.pause()`; its screenshot / record / fullscreen
    // controls call `window.game.screen.*`) and for tooling.
    // Harmless for shipped games; last Game constructed wins.
    if (typeof window !== 'undefined') (window as unknown as { game: Game }).game = this;
  }

  /**
   * The boot banner — one console line with colour blocks, the engine name +
   * version, and a clickable homepage link (devtools auto-link bare URLs).
   * Logged once per page, no matter how many Games are constructed.
   */
  private banner(): void {
    if (Game.bannerShown || typeof console === 'undefined') return;
    Game.bannerShown = true;
    // Every segment carries the same 2px vertical padding so the colour blocks
    // and the version badge render at the SAME height (a bare space is shorter).
    console.log(
      `%c %c %c %c %c ${this.version} %c https://phaser.io`,
      'background: #ff47b6; padding: 2px 3px',
      'background: #9742f5; padding: 2px 3px',
      'background: #3d8bff; padding: 2px 3px',
      'background: #2bd9c6; padding: 2px 3px',
      'color: #ffffff; background: #0f1320; padding: 2px 8px',
      'color: #3d8bff',
    );
  }

  /**
   * Boot the engine. WebGPU is tried first; where it's absent (or where
   * `window.PHASER_WEBGPU === false` / a `?webgl` URL param forces it, for
   * testing) the engine falls back to the WebGL2 backend — a separate, lazily
   * loaded render path with core feature parity (high-end effects are
   * WebGPU-only; see docs/webgl2-fallback-plan.md). Only when BOTH are absent
   * does this show an on-page message and reject.
   */
  static async create(opts: GameOptions = {}): Promise<Game> {
    const canvas = makeCanvas(opts.container);
    const onError = opts.overlay === false ? (m: string) => console.error(m) : installErrorOverlay();
    // The forced-fallback switches (both checked so the examples browser can
    // inject a query param — an iframe can't set a window global before the
    // page's module executes).
    const forceGl = typeof window !== 'undefined' && (
      (window as unknown as { PHASER_WEBGPU?: unknown }).PHASER_WEBGPU === false ||
      (typeof location !== 'undefined' && /[?&]webgl(=|&|$)/.test(location.search))
    );
    const gpu = forceGl ? null : await Gpu.init(canvas, { onError });
    let glr: GlRenderer | null = null;
    if (!gpu) {
      const mod = await import('./webgl-core.js');
      glr = await mod.GlRenderer.init(canvas, { onError, pixelArt: opts.pixelArt === true });
      if (glr) {
        console.info(forceGl
          ? 'Phaser AE: WebGL2 fallback forced (PHASER_WEBGPU=false / ?webgl).'
          : 'Phaser AE: WebGPU unavailable — using the WebGL2 fallback renderer.');
      }
    }
    if (!gpu && !glr) {
      const div = document.createElement('div');
      div.style.cssText = 'position:fixed;inset:0;display:flex;align-items:center;justify-content:center;color:#fff;font:16px monospace;text-align:center;padding:24px';
      div.textContent = 'This game needs WebGPU or WebGL2 (any modern browser).';
      canvas.replaceWith(div);
      throw new Error('WebGPU and WebGL2 unavailable');
    }
    canvas.style.touchAction = 'none';
    const game = new Game(gpu, glr, opts);
    // Keyboard state is Input's alone — it owns the only keydown/keyup/blur
    // listeners and both granularities read from them (`input.key(code)` and
    // the bound actions). Game deliberately keeps no second copy.
    return game;
  }

  /**
   * Transition to the scene registered under `role` ('title', 'play',
   * 'gameOver', 'intro' or a custom key). The old scene — sprites, camera,
   * rules — is dropped whole; the new one is built via setup(data).
   * Built-in fallbacks cover 'title' and 'gameOver'.
   */
  go(role: string, data?: unknown): void {
    void this.transition(role, data).catch((err) => {
      console.error(`Scene transition to '${role}' failed:`, err);
    });
  }

  /** @internal The actual goto flow — async so scene preload() can load assets. */
  private async transition(role: string, data?: unknown): Promise<void> {
    const DEFAULTS: Record<string, new () => Scene> = { title: DefaultTitle, gameOver: DefaultGameOver };
    const Cls = this.roster?.[role] ?? DEFAULTS[role];
    if (!Cls) throw new Error(`No scene registered for role '${role}'`);
    // Detach the outgoing scene's input FIRST — a stale onTap re-triggering
    // goto mid-transition was raster's classic leak. Then wipe ALL input
    // state: a key/pointer released just after the switch must not fire in
    // the new scene (the "release quits game-over" bug).
    this.current?._deactivate();
    this.input.reset();
    const scene = this.attach(new Cls());

    const load = new Preload(this.sound, (url) => this.loadModelDataVia(url));
    const custom = scene.preload(load);
    if (load.pending > 0) {
      // Something genuinely needs loading → show the loading screen, held for
      // at least LOADING_MIN_MS so a cached load still shows a smooth fill.
      const loader = this.attach(new LoadingScene());
      loader.progressFn = () => load.progress;
      loader.custom = this.drawLoading;
      this.current = loader;
      await Promise.all([
        load.all(),
        Promise.resolve(custom),
        new Promise<void>((r) => setTimeout(r, LOADING_MIN_MS)),
      ]);
    } else {
      // Nothing pending — settle the (instant) queue + any async preload work.
      await Promise.all([load.all(), Promise.resolve(custom)]);
    }
    // Whatever the queue held, never let setup() bake text before the document's
    // fonts have settled: a face still in flight rasterizes as a fallback and
    // that wrong glyph set is permanent. This covers @font-face declared in the
    // host page, which the load queue knows nothing about; resolves immediately
    // when nothing is pending.
    await fontsSettled();

    this.fx.clear();               // particles never leak across scenes
    // setup() is awaitable and the engine DOCUMENTS async work there —
    // `await game.assets.msdfFont(...)`, `await game.world3d(...)`,
    // `await Physics2d.create(...)`. Await it with the loading screen (or the
    // outgoing scene) STILL on screen, so the incoming scene never renders a
    // frame before its atlas frames / font textures exist. Skipping this await
    // was the "first-run title screen shows the font atlas" corruption: the
    // half-built scene drew for a frame or two sampling whatever was already in
    // the shared atlas; on the 2nd visit everything's built, so it looked fine.
    await Promise.resolve(scene.setup(data));
    // A concurrent go() may have taken over while preload/setup ran — detach
    // whatever is current (idempotent) before we swap in.
    this.current?._deactivate();
    this.current = scene;
    scene._activate();
    // The grace window starts when the scene becomes interactive: frantic
    // fire-tapping can't instantly dismiss what it shows (game.inputGrace).
    this.input.ignoreFor(this.inputGrace);
    // The first real scene is now live — signal the host page exactly once…
    this.signalReady();
    // …and if this IS the main gameplay scene (role 'play', past any title),
    // signal that too — the host hooks it to screenshot the game in motion.
    this.signalPlaying(role);
  }

  /** Wire a scene to this game's services (size/view hooks + back-reference). */
  private attach<T extends Scene>(scene: T): T {
    scene.game = this;
    scene.frameSizer = (f) => this.assets.frameSize(f);
    scene.viewRect = () => this.view;
    return scene;
  }


  /**
   * Opt into the 3D layer: a perspective world (Y-UP) of boxes + billboard
   * sprites rendered UNDER the 2D layer and HUD. The 3D core ships as a
   * separate lazy chunk (world3d-core.js) — the first call loads it, so:
   * `const world = await game.world3d({ ... })` (one await in setup, the
   * physics pattern). Idempotent: later calls resolve to the same world.
   */
  /**
   * SSAO (Lighting 2.0 tier 3) — screen-space ambient occlusion over the 3D
   * world: creases, contact points and corners darken naturally. Costs one
   * half-res estimate + blur per frame. `world.ssao(true)`,
   * `world.ssao({ radius, strength, power })` to tune, `false` to stop.
   * Requires a 3D world (it reads the world depth buffer).
   */
  /** Project a 3D world point into the 2D LAYER's coordinates — draw a
   * label/health bar at the returned x/y with the normal 2D verbs and it
   * pins to the 3D object. null before the first frame or without a world;
   * check `.visible` before drawing (behind-the-camera points project). */
  project3d(x: number, y: number, z: number): { x: number; y: number; depth: number; visible: boolean } | null {
    const p = this.world?.project(x, y, z);
    if (!p) return null;
    const r = this.canvas.getBoundingClientRect();
    const w = this.input.toWorld({ clientX: r.left + p.x, clientY: r.top + p.y });
    return { x: w.x, y: w.y, depth: p.depth, visible: p.visible };
  }

  /**
   * @internal The engine side of `world.ssao()` — the passes are composited by
   * Game (they read the world depth buffer), so the world routes here through
   * the `_fx` hook installed in world3d().
   */
  private applySsao(on: boolean | SsaoOptions = true): void {
    if (this.glr) {
      // The GL world owns its depth-effect passes (webgl3d). Remember the
      // setting until world3d() builds one (the WebGPU pending pattern).
      if (this.glWorld) this.glWorldFx()?.setSsao?.(on);
      else this.pendingSsao = on;
      return;
    }
    if (!this.ssaoPass) {
      // The pass lives in the lazy 3D chunk. Remember the setting and kick
      // the load — it applies as soon as the chunk arrives (SSAO only draws
      // over a 3D world anyway, so nothing is visibly deferred).
      this.pendingSsao = on;
      void this.load3d();
      return;
    }
    if (on === false) {
      this.ssaoPass.enabled = false;
      return;
    }
    this.ssaoPass.enabled = true;
    if (typeof on === 'object') Object.assign(this.ssaoPass.opts, on);
  }

  /** @internal The engine side of `world.rays()` — see {@link applySsao}. */
  private applyRays(on: boolean | RaysOptions = true): void {
    if (this.glr) {
      if (this.glWorld) this.glWorldFx()?.setRays?.(on);
      else this.pendingRays = on;
      return;
    }
    if (!this.raysPass) {
      this.pendingRays = on;
      void this.load3d();
      return;
    }
    if (on === false) {
      this.raysPass.enabled = false;
      return;
    }
    this.raysPass.enabled = true;
    if (typeof on === 'object') Object.assign(this.raysPass.opts, on);
  }

  /**
   * @internal Give a freshly built world its `ssao()` / `rays()` — the passes
   * are owned and composited here (they read the world depth buffer), so the
   * world's public verbs route back through these appliers.
   */
  private attachWorldFx(world: World3d): void {
    (world as unknown as { _fx: World3dFxHook })._fx = {
      ssao: (on) => this.applySsao(on),
      rays: (on) => this.applyRays(on),
    };
  }

  /** @internal The GL world's optional depth-effect surface (ssao/rays). */
  private glWorldFx(): { setSsao?: (on: boolean | SsaoOptions) => void; setRays?: (on: boolean | RaysOptions) => void } | null {
    return this.glWorld as unknown as { setSsao?: (on: boolean | SsaoOptions) => void; setRays?: (on: boolean | RaysOptions) => void } | null;
  }

  /** @internal One-shot warnings for WebGPU-only features hit on the fallback. */
  private glWarned = new Set<string>();
  private warnGlOnly(feature: string): void {
    if (this.glWarned.has(feature)) return;
    this.glWarned.add(feature);
    console.warn(`Phaser AE: '${feature}' is WebGPU-only — ignored on the WebGL fallback renderer.`);
  }

  /** Load the 3D chunk once (idempotent) and stand up the ssao/rays passes. */
  private load3d(): Promise<typeof import('./core3d.js')> {
    return this.core3d ??= import('./core3d.js').then((core) => {
      if (this.gpu) {
        this.ssaoPass = new core.SsaoPass(this.gpu.device, this.gpu.format);
        this.raysPass = new core.RaysPass(this.gpu.device, this.gpu.format);
        if (this.pendingSsao !== null) { this.applySsao(this.pendingSsao); this.pendingSsao = null; }
        if (this.pendingRays !== null) { this.applyRays(this.pendingRays); this.pendingRays = null; }
      }
      return core;
    });
  }

  /** @internal Model DATA loading for preload — rides the backend's own 3D
   *  chunk so the fallback never downloads the WebGPU 3D core. */
  private loadModelDataVia(url: string): Promise<unknown> {
    if (this.glr) return import('./webgl3d-core.js').then((m) => m.loadModelData(url));
    return this.load3d().then((m) => m.loadModelData(url));
  }

  world3d(opts?: World3dOptions): Promise<World3d> {
    if (this.glr) {
      // The WebGL 3D subset rides its own lazy chunk. The returned object
      // implements the World3d core surface (meshes/models/billboards/terrain/
      // picking); WebGPU-only members are inert stubs — see the plan doc §3.6.
      return this.worldP ??= import('./webgl3d-core.js').then((m) => {
        this.glWorld = new m.GlWorld3d(this.glr!, this.atlas, { ...opts });
        this.glWorld.canvasEl = this.canvas;
        this.glr!.attachWorld(this.glWorld);
        if (this.pendingSsao !== null) { this.glWorldFx()?.setSsao?.(this.pendingSsao); this.pendingSsao = null; }
        if (this.pendingRays !== null) { this.glWorldFx()?.setRays?.(this.pendingRays); this.pendingRays = null; }
        this.world = this.glWorld as unknown as World3d;
        this.attachWorldFx(this.world);
        return this.world;
      });
    }
    return this.worldP ??= this.load3d().then((core) => {
      // Billboards keep NEAREST under pixelArt (blocky sampling is a 2D-batch
      // shader; nearest is the crisp fallback in the 3D pass for now).
      const filter: GPUFilterMode = this.pixelArt ? 'nearest' : this.filter;
      this.world = new core.World3d(this.gpu!.device, this.gpu!.format, this.atlas, { filter, ...opts });
      this.world.canvasEl = this.canvas;
      if (this.atlasView) this.world.setTexture(this.atlasView);
      this.attachWorldFx(this.world);
      return this.world;
    });
  }

  /** A world X at fraction f across this frame's view (0 = left edge, 1 = right). Camera-aware. */
  vw(f: number): number {
    return this.view.x + f * this.view.w;
  }

  /** A world Y at fraction f down this frame's view (0 = top edge, 1 = bottom). Camera-aware. */
  vh(f: number): number {
    return this.view.y + f * this.view.h;
  }

  /** Run `fn` at the fixed simulation step (see FixedClock) — physics/sims go here, not in the frame callback. */
  onStep(fn: (step: number) => void): void {
    this.stepFns.push(fn);
  }

  /**
   * Start the frame loop. Each frame: fixed-step callbacks → scene update →
   * scene draw → your `frame` callback (drawn ON TOP of the scene) → render.
   */
  run(frame?: (draw: Draw, dt: number, t: number) => void): void {
    this.stop();
    if (this.destroyed) return;
    this.last = -1;
    if (this.roster && !this.booted) {
      this.booted = true;
      this.go(this.roster['intro'] ? 'intro' : this.roster['title'] ? 'title' : 'play');
    } else if (!this.roster && !this.booted) {
      this.booted = true;
      this.current._activate(); // the implicit scene's input goes live too
      // The implicit single scene IS the gameplay for a toy/demo — signal the
      // host page it's booted and in play (roster games signal from transition()).
      this.signalReady();
      this.signalPlaying('play');
    }
    const tick = (now: number): void => {
      if (!this.running || this.destroyed) return; // a stray frame after pause()/stop() is a no-op
      this.raf = requestAnimationFrame(tick);
      const dt = this.last < 0 ? 0 : Math.min(0.05, (now - this.last) / 1000);
      this.last = now;
      this.time += dt;

      const surface = (this.gpu ?? this.glr)!;
      surface.fit();
      if (surface.dead) return;
      if (this.atlas.dirty || this.atlas.generation !== this.uploadedGen || !this.textureReady) this.uploadAtlas();

      const view = this.view as { x: number; y: number; w: number; h: number };
      view.h = this.worldHeight;
      view.w = this.worldHeight * (this.canvas.width / Math.max(1, this.canvas.height));

      const steps = this.clock.advance(dt);
      for (let s = 0; s < steps; s++) for (const fn of this.stepFns) fn(this.clock.step);

      // Tweens advance BEFORE the scene updates (mirrors the raster loop's
      // `tween.update(tick)` → `scene.run()` ordering).
      this.tween.update(dt);
      this.input.tickGrace(dt);

      const scene = this.current;
      scene.update(dt);
      // The 3D layer's attached physics world steps beside the scene update
      // (World3d has no per-frame update hook of its own): behaviors have
      // already moved kinematics, so the sim sees final targets and writes
      // final dynamic poses before the render below reads them.
      this.world?.physics?.update(dt);
      this.fx.update(dt);
      this.vector.update(dt);         // shatter fragments fly + fade
      const camera = scene.camera;
      // WORLD view: worldHeight units (set above), magnified by camera.zoom
      // (experimental; default 1). camera.update centres a followed target in it.
      const z = camera.zoom > 0 ? camera.zoom : 1;
      view.w /= z;
      view.h /= z;
      camera.update(dt, view.w, view.h);
      view.x = camera.x + camera.shakeX;
      view.y = camera.y + camera.shakeY;

      // HUD reference: CSS PIXELS — screen space, independent of worldHeight and
      // the camera. A given font size is therefore the SAME visual size in every
      // game (like DOM text), not a fraction of whatever worldHeight was picked.
      // `game.hud.w` / `game.hud.h` report these; anchor HUD furniture to them.
      const hudW = this.canvas.clientWidth || (typeof window !== 'undefined' ? window.innerWidth : 0) || this.canvas.width;
      const hudH = this.canvas.clientHeight || (typeof window !== 'undefined' ? window.innerHeight : 0) || this.canvas.height;

      // Text tracing (the debug overlay's bounds boxes) costs nothing unless on.
      this.draw.traceText = this.hud.traceText = !!this.debugOpts?.textBounds;
      this.cursorWanted = false;
      this.draw.begin(view.x, view.y, view.w, view.h, this.time);
      // Both text passes are told their DEVICE PIXELS PER DRAW UNIT, so a
      // UnicodeText block can rasterize itself at exactly the density it will be
      // sampled at (world units scale with the camera; the HUD is CSS px × dpr).
      // Clip rects arrive normalised to the surface; the passes scale them into
      // the render target, so both need its device-pixel size.
      const fbW = this.canvas.width, fbH = this.canvas.height;
      this.sceneOrder.begin();
      this.hudOrder.begin();
      this.msdf.begin(view.x, view.y, view.w, view.h, fbW / Math.max(1, view.w), fbW, fbH);
      this.msdfHud.begin(0, 0, hudW, hudH, fbW / Math.max(1, hudW), fbW, fbH);
      this.ui.begin(view.x, view.y, view.w, view.h, fbW, fbH);
      this.uiHud.begin(0, 0, hudW, hudH, fbW, fbH);
      this.triBatch.begin(view.x, view.y, view.w, view.h);
      this.vector.begin(view.x, view.y, view.w, view.h);
      this._lights2d?.begin(view.x, view.y, view.w, view.h, this.time);
      this.hud.begin(0, 0, hudW, hudH, this.time); // screen space (CSS px), camera-proof
      scene.draw(this.draw);
      this.fx.draw(this.draw);              // particles over the scene
      frame?.(this.draw, dt, this.time);
      // The orbit rig writes the 3D camera AFTER the frame callback: the
      // callback is where games move the followed target and re-aim
      // rig.target. Ticking the rig first built the camera from LAST
      // frame's target — a one-frame lag that's invisible at constant
      // velocity (constant offset) but under ANY acceleration (a carve,
      // a jump's tilt phases) the offset flips direction every frame:
      // the rider looked like he was "interpolating between his current
      // and previous position" (Rich's snowboard jitter, found the
      // third time it was hunted).
      this.world?.tick(dt);
      scene.drawHud(this.hud);              // the scene's screen-space UI pass
      // Deferred UI overlays (an open dropdown's popup) paint LAST on each
      // surface, so they cover whatever was drawn after the widget itself.
      this.draw.flushUiOverlays();
      this.hud.flushUiOverlays();
      if (this.debugOpts) {
        this.debugOverlay.draw(this.draw, this.hud, scene, this.debugOpts, {
          dt, view,
          particles: this.fx.count,
          counts3d: this.world?.counts ?? null,
          font: () => this.assets.font({ font: '13px monospace' }),
        });
      }
      // Hovering an interactive text block gives the canvas the hand cursor —
      // the thing that makes a text link READ as clickable. Only written on a
      // change (touching style every frame forces layout work in the browser).
      const cursor = this.cursorWanted ? 'pointer' : '';
      if (cursor !== this.cursorNow) {
        this.cursorNow = cursor;
        this.canvas.style.cursor = cursor;
      }
      const flash = scene.camera.flashRGBA;
      if (flash) {
        // Straight onto the HUD batch (over everything, fades out linearly).
        this.hudBatch.push(0, 0, hudW, hudH, this.atlas.frames[0], 3, 0, 0, 0, flash[0], flash[1], flash[2], flash[3]);
      }

      if (this.backdrops.active) this.backdrops.frame(this.canvas.width, this.canvas.height, this.time, view);
      if (this.glr) {
        // The WebGL backend replays the same composition order against GL
        // state (see webgl/renderer.ts) — one call, separate path.
        this.glr.renderFrame({
          width: this.canvas.width,
          height: this.canvas.height,
          bg: this.bg,
          time: this.time,
          world: this.glWorld,
          hudAboveFx: this.hudAboveFx,
        });
      } else {
        this.renderFrameWebGpu(view, dt);
      }
      // The canvas is now a COMPLETE frame — drain a pending screenshot here so
      // the host never captures a half-drawn frame (see screen.screenshot()).
      if (this.screen._shotPending) this.screen._drainShot();
      // End-of-tick input housekeeping (mirrors the raster loop: clearPressed
      // runs AFTER the scene so pressed()/released() edges survive the frame).
      this.input.clearPressed();
    };
    this.tickFn = tick;
    this.running = true;
    this.raf = requestAnimationFrame(tick);
  }

  /** @internal The WebGPU render tail — every encoder/pass of one frame.
   *  Extracted verbatim from the run loop so the WebGL branch stays a single
   *  call; only ever invoked on the WebGPU backend. */
  private renderFrameWebGpu(view: { x: number; y: number; w: number; h: number }, dt: number): void {
      const gpu = this.gpu!;
      const device = gpu.device;
      const encoder = device.createCommandEncoder();
      const [r, g, b, a] = this.bg;
      const target = gpu.context.getCurrentTexture().createView();
      const depthView = this.ensureDepth().createView();
      // With post effects active, the world renders offscreen and the chain
      // lands on the swapchain; the HUD is drawn after (unless hudAboveFx=false).
      const post = this.postChain.active;
      const sceneView = post ? this.postChain.sceneView(this.canvas.width, this.canvas.height) : target;
      const hudInScene = !post || !this.hudAboveFx;
      // 3D first, in its OWN passes: perspective depth never mixes with the
      // 2D z mapping, so the 2D layer + HUD always composite cleanly on top.
      // The 3D frame is TWO passes over a dedicated, sampleable depth
      // texture: pass A (opaque — meshes/billboards) STORES depth; pass B
      // (translucent — trails/particles/wisps) attaches it READ-ONLY and can
      // therefore also sample it (soft particles). The stored depth persists
      // to next frame, where the GPU-particle compute collides against it.
      // With MSAA (the default) both passes render 4× and pass B resolves
      // into the swapchain — smooth mesh edges, no cost to the 2D layer.
      if (this.world) {
        const msaa = this.world.sampleCount > 1;
        const clear = { r: r * a, g: g * a, b: b * a, a };
        const worldDepth = this.ensureWorldDepth();
        const worldDepthView = this.worldDepthView!;
        const aspect = this.canvas.width / Math.max(1, this.canvas.height);
        // The world's frame prep: camera matrices, instance packing, the
        // cluster-light kernel, the GPU-particle sim (against LAST frame's
        // depth) and the shadow-map pass — all encoded BEFORE the passes.
        this.world.prepare(encoder, aspect, dt, worldDepth, this.canvas.width, this.canvas.height);
        const passA = encoder.beginRenderPass({
          colorAttachments: [msaa ? {
            view: this.ensureMsaa().color.createView(),
            clearValue: clear,
            loadOp: 'clear',
            storeOp: 'store',
          } : {
            view: sceneView,
            clearValue: clear,
            loadOp: 'clear',
            storeOp: 'store',
          }],
          depthStencilAttachment: {
            view: worldDepthView,
            depthClearValue: 1,
            depthLoadOp: 'clear',
            depthStoreOp: 'store',
          },
        });
        // Backdrops paint FIRST, behind the meshes (the fogged world draws over).
        this.backdrops.draw(passA, msaa ? this.world.sampleCount : 1);
        this.world.renderOpaque(passA);
        passA.end();
        const passB = encoder.beginRenderPass({
          colorAttachments: [msaa ? {
            view: this.ensureMsaa().color.createView(),
            resolveTarget: sceneView,
            loadOp: 'load',
            storeOp: 'discard',
          } : {
            view: sceneView,
            loadOp: 'load',
            storeOp: 'store',
          }],
          // Read-only: translucents TEST depth but never write, and the same
          // texture is simultaneously bound for sampling in pass B shaders.
          depthStencilAttachment: {
            view: worldDepthView,
            depthReadOnly: true,
          },
        });
        this.world.renderTranslucent(passB);
        passB.end();
        // SSAO: estimate + blur from this frame's opaque depth; the result
        // multiplies into the resolved image at the top of the scene pass.
        const pi = this.world.projInfo;
        if (this.ssaoPass?.enabled && pi) {
          this.ssaoPass.render(encoder, worldDepth, pi.proj, pi.projA, pi.projB, this.canvas.width, this.canvas.height);
        }
        // Underwater light shafts: the half-res march the composite blurs up
        // (no-ops when the camera is dry).
        this.world.renderUnderwaterShafts(encoder, worldDepth, this.canvas.width, this.canvas.height);
        // God rays: march the opaque depth toward the projected sun. STRICTLY
        // an ABOVE-WATER effect: it marches in SCREEN space with uniform
        // steps, so underwater it painted camera-anchored concentric bands —
        // Rich's "herringbone / stacked discs that scroll their texture when
        // I move" (five rounds of chasing it in the volumetric shafts, which
        // were innocent). It fades out over the first half-metre of
        // submersion; the volumetric shaft pass owns underwater light.
        if (this.raysPass?.enabled) {
          let sun = this.world.sunScreen;
          const uw = this.world.underwater3d;
          const under = uw && uw.active && !uw.dead ? uw.fullUnder : 0;
          if (sun && under > 0) {
            sun = { ...sun, intensity: sun.intensity * (1 - under) };
          }
          if (sun && under < 1) this.raysPass.render(encoder, worldDepth, sun, this.canvas.width, this.canvas.height);
        }
      }
      // Blurred-glow prepass: sprites stamp silhouettes and the vector layer
      // stamps soft line cores into one half-res target; the blur runs once
      // for both and composites additively inside the scene pass below.
      this.vector.prepare();
      if (this.vector.glowSize > 0) this.glowPass.wake(this.vector.glowSize);
      if (this.glowPass.active) {
        this.glowPass.render(encoder, this.canvas.width, this.canvas.height,
          (p) => this.vector.stampGlow(p, Math.max(1, this.canvas.width >> 1), Math.max(1, this.canvas.height >> 1)));
      }
      const pass = encoder.beginRenderPass({
        colorAttachments: [{
          view: sceneView,
          clearValue: { r: r * a, g: g * a, b: b * a, a },
          loadOp: this.world ? 'load' : 'clear',
          storeOp: 'store',
        }],
        depthStencilAttachment: {
          view: depthView,
          depthClearValue: 1,
          depthLoadOp: 'clear', // fresh depth: the 2D layer stacks over the 3D world
          depthStoreOp: 'discard',
        },
      });
      // Backdrops paint behind everything (already drawn in the 3D pass if one ran).
      if (!this.world) this.backdrops.draw(pass, 1);
      if (this.world) this.ssaoPass?.composite(pass); // AO darkens the resolved 3D image under all 2D
      // Underwater absorption/murk fogs the (AO'd) 3D image before the shafts
      // add over it — same slot as SSAO, still under all 2D/HUD.
      if (this.world && this.worldDepth) this.world.compositeUnderwater(pass, this.worldDepth);
      if (this.world) this.raysPass?.composite(pass); // then the shafts ADD over it, still under all 2D
      this.glowPass.composite(pass); // blurred glows FIRST — halos sit BEHIND the bodies
      this._lights2d?.draw(pass, 'under'); // FLOOR lights: under the sprites (opaque sprites occlude them)
      // EVERY 2D pass, in the order the game drew it — opaque sprites, blended
      // quads, filled polygons, particles, text and panels alike.
      this.walkSurface(pass, this.sceneOrder, this.sceneSrcs());
      this.vector.draw(pass, this.canvas.width, this.canvas.height);   // line art — retained, still a fixed slot
      this._lights2d?.draw(pass, 'over'); // OVERHEAD lights: add over the whole scene, covering sprites
      if (hudInScene) {                   // HUD in-scene when no post
        this.walkSurface(pass, this.hudOrder, this.hudSrcs());
      }
      pass.end();

      if (post) {
        this.postChain.run(encoder, target, this.time);
        if (!hudInScene) {
          // HUD above the effects: its own pass on the swapchain, fresh depth.
          const hudPass = encoder.beginRenderPass({
            colorAttachments: [{ view: target, loadOp: 'load', storeOp: 'store' }],
            depthStencilAttachment: {
              view: depthView,
              depthClearValue: 1,
              depthLoadOp: 'clear',
              depthStoreOp: 'discard',
            },
          });
          this.walkSurface(hudPass, this.hudOrder, this.hudSrcs());
          hudPass.end();
        }
      }
      device.queue.submit([encoder.finish()]);
      // GPU-particle alive-count readbacks map AFTER the submit (a buffer
      // with a pending map may not appear inside one).
      this.world?.afterSubmit();
  }

  /** Stop the frame loop (run() restarts it). */
  /**
   * Draw one surface's UI stack, layer by layer.
   *
   * Panels, bitmap labels and MSDF text are three batches because they are three
   * shaders — but they are ONE stack, so they advance together. Walking layers
   * in step is what lets a window (see `Ui.window`) sit wholly above the window
   * below it: its panels cover the other's panels AND its text, with no stencil
   * and no separate surface.
   *
   * Layer 0 is the frame's ordinary UI, so the common case is one pass of the
   * loop and exactly the three draws it always was.
   */
  /**
   * Replay one surface's 2D content in the order the game drew it.
   *
   * Quads, text and panels are three shaders and can never share a batch, so the
   * frame breaks the batch and swaps pipeline wherever the game alternated. That
   * costs draw calls, deliberately: `d.panel(...)` then `d.text(...)` means the
   * text is ON the panel, and no ordering rule beats writing what you meant.
   *
   * LAYERS are the one thing call order cannot express — "this dialog is above
   * everything already on screen". Each layer is walked in full before the next,
   * so a modal covers the screen below it, text and furniture together.
   */
  private walkSurface(
    pass: GPURenderPassEncoder, order: DrawOrder,
    srcs: ReadonlyArray<{ drawRange(p: GPURenderPassEncoder, first: number, n: number): void } | null>,
  ): void {
    for (let n = 0; n <= order.maxLayer; n++) {
      for (const seg of order.segs) {
        if (seg.layer !== n) continue;
        srcs[seg.src]?.drawRange(pass, seg.first, seg.n);
      }
    }
  }

  /** The surface's passes, indexed by SRC id — the walk's dispatch table. */
  private sceneSrcs(): ReadonlyArray<{ drawRange(p: GPURenderPassEncoder, first: number, n: number): void } | null> {
    return [this.blendBatch, this.msdf, this.ui, this.textBatch,
            this.cutoutBatch, this.addBatch, this.triBatch, this.gridBatch, this.fxBatch];
  }

  private hudSrcs(): ReadonlyArray<{ drawRange(p: GPURenderPassEncoder, first: number, n: number): void } | null> {
    return [this.hudBatch, this.msdfHud, this.uiHud, this.hudTextBatch,
            this.hudBatch, this.hudBatch, null, null, null];
  }

  stop(): void {
    this.running = false;
    if (this.raf) cancelAnimationFrame(this.raf);
    this.raf = 0;
  }

  /** `true` while the loop is frozen by `pause()` (booted, not yet destroyed). */
  get paused(): boolean { return this.booted && !this.running && !this.destroyed; }

  /** `true` once `destroy()` has run — the instance is permanently inert. */
  get isDestroyed(): boolean { return this.destroyed; }

  /**
   * Freeze the run loop — updates and rendering stop, the last frame stays on
   * screen — and silence all sound (muted, not stopped: music holds its place).
   * Idempotent; no-op after `destroy()`. Called by the host page's pause control.
   */
  pause(): void {
    if (!this.running || this.destroyed) return;
    this.running = false;
    if (this.raf) { cancelAnimationFrame(this.raf); this.raf = 0; }
    this.soundMutedBeforePause = this.sound.muted;
    this.sound.mute(true);
  }

  /**
   * Restart the run loop after `pause()` and restore sound to its pre-pause mute
   * state. The first delta is clamped (last = -1) so time never jumps across the
   * gap. Idempotent; no-op after `destroy()` or before the first `run()`.
   */
  resume(): void {
    if (this.running || this.destroyed || !this.tickFn) return;
    this.running = true;
    this.last = -1; // clamp the first delta after the pause gap
    this.sound.mute(this.soundMutedBeforePause);
    this.raf = requestAnimationFrame(this.tickFn);
  }

  /**
   * Permanently stop the game: cancel the loop, tear down input / audio / tween,
   * and release resources. After this every method is a no-op. Idempotent.
   */
  destroy(): void {
    if (this.destroyed) return;
    this.destroyed = true;
    this.running = false;
    this.stop();                                  // cancels the rAF
    this.screen._destroy();                       // stops recording, leaves CSS fullscreen
    // Every listener this game attached — window keys/blur (here), plus input's
    // own keyboard/mouse/touch/pointer set, and the current scene's handlers.
    for (const [type, fn] of this.winListeners) window.removeEventListener(type, fn);
    this.winListeners = [];
    this.current?._deactivate();
    this.input.destroy();
    this.sound.destroy();
    this.tween.destroy();
    // GPU: drop the big attachments, then destroy the device — that frees every
    // remaining texture/buffer (atlas, world meshes, post targets) in one call.
    this.msaaColor?.destroy(); this.msaaColor = null;
    this.worldDepth?.destroy(); this.worldDepth = null; this.worldDepthView = null;
    this.depth?.destroy(); this.depth = null;
    this.gpu?.destroy();
    this.glr?.destroy();
    // Free every cached asset (images, text, binaries, model geometry/textures).
    clearAssetCaches();
  }

  /**
   * @internal Fire the global `window.PhaserGameReady()` callback once, the first
   * time a real scene finishes building. The engine drives this automatically —
   * the host page hooks it to learn the game has booted and put something on
   * screen. The `_readyFired` guard makes it strictly one-shot.
   */
  private signalReady(): void {
    if (this._readyFired) return;
    this._readyFired = true;
    if (typeof window === 'undefined') return;
    const cb = (window as unknown as { PhaserGameReady?: unknown }).PhaserGameReady;
    if (typeof cb === 'function') {
      try {
        (cb as () => void)();
      } catch (err) {
        // A throwing host callback must never break the boot/transition flow.
        console.error('window.PhaserGameReady() threw:', err);
      }
    }
  }

  /**
   * @internal Fire the global `window.PhaserGamePlaying()` callback once, the
   * first time the `'play'` scene — the main gameplay screen, past any
   * title/menu — finishes building. The host page hooks it to screenshot the
   * game in motion rather than its title. The `_playingFired` guard makes it
   * strictly one-shot (replaying the level never re-fires it).
   */
  private signalPlaying(role: string): void {
    if (this._playingFired || role !== 'play') return;
    this._playingFired = true;
    if (typeof window === 'undefined') return;
    const cb = (window as unknown as { PhaserGamePlaying?: unknown }).PhaserGamePlaying;
    if (typeof cb === 'function') {
      try {
        (cb as () => void)();
      } catch (err) {
        // A throwing host callback must never break the boot/transition flow.
        console.error('window.PhaserGamePlaying() threw:', err);
      }
    }
  }

  private ensureMsaa(): { color: GPUTexture } {
    const { width, height } = this.canvas;
    const count = this.world?.sampleCount ?? 4;
    if (!this.msaaColor || this.msaaColor.width !== width || this.msaaColor.height !== height) {
      this.msaaColor?.destroy();
      this.msaaColor = this.gpu!.device.createTexture({
        size: { width, height }, format: this.gpu!.format, sampleCount: count,
        usage: 0x10 /* RENDER_ATTACHMENT */,
      });
    }
    return { color: this.msaaColor };
  }

  /** The 3D passes' dedicated depth — SAMPLEABLE (soft particles, compute
   * collision) and persistent across frames (stored, never discarded), at
   * the world's sample count. Separate from the 2D layer's depth, which is
   * cleared by the scene pass every frame. */
  private ensureWorldDepth(): GPUTexture {
    const { width, height } = this.canvas;
    const count = this.world?.sampleCount ?? 4;
    if (!this.worldDepth || this.worldDepth.width !== width || this.worldDepth.height !== height) {
      this.worldDepth?.destroy();
      this.worldDepth = this.gpu!.device.createTexture({
        size: { width, height }, format: DEPTH_FORMAT, sampleCount: count,
        usage: 0x10 | 0x4 /* RENDER_ATTACHMENT | TEXTURE_BINDING */,
      });
      this.worldDepthView = this.worldDepth.createView();
    }
    return this.worldDepth;
  }

  private ensureDepth(): GPUTexture {
    const { width, height } = this.canvas;
    if (!this.depth || this.depth.width !== width || this.depth.height !== height) {
      this.depth?.destroy();
      this.depth = this.gpu!.device.createTexture({
        size: { width, height },
        format: DEPTH_FORMAT,
        usage: 0x10 /* RENDER_ATTACHMENT */,
      });
    }
    return this.depth;
  }

  private uploadAtlas(): void {
    if (this.atlas.dirty || !this.atlas.canvas) this.atlas.build();
    if (this.glr) {
      // The GL renderer owns the atlas texture + fan-out on its backend.
      this.glr.uploadAtlas(this.atlas.canvas!);
      this.uploadedGen = this.atlas.generation;
      this.textureReady = true;
      return;
    }
    const texture = textureFromCanvas(this.gpu!.device, this.atlas.canvas!);
    const view = texture.createView();
    this.atlasView = view;
    this.cutoutBatch.setTexture(view);
    this.blendBatch.setTexture(view);
    this.addBatch.setTexture(view);
    this.fxBatch.setTexture(view);
    this.gridBatch.setTexture(view);
    this.glowPass.setTexture(view);
    this.hudBatch.setTexture(view);
    this.textBatch.setTexture(view);
    this.hudTextBatch.setTexture(view);
    this.world?.setTexture(view);
    this.uploadedGen = this.atlas.generation;
    this.textureReady = true;
  }
}

function makeCanvas(container?: HTMLElement | string): HTMLCanvasElement {
  // The engine OWNS the canvas — always freshly created, so it can never be a
  // mis-configured (e.g. WebGL) context handed in by mistake. The caller only
  // chooses WHERE it lives.
  const canvas = document.createElement('canvas');
  const host = typeof container === 'string'
    ? document.querySelector<HTMLElement>(container)
    : container ?? null;
  if (host) {
    canvas.style.cssText = 'display:block;width:100%;height:100%';   // fill the host box
    host.appendChild(canvas);
  } else {
    canvas.style.cssText = 'position:fixed;inset:0;width:100vw;height:100vh;display:block'; // fill the viewport
    document.body.appendChild(canvas);
  }
  return canvas;
}
