// 2D LIGHTS — a real additive lighting layer for top-down / side-on games.
// Point + spot lights with soft radial/cone falloff, HARD SHADOWS thrown by
// actual scenery (segment/box/polygon occluders via Visibility2d), and additive
// blending so overlapping coloured lights MIX (green + orange = yellow). Flicker
// (candles/torches) is built in.
//
// It renders as ONE instanced pipeline: each light's visibility polygon is
// fanned into triangles (instance = the three corners + the light's params) and
// a fragment shader computes per-pixel falloff — so the shadow shape is exact
// and free (the fan only covers the lit area). Additive, so it ADDS light over
// whatever the game already drew: draw your scene, drop a dark ambient overlay
// (a translucent black rect), then this layer adds the lights back.
//
// The pipeline follows the engine's instanced pattern (see batch.ts): a view
// uniform maps the world rect to the canvas; a storage buffer holds the
// per-triangle instances; GPU objects rebuild from CPU state on device loss.

import { BITS } from './gpu.js';
import { DEPTH_FORMAT } from './batch.js';
import { Visibility2d } from './visibility2d.js';

const FLOATS = 16; // per triangle instance: tri(4) triC(4) params(4) color(4)

// Penumbra sampling: a soft-shadow light is sampled as a small disc of this
// many points (sunflower/golden-angle spread over the unit disc). The union of
// their hard visibility polygons, each at 1/N intensity, is a real soft shadow.
const SOFT_DISK: Array<[number, number]> = (() => {
  const N = 12, out: Array<[number, number]> = [];
  const golden = Math.PI * (3 - Math.sqrt(5));
  for (let k = 0; k < N; k++) { const r = Math.sqrt((k + 0.5) / N); const a = k * golden; out.push([Math.cos(a) * r, Math.sin(a) * r]); }
  return out;
})();
const HARD_SAMPLE: Array<[number, number]> = [[0, 0]];

/** A live 2D light — mutate its fields (position, colour, radius…) each frame. */
export interface Light2d {
  /** Light kind. */ type: 'point' | 'spot';
  /** World X. */ x: number;
  /** World Y. */ y: number;
  /** Reach in world units (falloff hits 0 here). */ radius: number;
  /** Peak brightness. */ intensity: number;
  /** Colour `[r, g, b]`, 0..1. */ color: [number, number, number];
  /** Falloff exponent — 1 ≈ linear, 2 = softer core, higher = tighter. */ falloff: number;
  /** Spot facing in radians (spot only). */ dir: number;
  /** Spot full cone angle in radians (spot only). */ cone: number;
  /** Flicker amount 0..1 (candles/torches); 0 = steady. */ flicker: number;
  /** Flicker speed multiplier. */ flickerSpeed: number;
  /** Per-light phase so many flames don't sync. */ phase: number;
  /** Compositing HEIGHT. `'over'` (default) sits ABOVE the scene — it brightens
   *  the sprites under it (an overhead street lamp). `'under'` lights the FLOOR
   *  BENEATH the sprites — drawn before them, so opaque sprites occlude it and
   *  their pixels are never tinted (a glow that follows the paddle/ball). */
  layer: 'over' | 'under';
  /** Cast shadows off the occluders (opt-in — the per-light visibility
   *  raycast). `false` (default) = a cheap glowing radial light, so thousands
   *  are affordable. */ shadows: boolean;
  /** Penumbra size in world units when `shadows` is on — the light is sampled
   *  as a small disc of this radius, so shadow edges go SOFT. `0` = razor-hard.
   *  Softness costs extra visibility samples, so keep shadow-casters to dozens
   *  (glows without shadows still scale to thousands). */ softness: number;
  /** Toggle without removing. */ on: boolean;
}

/** Options for {@link Lights2d.point}. */
export interface PointLight2dOptions {
  radius?: number; intensity?: number; color?: [number, number, number];
  falloff?: number; flicker?: number; flickerSpeed?: number; phase?: number;
  /** Cast shadows off occluders (default `false` — a plain glow). */
  shadows?: boolean;
  /** Penumbra size in world units (default `6` when shadows are on; `0` = hard). */
  softness?: number;
  /** `'over'` (default) covers the sprites; `'under'` lights the floor beneath them. */
  layer?: 'over' | 'under';
}
/** Options for {@link Lights2d.spot}. */
export interface SpotLight2dOptions extends PointLight2dOptions {
  /** Facing in radians. */ dir?: number;
  /** Full cone angle in radians (default ~0.9). */ cone?: number;
}

const wgsl = /* wgsl */ `
struct U { view: vec4f }                 // world rect mapped to the canvas: x, y, w, h
struct Inst { tri: vec4f, triC: vec4f, params: vec4f, color: vec4f }
// tri   = ax, ay, bx, by            triC = cx, cy, lightX, lightY
// params = radius, intensity, coneCos, coneDir       color = r, g, b, falloffPow
struct VSOut {
  @builtin(position) pos: vec4f,
  @location(0) world: vec2f,
  @location(1) light: vec2f,
  @location(2) params: vec4f,
  @location(3) color: vec4f,
}
@group(0) @binding(0) var<uniform> u: U;
@group(0) @binding(1) var<storage, read> inst: array<Inst>;

@vertex
fn vs(@builtin(vertex_index) vi: u32, @builtin(instance_index) ii: u32) -> VSOut {
  let d = inst[ii];
  var p = d.triC.xy;                      // vertex 2 = the light centre
  if (vi == 0u) { p = d.tri.xy; }         // vertex 0 = A
  else if (vi == 1u) { p = d.tri.zw; }    // vertex 1 = B
  let ndc = (p - u.view.xy) / u.view.zw * 2.0 - 1.0;
  var o: VSOut;
  o.pos = vec4f(ndc.x, -ndc.y, 0.0, 1.0);
  o.world = p;
  o.light = d.triC.zw;
  o.params = d.params;
  o.color = d.color;
  return o;
}

@fragment
fn fs(in: VSOut) -> @location(0) vec4f {
  let dist = distance(in.world, in.light);
  let radius = in.params.x;
  var atten = clamp(1.0 - dist / radius, 0.0, 1.0);
  atten = pow(atten, max(in.color.w, 0.25));
  let coneCos = in.params.z;
  if (coneCos > -1.5) {                   // spot: fade outside the cone
    let da = atan2(in.world.y - in.light.y, in.world.x - in.light.x) - in.params.w;
    let cd = cos(da);
    atten = atten * smoothstep(coneCos, mix(coneCos, 1.0, 0.15), cd);
  }
  let b = atten * in.params.y;
  return vec4f(in.color.rgb * b, b);      // premultiplied — additive one/one
}
`;

// AMBIENT: a fullscreen triangle that MULTIPLIES the scene down to the ambient
// colour (unlit surfaces show dimly; the additive lights add on top). Drawn
// before the over-lights.
const ambientWgsl = /* wgsl */ `
struct A { color: vec4f }
@group(0) @binding(0) var<uniform> a: A;
@vertex
fn vs(@builtin(vertex_index) vi: u32) -> @builtin(position) vec4f {
  var p = array<vec2f, 3>(vec2f(-1.0, -1.0), vec2f(3.0, -1.0), vec2f(-1.0, 3.0));
  return vec4f(p[vi], 0.0, 1.0);
}
@fragment
fn fs() -> @location(0) vec4f { return a.color; }
`;

/**
 * The 2D light layer. Add occluders (scenery) + lights, update them each frame,
 * and the layer draws additive, shadowed, colour-mixing lights over the scene.
 * Reach it from a `Game` as `game.lights2d` (created on first use).
 *
 * ```ts
 * const lights = game.lights2d;
 * lights.occluders.addRect(x, y, w, h);            // scenery casts shadow
 * const torch = lights.point(300, 200, { radius: 260, color: [1, 0.7, 0.35], flicker: 0.4 });
 * const lamp  = lights.spot(500, 120, { radius: 400, dir: Math.PI / 2, cone: 0.8, color: [0.6, 0.8, 1] });
 * // each frame just mutate torch.x / torch.y / … ; draw a dark overlay first for atmosphere.
 * ```
 */
export class Lights2d {
  /** Scenery that casts shadows — add rects / segments / polys to it. */
  readonly occluders = new Visibility2d();
  /** The active lights (mutate freely; `point()`/`spot()` append here). */
  readonly lights: Light2d[] = [];
  /** Ambient (base) light colour, `[r,g,b]` 0..1 — the scene is multiplied down
   *  to this before the lights add, so unlit surfaces show DIMLY instead of pure
   *  black. `[1,1,1]` (default) = no ambient darkening; `[0,0,0]` = black unlit;
   *  `[0.12,0.12,0.16]` = a dim blue night. Tint it warm/cool for mood. */
  ambient: [number, number, number] = [1, 1, 1];

  private data: Float32Array;
  private count = 0;
  private capacity = 4096;
  private time = 0;
  private uniformData = new Float32Array(4);
  private vx = 0; private vy = 0; private vw = 0; private vh = 0;
  private underTris = 0;   // triangle count of the 'under' layer (draw split point)
  /** Lights drawn last frame after culling — for HUD/debug. */
  visible = 0;
  /** Of those, how many cast shadows (the expensive ones) — for HUD/debug. */
  visibleShadow = 0;

  private device!: GPUDevice;
  private pipeline!: GPURenderPipeline;
  private layout!: GPUBindGroupLayout;
  private uniforms!: GPUBuffer;
  private instances!: GPUBuffer;
  private bind!: GPUBindGroup;
  private ambientPipeline!: GPURenderPipeline;
  private ambientUniform!: GPUBuffer;
  private ambientBind!: GPUBindGroup;
  private ambientData = new Float32Array(4);

  constructor(device: GPUDevice, private format: GPUTextureFormat) {
    this.data = new Float32Array(this.capacity * FLOATS);
    this.rebuild(device);
  }

  /** (Re)create every GPU object — the device-loss recovery path. */
  rebuild(device: GPUDevice): void {
    this.device = device;
    this.layout = device.createBindGroupLayout({
      entries: [
        { binding: 0, visibility: BITS.STAGE_VERTEX, buffer: { type: 'uniform' } },
        { binding: 1, visibility: BITS.STAGE_VERTEX, buffer: { type: 'read-only-storage' } },
      ],
    });
    const module = device.createShaderModule({ code: wgsl });
    void module.getCompilationInfo().then((info) => {
      for (const m of info.messages) if (m.type === 'error') console.error(`Lights2d WGSL ${m.lineNum}:${m.linePos} ${m.message}`);
    });
    this.pipeline = device.createRenderPipeline({
      layout: device.createPipelineLayout({ bindGroupLayouts: [this.layout] }),
      vertex: { module, entryPoint: 'vs' },
      fragment: {
        module, entryPoint: 'fs',
        targets: [{
          format: this.format,
          blend: {
            color: { srcFactor: 'one', dstFactor: 'one' },
            alpha: { srcFactor: 'one', dstFactor: 'one' },
          },
        }],
      },
      depthStencil: { format: DEPTH_FORMAT, depthWriteEnabled: false, depthCompare: 'always' },
      primitive: { topology: 'triangle-list' },
    });
    this.uniforms = device.createBuffer({ size: 16, usage: BITS.UNIFORM | BITS.COPY_DST });
    this.instances = device.createBuffer({ size: this.capacity * FLOATS * 4, usage: BITS.STORAGE | BITS.COPY_DST });
    this.makeBind();

    // Ambient multiply pipeline (scene × ambient), drawn before the over-lights.
    const aLayout = device.createBindGroupLayout({ entries: [{ binding: 0, visibility: BITS.STAGE_FRAGMENT, buffer: { type: 'uniform' } }] });
    const aMod = device.createShaderModule({ code: ambientWgsl });
    void aMod.getCompilationInfo().then((info) => {
      for (const m of info.messages) if (m.type === 'error') console.error(`Lights2d ambient WGSL ${m.lineNum}:${m.linePos} ${m.message}`);
    });
    this.ambientPipeline = device.createRenderPipeline({
      layout: device.createPipelineLayout({ bindGroupLayouts: [aLayout] }),
      vertex: { module: aMod, entryPoint: 'vs' },
      fragment: {
        module: aMod, entryPoint: 'fs',
        targets: [{
          format: this.format,
          blend: {
            color: { srcFactor: 'dst', dstFactor: 'zero' },   // result = ambient × scene
            alpha: { srcFactor: 'zero', dstFactor: 'one' },    // keep dst alpha
          },
        }],
      },
      depthStencil: { format: DEPTH_FORMAT, depthWriteEnabled: false, depthCompare: 'always' },
      primitive: { topology: 'triangle-list' },
    });
    this.ambientUniform = device.createBuffer({ size: 16, usage: BITS.UNIFORM | BITS.COPY_DST });
    this.ambientBind = device.createBindGroup({ layout: aLayout, entries: [{ binding: 0, resource: { buffer: this.ambientUniform } }] });
  }

  private makeBind(): void {
    this.bind = this.device.createBindGroup({
      layout: this.layout,
      entries: [
        { binding: 0, resource: { buffer: this.uniforms } },
        { binding: 1, resource: { buffer: this.instances } },
      ],
    });
  }

  // ── Lights ─────────────────────────────────────────────────────────────────

  /** Add a point light; returns its handle (mutate to move / recolour it). */
  point(x: number, y: number, opts: PointLight2dOptions = {}): Light2d {
    const l: Light2d = {
      type: 'point', x, y,
      radius: opts.radius ?? 240, intensity: opts.intensity ?? 1,
      color: opts.color ?? [1, 1, 1], falloff: opts.falloff ?? 2,
      dir: 0, cone: 0,
      flicker: opts.flicker ?? 0, flickerSpeed: opts.flickerSpeed ?? 1, phase: opts.phase ?? 0,
      shadows: opts.shadows ?? false, softness: opts.softness ?? 6, layer: opts.layer ?? 'over', on: true,
    };
    this.lights.push(l);
    return l;
  }

  /** Add a spot light (a cone). `dir` faces in radians, `cone` is the full angle. */
  spot(x: number, y: number, opts: SpotLight2dOptions = {}): Light2d {
    const l: Light2d = {
      type: 'spot', x, y,
      radius: opts.radius ?? 360, intensity: opts.intensity ?? 1,
      color: opts.color ?? [1, 1, 1], falloff: opts.falloff ?? 2,
      dir: opts.dir ?? 0, cone: opts.cone ?? 0.9,
      flicker: opts.flicker ?? 0, flickerSpeed: opts.flickerSpeed ?? 1, phase: opts.phase ?? 0,
      shadows: opts.shadows ?? false, softness: opts.softness ?? 6, layer: opts.layer ?? 'over', on: true,
    };
    this.lights.push(l);
    return l;
  }

  /** Remove a light. */
  remove(light: Light2d): void {
    const i = this.lights.indexOf(light);
    if (i >= 0) this.lights.splice(i, 1);
  }

  /** Remove all lights. */
  clear(): void { this.lights.length = 0; }

  // ── Frame ──────────────────────────────────────────────────────────────────

  /** Start a frame: map the world rect onto the canvas (same as the batches). */
  begin(viewX: number, viewY: number, viewW: number, viewH: number, time: number): void {
    this.uniformData[0] = viewX; this.uniformData[1] = viewY;
    this.uniformData[2] = viewW; this.uniformData[3] = viewH;
    this.vx = viewX; this.vy = viewY; this.vw = viewW; this.vh = viewH;
    this.time = time;
    // Shadowed lights' rays terminate at the visible window.
    this.occluders.setBounds(viewX, viewY, viewW, viewH);
    this.count = 0;
  }

  private flicker(l: Light2d): number {
    if (l.flicker <= 0) return 1;
    const t = this.time * l.flickerSpeed;
    // Layered sines → an irregular, candle-like wobble in [0,1].
    const n = 0.5 + 0.5 * (Math.sin(t * 11.3 + l.phase) * 0.6 + Math.sin(t * 23.7 + l.phase * 1.7) * 0.4);
    return 1 - l.flicker * (1 - n);
  }

  // Push one triangle (corners A, B, C) carrying the light params. C is a real
  // corner; the light centre (lx, ly) is stored separately for the fragment
  // falloff — so the same instance format serves the shadow FAN (C = the light
  // centre / apex) and the plain QUAD (C = a bbox corner).
  private pushTri(ax: number, ay: number, bx: number, by: number, cx: number, cy: number, lx: number, ly: number, radius: number, intensity: number, coneCos: number, coneDir: number, col: [number, number, number], pow: number): void {
    if (this.count >= this.capacity) this.grow();
    const o = this.count * FLOATS, d = this.data;
    d[o] = ax; d[o + 1] = ay; d[o + 2] = bx; d[o + 3] = by;
    d[o + 4] = cx; d[o + 5] = cy; d[o + 6] = lx; d[o + 7] = ly;
    d[o + 8] = radius; d[o + 9] = intensity; d[o + 10] = coneCos; d[o + 11] = coneDir;
    d[o + 12] = col[0]; d[o + 13] = col[1]; d[o + 14] = col[2]; d[o + 15] = pow;
    this.count++;
  }

  private grow(): void {
    this.capacity *= 2;
    const next = new Float32Array(this.capacity * FLOATS);
    next.set(this.data);
    this.data = next;
    this.instances.destroy();
    this.instances = this.device.createBuffer({ size: this.capacity * FLOATS * 4, usage: BITS.STORAGE | BITS.COPY_DST });
    this.makeBind();
  }

  /** @internal Cull + tessellate one light — a plain radial QUAD (2 triangles)
   *  by default, or the shadowed visibility FAN when it opts in. */
  private emitLight(l: Light2d): void {
    if (!l.on || l.radius <= 0) return;
    // Cull: the light's reach circle must touch the visible window.
    if (l.x + l.radius < this.vx || l.x - l.radius > this.vx + this.vw ||
        l.y + l.radius < this.vy || l.y - l.radius > this.vy + this.vh) return;
    const intensity = l.intensity * this.flicker(l);
    if (intensity <= 0.001) return;
    const coneCos = l.type === 'spot' ? Math.cos(l.cone * 0.5) : -2;
    this.visible++;
    if (l.shadows) {
      this.visibleShadow++;
      // Shadowed: fan the visibility polygon (apex = the light). Soft shadows
      // sample the light as a disc — the union of the jittered polygons at
      // 1/N intensity is the penumbra.
      const samples = l.softness > 0 ? SOFT_DISK : HARD_SAMPLE;
      const sub = intensity / samples.length;
      for (const [ox, oy] of samples) {
        const lx = l.x + ox * l.softness, ly = l.y + oy * l.softness;
        const poly = this.occluders.visibility(lx, ly, l.radius);
        if (poly.length < 2) continue;
        for (let i = 0; i < poly.length; i++) {
          const a = poly[i], b = poly[(i + 1) % poly.length];
          this.pushTri(a.x, a.y, b.x, b.y, lx, ly, lx, ly, l.radius, sub, coneCos, l.dir, l.color, l.falloff);
        }
      }
    } else {
      // Plain glow: a quad covering the reach circle (falloff does the shape).
      const r = l.radius;
      const x0 = l.x - r, y0 = l.y - r, x1 = l.x + r, y1 = l.y + r;
      this.pushTri(x0, y0, x1, y0, x0, y1, l.x, l.y, r, intensity, coneCos, l.dir, l.color, l.falloff);
      this.pushTri(x1, y0, x1, y1, x0, y1, l.x, l.y, r, intensity, coneCos, l.dir, l.color, l.falloff);
    }
  }

  /** @internal Emit UNDER-layer lights first (`[0, underTris)`) then OVER-layer
   *  (`[underTris, count)`), so the two draw phases can pick their sub-range. */
  private buildAll(): void {
    this.count = 0; this.visible = 0; this.visibleShadow = 0;
    for (const l of this.lights) if (l.layer === 'under') this.emitLight(l);
    this.underTris = this.count;
    for (const l of this.lights) if (l.layer !== 'under') this.emitLight(l);
  }

  /**
   * Draw one compositing PHASE. `'under'` (called before the sprite batches)
   * builds + uploads the whole frame and draws the floor lights; `'over'`
   * (called after the scene) draws the lights that cover the sprites. Between
   * them the game draws its sprites, so `'under'` lights never touch them.
   */
  draw(pass: GPURenderPassEncoder, phase: 'under' | 'over'): void {
    if (phase === 'under') {
      this.buildAll();
      if (this.count > 0) {
        this.device.queue.writeBuffer(this.uniforms, 0, this.uniformData);
        this.device.queue.writeBuffer(this.instances, 0, this.data.buffer, 0, this.count * FLOATS * 4);
      }
    } else {
      this.drawAmbient(pass);   // darken the scene to the ambient base, then the lights add
    }
    const first = phase === 'under' ? 0 : this.underTris;
    const num = phase === 'under' ? this.underTris : this.count - this.underTris;
    if (num <= 0) return;
    pass.setPipeline(this.pipeline);
    pass.setBindGroup(0, this.bind);
    pass.draw(3, num, 0, first);
  }

  /** @internal Multiply the scene down to the ambient colour (skipped when the
   *  ambient is white — no darkening). */
  private drawAmbient(pass: GPURenderPassEncoder): void {
    const [r, g, b] = this.ambient;
    if (r >= 0.999 && g >= 0.999 && b >= 0.999) return;
    this.ambientData[0] = r; this.ambientData[1] = g; this.ambientData[2] = b; this.ambientData[3] = 1;
    this.device.queue.writeBuffer(this.ambientUniform, 0, this.ambientData);
    pass.setPipeline(this.ambientPipeline);
    pass.setBindGroup(0, this.ambientBind);
    pass.draw(3);
  }
}
