/** Static sprite-vs-world tile collision: swept AABB + slope trace used by Physics each frame. */

import { TileGrid } from './tile-grid.js';
import type { Vec2 } from './util.js';

/**
 * Slope line definition for a single tile: `[x1, y1, x2, y2, solid]` in tile-local 0..1 coordinates.
 * Solid `true` means the area behind the line is filled (one-way platforms set `false`).
 * Synonym: slope tile, angled tile, ramp definition.
 */
export type TileDef = [number, number, number, number, boolean];

/** Map of tile index → `TileDef`. Pass to `CollisionGrid` to define which tile indices are slopes. */
export type TileDefs = Record<number, TileDef>;

/**
 * Tangent and outward normal vectors for a slope tile hit during a swept trace.
 * `x`/`y` = tangent (slide direction); `nx`/`ny` = surface normal (reflect direction).
 */
export interface SlopeNormal {
  /** Tangent vector X component (slope slide direction). */
  x: number;
  /** Tangent vector Y component (slope slide direction). */
  y: number;
  /** Surface normal X component (outward from slope face). */
  nx: number;
  /** Surface normal Y component (outward from slope face). */
  ny: number;
}

/**
 * Result returned by `CollisionGrid.trace()` after a swept AABB movement test.
 * `Physics.handleMovementTrace` reads this to resolve velocity and snap position.
 */
export interface TraceResult {
  /** Which axes collided and whether a slope was hit. */
  collision: { x: boolean; y: boolean; slope: SlopeNormal | false };
  /** Final snapped world position after resolving all collisions. */
  position: Vec2;
  /** Tile index that caused each axis collision (0 if no collision on that axis). */
  tile: Vec2;
}

/**
 * Structural interface satisfied by both `CollisionGrid` and the no-op dummy.
 * Pass to `Scene.collisionMap` to swap in a custom collision implementation.
 */
export interface CollisionGridLike {
  /** Swept AABB trace from `(x, y)` by `(vx, vy)` for a box of `objectWidth × objectHeight`. */
  trace(
    x: number,
    y: number,
    vx: number,
    vy: number,
    objectWidth: number,
    objectHeight: number,
  ): TraceResult;
}

/**
 * Tile-based static collision map used as a scene's `collisionMap`.
 * Tile index `1` = fully solid; indices `2..lastSlope` = slope tiles defined in `tiledef`; indices above `lastSlope` = fully solid.
 * The swept trace is sub-stepped so fast-moving sprites never tunnel through walls.
 * Synonym: world collision, tile collision, static geometry, tilemap collision.
 */
export class CollisionGrid extends TileGrid implements CollisionGridLike {
  /** Highest tile index that maps to a slope definition; tiles above this value are treated as fully solid. @internal */
  lastSlope: number = 1;
  /** Slope line definitions keyed by tile index. Defaults to `CollisionGrid.defaultTileDef`. */
  tiledef: TileDefs;

  constructor(tilesize: number, data: number[][], tiledef?: TileDefs) {
    super(tilesize, data);
    this.tiledef = tiledef || CollisionGrid.defaultTileDef;

    // Highest tile index that is still a slope def; tiles above it are fully
    // solid. This is the max key across the slope defs.
    for (const t in this.tiledef) {
      const key = parseInt(t, 10);
      if (key > this.lastSlope) {
        this.lastSlope = key;
      }
    }
  }

  /**
   * Swept AABB trace from world position `(x, y)` by velocity `(vx, vy)` for a box of `objectWidth × objectHeight` pixels.
   * Sub-steps the movement so no tile is ever skipped at high speed. Returns a `TraceResult` with the resolved position and collision flags.
   * Called automatically by `Physics.updateBody`; call manually only for custom movement.
   */
  trace(
    x: number,
    y: number,
    vx: number,
    vy: number,
    objectWidth: number,
    objectHeight: number,
  ): TraceResult {
    const res: TraceResult = {
      collision: { x: false, y: false, slope: false },
      position: { x, y },
      tile: { x: 0, y: 0 },
    };

    // Break the trace into steps no larger than a tile. The +0.1 forces an
    // extra step whenever vx/vy is an exact multiple of tilesize, so the very
    // first tile is never skipped.
    const steps = Math.ceil((Math.max(Math.abs(vx), Math.abs(vy)) + 0.1) / this.tilesize);
    if (steps > 1) {
      let sx = vx / steps;
      let sy = vy / steps;

      for (let i = 0; i < steps && (sx || sy); i++) {
        this._traceStep(res, x, y, sx, sy, objectWidth, objectHeight, vx, vy, i);

        x = res.position.x;
        y = res.position.y;
        if (res.collision.x) {
          sx = 0;
          vx = 0;
        }
        if (res.collision.y) {
          sy = 0;
          vy = 0;
        }
        if (res.collision.slope) {
          break;
        }
      }
    } else {
      this._traceStep(res, x, y, vx, vy, objectWidth, objectHeight, vx, vy, 0);
    }

    return res;
  }

  /** @internal Performs one sub-step of the swept trace, testing horizontal then vertical tile collisions. */
  private _traceStep(
    res: TraceResult,
    x: number,
    y: number,
    vx: number,
    vy: number,
    width: number,
    height: number,
    rvx: number,
    rvy: number,
    step: number,
  ): void {
    res.position.x += vx;
    res.position.y += vy;

    let t = 0;

    // Horizontal collision (walls).
    if (vx) {
      const pxOffsetX = vx > 0 ? width : 0;
      const tileOffsetX = vx < 0 ? this.tilesize : 0;

      const firstTileY = Math.max(Math.floor(y / this.tilesize), 0);
      const lastTileY = Math.min(Math.ceil((y + height) / this.tilesize), this.height);
      const tileX = Math.floor((res.position.x + pxOffsetX) / this.tilesize);

      // Also test the current tile, in case it's a line def we could still hit.
      let prevTileX = Math.floor((x + pxOffsetX) / this.tilesize);
      if (step > 0 || tileX === prevTileX || prevTileX < 0 || prevTileX >= this.width) {
        prevTileX = -1;
      }

      if (tileX >= 0 && tileX < this.width) {
        for (let tileY = firstTileY; tileY < lastTileY; tileY++) {
          if (prevTileX !== -1) {
            t = this.data[tileY][prevTileX];
            if (
              t > 1 &&
              t <= this.lastSlope &&
              this._checkTileDef(res, t, x, y, rvx, rvy, width, height, prevTileX, tileY)
            ) {
              break;
            }
          }

          t = this.data[tileY][tileX];
          if (
            t === 1 ||
            t > this.lastSlope || // fully solid tile?
            (t > 1 && this._checkTileDef(res, t, x, y, rvx, rvy, width, height, tileX, tileY)) // slope?
          ) {
            if (t > 1 && t <= this.lastSlope && res.collision.slope) {
              break;
            }

            res.collision.x = true;
            res.tile.x = t;
            x = res.position.x = tileX * this.tilesize - pxOffsetX + tileOffsetX;
            rvx = 0;
            break;
          }
        }
      }
    }

    // Vertical collision (floor, ceiling).
    if (vy) {
      const pxOffsetY = vy > 0 ? height : 0;
      const tileOffsetY = vy < 0 ? this.tilesize : 0;

      const firstTileX = Math.max(Math.floor(res.position.x / this.tilesize), 0);
      const lastTileX = Math.min(Math.ceil((res.position.x + width) / this.tilesize), this.width);
      const tileY = Math.floor((res.position.y + pxOffsetY) / this.tilesize);

      let prevTileY = Math.floor((y + pxOffsetY) / this.tilesize);
      if (step > 0 || tileY === prevTileY || prevTileY < 0 || prevTileY >= this.height) {
        prevTileY = -1;
      }

      if (tileY >= 0 && tileY < this.height) {
        for (let tileX = firstTileX; tileX < lastTileX; tileX++) {
          if (prevTileY !== -1) {
            t = this.data[prevTileY][tileX];
            if (
              t > 1 &&
              t <= this.lastSlope &&
              this._checkTileDef(res, t, x, y, rvx, rvy, width, height, tileX, prevTileY)
            ) {
              break;
            }
          }

          t = this.data[tileY][tileX];
          if (
            t === 1 ||
            t > this.lastSlope || // fully solid tile?
            (t > 1 && this._checkTileDef(res, t, x, y, rvx, rvy, width, height, tileX, tileY)) // slope?
          ) {
            if (t > 1 && t <= this.lastSlope && res.collision.slope) {
              break;
            }

            res.collision.y = true;
            res.tile.y = t;
            res.position.y = tileY * this.tilesize - pxOffsetY + tileOffsetY;
            break;
          }
        }
      }
    }
  }

  /** @internal Tests one slope tile definition against the moving box; writes `res.collision.slope` and snaps `res.position` on a hit. */
  private _checkTileDef(
    res: TraceResult,
    t: number,
    x: number,
    y: number,
    vx: number,
    vy: number,
    width: number,
    height: number,
    tileX: number,
    tileY: number,
  ): boolean {
    const def = this.tiledef[t];
    if (!def) {
      return false;
    }

    const lx = (tileX + def[0]) * this.tilesize;
    const ly = (tileY + def[1]) * this.tilesize;
    const lvx = (def[2] - def[0]) * this.tilesize;
    const lvy = (def[3] - def[1]) * this.tilesize;
    const solid = def[4];

    // The box corner to test, relative to the line.
    const tx = x + vx + (lvy < 0 ? width : 0) - lx;
    const ty = y + vy + (lvx > 0 ? height : 0) - ly;

    // Is the box corner behind the line?
    if (lvx * ty - lvy * tx > 0) {
      // Lines are solid from one side only — dismiss if approached from behind.
      if (vx * -lvy + vy * lvx < 0) {
        return solid;
      }

      const length = Math.sqrt(lvx * lvx + lvy * lvy);
      const nx = lvy / length;
      const ny = -lvx / length;

      const proj = tx * nx + ty * ny;
      const px = nx * proj;
      const py = ny * proj;

      // Projected out further than we moved? Full-tile collision for solid
      // tiles; for non-solid, only if we were in front of the line.
      if (px * px + py * py >= vx * vx + vy * vy) {
        return solid || lvx * (ty - vy) - lvy * (tx - vx) < 0.5;
      }

      res.position.x = x + vx - px;
      res.position.y = y + vy - py;
      res.collision.slope = { x: lvx, y: lvy, nx, ny };
      return true;
    }

    return false;
  }

  /**
   * Built-in slope tile definitions covering 15°, 22°, 45°, 67°, and 75° ramps in all four diagonal directions, plus cardinal one-way edges.
   * Assigned automatically when no `tiledef` is passed to the constructor.
   * Synonym: default slopes, ramp tiles, angled tiles.
   */
  static defaultTileDef: TileDefs = (() => {
    const H = 1 / 2;
    const N = 1 / 3;
    const M = 2 / 3;
    const S = true; // SOLID
    const X = false; // NON_SOLID
    return {
      /* 15 NE */ 5: [0, 1, 1, M, S], 6: [0, M, 1, N, S], 7: [0, N, 1, 0, S],
      /* 22 NE */ 3: [0, 1, 1, H, S], 4: [0, H, 1, 0, S],
      /* 45 NE */ 2: [0, 1, 1, 0, S],
      /* 67 NE */ 10: [H, 1, 1, 0, S], 21: [0, 1, H, 0, S],
      /* 75 NE */ 32: [M, 1, 1, 0, S], 43: [N, 1, M, 0, S], 54: [0, 1, N, 0, S],

      /* 15 SE */ 27: [0, 0, 1, N, S], 28: [0, N, 1, M, S], 29: [0, M, 1, 1, S],
      /* 22 SE */ 25: [0, 0, 1, H, S], 26: [0, H, 1, 1, S],
      /* 45 SE */ 24: [0, 0, 1, 1, S],
      /* 67 SE */ 11: [0, 0, H, 1, S], 22: [H, 0, 1, 1, S],
      /* 75 SE */ 33: [0, 0, N, 1, S], 44: [N, 0, M, 1, S], 55: [M, 0, 1, 1, S],

      /* 15 NW */ 16: [1, N, 0, 0, S], 17: [1, M, 0, N, S], 18: [1, 1, 0, M, S],
      /* 22 NW */ 14: [1, H, 0, 0, S], 15: [1, 1, 0, H, S],
      /* 45 NW */ 13: [1, 1, 0, 0, S],
      /* 67 NW */ 8: [H, 1, 0, 0, S], 19: [1, 1, H, 0, S],
      /* 75 NW */ 30: [N, 1, 0, 0, S], 41: [M, 1, N, 0, S], 52: [1, 1, M, 0, S],

      /* 15 SW */ 38: [1, M, 0, 1, S], 39: [1, N, 0, M, S], 40: [1, 0, 0, N, S],
      /* 22 SW */ 36: [1, H, 0, 1, S], 37: [1, 0, 0, H, S],
      /* 45 SW */ 35: [1, 0, 0, 1, S],
      /* 67 SW */ 9: [1, 0, H, 1, S], 20: [H, 0, 0, 1, S],
      /* 75 SW */ 31: [1, 0, M, 1, S], 42: [M, 0, N, 1, S], 53: [N, 0, 0, 1, S],

      /* Go N */ 12: [0, 0, 1, 0, X],
      /* Go S */ 23: [1, 1, 0, 1, X],
      /* Go E */ 34: [1, 0, 1, 1, X],
      /* Go W */ 45: [0, 1, 0, 0, X],
    };
  })();

  /**
   * A no-op `CollisionGridLike` that never blocks movement — use as a scene's `collisionMap` when you have no tile collision.
   * Synonym: passthrough collision, no collision map, open world.
   */
  static staticNoCollision: CollisionGridLike = {
    trace(x: number, y: number, vx: number, vy: number): TraceResult {
      return {
        collision: { x: false, y: false, slope: false },
        position: { x: x + vx, y: y + vy },
        tile: { x: 0, y: 0 },
      };
    },
  };
}
