/**
 * Physics3d — OPTIONAL rigid-body physics for the World3d layer. A thin,
 * engine-vocabulary wrapper over a vendored WASM physics core that ships as a
 * SEPARATE chunk (`physics3d-core.mjs`, ~1 MB): games that never call
 * `Physics3d.create()` never load a byte of it.
 *
 *   // setup() — one await, then attach to the world and it's hands-free:
 *   this.sim = await Physics3d.create({ gravity: -20 });
 *   world.physics = this.sim;                    // the game steps + syncs it
 *   this.sim.bind(ground, { type: 'static' });   // level geometry
 *   const crate = this.sim.bind(crateMesh, { bounce: 0.2 });
 *   crate.impulse({ x: 0, y: 6, z: -3 });
 *
 * What the wrapper hides ON PURPOSE (never reach past it): the WASM module
 * and its manual memory rules, body/shape handle plumbing, quaternion
 * conventions (bodies write the mesh's yaw/pitch/roll pose — steer dynamics
 * with forces, never by setting the rotation), density units (a 1×1×1 box has
 * mass 1), bigint collision bits (use string `group`/`hits` names), and the
 * fixed-timestep accumulator.
 *
 * V2 NOTE: World3d meshes are retained INSTANCED handles (x/y/z, w/h/d,
 * yaw/pitch/roll) with no vertex data on the handle, so the collision shapes
 * derivable from w/h/d alone are the primitives: `box`, `sphere`, `capsule`.
 * For loaded models there is also `'hull'` — the caller PASSES the convex
 * points (`hullOfVerts` over the model's unit-fit geometry) since the handle
 * carries no vertex data; the wrapper scales them by w/h/d exactly like box
 * half-extents. (Raster's `ring`/`mesh` shapes did not survive the port.)
 */

import { vec3, type V3 as Vec3 } from './math3d.js';

/**
 * The structural mesh shape `bind()` accepts — anything with a World3d
 * `Mesh3d`'s pose fields (a real Mesh3d, or a plain object in headless tests).
 * `w/h/d` are the FULL sizes along each axis (the v2 unit-geometry rule: a
 * sphere with w=h=d=2 has radius 1); `yaw/pitch/roll` are Euler radians
 * applied in the renderer's Y→X→Z order.
 */
export interface MeshLike3d {
  x: number; y: number; z: number;
  w: number; h: number; d: number;
  yaw: number; pitch: number; roll: number;
}

// ─── Internal core-module surface (deliberately untyped beyond what we use;
// the vendored chunk carries its own behavior, this wrapper is the contract).
type B3 = any;
type Id = { index1: number; world0: number; generation: number };
const idKey = (id: Id): string => id.index1 + ':' + id.generation;

// Resolve the physics core: the shipped sibling chunk first (dist/ + sandbox
// layout), then the repo vendor file (dev + headless tests from src).
async function loadCore(explicit?: string): Promise<B3> {
  // NOTE: the URL argument must stay a VARIABLE — a literal lets vite
  // statically resolve the vendor path at build time and INLINE the ~1 MB
  // WASM core into the main bundle as a base64 data: URL, silently
  // defeating the lazy-chunk design (this shipped once).
  const candidates = (explicit
    ? [explicit]
    : [
        './physics3d-core.mjs',            // next to webgpu.js (shipped)
        '../physics3d-core.mjs',           // dist/webgpu/ types layout
        '../../vendor/physics3d-core.mjs', // dev: src/lib → vendor/
      ]).map((p) => new URL(p, import.meta.url).href);
  let lastErr: unknown = null;
  for (const url of candidates) {
    try {
      const mod = await import(/* @vite-ignore */ url);
      return await mod.default();
    } catch (e) {
      lastErr = e;
    }
  }
  throw new Error('Physics3d: physics core module not found (physics3d-core.mjs). ' + String(lastErr));
}

/** Options for `Physics3d.create`. */
export interface Physics3dOptions {
  /** Gravity: a number is world-units/s² straight down (`-20` default — arcade-weighty), or a full vector. */
  gravity?: number | Vec3;
  /** Override the physics core module URL (rarely needed — the default finds the shipped chunk). */
  module?: string;
}

/** Options for `world.bind`. */
export interface BindOptions {
  /**
   * `'dynamic'` (default) — fully simulated. `'static'` — immovable level
   * geometry. `'kinematic'` — YOU move the mesh (position/rotation as usual)
   * and it pushes dynamic bodies physically (moving platforms, doors on
   * rails).
   */
  type?: 'dynamic' | 'static' | 'kinematic';
  /**
   * Collision shape: `'auto'` (default — a box of the mesh's w/h/d),
   * `'sphere'`, `'capsule'` (upright), or `'hull'` (convex wrap of the
   * `points` you supply — loaded OBJ/GLB models, ramps, rocks; build them
   * with `hullOfVerts` over the model's geometry). Match it to the visual:
   * World3d spheres want `'sphere'`, capsule pawns want `'capsule'`,
   * everything box-ish (boxes, roundedBoxes, panels) is happy as a box.
   * NOTE a hull is CONVEX — a donut's hull is a solid disc.
   */
  shape?: 'auto' | 'box' | 'sphere' | 'capsule' | 'hull';
  /**
   * The `'hull'` shape's point cloud: flat xyz triples in the mesh's LOCAL /
   * unit space (the same space as unit-fit model geometry — spanning ±0.5
   * per full-size axis). The wrapper scales them by the mesh's w/h/d exactly
   * like it derives box half-extents. Feed it `hullOfVerts(model.verts)`.
   * Required for `shape: 'hull'` (missing/degenerate points fall back to the
   * w/h/d box).
   */
  points?: Float32Array;
  /** Surface grip 0..1+. Default `0.5`. */
  friction?: number;
  /** Bounciness 0..1. Default `0`. */
  bounce?: number;
  /** Rolling resistance 0..~0.1 — rolling bodies naturally slow down (rubber tyres, felt balls). Default `0` (rolls forever). */
  rollingResistance?: number;
  /** Total mass (dynamic bodies). Default: ~1 per cubic unit of bounds. */
  mass?: number;
  /** Collision group name (see `hits`). Default `'default'`. */
  group?: string;
  /** Group names this body collides with. Default: everything. */
  hits?: string[];
  /** Sensor mode: overlaps fire `onEnter`/`onExit` but apply NO contact forces (pickup zones, pressure plates). */
  trigger?: boolean;
  /** A body entered this trigger (trigger bodies only). */
  onEnter?: (other: Body3d) => void;
  /** A body left this trigger (trigger bodies only). */
  onExit?: (other: Body3d) => void;
  /** Contact started with another body (`speed` = approach speed — gate impact sounds on it). Fires only above the solver's impact threshold; use `onTouch` for every contact. */
  onHit?: (other: Body3d, speed: number) => void;
  /** Contact BEGAN with another body (any speed — standing-on bookkeeping, stickiness, "what am I touching"). */
  onTouch?: (other: Body3d) => void;
  /** Contact ENDED with another body — the pair separated (left the platform, dropped the crate). */
  onRelease?: (other: Body3d) => void;
  /** Continuous collision for fast movers (bullets) — stops tunneling through thin walls. */
  fast?: boolean;
  /** Linear damping (air drag). Default `0`. */
  damping?: number;
  /** Angular damping. Default `0.05`. */
  angularDamping?: number;
  /** Gravity multiplier for this body (0 = floats). Default `1`. */
  gravityScale?: number;
  /** Freeze all rotation (top-down pucks, upright props). Default `false`. */
  lockRotation?: boolean;
  /** Allow very fast rotation (the solver clamps angular speed by default) — set on WHEELS and other high-RPM bodies or their top speed rev-limits. Default `false`. */
  fastSpin?: boolean;
  /**
   * Center-of-mass offset in the mesh's LOCAL space. A car with `balance:
   * {y: -0.4}` carries its weight low like a real car (planted, hard to
   * flip); a roly-poly toy uses a big negative y. Default: the geometric
   * center of the collision shape.
   */
  balance?: Vec3;
  /**
   * Conveyor belt: the surface drags whatever rests on it at this velocity
   * (the body itself stays put — usually a `'static'` belt). The vector is in
   * the shape's LOCAL space: an unrotated belt moving cargo along world −Z is
   * `{ x: 0, y: 0, z: -3 }`; rotate the mesh and the belt direction turns
   * with it. Higher `friction` = more grip on the cargo.
   */
  conveyor?: Vec3;
  /**
   * Family name: bodies sharing a family NEVER collide with each other while
   * still colliding with the rest of the world — the ragdoll/compound-creature
   * knob (limbs must overlap at the joints without fighting). Independent of
   * `group`/`hits`.
   */
  family?: string;
}

/** Options for `world.character`. */
export interface Character3dOptions {
  /** Capsule radius. Default `0.4`. */
  radius?: number;
  /** Total capsule height. Default `1.7`. */
  height?: number;
  /** Ground friction while standing still. Default `0.1` (low — movement is velocity-driven). */
  friction?: number;
  /** Collision group. Default `'characters'`. */
  group?: string;
}

/** Options for `world.hinge`. */
export interface HingeOptions {
  /** World-space anchor point the hinge rotates around. */
  at: Vec3;
  /** World-space hinge axis. Default `{x:0, y:1, z:0}` (a door). */
  axis?: Vec3;
  /** Swing limits in radians `[min, max]` about the axis. Omit for free spin. */
  limits?: [number, number];
  /** Drive the hinge: radians/second (+ torque budget). The windmill/motor knob. */
  motor?: { speed: number; torque?: number };
}

/** Options for `world.slider`. */
export interface SliderOptions {
  /** World-space anchor on the slide axis. */
  at: Vec3;
  /** World-space slide axis. Default `{x:0, y:1, z:0}` (an elevator). */
  axis?: Vec3;
  /** Travel limits along the axis `[min, max]` in world units. */
  limits?: [number, number];
  /** Drive the slide: units/second (+ force budget). */
  motor?: { speed: number; force?: number };
}

/** Options for `world.spring`. */
export interface SpringOptions {
  /** Rest length. Default: the current distance between the two anchors. */
  length?: number;
  /** Spring stiffness in Hz (oscillations/sec). Default `3`. */
  hertz?: number;
  /** Damping 0..1 (1 = no wobble). Default `0.35`. */
  damping?: number;
  /** World anchor on body A. Default: A's origin. */
  atA?: Vec3;
  /** World anchor on body B. Default: B's origin. */
  atB?: Vec3;
}

/** Options for `world.socket` (ball-and-socket joint). */
export interface SocketOptions {
  /** World-space anchor — the ball center (a shoulder, a hip, a chain link). */
  at: Vec3;
  /**
   * The rest-pose axis the swing cone opens around, world space — point it
   * along the CHILD limb (shoulder → elbow). Default `{x:0, y:-1, z:0}`
   * (a limb hanging down).
   */
  axis?: Vec3;
  /** Max swing away from `axis` in radians. Omit for a free ball joint. */
  swing?: number;
  /** Twist limits about `axis` in radians `[min, max]`. Omit for free twist. */
  twist?: [number, number];
  /** Joint stiffness: a soft spring pulling back to the rest pose (Hz). Adds life to ragdolls. Default off. */
  stiffness?: number;
}

/** Options for `world.wheel` — a vehicle wheel with suspension, drive and steering. */
export interface WheelOptions {
  /** World-space wheel center at rest pose. */
  at: Vec3;
  /** World-space axle (spin) axis. Default `{x:1, y:0, z:0}` — a car facing ±Z. */
  axle?: Vec3;
  /** Suspension spring stiffness in Hz. Default `3.5`. */
  hertz?: number;
  /** Suspension damping 0..1 (1 = no bounce). Default `0.7`. */
  damping?: number;
  /** Suspension travel `[down, up]` in world units around the rest pose. Default `[-0.25, 0.15]`. */
  travel?: [number, number];
  /** This wheel is powered — `joint.motor(speed)` drives it (rad/s). Torque budget optional. */
  drive?: boolean | { torque?: number };
  /** This wheel steers — `joint.steer(angle)` aims it (radians). `limit` caps the lock. Default lock `0.65`. */
  steer?: boolean | { limit?: number; torque?: number };
}

/** Options for `world.grab` (motor joint — hold + drive a body relative to another). */
export interface GrabOptions {
  /** Max holding force (how heavy a thing it can carry against gravity/knocks). Default `200`. */
  force?: number;
  /** Max holding torque (how firmly it resists spinning away). Default `100`. */
  torque?: number;
  /** Hold spring stiffness in Hz. Default `5` (snappy). Lower = laggy tractor-beam feel. */
  stiffness?: number;
  /** Hold damping 0..1. Default `0.8`. */
  damping?: number;
}

/** A joint — keep the handle to drive its motor or `destroy()` it. */
export interface Joint3d {
  /** Retune the motor (hinge: rad/s; slider: units/s; wheel: spin rad/s). No-op on springs/welds. */
  motor(speed: number, strength?: number): void;
  /** Steer a wheel joint to this angle in radians (no-op on other joints). */
  steer?(angle: number): void;
  /** Grab joints: drive the held body at this relative velocity (units/s, optional angular rad/s). */
  drive?(linear: Vec3, angular?: Vec3): void;
  /** Remove the joint (bodies separate). */
  destroy(): void;
  /** @internal */
  _id: Id;
}

/**
 * A physics body bound to a mesh. Dynamic bodies OWN the mesh transform —
 * steer them with `impulse`/`force`/`velocity`, never by writing x/y/z
 * (except `teleport`). Kinematic bodies are the reverse: move the MESH.
 */
export class Body3d {
  /** The mesh this body drives (dynamic) or follows (kinematic). */
  readonly mesh: MeshLike3d;
  /** `'dynamic' | 'static' | 'kinematic'`. */
  readonly type: 'dynamic' | 'static' | 'kinematic';
  /** Contact callback (assign any time). */
  onHit: ((other: Body3d, speed: number) => void) | null = null;
  /** Contact began / ended (any speed). */
  onTouch: ((other: Body3d) => void) | null = null;
  onRelease: ((other: Body3d) => void) | null = null;
  /** Trigger callbacks (trigger bodies). */
  onEnter: ((other: Body3d) => void) | null = null;
  onExit: ((other: Body3d) => void) | null = null;

  /** @internal */
  _body: Id;
  /** @internal */
  readonly _world: Physics3d;

  /** @internal */
  constructor(w: Physics3d, body: Id, mesh: MeshLike3d, type: 'dynamic' | 'static' | 'kinematic') {
    this._world = w;
    this._body = body;
    this.mesh = mesh;
    this.type = type;
  }

  /** Current linear velocity. */
  get velocity(): Vec3 {
    return this._world._b3.b3Body_GetLinearVelocity(this._body);
  }
  set velocity(v: Vec3) {
    this._world._b3.b3Body_SetLinearVelocity(this._body, v);
    this._world._b3.b3Body_SetAwake(this._body, true);
  }

  /** Current angular velocity (rad/s per axis). */
  get spin(): Vec3 {
    return this._world._b3.b3Body_GetAngularVelocity(this._body);
  }
  set spin(v: Vec3) {
    this._world._b3.b3Body_SetAngularVelocity(this._body, v);
    this._world._b3.b3Body_SetAwake(this._body, true);
  }

  /** The body's mass (dynamic bodies). */
  get mass(): number {
    return this._world._b3.b3Body_GetMass(this._body);
  }

  /**
   * Instant kick, scaled so `impulse({y: 6})` pops a 1-mass crate ~as high as
   * you'd guess regardless of its actual mass. Pass `at` (world point) to
   * also spin it — hits off-center tumble.
   */
  impulse(v: Partial<Vec3>, at?: Vec3): void {
    const m = this.mass || 1;
    const j = { x: (v.x ?? 0) * m, y: (v.y ?? 0) * m, z: (v.z ?? 0) * m };
    if (at) this._world._b3.b3Body_ApplyLinearImpulse(this._body, j, at, true);
    else this._world._b3.b3Body_ApplyLinearImpulseToCenter(this._body, j, true);
  }

  /** Continuous push (accumulates until the next step) — thrusters, wind. Mass-scaled like `impulse`. */
  force(v: Partial<Vec3>): void {
    const m = this.mass || 1;
    this._world._b3.b3Body_ApplyForceToCenter(this._body, { x: (v.x ?? 0) * m, y: (v.y ?? 0) * m, z: (v.z ?? 0) * m }, true);
  }

  /** Instantly move the body (and its mesh) — respawns. Clears velocity. Optional `rotation` is Euler radians (the mesh's yaw/pitch/roll convention); omitted = upright. */
  teleport(position: Vec3, rotation?: { yaw?: number; pitch?: number; roll?: number }): void {
    const b3 = this._world._b3;
    const bq = rotation
      ? eulerQuat(rotation.yaw ?? 0, rotation.pitch ?? 0, rotation.roll ?? 0)
      : { v: { x: 0, y: 0, z: 0 }, s: 1 };
    b3.b3Body_SetTransform(this._body, position, bq);
    b3.b3Body_SetLinearVelocity(this._body, { x: 0, y: 0, z: 0 });
    b3.b3Body_SetAngularVelocity(this._body, { x: 0, y: 0, z: 0 });
    b3.b3Body_SetAwake(this._body, true);
    this.mesh.x = position.x; this.mesh.y = position.y; this.mesh.z = position.z;
    // Reset the interpolation history — a respawn must never smear across the map.
    this._seedPose(position, { x: bq.v.x, y: bq.v.y, z: bq.v.z, w: bq.s });
  }

  /** @internal Set once destroyed — every later call is a safe no-op. */
  _dead = false;

  /** @internal Pose history for render interpolation: [x,y,z, qx,qy,qz,qw] at
   * the previous (`_pose0`) and latest (`_pose1`) fixed physics step. */
  _pose0 = new Float32Array([0, 0, 0, 0, 0, 0, 1]);
  _pose1 = new Float32Array([0, 0, 0, 0, 0, 0, 1]);

  /** @internal Seed both history slots (spawn/teleport — never smear across a jump). */
  _seedPose(p: Vec3, q: { x: number; y: number; z: number; w: number }): void {
    this._pose0[0] = this._pose1[0] = p.x;
    this._pose0[1] = this._pose1[1] = p.y;
    this._pose0[2] = this._pose1[2] = p.z;
    this._pose0[3] = this._pose1[3] = q.x;
    this._pose0[4] = this._pose1[4] = q.y;
    this._pose0[5] = this._pose1[5] = q.z;
    this._pose0[6] = this._pose1[6] = q.w;
  }

  /**
   * Remove this body from the world (the mesh stays where it was). Safe to
   * call twice — the second call is a no-op. (Body slots are recycled by the
   * solver; an unguarded double-destroy could kill an unrelated NEW body.)
   */
  destroy(): void {
    if (this._dead) return;
    this._dead = true;
    this._world._removeBody(this);
  }
}

/**
 * A capsule character controller: a rotation-locked dynamic body with
 * velocity-driven movement — pushes crates, rides platforms, climbs shallow
 * steps by capsule shape, and reports `grounded` for jump gating.
 *
 *   this.hero = this.sim.character(heroMesh, { radius: 0.4, height: 1.6 });
 *   // in update(): this.hero.move({ x, z }, 6); if (jump && this.hero.grounded) this.hero.jump(9);
 */
export class Character3d extends Body3d {
  /** @internal */
  private readonly half: number;

  /** @internal */
  constructor(w: Physics3d, body: Id, mesh: MeshLike3d, height: number) {
    super(w, body, mesh, 'dynamic');
    this.half = height / 2;
  }

  /** Steer: set horizontal velocity toward `dir` (any length) at `speed`, keeping vertical motion. */
  move(dir: { x: number; z: number }, speed: number): void {
    const len = Math.hypot(dir.x, dir.z);
    const v = this.velocity;
    if (len < 0.001) {
      this.velocity = { x: v.x * 0.8, y: v.y, z: v.z * 0.8 }; // glide to a stop
      return;
    }
    this.velocity = { x: (dir.x / len) * speed, y: v.y, z: (dir.z / len) * speed };
  }

  /** Standing on something (within a small tolerance below the feet)? */
  get grounded(): boolean {
    const m = this.mesh;
    const r = this._world.raycast({ x: m.x, y: m.y, z: m.z }, { x: 0, y: -1, z: 0 }, this.half + 0.25, this);
    return r !== null;
  }

  /** Jump with takeoff speed `v` (only fires while `grounded`). Returns whether it fired. */
  jump(v: number): boolean {
    if (!this.grounded) return false;
    const vel = this.velocity;
    this.velocity = { x: vel.x, y: v, z: vel.z };
    return true;
  }
}

/**
 * The physics world. `await Physics3d.create()` once in an async setup, bind
 * meshes, attach to the world (`world.physics = sim`) and everything else is
 * hands-free. All shapes are built from each mesh's CURRENT pose + w/h/d at
 * bind time — place meshes first, bind second.
 */
export class Physics3d {
  /** @internal The core module. */
  _b3: B3;
  /** @internal */
  private world: Id;
  /** @internal All live bodies by id key (event lookups). */
  private readonly bodies = new Map<string, Body3d>();
  /** @internal Mesh → body (rebind guards, mesh-based queries). */
  private readonly byMesh = new Map<MeshLike3d, Body3d>();
  /** @internal Kinematic bodies (mesh drives body each step). */
  private readonly kinematics: Body3d[] = [];
  /** @internal Collision group name → category bit. */
  private readonly groups = new Map<string, bigint>();
  /** @internal Family name → negative filter-group index (self-collision off). */
  private readonly families = new Map<string, number>();
  /** @internal Event buffers (allocated once). */
  private evBuf: unknown;
  private evTouch: unknown;
  private evHit: unknown;
  private evSensor: unknown;
  /** @internal Fixed-step accumulator. */
  private acc = 0;
  /** Diagnostic: count of body handles found stale during sync (should stay 0). */
  invalidBodies = 0;

  private constructor(b3: B3, world: Id) {
    this._b3 = b3;
    this.world = world;
    this.evBuf = b3.createEventsBuffer();
    this.evTouch = b3.createContactTouchEvent();
    this.evHit = b3.createContactHitEvent();
    this.evSensor = b3.createSensorTouchEvent();
  }

  /**
   * Load the physics core (first call fetches the ~1 MB chunk; later calls
   * are instant) and create a world. One world per scene is the pattern.
   */
  static async create(opts: Physics3dOptions = {}): Promise<Physics3d> {
    const b3 = await loadCore(opts.module);
    const def = b3.b3DefaultWorldDef();
    const g = opts.gravity ?? -20;
    def.gravity = typeof g === 'number' ? { x: 0, y: g, z: 0 } : { ...g };
    const world = b3.b3CreateWorld(def);
    return new Physics3d(b3, world);
  }

  /** @internal Category bit for a group name (created on first use). */
  private groupBit(name: string): bigint {
    let bit = this.groups.get(name);
    if (bit === undefined) {
      bit = 1n << BigInt(this.groups.size);
      this.groups.set(name, bit);
    }
    return bit;
  }

  /** @internal Build the b3 filter for group/hits/family options. */
  private filterFor(group: string, hits?: string[], family?: string): { categoryBits: bigint; maskBits: bigint; groupIndex: number } {
    const cat = this.groupBit(group);
    let mask = ~0n & ((1n << 62n) - 1n);
    if (hits) {
      mask = 0n;
      for (const h of hits) mask |= this.groupBit(h);
    }
    // A family is a NEGATIVE filter-group index: same index → never collide
    // with each other (ragdoll limbs overlap at their joints in peace).
    let groupIndex = 0;
    if (family) {
      let idx = this.families.get(family);
      if (idx === undefined) {
        idx = -(this.families.size + 1);
        this.families.set(family, idx);
      }
      groupIndex = idx;
    }
    return { categoryBits: cat, maskBits: mask, groupIndex };
  }

  /**
   * Give a mesh a physics body. The shape is built from the mesh's w/h/d;
   * position/rotation come from where the mesh IS right now. Returns the
   * `Body3d` (dynamic bodies then own the mesh's transform).
   */
  bind(mesh: MeshLike3d, opts: BindOptions = {}): Body3d {
    const existing = this.byMesh.get(mesh);
    if (existing) return existing;
    const b3 = this._b3;
    const type = opts.type ?? 'dynamic';

    let shape = opts.shape ?? 'auto';
    if (shape === 'auto') shape = 'box';

    const def = b3.b3DefaultBodyDef();
    def.position = { x: mesh.x, y: mesh.y, z: mesh.z };
    // The starting pose absorbs the mesh's Euler rotation. Unlike raster there
    // is NO separate quat channel on a v2 mesh: the sync below writes the body
    // pose back as yaw/pitch/roll every frame, so nothing double-rotates.
    const startQuat = eulerQuat(mesh.yaw, mesh.pitch, mesh.roll);
    def.rotation = startQuat;
    def.type = type === 'dynamic' ? b3.b3BodyType.b3_dynamicBody
      : type === 'kinematic' ? b3.b3BodyType.b3_kinematicBody
      : b3.b3BodyType.b3_staticBody;
    // Continuous collision sweeps support the primitive shapes only — a
    // bulleted hull can tunnel WORSE than a discrete one, so never set it.
    if (opts.fast && shape !== 'hull') def.isBullet = true;
    if (opts.damping !== undefined) def.linearDamping = opts.damping;
    def.angularDamping = opts.angularDamping ?? 0.05;
    if (opts.gravityScale !== undefined) def.gravityScale = opts.gravityScale;
    if (opts.lockRotation) def.motionLocks = { linearX: false, linearY: false, linearZ: false, angularX: true, angularY: true, angularZ: true };
    if (opts.fastSpin) def.allowFastRotation = true;
    const body = b3.b3CreateBody(this.world, def);

    const sd = b3.b3DefaultShapeDef();
    sd.baseMaterial.friction = opts.friction ?? 0.5;
    sd.baseMaterial.restitution = opts.bounce ?? 0;
    if (opts.rollingResistance) sd.baseMaterial.rollingResistance = opts.rollingResistance;
    sd.enableContactEvents = true;
    sd.enableHitEvents = true;      // onHit reads hit events (approach speed included)
    sd.enableSensorEvents = true;   // everyone can visit triggers
    sd.filter = this.filterFor(opts.group ?? 'default', opts.hits, opts.family);
    if (opts.trigger) sd.isSensor = true;
    if (opts.conveyor) sd.baseMaterial.tangentVelocity = { ...opts.conveyor };

    // ── Shape from the mesh's w/h/d (v2 geometry is origin-centered, and the
    // handle sizes ARE the world sizes: a sphere with w=h=d=2 has radius 1). ──
    const vol = Math.max(0.001, mesh.w * mesh.h * mesh.d);
    // Density so a unit cube weighs 1 — or hit the requested total mass.
    sd.density = opts.mass !== undefined ? opts.mass / vol : 1;

    if (shape === 'sphere') {
      const r = (Math.max(mesh.w, mesh.h, mesh.d) / 2) || 0.5;
      b3.b3CreateSphereShape(body, sd, { center: { x: 0, y: 0, z: 0 }, radius: r });
    } else if (shape === 'capsule') {
      const r = (Math.max(mesh.w, mesh.d) / 2) || 0.3;
      const half = Math.max(0.01, mesh.h / 2 - r);
      b3.b3CreateCapsuleShape(body, sd, {
        center1: { x: 0, y: -half, z: 0 },
        center2: { x: 0, y: half, z: 0 },
        radius: r,
      });
    } else if (shape === 'hull') {
      // Convex wrap of caller-supplied LOCAL/unit-space points (a model's
      // `hullOfVerts` output), scaled by w/h/d — the exact rule the box
      // half-extents use. The core COPIES the hull into the world, so the
      // temporary is freed right after.
      let made = false;
      const src = opts.points;
      if (src && src.length >= 12) {
        // The core likes small hulls — sample down anything oversized.
        const count = Math.floor(src.length / 3);
        const step = Math.max(1, Math.ceil(count / 180));
        const pts: number[] = [];
        for (let i = 0; i < count; i += step) {
          pts.push(src[i * 3] * mesh.w, src[i * 3 + 1] * mesh.h, src[i * 3 + 2] * mesh.d);
        }
        const hull = b3.b3CreateHull(pts);
        if (hull) {
          b3.b3CreateHullShape(body, sd, hull);
          hull.delete(); // hulls are COPIED into the world
          made = true;
        }
      }
      // No/degenerate points (a flat or tiny cloud the core rejects): the
      // w/h/d box still collides sensibly.
      if (!made) b3.b3CreateBoxShape(body, sd, mesh.w / 2, mesh.h / 2, mesh.d / 2);
    } else {
      b3.b3CreateBoxShape(body, sd, mesh.w / 2, mesh.h / 2, mesh.d / 2);
    }

    // Shift the center of mass (weight distribution — low CoM = planted).
    if (opts.balance && type === 'dynamic') {
      const md = b3.b3Body_GetMassData(body);
      md.center = { x: md.center.x + opts.balance.x, y: md.center.y + opts.balance.y, z: md.center.z + opts.balance.z };
      b3.b3Body_SetMassData(body, md);
    }

    const wrapped = new Body3d(this, body, mesh, type);
    wrapped._seedPose({ x: mesh.x, y: mesh.y, z: mesh.z }, { x: startQuat.v.x, y: startQuat.v.y, z: startQuat.v.z, w: startQuat.s });
    wrapped.onHit = opts.onHit ?? null;
    wrapped.onTouch = opts.onTouch ?? null;
    wrapped.onRelease = opts.onRelease ?? null;
    wrapped.onEnter = opts.onEnter ?? null;
    wrapped.onExit = opts.onExit ?? null;
    this.bodies.set(idKey(body), wrapped);
    this.byMesh.set(mesh, wrapped);
    if (type === 'kinematic') this.kinematics.push(wrapped);
    return wrapped;
  }

  /** The capsule character controller (see `Character3d`). The mesh should be roughly `height` tall with its origin at the center. */
  character(mesh: MeshLike3d, opts: Character3dOptions = {}): Character3d {
    const b3 = this._b3;
    const radius = opts.radius ?? 0.4;
    const height = opts.height ?? 1.7;
    const def = b3.b3DefaultBodyDef();
    def.position = { x: mesh.x, y: mesh.y, z: mesh.z };
    def.type = b3.b3BodyType.b3_dynamicBody;
    def.motionLocks = { linearX: false, linearY: false, linearZ: false, angularX: true, angularY: true, angularZ: true };
    def.sleepThreshold = 0; // a controller must never doze off mid-input
    const body = b3.b3CreateBody(this.world, def);
    const sd = b3.b3DefaultShapeDef();
    sd.baseMaterial.friction = opts.friction ?? 0.1;
    sd.enableContactEvents = true;
    sd.enableSensorEvents = true;
    sd.filter = this.filterFor(opts.group ?? 'characters');
    sd.density = 1 / Math.max(0.01, Math.PI * radius * radius * height);
    const half = Math.max(0.01, height / 2 - radius);
    b3.b3CreateCapsuleShape(body, sd, {
      center1: { x: 0, y: -half, z: 0 },
      center2: { x: 0, y: half, z: 0 },
      radius,
    });
    const c = new Character3d(this, body, mesh, height);
    c._seedPose({ x: mesh.x, y: mesh.y, z: mesh.z }, { x: 0, y: 0, z: 0, w: 1 });
    this.bodies.set(idKey(body), c);
    this.byMesh.set(mesh, c);
    return c;
  }

  /** Look up the body bound to a mesh (or `null`). */
  bodyOf(mesh: MeshLike3d): Body3d | null {
    return this.byMesh.get(mesh) ?? null;
  }

  /**
   * Nearest physics hit along a ray — the PHYSICS-world query (line of sight
   * to bodies, ground checks). Pass `ignore` to skip one body (the shooter).
   */
  raycast(origin: Vec3, dir: Vec3, maxDistance: number = 100, ignore?: Body3d, opts?: { hits?: string[] }): { body: Body3d; point: Vec3; normal: Vec3; distance: number } | null {
    const b3 = this._b3;
    const len = Math.hypot(dir.x, dir.y, dir.z) || 1;
    const t = { x: (dir.x / len) * maxDistance, y: (dir.y / len) * maxDistance, z: (dir.z / len) * maxDistance };
    const res = b3.b3World_CastRayClosest(this.world, origin, t, this.queryFilterFor(opts?.hits));
    if (!res.hit) return null;
    const body = this.bodyOfShape(res.shapeId) ?? null;
    if (!body) return null;
    if (ignore && body === ignore) {
      // One retry from just past the ignored hit.
      const d = res.fraction * maxDistance + 0.01;
      const o2 = { x: origin.x + (dir.x / len) * d, y: origin.y + (dir.y / len) * d, z: origin.z + (dir.z / len) * d };
      return this.raycast(o2, dir, maxDistance - d, undefined, opts);
    }
    return {
      body,
      point: { ...res.point },
      normal: { ...res.normal },
      distance: res.fraction * maxDistance,
    };
  }

  /**
   * EVERY hit along a ray, sorted nearest-first — pierce-through weapons,
   * "what's between me and the target" lists. Pass `hits` to only see those
   * collision groups.
   */
  raycastAll(origin: Vec3, dir: Vec3, maxDistance: number = 100, opts?: { hits?: string[] }): { body: Body3d; point: Vec3; normal: Vec3; distance: number }[] {
    const b3 = this._b3;
    const len = Math.hypot(dir.x, dir.y, dir.z) || 1;
    const t = { x: (dir.x / len) * maxDistance, y: (dir.y / len) * maxDistance, z: (dir.z / len) * maxDistance };
    const results: { body: Body3d; point: Vec3; normal: Vec3; distance: number }[] = [];
    b3.b3World_CastRay(this.world, origin, t, this.queryFilterFor(opts?.hits), (shapeId: Id, point: Vec3, normal: Vec3, fraction: number) => {
      const body = this.bodyOfShape(shapeId);
      if (body) results.push({ body, point: { ...point }, normal: { ...normal }, distance: fraction * maxDistance });
      return 1; // keep going — we want them all
    });
    results.sort((a, b) => a.distance - b.distance);
    return results;
  }

  /**
   * Every body overlapping a SPHERE (exact narrowphase) — blast radii, aura
   * effects, "who is standing near the shrine". Pass `hits` to restrict to
   * collision groups.
   */
  overlap(center: Vec3, radius: number, opts?: { hits?: string[] }): Body3d[] {
    // A sphere proxy is a single point with a convex radius.
    return this.overlapProxy(center, [0, 0, 0], radius, opts);
  }

  /** Every body overlapping an axis-aligned BOX of `size` at `center` — room zones, platform occupancy. */
  overlapBox(center: Vec3, size: Vec3, opts?: { hits?: string[] }): Body3d[] {
    const pts: number[] = [];
    for (let c = 0; c < 8; c++) {
      pts.push(
        (c & 1 ? 0.5 : -0.5) * size.x,
        (c & 2 ? 0.5 : -0.5) * size.y,
        (c & 4 ? 0.5 : -0.5) * size.z,
      );
    }
    return this.overlapProxy(center, pts, 0, opts);
  }

  /** @internal Shared overlap plumbing: convex point proxy + radius at origin. */
  private overlapProxy(origin: Vec3, points: number[], radius: number, opts?: { hits?: string[] }): Body3d[] {
    const found: Body3d[] = [];
    const seen = new Set<Body3d>();      // multi-shape bodies report once
    this._b3.b3World_OverlapShape(this.world, origin, points, radius, this.queryFilterFor(opts?.hits), (shapeId: Id) => {
      const body = this.bodyOfShape(shapeId);
      if (body && !seen.has(body)) {
        seen.add(body);
        found.push(body);
      }
      return true;
    });
    return found;
  }

  /** @internal Query filter honoring the string collision groups. */
  private queryFilterFor(hits?: string[]): unknown {
    const filter = this._b3.b3DefaultQueryFilter();
    if (hits) {
      let mask = 0n;
      for (const h of hits) mask |= this.groupBit(h);
      filter.maskBits = mask;
    }
    return filter;
  }

  /** Radial blast: every dynamic body within `radius` gets a mass-scaled outward kick (with a little lift). */
  explosion(at: Vec3, radius: number, strength: number): void {
    for (const body of this.bodies.values()) {
      if (body.type !== 'dynamic') continue;
      const p = body.mesh;
      const dx = p.x - at.x, dy = p.y - at.y, dz = p.z - at.z;
      const d = Math.hypot(dx, dy, dz);
      if (d > radius || d < 0.0001) continue;
      const k = strength * (1 - d / radius);
      body.impulse({ x: (dx / d) * k, y: (dy / d) * k + k * 0.35, z: (dz / d) * k });
    }
  }

  // ─── Joints ────────────────────────────────────────────────────────────────

  /** @internal Fill base joint fields (bodies + local frames from a world anchor + axis→local-Z quats). */
  private jointBase(def: any, a: Body3d, b: Body3d, at: Vec3, axis: Vec3): void {
    def.base.bodyIdA = a._body;
    def.base.bodyIdB = b._body;
    const qAxis = quatFromZTo(axis);
    def.base.localFrameA = this.toLocalFrame(a, at, qAxis);
    def.base.localFrameB = this.toLocalFrame(b, at, qAxis);
  }

  /** @internal World point+rotation → a body's local joint frame. */
  private toLocalFrame(body: Body3d, at: Vec3, q: { v: Vec3; s: number }): { p: Vec3; q: { v: Vec3; s: number } } {
    const b3 = this._b3;
    const bp = b3.b3Body_GetPosition(body._body);
    const bq = b3.b3Body_GetRotation(body._body);
    const inv = quatConj(bq);
    const rel = quatRotate(inv, { x: at.x - bp.x, y: at.y - bp.y, z: at.z - bp.z });
    return { p: rel, q: quatMul(inv, q) };
  }

  /**
   * A hinge (revolute joint): doors, windmill hubs, seesaws, drawbridges,
   * wheels. Anchor at the world point, spinning about `axis`. Add `motor` to
   * drive it; `limits` to stop the swing.
   */
  hinge(a: Body3d, b: Body3d, opts: HingeOptions): Joint3d {
    const b3 = this._b3;
    const def = b3.b3DefaultRevoluteJointDef();
    this.jointBase(def, a, b, opts.at, opts.axis ?? vec3(0, 1, 0));
    if (opts.limits) {
      def.enableLimit = true;
      def.lowerAngle = opts.limits[0];
      def.upperAngle = opts.limits[1];
    }
    if (opts.motor) {
      def.enableMotor = true;
      def.motorSpeed = opts.motor.speed;
      def.maxMotorTorque = opts.motor.torque ?? 1000;
    }
    const id = b3.b3CreateRevoluteJoint(this.world, def);
    const self = this;
    return {
      _id: id,
      motor(speed: number, strength?: number): void {
        self._b3.b3RevoluteJoint_EnableMotor(id, true);
        self._b3.b3RevoluteJoint_SetMotorSpeed(id, speed);
        self._b3.b3Joint_WakeBodies(id); // a parked motor must restart a SLEEPING island
        if (strength !== undefined) self._b3.b3RevoluteJoint_SetMaxMotorTorque(id, strength);
      },
      destroy(): void { self._b3.b3DestroyJoint(id, true); },
    };
  }

  /**
   * A ball-and-socket (spherical joint): shoulders, hips, necks, chain links,
   * hanging signs. Free rotation about the anchor, optionally fenced by a
   * `swing` cone around `axis` and `twist` limits about it — the ragdoll
   * joint (pair with `family` on the limb bodies so they overlap in peace).
   */
  socket(a: Body3d, b: Body3d, opts: SocketOptions): Joint3d {
    const b3 = this._b3;
    const def = b3.b3DefaultSphericalJointDef();
    this.jointBase(def, a, b, opts.at, opts.axis ?? vec3(0, -1, 0));
    if (opts.swing !== undefined) {
      def.enableConeLimit = true;
      def.coneAngle = opts.swing;
    }
    if (opts.twist) {
      def.enableTwistLimit = true;
      def.lowerTwistAngle = opts.twist[0];
      def.upperTwistAngle = opts.twist[1];
    }
    if (opts.stiffness !== undefined) {
      def.enableSpring = true;
      def.hertz = opts.stiffness;
      def.dampingRatio = 0.7;
    }
    const id = b3.b3CreateSphericalJoint(this.world, def);
    const self = this;
    return {
      _id: id,
      motor(): void { /* sockets have no scalar motor */ },
      destroy(): void { self._b3.b3DestroyJoint(id, true); },
    };
  }

  /** A slider (prismatic joint): elevators, pistons, sliding doors, plungers. */
  slider(a: Body3d, b: Body3d, opts: SliderOptions): Joint3d {
    const b3 = this._b3;
    const def = b3.b3DefaultPrismaticJointDef();
    // Prismatic slides along local X — build the frame with X aimed at `axis`.
    const axis = opts.axis ?? vec3(0, 1, 0);
    const def2 = def;
    def2.base.bodyIdA = a._body;
    def2.base.bodyIdB = b._body;
    const qAxis = quatFromXTo(axis);
    def2.base.localFrameA = this.toLocalFrame(a, opts.at, qAxis);
    def2.base.localFrameB = this.toLocalFrame(b, opts.at, qAxis);
    if (opts.limits) {
      def.enableLimit = true;
      def.lowerTranslation = opts.limits[0];
      def.upperTranslation = opts.limits[1];
    }
    if (opts.motor) {
      def.enableMotor = true;
      def.motorSpeed = opts.motor.speed;
      def.maxMotorForce = opts.motor.force ?? 1000;
    }
    const id = b3.b3CreatePrismaticJoint(this.world, def);
    const self = this;
    return {
      _id: id,
      motor(speed: number, strength?: number): void {
        self._b3.b3PrismaticJoint_EnableMotor(id, true);
        self._b3.b3PrismaticJoint_SetMotorSpeed(id, speed);
        self._b3.b3Joint_WakeBodies(id);
        if (strength !== undefined) self._b3.b3PrismaticJoint_SetMaxMotorForce(id, strength);
      },
      destroy(): void { self._b3.b3DestroyJoint(id, true); },
    };
  }

  /**
   * A vehicle wheel: suspension spring + spin motor + steering in ONE joint —
   * the entire car recipe is a chassis, four wheel bodies, four of these.
   * Drive with `joint.motor(radPerSec)`, aim with `joint.steer(angle)`.
   * Convention: suspension travels world-vertical at the rest pose; the wheel
   * spins about `axle` (default +X — a car built facing ±Z).
   */
  wheel(chassis: Body3d, wheelBody: Body3d, opts: WheelOptions): Joint3d {
    const b3 = this._b3;
    const def = b3.b3DefaultWheelJointDef();
    // Joint frame per the solver's convention: frame X = suspension axis
    // (world up at rest) and frame Z = the axle the wheel spins about.
    const al = Math.hypot(opts.axle?.x ?? 1, opts.axle?.y ?? 0, opts.axle?.z ?? 0) || 1;
    const fz = { x: (opts.axle?.x ?? 1) / al, y: (opts.axle?.y ?? 0) / al, z: (opts.axle?.z ?? 0) / al };
    const fx = vec3(0, 1, 0);
    const fy = { x: fz.y * fx.z - fz.z * fx.y, y: fz.z * fx.x - fz.x * fx.z, z: fz.x * fx.y - fz.y * fx.x };
    const q = quatFromCols(fx, fy, fz);
    def.base.bodyIdA = chassis._body;
    def.base.bodyIdB = wheelBody._body;
    def.base.localFrameA = this.toLocalFrame(chassis, opts.at, q);
    def.base.localFrameB = this.toLocalFrame(wheelBody, opts.at, q);
    def.enableSuspensionSpring = true;
    def.suspensionHertz = opts.hertz ?? 3.5;
    def.suspensionDampingRatio = opts.damping ?? 0.7;
    const [travelLo, travelHi] = opts.travel ?? [-0.25, 0.15];
    def.enableSuspensionLimit = true;
    def.lowerSuspensionLimit = travelLo;
    def.upperSuspensionLimit = travelHi;
    if (opts.drive) {
      def.enableSpinMotor = true;
      def.spinSpeed = 0;
      def.maxSpinTorque = (typeof opts.drive === 'object' ? opts.drive.torque : undefined) ?? 80;
    }
    if (opts.steer) {
      const lock = (typeof opts.steer === 'object' ? opts.steer.limit : undefined) ?? 0.65;
      def.enableSteering = true;
      def.steeringHertz = 6;
      def.steeringDampingRatio = 1;
      def.maxSteeringTorque = (typeof opts.steer === 'object' ? opts.steer.torque : undefined) ?? 400;
      def.enableSteeringLimit = true;
      def.lowerSteeringLimit = -lock;
      def.upperSteeringLimit = lock;
      def.targetSteeringAngle = 0;
    }
    const id = b3.b3CreateWheelJoint(this.world, def);
    const self = this;
    return {
      _id: id,
      motor(speed: number, strength?: number): void {
        self._b3.b3WheelJoint_EnableSpinMotor(id, true);
        self._b3.b3WheelJoint_SetSpinMotorSpeed(id, speed);
        self._b3.b3Joint_WakeBodies(id); // throttle from standstill: wake the sleeping car
        if (strength !== undefined) self._b3.b3WheelJoint_SetMaxSpinTorque(id, strength);
      },
      steer(angle: number): void {
        self._b3.b3WheelJoint_SetTargetSteeringAngle(id, angle);
        self._b3.b3Joint_WakeBodies(id);
      },
      destroy(): void { self._b3.b3DestroyJoint(id, true); },
    };
  }

  /** A springy rope (distance joint with a soft spring): pendulums, cranes, bungees, suspension. */
  spring(a: Body3d, b: Body3d, opts: SpringOptions = {}): Joint3d {
    const b3 = this._b3;
    const def = b3.b3DefaultDistanceJointDef();
    const pa = opts.atA ?? this._b3.b3Body_GetPosition(a._body);
    const pb = opts.atB ?? this._b3.b3Body_GetPosition(b._body);
    def.base.bodyIdA = a._body;
    def.base.bodyIdB = b._body;
    const idq = { v: { x: 0, y: 0, z: 0 }, s: 1 };
    def.base.localFrameA = this.toLocalFrame(a, pa, idq);
    def.base.localFrameB = this.toLocalFrame(b, pb, idq);
    def.length = opts.length ?? Math.max(0.01, Math.hypot(pb.x - pa.x, pb.y - pa.y, pb.z - pa.z));
    if (opts.hertz !== undefined || opts.damping !== undefined) {
      def.enableSpring = true;
      def.hertz = opts.hertz ?? 3;
      def.dampingRatio = opts.damping ?? 0.35;
    }
    const id = b3.b3CreateDistanceJoint(this.world, def);
    const self = this;
    return {
      _id: id,
      motor(): void { /* springs have no motor */ },
      destroy(): void { self._b3.b3DestroyJoint(id, true); },
    };
  }

  /**
   * A motorized grip (motor joint): softly HOLDS body `b` at its current pose
   * relative to `a`, with force/torque budgets — tractor beams, grabber claws,
   * magnets, telekinesis, "carry the crate in front of the player". Unlike
   * `weld` it's springy and breakable-feeling; unlike `spring` it holds
   * orientation too. `joint.drive(v)` slides the held pose around.
   */
  grab(a: Body3d, b: Body3d, opts: GrabOptions = {}): Joint3d {
    const b3 = this._b3;
    const def = b3.b3DefaultMotorJointDef();
    // Anchor the relationship AS IT IS NOW: frame A at b's current pose.
    const bp = b3.b3Body_GetPosition(b._body);
    const bq = b3.b3Body_GetRotation(b._body);
    def.base.bodyIdA = a._body;
    def.base.bodyIdB = b._body;
    def.base.localFrameA = this.toLocalFrame(a, bp, bq);
    def.base.localFrameB = { p: { x: 0, y: 0, z: 0 }, q: { v: { x: 0, y: 0, z: 0 }, s: 1 } };
    def.linearHertz = opts.stiffness ?? 5;
    def.linearDampingRatio = opts.damping ?? 0.8;
    def.maxSpringForce = opts.force ?? 200;
    def.angularHertz = opts.stiffness ?? 5;
    def.angularDampingRatio = opts.damping ?? 0.8;
    def.maxSpringTorque = opts.torque ?? 100;
    def.maxVelocityForce = opts.force ?? 200;
    def.maxVelocityTorque = opts.torque ?? 100;
    const id = b3.b3CreateMotorJoint(this.world, def);
    b3.b3Joint_WakeBodies(id);
    const self = this;
    return {
      _id: id,
      motor(): void { /* use drive() on grab joints */ },
      drive(linear: Vec3, angular?: Vec3): void {
        self._b3.b3MotorJoint_SetLinearVelocity(id, { ...linear });
        if (angular) self._b3.b3MotorJoint_SetAngularVelocity(id, { ...angular });
        self._b3.b3Joint_WakeBodies(id);
      },
      destroy(): void { self._b3.b3DestroyJoint(id, true); },
    };
  }

  /** Lock two bodies rigidly together (build a compound after the fact, glue a rider to a platform). */
  weld(a: Body3d, b: Body3d, at?: Vec3): Joint3d {
    const b3 = this._b3;
    const def = b3.b3DefaultWeldJointDef();
    const anchor = at ?? this._b3.b3Body_GetPosition(b._body);
    this.jointBase(def, a, b, anchor, vec3(0, 0, 1));
    const id = b3.b3CreateWeldJoint(this.world, def);
    const self = this;
    return {
      _id: id,
      motor(): void { /* welds have no motor */ },
      destroy(): void { self._b3.b3DestroyJoint(id, true); },
    };
  }

  // ─── Stepping ──────────────────────────────────────────────────────────────

  /**
   * Advance the simulation and sync every bound mesh. Attach the world to the
   * 3D layer (`world.physics = sim`) and this is called for you every frame —
   * call it yourself only when running physics without a World3d.
   */
  update(dt: number): void {
    const b3 = this._b3;
    // Kinematics: the MESH is the target — physics chases it.
    for (const k of this.kinematics) {
      b3.b3Body_SetTargetTransform(k._body, { p: { x: k.mesh.x, y: k.mesh.y, z: k.mesh.z }, q: eulerQuat(k.mesh.yaw, k.mesh.pitch, k.mesh.roll) }, 1 / 60, true);
    }
    // Fixed 60 Hz steps (max 3/frame — a hitch must not spiral).
    this.acc = Math.min(this.acc + dt, 3 / 60);
    while (this.acc >= 1 / 60 - 1e-9) {
      this.acc -= 1 / 60;
      b3.b3World_Step(this.world, 1 / 60, 4);
      this.pumpEvents();
      // Roll the pose history: what WAS current becomes the previous step.
      for (const body of this.bodies.values()) {
        if (body.type !== 'dynamic' || body._dead) continue;
        if (!b3.b3Body_IsValid(body._body)) {
          // Should be impossible — if it happens the id went stale underneath
          // us. Count it (diagnosable via `world.invalidBodies`), quarantine
          // the handle, and leave the mesh where it last was.
          this.invalidBodies++;
          body._dead = true;
          this.bodies.delete(idKey(body._body));
          this.byMesh.delete(body.mesh);
          continue;
        }
        const prev = body._pose0, curr = body._pose1;
        prev.set(curr);
        const p = b3.b3Body_GetPosition(body._body);
        const q = b3.b3Body_GetRotation(body._body);
        curr[0] = p.x; curr[1] = p.y; curr[2] = p.z;
        curr[3] = q.v.x; curr[4] = q.v.y; curr[5] = q.v.z; curr[6] = q.s;
      }
    }
    // Sync meshes at the RENDER pose: interpolated between the last two 60 Hz
    // steps by the accumulator fraction — on 120 Hz+ displays the fixed-step
    // sim would otherwise snap poses every OTHER frame while cameras glide
    // every frame ("ghost car" judder).
    const alpha = Math.max(0, Math.min(1, this.acc * 60));
    for (const body of this.bodies.values()) {
      if (body.type !== 'dynamic' || body._dead) continue;
      const a = body._pose0, b = body._pose1;
      const mesh = body.mesh;
      mesh.x = a[0] + (b[0] - a[0]) * alpha;
      mesh.y = a[1] + (b[1] - a[1]) * alpha;
      mesh.z = a[2] + (b[2] - a[2]) * alpha;
      // Normalized quat lerp (steps are 1/60 apart — nlerp is exact enough),
      // sign-corrected so we never blend the long way round.
      let qx = b[3], qy = b[4], qz = b[5], qw = b[6];
      const dot = a[3] * qx + a[4] * qy + a[5] * qz + a[6] * qw;
      const s = dot < 0 ? -1 : 1;
      qx = a[3] + (qx * s - a[3]) * alpha;
      qy = a[4] + (qy * s - a[4]) * alpha;
      qz = a[5] + (qz * s - a[5]) * alpha;
      qw = a[6] + (qw * s - a[6]) * alpha;
      const inv = 1 / (Math.hypot(qx, qy, qz, qw) || 1);
      // v2 meshes have NO quaternion channel — the renderer applies Euler
      // yaw/pitch/roll in-shader (Y→X→Z). Decompose the body quat into that
      // exact order so the rendered pose matches the simulated one.
      quatToEuler(qx * inv, qy * inv, qz * inv, qw * inv, mesh);
    }
  }

  /** @internal Resolve an event shape id to a live Body3d — events can carry
   * shapes of bodies destroyed this frame, so validate before dereferencing. */
  private bodyOfShape(shapeId: Id): Body3d | undefined {
    if (!this._b3.b3Shape_IsValid(shapeId)) return undefined;
    return this.bodies.get(idKey(this._b3.b3Shape_GetBody(shapeId)));
  }

  /** @internal Drain contact + sensor events into wrapper callbacks. */
  private pumpEvents(): void {
    const b3 = this._b3;
    b3.getEvents(this.evBuf, this.world);
    const nHit = b3.getNumContactHitEvents(this.evBuf);
    for (let i = 0; i < nHit; i++) {
      b3.getContactHitEventAt(this.evHit, this.evBuf, i);
      const ev = this.evHit as { shapeIdA: Id; shapeIdB: Id; approachSpeed: number };
      const a = this.bodyOfShape(ev.shapeIdA);
      const bb = this.bodyOfShape(ev.shapeIdB);
      if (a && bb) {
        a.onHit?.(bb, ev.approachSpeed);
        bb.onHit?.(a, ev.approachSpeed);
      }
    }
    // Contact begin/end (any speed): onTouch / onRelease.
    const nCBegin = b3.getNumContactBeginEvents(this.evBuf);
    for (let i = 0; i < nCBegin; i++) {
      b3.getContactBeginEventAt(this.evTouch, this.evBuf, i);
      const ev = this.evTouch as { shapeIdA: Id; shapeIdB: Id };
      const a = this.bodyOfShape(ev.shapeIdA);
      const bb = this.bodyOfShape(ev.shapeIdB);
      if (a && bb) {
        a.onTouch?.(bb);
        bb.onTouch?.(a);
      }
    }
    const nCEnd = b3.getNumContactEndEvents(this.evBuf);
    for (let i = 0; i < nCEnd; i++) {
      b3.getContactEndEventAt(this.evTouch, this.evBuf, i);
      const ev = this.evTouch as { shapeIdA: Id; shapeIdB: Id };
      const a = this.bodyOfShape(ev.shapeIdA);
      const bb = this.bodyOfShape(ev.shapeIdB);
      if (a && bb) {
        a.onRelease?.(bb);
        bb.onRelease?.(a);
      }
    }
    const nBegin = b3.getNumSensorBeginEvents(this.evBuf);
    for (let i = 0; i < nBegin; i++) {
      b3.getSensorBeginEventAt(this.evSensor, this.evBuf, i);
      const ev = this.evSensor as { sensorShapeId: Id; visitorShapeId: Id };
      const sensor = this.bodyOfShape(ev.sensorShapeId);
      const visitor = this.bodyOfShape(ev.visitorShapeId);
      if (sensor && visitor) sensor.onEnter?.(visitor);
    }
    const nEnd = b3.getNumSensorEndEvents(this.evBuf);
    for (let i = 0; i < nEnd; i++) {
      b3.getSensorEndEventAt(this.evSensor, this.evBuf, i);
      const ev = this.evSensor as { sensorShapeId: Id; visitorShapeId: Id };
      const sensor = this.bodyOfShape(ev.sensorShapeId);
      const visitor = this.bodyOfShape(ev.visitorShapeId);
      if (sensor && visitor) sensor.onExit?.(visitor);
    }
  }

  /** @internal */
  _removeBody(body: Body3d): void {
    this.bodies.delete(idKey(body._body));
    this.byMesh.delete(body.mesh);
    const ki = this.kinematics.indexOf(body);
    if (ki >= 0) this.kinematics.splice(ki, 1);
    if (this._b3.b3Body_IsValid(body._body)) this._b3.b3DestroyBody(body._body);
  }

  /** Tear the world down (frees the WASM side). The meshes stay. */
  destroy(): void {
    const b3 = this._b3;
    b3.destroyEventsBuffer?.(this.evBuf);
    b3.b3DestroyWorld(this.world);
    this.bodies.clear();
    this.byMesh.clear();
    this.kinematics.length = 0;
  }
}

// ─── Tiny quat helpers (b3 convention: { v: {x,y,z}, s }). ──────────────────
type BQ = { v: Vec3; s: number };

/**
 * Euler (v2 mesh yaw/pitch/roll) → quat, in the RENDERER'S composition order.
 * The World3d WGSL `rotate()` applies roll (about Z), then pitch (about X),
 * then yaw (about Y): world = Ry(yaw)·Rx(pitch)·Rz(roll)·v. So the quat is
 * qy·qx·qz — identical to raster's mesh-matrix Y→X→Z order.
 */
function eulerQuat(yaw: number, pitch: number, roll: number): BQ {
  const cy = Math.cos(yaw / 2), sy = -Math.sin(yaw / 2);   // qY(−yaw): right-hand-turn yaw (see transform3d)
  const cx = Math.cos(pitch / 2), sx = Math.sin(pitch / 2);
  const cz = Math.cos(roll / 2), sz = Math.sin(roll / 2);
  const qy: BQ = { v: { x: 0, y: sy, z: 0 }, s: cy };
  const qx: BQ = { v: { x: sx, y: 0, z: 0 }, s: cx };
  const qz: BQ = { v: { x: 0, y: 0, z: sz }, s: cz };
  return quatMul(quatMul(qy, qx), qz);
}

/**
 * Quat → the mesh's yaw/pitch/roll, decomposed in the SAME Ry(yaw)·Rx(pitch)·
 * Rz(roll) order the shader applies — writing these onto the mesh reproduces
 * the body's exact orientation on screen. From the rotation matrix of that
 * product: m12 = −sin(pitch), m02/m22 = yaw, m10/m11 = roll.
 *
 * GIMBAL CAVEAT: at pitch = ±90° yaw and roll collapse onto the same axis, so
 * the split between them is arbitrary there (we put it all in yaw). A single
 * FRAME'S pose is still exact — every decomposition renders the right
 * orientation — but a body tumbling THROUGH the pole can see yaw/roll swap
 * values discontinuously between frames. That's invisible on screen (the
 * composed rotation stays continuous); only code that reads and reasons about
 * the raw yaw/pitch/roll numbers of a tumbling body would notice.
 */
function quatToEuler(x: number, y: number, z: number, w: number, out: { yaw: number; pitch: number; roll: number }): void {
  const sinPitch = 2 * (w * x - y * z);          // −m12
  if (Math.abs(sinPitch) > 0.99999) {
    // Pole: pitch is ±90°, yaw−roll (or yaw+roll) is all that's defined.
    out.pitch = sinPitch > 0 ? Math.PI / 2 : -Math.PI / 2;
    out.roll = 0;
    // Yaw negated to match eulerQuat's qY(−yaw) — right-hand-turn convention.
    out.yaw = -Math.atan2(Math.sign(sinPitch) * 2 * (x * y - w * z), 1 - 2 * (y * y + z * z));
    return;
  }
  out.pitch = Math.asin(sinPitch);
  out.yaw = -Math.atan2(2 * (x * z + w * y), 1 - 2 * (x * x + y * y));   // −(m02 / m22): right-hand-turn yaw
  out.roll = Math.atan2(2 * (x * y + w * z), 1 - 2 * (x * x + z * z));  // m10 / m11
}

function quatMul(a: BQ, b: BQ): BQ {
  return {
    v: {
      x: a.s * b.v.x + a.v.x * b.s + a.v.y * b.v.z - a.v.z * b.v.y,
      y: a.s * b.v.y - a.v.x * b.v.z + a.v.y * b.s + a.v.z * b.v.x,
      z: a.s * b.v.z + a.v.x * b.v.y - a.v.y * b.v.x + a.v.z * b.s,
    },
    s: a.s * b.s - a.v.x * b.v.x - a.v.y * b.v.y - a.v.z * b.v.z,
  };
}

function quatConj(q: BQ): BQ {
  return { v: { x: -q.v.x, y: -q.v.y, z: -q.v.z }, s: q.s };
}

function quatRotate(q: BQ, p: Vec3): Vec3 {
  const r = quatMul(quatMul(q, { v: p, s: 0 }), quatConj(q));
  return { x: r.v.x, y: r.v.y, z: r.v.z };
}

// The quat mapping unit `fromAxis` (0,0,1 or 1,0,0) onto `to`.
function quatFromTo(from: Vec3, to: Vec3): BQ {
  const l = Math.hypot(to.x, to.y, to.z) || 1;
  const t = { x: to.x / l, y: to.y / l, z: to.z / l };
  const d = from.x * t.x + from.y * t.y + from.z * t.z;
  if (d > 0.99999) return { v: { x: 0, y: 0, z: 0 }, s: 1 };
  if (d < -0.99999) {
    // 180°: any perpendicular axis.
    const axis = Math.abs(from.x) < 0.9 ? { x: 1, y: 0, z: 0 } : { x: 0, y: 1, z: 0 };
    const cx = from.y * axis.z - from.z * axis.y;
    const cy = from.z * axis.x - from.x * axis.z;
    const cz = from.x * axis.y - from.y * axis.x;
    const cl = Math.hypot(cx, cy, cz) || 1;
    return { v: { x: cx / cl, y: cy / cl, z: cz / cl }, s: 0 };
  }
  const cx = from.y * t.z - from.z * t.y;
  const cy = from.z * t.x - from.x * t.z;
  const cz = from.x * t.y - from.y * t.x;
  const s = Math.sqrt((1 + d) * 2);
  return { v: { x: cx / s, y: cy / s, z: cz / s }, s: s / 2 };
}

function quatFromZTo(axis: Vec3): BQ { return quatFromTo({ x: 0, y: 0, z: 1 }, axis); }
function quatFromXTo(axis: Vec3): BQ { return quatFromTo({ x: 1, y: 0, z: 0 }, axis); }

// Quat from an orthonormal basis (columns = the frame's world axes).
function quatFromCols(cx: Vec3, cy: Vec3, cz: Vec3): BQ {
  const m00 = cx.x, m10 = cx.y, m20 = cx.z;
  const m01 = cy.x, m11 = cy.y, m21 = cy.z;
  const m02 = cz.x, m12 = cz.y, m22 = cz.z;
  const trace = m00 + m11 + m22;
  if (trace > 0) {
    const s = Math.sqrt(trace + 1) * 2;
    return { v: { x: (m21 - m12) / s, y: (m02 - m20) / s, z: (m10 - m01) / s }, s: s / 4 };
  } else if (m00 > m11 && m00 > m22) {
    const s = Math.sqrt(1 + m00 - m11 - m22) * 2;
    return { v: { x: s / 4, y: (m01 + m10) / s, z: (m02 + m20) / s }, s: (m21 - m12) / s };
  } else if (m11 > m22) {
    const s = Math.sqrt(1 + m11 - m00 - m22) * 2;
    return { v: { x: (m01 + m10) / s, y: s / 4, z: (m12 + m21) / s }, s: (m02 - m20) / s };
  }
  const s = Math.sqrt(1 + m22 - m00 - m11) * 2;
  return { v: { x: (m02 + m20) / s, y: (m12 + m21) / s, z: s / 4 }, s: (m10 - m01) / s };
}
