/** Unified mouse + touch (multi-touch) pointer model with gesture recognition: tap, doubleTap, longPress, pan, swipe, pointerDown/Up/Move. All coordinates are in world space. */

// v2: raster's util Vec2 inlined locally (v2 has no util.ts vector types).
interface Vec2 { x: number; y: number }

// ─── Types ─────────────────────────────────────────────────────────────────

/** A single tracked input point — one mouse cursor or one touch finger. */
export interface Pointer {
  /** Stable id — `'mouse'` for the mouse, the touch's DOM `identifier` (as string) for touches. */
  id: string;
  /** Current position in world coordinates (the W,H you pass to `main`). */
  x: number;
  /** Current position in world coordinates. */
  y: number;
  /** Position when the pointer last went down (world coords). */
  startX: number;
  /** Position when the pointer last went down (world coords). */
  startY: number;
  /** Movement since the previous frame in world px (zero between frames). */
  dx: number;
  /** Movement since the previous frame in world px (zero between frames). */
  dy: number;
  /** Instantaneous velocity in world-px / second, computed over the last ~80 ms of motion. Zero between presses and reset to zero on each pointer-down. Read this at release to throw a sprite at the speed the player let go (no need to hit any swipe threshold). */
  vx: number;
  /** See `vx`. */
  vy: number;
  /** `true` while the pointer is pressed (mouse button held / finger on screen). */
  isDown: boolean;
  /** `performance.now()` at the last false→true transition of `isDown`. */
  downTime: number;
  /** `true` if this pointer comes from a TouchEvent, `false` if from a MouseEvent. Both behave the same in game code. */
  isTouch: boolean;
}

/** Base payload for every gesture event callback. */
export interface PointerEventBase {
  /** The pointer that triggered this gesture. */
  pointer: Pointer;
  /** World x-coordinate of the gesture. */
  x: number;
  /** World y-coordinate of the gesture. */
  y: number;
}

/** Payload for `onTap` — a quick down+up with no drag. */
export interface TapEvent extends PointerEventBase {
  /** Milliseconds between pointer-down and pointer-up. */
  duration: number;
}

/** Payload for `onDoubleTap` — two taps within `doubleTapDelay` in the same area. */
export interface DoubleTapEvent extends PointerEventBase {
  /** Milliseconds between the two taps. */
  interval: number;
}

/** Payload for `onLongPress` — pointer held stationary for `longPressDelay` ms. */
export interface LongPressEvent extends PointerEventBase {
  /** Milliseconds the pointer was held before the long-press fired. */
  duration: number;
}

/** Payload for `onPan` — fired continuously while a pressed pointer moves beyond `panThreshold`. */
export interface PanEvent extends PointerEventBase {
  /** Total movement since pointer-down (world px). */
  totalDx: number;
  /** Total movement since pointer-down (world px). */
  totalDy: number;
  /** Movement since the last pan frame (world px). */
  dx: number;
  /** Movement since the last pan frame (world px). */
  dy: number;
}

/** The dominant direction axis of a swipe gesture. */
export type SwipeDirection = 'up' | 'down' | 'left' | 'right';

/** Payload for `onSwipe` — a fast directional release exceeding `swipeMinDistance` and `swipeMinVelocity`. */
export interface SwipeEvent extends PointerEventBase {
  /** Dominant axis of the release (`'left'`, `'right'`, `'up'`, or `'down'`). */
  direction: SwipeDirection;
  /** Release velocity in world px / second. */
  velocity: number;
  /** Total distance from pointer-down to pointer-up (world px). */
  distance: number;
  /** Swipe angle in radians — `atan2(dy, dx)`. 0 = right, π/2 = down. */
  angle: number;
}

/** Handler for tap (click / single-touch) events. Return `false` to stop propagation to lower handlers. */
export type TapHandler = (e: TapEvent) => boolean | void;
/** Handler for double-tap events. Return `false` to stop propagation to lower handlers. */
export type DoubleTapHandler = (e: DoubleTapEvent) => boolean | void;
/** Handler for long-press (press-and-hold) events. Return `false` to stop propagation. */
export type LongPressHandler = (e: LongPressEvent) => boolean | void;
/** Handler for pan (drag) events. Return `false` to stop propagation. */
export type PanHandler = (e: PanEvent) => boolean | void;
/** Handler for swipe (fast directional flick) events. Return `false` to stop propagation. */
export type SwipeHandler = (e: SwipeEvent) => boolean | void;
/** Handler for raw pointer-down, pointer-up, or pointer-move events. Return `false` to stop propagation. */
export type PointerHandler = (p: Pointer) => boolean | void;

/** Gesture recognition thresholds. Mutate `PointerTracker.options` at runtime to adjust. */
export interface GestureOptions {
  /** Max ms between pointer-down and pointer-up to count as a tap. Default `250`. */
  tapMaxDuration: number;
  /** Max world-px movement during a tap; more than this is treated as a drag. Default `8`. */
  tapTolerance: number;
  /** Max ms between two taps to count as a double-tap. Default `300`. */
  doubleTapDelay: number;
  /** Max world-px between the two tap positions for a double-tap. Default `16`. */
  doubleTapDistance: number;
  /** Ms a stationary pointer must be held before a long-press fires. Default `600`. */
  longPressDelay: number;
  /** Max world-px movement during a long-press hold before it is cancelled. Default `8`. */
  longPressTolerance: number;
  /** Min world-px traveled between pointer-down and pointer-up for a swipe to register. Default `20`. */
  swipeMinDistance: number;
  /** Min velocity in world-px / s at release for a swipe to register. Default `300`. */
  swipeMinVelocity: number;
  /** Min world-px movement during a hold before pan events start firing. Default `4`. */
  panThreshold: number;
}

const DEFAULT_OPTIONS: GestureOptions = {
  tapMaxDuration: 250,
  tapTolerance: 8,
  doubleTapDelay: 300,
  doubleTapDistance: 16,
  longPressDelay: 600,
  longPressTolerance: 8,
  swipeMinDistance: 20,
  swipeMinVelocity: 300,
  panThreshold: 4,
};

/** @internal Per-pointer gesture state accumulated between down and up. */
interface PointerInternal extends Pointer {
  longPressTimer: number | null;
  recentSamples: { x: number; y: number; t: number }[];
  panStarted: boolean;
}

// ─── PointerTracker ────────────────────────────────────────────────────────

/**
 * Tracks mouse and multi-touch pointers and runs gesture recognition on top.
 * Attached lazily to the canvas by `Input.initMouse()`; accessed via `game.input.pointerTracker`
 * or the convenience shims on `Input` / `SceneInput`.
 */
export class PointerTracker {
  /** The canvas that gesture listeners are attached to. */
  private readonly canvas: HTMLCanvasElement | null;

  /**
   * Maps client (CSS-pixel) coordinates to world coordinates. Injected by the Game
   * (Game injects the one screen→world mapping; `input.toWorld()` reads the same one).
   * Defaults to a rect-relative fallback so the tracker still works standalone.
   */
  mapToWorld: (clientX: number, clientY: number) => { x: number; y: number };

  constructor(
    canvas: HTMLCanvasElement | null = null,
    mapToWorld?: (clientX: number, clientY: number) => { x: number; y: number },
  ) {
    this.canvas = canvas;
    this.mapToWorld = mapToWorld ?? ((clientX, clientY) => {
      // Rect-relative fallback: world units = CSS pixels from the canvas top-left.
      const rect = this.canvas?.getBoundingClientRect();
      return { x: clientX - (rect?.left ?? 0), y: clientY - (rect?.top ?? 0) };
    });
  }

  /** Gesture recognition thresholds. Mutate at runtime to change sensitivity. */
  options: GestureOptions = { ...DEFAULT_OPTIONS };

  /** @internal All active pointers keyed by id. */
  private byId: Map<string, PointerInternal> = new Map();

  /** The primary pointer — mouse if tracked, else the first active touch. `null` when nothing is active. */
  primary: Pointer | null = null;

  /**
   * Forget every in-flight pointer (scene transitions): cancels pending
   * long-press timers and drops tracked pointers, so a press that started in
   * the OLD scene can't complete a tap/swipe in the new one. The next real
   * pointer event starts fresh.
   */
  reset(): void {
    for (const p of this.byId.values()) {
      if (p.longPressTimer !== null && typeof window !== 'undefined') window.clearTimeout(p.longPressTimer);
    }
    this.byId.clear();
    this.primary = null;
  }

  /** @internal Previous tap record for double-tap detection. */
  private _lastTap: { x: number; y: number; t: number; id: string } | null = null;

  private tapHandlers: TapHandler[] = [];
  private doubleTapHandlers: DoubleTapHandler[] = [];
  private longPressHandlers: LongPressHandler[] = [];
  private panHandlers: PanHandler[] = [];
  private swipeHandlers: SwipeHandler[] = [];
  private downHandlers: PointerHandler[] = [];
  private upHandlers: PointerHandler[] = [];
  private moveHandlers: PointerHandler[] = [];

  /** @internal `true` once DOM listeners have been attached via `attach()`. */
  private attached: boolean = false;

  /** @internal `true` once `touch-action: none` has been set on the canvas. */
  private touchActionSet: boolean = false;

  // ─── Public listener registration ────────────────────────────────────────

  /**
   * Subscribe to tap events (quick down+up, no drag). Works for mouse clicks and touch taps.
   * @returns An unsubscribe function.
   */
  onTap(handler: TapHandler): () => void { this.tapHandlers.push(handler); return () => removeFrom(this.tapHandlers, handler); }

  /**
   * Subscribe to double-tap events (two taps within `doubleTapDelay` in the same area).
   * @returns An unsubscribe function.
   */
  onDoubleTap(handler: DoubleTapHandler): () => void { this.doubleTapHandlers.push(handler); return () => removeFrom(this.doubleTapHandlers, handler); }

  /**
   * Subscribe to long-press events (pointer held stationary for `longPressDelay` ms without moving).
   * @returns An unsubscribe function.
   */
  onLongPress(handler: LongPressHandler): () => void { this.longPressHandlers.push(handler); return () => removeFrom(this.longPressHandlers, handler); }

  /**
   * Subscribe to pan events — fired continuously while a pressed pointer moves beyond `panThreshold`. Use for drag/scroll interactions.
   * @returns An unsubscribe function.
   */
  onPan(handler: PanHandler): () => void { this.panHandlers.push(handler); return () => removeFrom(this.panHandlers, handler); }

  /**
   * Subscribe to swipe events (fast directional release: left/right/up/down). Use for swipe-to-dismiss or flick gestures.
   * @returns An unsubscribe function.
   */
  onSwipe(handler: SwipeHandler): () => void { this.swipeHandlers.push(handler); return () => removeFrom(this.swipeHandlers, handler); }

  /**
   * Subscribe to raw pointer-down events (mouse button pressed or finger touched the canvas).
   * @returns An unsubscribe function.
   */
  onPointerDown(handler: PointerHandler): () => void { this.downHandlers.push(handler); return () => removeFrom(this.downHandlers, handler); }

  /**
   * Subscribe to raw pointer-up events (mouse button released or finger lifted).
   * @returns An unsubscribe function.
   */
  onPointerUp(handler: PointerHandler): () => void { this.upHandlers.push(handler); return () => removeFrom(this.upHandlers, handler); }

  /**
   * Subscribe to raw pointer-move events (mouse moved or touch dragged). Fires each frame the pointer position changes, including hover (mouse only).
   * @returns An unsubscribe function.
   */
  onPointerMove(handler: PointerHandler): () => void { this.moveHandlers.push(handler); return () => removeFrom(this.moveHandlers, handler); }

  /** All currently active pointers (mouse + every touch finger on screen). */
  get pointers(): Pointer[] {
    const out: Pointer[] = [];
    for (const p of this.byId.values()) out.push(p);
    return out;
  }

  /** `true` if any pointer currently has a button/finger pressed. */
  get isAnyDown(): boolean {
    for (const p of this.byId.values()) if (p.isDown) return true;
    return false;
  }

  // ─── DOM attachment ─────────────────────────────────────────────────────

  /** Attach canvas and window DOM listeners. Idempotent — safe to call multiple times. Called automatically by `Input.initMouse()`. */
  attach(): void {
    if (this.attached) return;
    this.attached = true;
    if (typeof document === 'undefined' || !this.canvas) return;
    const canvas = this.canvas;
    canvas.addEventListener('mousedown', this.onMouseDown, { passive: false });
    if (typeof window !== 'undefined') {
      window.addEventListener('mousemove', this.onMouseMove, { passive: false });
      window.addEventListener('mouseup', this.onMouseUp, { passive: false });
    }
    canvas.addEventListener('touchstart', this.onTouchStart, { passive: false });
    canvas.addEventListener('touchmove', this.onTouchMove, { passive: false });
    canvas.addEventListener('touchend', this.onTouchEnd, { passive: false });
    canvas.addEventListener('touchcancel', this.onTouchEnd, { passive: false });
    if (!this.touchActionSet) {
      canvas.style.touchAction = 'none';
      this.touchActionSet = true;
    }
  }

  /**
   * Remove all canvas and window listeners attached by `attach()`, clear tracked pointers,
   * and restore the canvas `touch-action`. Safe to call when never attached.
   */
  detach(): void {
    if (!this.attached) return;
    this.attached = false;
    this.byId.clear();
    if (typeof document === 'undefined' || !this.canvas) return;
    const canvas = this.canvas;
    canvas.removeEventListener('mousedown', this.onMouseDown);
    if (typeof window !== 'undefined') {
      window.removeEventListener('mousemove', this.onMouseMove);
      window.removeEventListener('mouseup', this.onMouseUp);
    }
    canvas.removeEventListener('touchstart', this.onTouchStart);
    canvas.removeEventListener('touchmove', this.onTouchMove);
    canvas.removeEventListener('touchend', this.onTouchEnd);
    canvas.removeEventListener('touchcancel', this.onTouchEnd);
    if (this.touchActionSet) {
      canvas.style.touchAction = '';
      this.touchActionSet = false;
    }
  }

  // ─── Per-frame housekeeping ──────────────────────────────────────────────

  /** Zero the per-frame `dx`/`dy` on every tracked pointer. Called by `Input.clearPressed()` at end of each game tick. */
  flushFrame(): void {
    for (const p of this.byId.values()) {
      p.dx = 0;
      p.dy = 0;
    }
  }

  // ─── DOM event handlers ─────────────────────────────────────────────────

  private onMouseDown = (event: MouseEvent): void => {
    if (event.button !== 0) return;
    const { x, y } = this.toWorld(event.clientX, event.clientY);
    this.pointerDown('mouse', x, y, false);
  };
  private onMouseUp = (event: MouseEvent): void => {
    if (event.button !== 0) return;
    const { x, y } = this.toWorld(event.clientX, event.clientY);
    this.pointerUp('mouse', x, y);
  };
  private onMouseMove = (event: MouseEvent): void => {
    const { x, y } = this.toWorld(event.clientX, event.clientY);
    const mouse = this.byId.get('mouse');
    if (mouse?.isDown) {
      this.pointerMove('mouse', x, y, false);
    } else if (this.isInsideCanvas(event.clientX, event.clientY)) {
      this.pointerMove('mouse', x, y, false);
    } else if (mouse) {
      const oldX = mouse.x, oldY = mouse.y;
      mouse.x = x; mouse.y = y;
      mouse.dx = x - oldX;
      mouse.dy = y - oldY;
      this.fire(this.moveHandlers, mouse);
    }
  };

  private isInsideCanvas(clientX: number, clientY: number): boolean {
    const rect = this.canvas!.getBoundingClientRect();
    return clientX >= rect.left && clientX <= rect.right
        && clientY >= rect.top && clientY <= rect.bottom;
  }

  private onTouchStart = (event: TouchEvent): void => {
    event.preventDefault();
    for (const t of Array.from(event.changedTouches)) {
      const { x, y } = this.toWorld(t.clientX, t.clientY);
      this.pointerDown(String(t.identifier), x, y, true);
    }
  };
  private onTouchMove = (event: TouchEvent): void => {
    event.preventDefault();
    for (const t of Array.from(event.changedTouches)) {
      const { x, y } = this.toWorld(t.clientX, t.clientY);
      this.pointerMove(String(t.identifier), x, y, true);
    }
  };
  private onTouchEnd = (event: TouchEvent): void => {
    event.preventDefault();
    for (const t of Array.from(event.changedTouches)) {
      const { x, y } = this.toWorld(t.clientX, t.clientY);
      this.pointerUp(String(t.identifier), x, y);
    }
  };

  // ─── World-coordinate translation ────────────────────────────────────────

  private toWorld(clientX: number, clientY: number): Vec2 {
    // v2: raster's canvas-rect + object-fit + Texture.scale mapping not ported —
    // the Game injects its view mapping via `mapToWorld` (`input.toWorld` reads it too),
    // so CSS and input can never disagree about the world rect.
    return this.mapToWorld(clientX, clientY);
  }

  // ─── Pointer state transitions ───────────────────────────────────────────

  /**
   * Inject a synthetic pointer-down event. Used internally by DOM handlers and externally for
   * headless tests or programmatic gesture replay.
   * @param id Pointer id (`'mouse'` or a touch identifier string).
   * @param x World x-coordinate.
   * @param y World y-coordinate.
   * @param isTouch `true` for touch events, `false` for mouse.
   */
  pointerDown(id: string, x: number, y: number, isTouch: boolean = false): void {
    const now = performance.now();
    let p = this.byId.get(id);
    if (!p) {
      p = {
        id, x, y, startX: x, startY: y, dx: 0, dy: 0,
        vx: 0, vy: 0,
        isDown: true, downTime: now, isTouch,
        longPressTimer: null,
        recentSamples: [],
        panStarted: false,
      };
      this.byId.set(id, p);
    } else {
      p.x = x; p.y = y;
      p.startX = x; p.startY = y;
      p.dx = 0; p.dy = 0;
      p.vx = 0; p.vy = 0;
      p.isDown = true;
      p.downTime = now;
      p.isTouch = isTouch;
      p.recentSamples.length = 0;
      p.panStarted = false;
    }
    p.recentSamples.push({ x, y, t: now });

    if (typeof window !== 'undefined') {
      p.longPressTimer = window.setTimeout(() => {
        if (!p) return;
        p.longPressTimer = null;
        if (!p.isDown) return;
        const distSq = (p.x - p.startX) ** 2 + (p.y - p.startY) ** 2;
        if (distSq > this.options.longPressTolerance ** 2) return;
        this.fire(this.longPressHandlers, {
          pointer: p, x: p.x, y: p.y,
          duration: performance.now() - p.downTime,
        });
      }, this.options.longPressDelay);
    }

    this.recomputePrimary();
    this.fire(this.downHandlers, p);
  }

  /**
   * Inject a synthetic pointer-move event. Hover-only moves for `'mouse'` (no button pressed)
   * create a hovering pointer so `onPointerMove` fires even before a click. Touch ids without
   * a prior `pointerDown` are ignored.
   * @param id Pointer id.
   * @param x World x-coordinate.
   * @param y World y-coordinate.
   * @param isTouch `true` for touch events.
   */
  pointerMove(id: string, x: number, y: number, isTouch: boolean = false): void {
    let p = this.byId.get(id);
    if (!p) {
      if (isTouch) return;
      p = {
        id, x, y, startX: x, startY: y, dx: 0, dy: 0,
        vx: 0, vy: 0,
        isDown: false, downTime: 0, isTouch: false,
        longPressTimer: null,
        recentSamples: [],
        panStarted: false,
      };
      this.byId.set(id, p);
    }
    const oldX = p.x, oldY = p.y;
    p.x = x; p.y = y;
    p.dx = x - oldX;
    p.dy = y - oldY;
    if (p.isDown) {
      const now = performance.now();
      p.recentSamples.push({ x, y, t: now });
      while (p.recentSamples.length > 1 && now - p.recentSamples[0].t > 80) {
        p.recentSamples.shift();
      }
      if (p.recentSamples.length >= 2) {
        const first = p.recentSamples[0];
        const last = p.recentSamples[p.recentSamples.length - 1];
        const dt = (last.t - first.t) / 1000;
        if (dt > 0) {
          p.vx = (last.x - first.x) / dt;
          p.vy = (last.y - first.y) / dt;
        }
      }
      const totalDx = x - p.startX;
      const totalDy = y - p.startY;
      if (!p.panStarted && totalDx * totalDx + totalDy * totalDy >= this.options.panThreshold ** 2) {
        p.panStarted = true;
      }
      if (p.panStarted) {
        if (p.longPressTimer !== null) {
          if (typeof window !== 'undefined') window.clearTimeout(p.longPressTimer);
          p.longPressTimer = null;
        }
        this.fire(this.panHandlers, {
          pointer: p, x, y,
          totalDx, totalDy,
          dx: p.dx, dy: p.dy,
        });
      }
    }
    this.recomputePrimary();
    this.fire(this.moveHandlers, p);
  }

  /**
   * Inject a synthetic pointer-up event. Triggers tap / double-tap / swipe detection,
   * then fires the raw pointer-up handlers. Used internally by DOM handlers and for
   * headless tests.
   * @param id Pointer id.
   * @param x World x-coordinate at release.
   * @param y World y-coordinate at release.
   */
  pointerUp(id: string, x: number, y: number): void {
    const p = this.byId.get(id);
    if (!p) return;
    if (!p.isDown) return;
    const now = performance.now();
    p.x = x; p.y = y;
    p.isDown = false;
    if (p.longPressTimer !== null) {
      if (typeof window !== 'undefined') window.clearTimeout(p.longPressTimer);
      p.longPressTimer = null;
    }
    const duration = now - p.downTime;
    const dx = x - p.startX;
    const dy = y - p.startY;
    const distance = Math.sqrt(dx * dx + dy * dy);

    const samples = p.recentSamples;
    while (samples.length > 0 && now - samples[0].t > 80) samples.shift();
    if (samples.length >= 2) {
      const first = samples[0];
      const last = samples[samples.length - 1];
      const dt = (last.t - first.t) / 1000;
      if (dt > 0) {
        p.vx = (last.x - first.x) / dt;
        p.vy = (last.y - first.y) / dt;
      } else {
        p.vx = 0; p.vy = 0;
      }
    } else {
      p.vx = 0; p.vy = 0;
    }

    if (duration <= this.options.tapMaxDuration && distance <= this.options.tapTolerance) {
      if (this._lastTap && now - this._lastTap.t <= this.options.doubleTapDelay) {
        const ddx = x - this._lastTap.x;
        const ddy = y - this._lastTap.y;
        if (ddx * ddx + ddy * ddy <= this.options.doubleTapDistance * this.options.doubleTapDistance) {
          this.fire(this.doubleTapHandlers, {
            pointer: p, x, y,
            interval: now - this._lastTap.t,
          });
          this._lastTap = null;
        }
      }
      this.fire(this.tapHandlers, { pointer: p, x, y, duration });
      this._lastTap = { x, y, t: now, id };
    } else {
      const velocity = Math.sqrt(p.vx * p.vx + p.vy * p.vy);
      if (distance >= this.options.swipeMinDistance && velocity >= this.options.swipeMinVelocity) {
        const direction: SwipeDirection = Math.abs(dx) > Math.abs(dy)
          ? (dx > 0 ? 'right' : 'left')
          : (dy > 0 ? 'down' : 'up');
        this.fire(this.swipeHandlers, {
          pointer: p, x, y,
          direction, velocity, distance,
          angle: Math.atan2(dy, dx),
        });
      }
    }

    this.fire(this.upHandlers, p);

    if (p.isTouch) {
      this.byId.delete(id);
    }
    this.recomputePrimary();
  }

  private recomputePrimary(): void {
    const mouse = this.byId.get('mouse');
    if (mouse) { this.primary = mouse; return; }
    for (const p of this.byId.values()) {
      if (p.isDown) { this.primary = p; return; }
    }
    this.primary = null;
  }

  private fire<T>(handlers: ((e: T) => boolean | void)[], event: T): void {
    const snapshot = handlers.slice();
    for (const h of snapshot) {
      if (h(event) === false) return;
    }
  }
}

function removeFrom<T>(arr: T[], item: T): void {
  const i = arr.indexOf(item);
  if (i >= 0) arr.splice(i, 1);
}

// ─── Sprite hit-testing ──────────────────────────────────────────────────────

/**
 * Returns `true` if world point `(px, py)` is inside the visible rectangle of a sprite.
 * Used by the gesture dispatch in `SceneInput` to determine which sprite captured a pointer.
 * v2: raster's scale/angle/pivot/`shape: 'circle'`/animation-sheet sizing not ported yet —
 * v2 sprites are plain AABBs (top-left `x`/`y` + `w`/`h` in world units).
 */
export function spriteContainsPoint(
  sprite: { x: number; y: number; w: number; h: number },
  px: number, py: number,
): boolean {
  return px >= sprite.x && px < sprite.x + sprite.w
      && py >= sprite.y && py < sprite.y + sprite.h;
}
