// Per-OBJECT sprite effects — the v2 successor to the raster engine's
// Sprite.fx palette. A STACKING BAG of modifiers on one sprite:
//
//   sprite.fx = { glow: { color: '#ffd147' }, flash: { duration: 0.25 } };
//
// Shader effects (this batch): glow (multi-ring gaussian halo), outline,
// blur, flash/tint (colour over the pixels), pixelate, wobble, glitch,
// dissolve (smooth organic noise), reveal (circular clip).
// Transform effects (CPU, applied in Draw): shake, squash — they ride the
// NORMAL batches, zero shader cost.
// Raster-parity gaps (deliberate, for later): afterImage (needs a trail
// stamp store), dissolve patterns beyond scatter.
//
// Mutual exclusion mirrors raster: ONE uv-distortion (pixelate > glitch >
// wobble) and ONE alpha gate (reveal > dissolve) apply; glow/outline share
// the halo slot (first wins); flash/tint share the colour-mod slot.
//
// Fx sprites render through this dedicated batch so the hot sprite path pays
// nothing. All taps/samples run unconditionally (uniform control flow); the
// mode selects are pure math.

import { BITS } from './gpu.js';
import { DEPTH_FORMAT, Z_RANGE, SRC_FX, type DrawOrder } from './batch.js';
import { rgba } from './color.js';
import type { Frame } from './atlas.js';

const FLOATS = 48; // 12 vec4s per instance — see Inst in the WGSL

export interface SpriteFx {
  /** Soft additive halo emanating from the body. */
  glow?: { color?: string; size?: number };
  /** Solid rim around the body (selection look). */
  outline?: { color?: string; size?: number };
  /** Gaussian-ish blur of the sprite itself. */
  blur?: { size?: number };
  /** Colour over the pixels; with `duration` it decays + auto-clears (hit feedback). */
  flash?: { color?: string; amount?: number; duration?: number; /** @internal */ _left?: number };
  /** Persistent colour overlay (status looks) — one colour, or a 4-corner GRADIENT
   * across the sprite: colors = [topLeft, topRight, bottomLeft, bottomRight]. */
  tint?: { color?: string; colors?: [string, string, string, string]; amount?: number };
  /** Chunky-pixel downsample of this sprite only. */
  pixelate?: { size?: number };
  /** Horizontal band ripple (hologram). */
  wobble?: { size?: number; speed?: number };
  /** Slice offsets + RGB split. */
  glitch?: { amount?: number; speed?: number };
  /** Organic noise dissolve: t 0 (whole) → 1 (gone), burning edge. */
  dissolve?: { t: number; seed?: number; color?: string };
  /** Expanding circular clip: t 0 (hidden) → 1 (shown); invert flips. */
  reveal?: { t: number; invert?: boolean };
  /** Random draw-offset jitter; with `duration` it decays + auto-clears. CPU — rides the normal batches. */
  shake?: { amount: number; duration?: number; /** @internal */ _left?: number };
  /** Squash-and-stretch oscillation (Hz); `cycles` makes it a one-shot pop. CPU. */
  squash?: { amount?: number; speed?: number; cycles?: number; /** @internal */ _t?: number };
}

/** True when the bag needs the fx shader (glow is the GlowPass's job; shake/squash are CPU transforms). */
export function fxNeedsShader(fx: SpriteFx): boolean {
  return !!(fx.outline || fx.blur || fx.flash || fx.tint ||
    fx.pixelate || fx.wobble || fx.glitch || fx.dissolve || fx.reveal);
}

// Flag bits (shader-side decode; bit 1 was glow, now owned by GlowPass).
const F_OUTLINE = 2, F_BLUR = 4, F_PIXELATE = 8, F_WOBBLE = 16,
  F_GLITCH = 32, F_DISSOLVE = 64, F_REVEAL = 128;

const WGSL = /* wgsl */ `
struct U { view: vec4f }
struct Inst {
  posSize: vec4f,
  misc: vec4f,        // rot, flags, z, time
  base: vec4f,        // sprite tint * alpha
  uv: vec4f,          // expanded rect (flip pre-applied)
  clampR: vec4f,      // the frame's true rect (normalized)
  halo: vec4f,        // glow/outline colour
  p1: vec4f,          // spreadU, spreadV, dissolveT, revealT (sign = invert)
  p2: vec4f,          // pixelCells, wobble(uv), glitch, seed
  // flash/tint corner colours (a = amount) — equal for a flat colour,
  // distinct for a bilinear GRADIENT tint across the sprite.
  cmodTL: vec4f,
  cmodTR: vec4f,
  cmodBL: vec4f,
  cmodBR: vec4f,
}
struct VSOut {
  @builtin(position) pos: vec4f,
  @location(0) uv: vec2f,
  @location(1) base: vec4f,
  @location(2) halo: vec4f,
  @location(3) cmod: vec4f,
  @location(4) clampR: vec4f,
  @location(5) p1: vec4f,
  @location(6) p2: vec4f,
  @location(7) ft: vec2f,     // flags, time
}

@group(0) @binding(0) var<uniform> u: U;
@group(0) @binding(1) var<storage, read> inst: array<Inst>;
@group(0) @binding(2) var samp: sampler;
@group(0) @binding(3) var tex: texture_2d<f32>;

@vertex
fn vs(@builtin(vertex_index) vi: u32, @builtin(instance_index) ii: u32) -> VSOut {
  let d = inst[ii];
  let c01 = vec2f(f32(vi & 1u), f32(vi >> 1u));
  let centre = d.posSize.xy + d.posSize.zw * 0.5;
  let off = (c01 - 0.5) * d.posSize.zw;
  let sn = sin(d.misc.x);
  let cn = cos(d.misc.x);
  let world = centre + vec2f(off.x * cn - off.y * sn, off.x * sn + off.y * cn);
  let ndc = (world - u.view.xy) / u.view.zw * 2.0 - 1.0;
  var out: VSOut;
  out.pos = vec4f(ndc.x, -ndc.y, 1.0 - d.misc.z, 1.0);
  out.uv = vec2f(mix(d.uv.x, d.uv.z, c01.x), mix(d.uv.y, d.uv.w, c01.y));
  out.base = d.base;
  out.halo = d.halo;
  // Corner colour at this vertex → bilinear gradient across the quad.
  out.cmod = mix(mix(d.cmodTL, d.cmodTR, c01.x), mix(d.cmodBL, d.cmodBR, c01.x), c01.y);
  out.clampR = d.clampR;
  out.p1 = d.p1;
  out.p2 = d.p2;
  out.ft = vec2f(d.misc.y, d.misc.w);
  return out;
}

fn inRect(p: vec2f, r: vec4f) -> f32 {
  return step(r.x, p.x) * step(p.x, r.z) * step(r.y, p.y) * step(p.y, r.w);
}
fn smpl(p: vec2f, r: vec4f) -> vec4f {
  return textureSample(tex, samp, clamp(p, r.xy, r.zw)) * inRect(p, r);
}
fn hash(p: vec2f) -> f32 {
  return fract(sin(dot(p, vec2f(127.1, 311.7))) * 43758.5453);
}
// Smooth 2-octave value noise — organic dissolve boundaries, no square cells.
fn vnoise(p: vec2f) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let w = f * f * (3.0 - 2.0 * f);
  let n = mix(
    mix(hash(i), hash(i + vec2f(1.0, 0.0)), w.x),
    mix(hash(i + vec2f(0.0, 1.0)), hash(i + vec2f(1.0, 1.0)), w.x), w.y);
  return n;
}

// 32 halo taps: 4 gaussian-weighted rings — and the whole pattern rotates by
// a per-PIXEL random angle, which turns sparse-ring ghosting into fine noise.
// That is what makes glow read as a true blurred silhouette (Photoshop-style
// outer glow) instead of overlapping circle copies.
const RING_R = array<f32, 4>(0.25, 0.5, 0.75, 1.0);
const RING_W = array<f32, 4>(1.0, 0.78, 0.5, 0.26);

@fragment
fn fs(in: VSOut) -> @location(0) vec4f {
  let flags = u32(in.ft.x + 0.5);
  let time = in.ft.y;
  let r = in.clampR;
  let rs = max(r.zw - r.xy, vec2f(0.0001));
  var uv = in.uv;
  var local = (uv - r.xy) / rs;

  // ── ONE uv distortion (pixelate > glitch > wobble) ─────────────────────────
  if ((flags & 8u) != 0u) {              // pixelate: snap to a cell grid
    let cells = max(2.0, in.p2.x);
    local = (floor(local * cells) + 0.5) / cells;
    uv = r.xy + local * rs;
  } else if ((flags & 32u) != 0u) {      // glitch: band jumps
    let band = floor(local.y * 12.0);
    let tick = floor(time * 14.0);
    let go = step(0.55, hash(vec2f(band * 3.1, tick + in.p2.w)));
    let jump = (hash(vec2f(band, tick)) - 0.5) * in.p2.z * go;
    uv = vec2f(uv.x + jump * rs.x, uv.y);
  } else if ((flags & 16u) != 0u) {      // wobble: sine band ripple
    uv = vec2f(uv.x + sin(local.y * 14.0 + time * 6.2831 * 1.4) * in.p2.y, uv.y);
  }

  // ── Sample (glitch splits RGB; split = 0 otherwise) ────────────────────────
  let split = select(0.0, in.p2.z * rs.x * 0.35, (flags & 32u) != 0u);
  let cR = smpl(uv + vec2f(split, 0.0), r);
  let cC = smpl(uv, r);
  let cB = smpl(uv - vec2f(split, 0.0), r);
  var body = vec4f(cR.r, cC.g, cB.b, max(cC.a, max(cR.a, cB.a) * step(0.001, split)));

  // ── Halo taps (outline / blur share one jittered ring set) ─────────────────
  var near = 0.0;
  var blurAcc = body * 1.6;
  var wSum = 1.6;
  let jit = hash(floor(in.pos.xy)) * 0.7854;    // per-pixel ring rotation
  for (var ring = 0u; ring < 4u; ring++) {
    let rr = RING_R[ring];
    let rw = RING_W[ring];
    for (var k = 0u; k < 8u; k++) {
      let ang = (f32(k) + f32(ring) * 0.4) * 0.7854 + jit;
      let o = vec2f(cos(ang), sin(ang)) * rr * in.p1.xy;
      let s = smpl(uv + o, r);
      near = max(near, s.a * step(0.7, rr));    // outline reads the outer ring
      blurAcc += s * rw;
      wSum += rw;
    }
  }

  if ((flags & 4u) != 0u) { body = blurAcc / wSum; }  // blur

  var a = body.a * in.base.a;
  var rgb = body.rgb * in.base.rgb;

  // ── ONE alpha gate (reveal > dissolve) ─────────────────────────────────────
  var edge = 0.0;
  if ((flags & 128u) != 0u) {            // reveal: circular clip
    let t = abs(in.p1.w);
    let dist = length((local - 0.5) * vec2f(rs.x / rs.y, 1.0) * vec2f(1.0, 1.0)) * 1.15;
    var vis = 1.0 - smoothstep(t - 0.03, t, dist / 0.85);
    if (in.p1.w < 0.0) { vis = 1.0 - vis; }
    a = a * vis;
  } else if ((flags & 64u) != 0u) {      // dissolve: smooth organic noise
    let t = in.p1.z * 1.12;              // overshoot so t=1 is fully gone
    let seed = vec2f(in.p2.w * 13.7, in.p2.w * 7.3);
    let n = 0.65 * vnoise(local * 5.0 + seed) + 0.35 * vnoise(local * 11.0 + seed * 1.7);
    let keep = smoothstep(t - 0.04, t + 0.04, n);
    edge = keep * (1.0 - smoothstep(t, t + 0.16, n));
    a = a * keep;
  }

  // ── Colour-over (flash / tint) ─────────────────────────────────────────────
  rgb = mix(rgb, in.cmod.rgb, in.cmod.a);

  // ── Compose: body over halo (glow lives in the GlowPass, not here) ─────────
  var outC = vec4f(rgb * a, a);
  if ((flags & 2u) != 0u) {              // outline: rim fills smoothly under the AA edge
    let rim = step(0.3, near) * (1.0 - body.a) * in.halo.a;
    outC = vec4f(outC.rgb + in.halo.rgb * rim, outC.a + rim);
  }
  // dissolve's burning edge rides the halo slot's colour
  outC = vec4f(outC.rgb + in.halo.rgb * edge * body.a, outC.a);
  return outC;
}
`;

const OUTLINE_DEFAULT = '#ffffff';
const DISSOLVE_DEFAULT = '#ff9a3d';

/** The dedicated per-object-fx batch (see file header). API mirrors QuadBatch. */
export class FxBatch {
  /** The surface's submission-order log — see batch.ts's DrawOrder. */
  private order: DrawOrder | null = null;
  private layer = 0;
  private uploaded = false;

  /** @internal Take part in a surface's submission order. */
  joinOrder(order: DrawOrder): void { this.order = order; }
  /** @see QuadBatch.setLayer */
  setLayer(n: number): void { this.layer = n; }
  private data: Float32Array<ArrayBuffer>;
  private count = 0;
  private capacity: number;
  private uniformData = new Float32Array(4);
  private filter: GPUFilterMode;

  private device!: GPUDevice;
  private pipeline!: GPURenderPipeline;
  private layout!: GPUBindGroupLayout;
  private sampler!: GPUSampler;
  private uniforms!: GPUBuffer;
  private instances!: GPUBuffer;
  private textureView: GPUTextureView | null = null;
  private bind: GPUBindGroup | null = null;

  constructor(device: GPUDevice, private format: GPUTextureFormat, opts: { filter?: GPUFilterMode; capacity?: number } = {}) {
    this.capacity = opts.capacity ?? 2048;
    this.filter = opts.filter ?? 'linear';
    this.data = new Float32Array(this.capacity * FLOATS);
    this.rebuild(device);
  }

  rebuild(device: GPUDevice): void {
    this.device = device;
    this.layout = device.createBindGroupLayout({
      entries: [
        { binding: 0, visibility: BITS.STAGE_VERTEX, buffer: { type: 'uniform' } },
        { binding: 1, visibility: BITS.STAGE_VERTEX, buffer: { type: 'read-only-storage' } },
        { binding: 2, visibility: BITS.STAGE_FRAGMENT, sampler: {} },
        { binding: 3, visibility: BITS.STAGE_FRAGMENT, texture: {} },
      ],
    });
    const module = device.createShaderModule({ code: WGSL });
    void module.getCompilationInfo().then((info) => {
      for (const m of info.messages) {
        if (m.type === 'error') console.error(`FxBatch WGSL ${m.lineNum}:${m.linePos} ${m.message}`);
      }
    });
    this.pipeline = device.createRenderPipeline({
      layout: device.createPipelineLayout({ bindGroupLayouts: [this.layout] }),
      vertex: { module, entryPoint: 'vs' },
      fragment: {
        module,
        entryPoint: 'fs',
        targets: [{
          format: this.format,
          blend: {
            color: { srcFactor: 'one', dstFactor: 'one-minus-src-alpha' },
            alpha: { srcFactor: 'one', dstFactor: 'one-minus-src-alpha' },
          },
        }],
      },
      depthStencil: { format: DEPTH_FORMAT, depthWriteEnabled: false, depthCompare: 'less-equal' },
      primitive: { topology: 'triangle-strip' },
    });
    this.sampler = device.createSampler({ magFilter: this.filter, minFilter: this.filter });
    this.uniforms = device.createBuffer({ size: 16, usage: BITS.UNIFORM | BITS.COPY_DST });
    this.instances = device.createBuffer({ size: this.capacity * FLOATS * 4, usage: BITS.STORAGE | BITS.COPY_DST });
    this.bind = null;
    this.textureView = null;
  }

  setTexture(view: GPUTextureView): void {
    this.textureView = view;
    this.makeBind();
  }

  private makeBind(): void {
    if (!this.textureView) return;
    this.bind = this.device.createBindGroup({
      layout: this.layout,
      entries: [
        { binding: 0, resource: { buffer: this.uniforms } },
        { binding: 1, resource: { buffer: this.instances } },
        { binding: 2, resource: this.sampler },
        { binding: 3, resource: this.textureView },
      ],
    });
  }

  begin(x: number, y: number, w: number, h: number): void {
    this.count = 0;
    this.layer = 0;
    this.uploaded = false;
    this.uniformData.set([x, y, w, h]);
  }

  /** Queue one fx sprite (margin expansion + uv extrapolation done here). */
  push(
    x: number, y: number, w: number, h: number, f: Frame,
    rot: number, flipX: boolean, z: number, fx: SpriteFx, time: number,
    tr: number, tg: number, tb: number, ta: number,
  ): void {
    this.order?.put(SRC_FX, this.count, this.layer);
    if (this.count === this.capacity) this.grow();
    let flags = 0;
    let margin = 0;
    let halo: readonly [number, number, number, number] = [0, 0, 0, 0];
    if (fx.outline) {
      flags |= F_OUTLINE;
      margin = Math.max(margin, fx.outline.size ?? 2);
      halo = rgba(fx.outline.color ?? OUTLINE_DEFAULT);
    }
    if (fx.blur) {
      flags |= F_BLUR;
      margin = Math.max(margin, fx.blur.size ?? 4);
    }
    if (fx.pixelate) flags |= F_PIXELATE;
    else if (fx.glitch) flags |= F_GLITCH;
    else if (fx.wobble) flags |= F_WOBBLE;
    let dissolveT = 0, revealT = 0, seed = 0;
    if (fx.reveal) {
      flags |= F_REVEAL;
      revealT = Math.max(0.0001, Math.min(1, fx.reveal.t)) * (fx.reveal.invert ? -1 : 1);
    } else if (fx.dissolve) {
      flags |= F_DISSOLVE;
      dissolveT = Math.max(0, Math.min(1, fx.dissolve.t));
      seed = fx.dissolve.seed ?? 0;
      if (!fx.outline) halo = rgba(fx.dissolve.color ?? DISSOLVE_DEFAULT);
    }
    // flash/tint → 4 corner colours (equal = flat; distinct = gradient tint).
    const corners = new Float32Array(16);
    if (fx.flash || fx.tint) {
      let amount = (fx.flash ? fx.flash.amount ?? 1 : fx.tint!.amount ?? 0.4);
      const fl = fx.flash;
      if (fl?.duration && fl._left !== undefined) amount *= Math.max(0, fl._left / fl.duration);
      amount = Math.min(1, Math.max(0, amount));
      const cs = fx.flash ? undefined : fx.tint!.colors;
      const single = rgba((fx.flash?.color ?? fx.tint?.color) ?? '#ffffff');
      for (let i = 0; i < 4; i++) {
        const c = cs ? rgba(cs[i]) : single;
        corners[i * 4] = c[0]; corners[i * 4 + 1] = c[1]; corners[i * 4 + 2] = c[2];
        corners[i * 4 + 3] = amount * c[3];
      }
    }

    // Margin expansion + uv extrapolation (halo taps reach outside the frame).
    const spreadU = (f.u1 - f.u0) * (margin / Math.max(1, w));
    const spreadV = (f.v1 - f.v0) * (margin / Math.max(1, h));
    let u0 = f.u0 - spreadU, u1 = f.u1 + spreadU;
    if (flipX) { const t = u0; u0 = u1; u1 = t; }

    const o = this.count * FLOATS;
    const d = this.data;
    d[o] = x - margin; d[o + 1] = y - margin; d[o + 2] = w + margin * 2; d[o + 3] = h + margin * 2;
    d[o + 4] = rot; d[o + 5] = flags; d[o + 6] = z / Z_RANGE; d[o + 7] = time;
    d[o + 8] = tr; d[o + 9] = tg; d[o + 10] = tb; d[o + 11] = ta;
    d[o + 12] = u0; d[o + 13] = f.v0 - spreadV; d[o + 14] = u1; d[o + 15] = f.v1 + spreadV;
    d[o + 16] = f.u0; d[o + 17] = f.v0; d[o + 18] = f.u1; d[o + 19] = f.v1;
    d[o + 20] = halo[0]; d[o + 21] = halo[1]; d[o + 22] = halo[2]; d[o + 23] = halo[3];
    d[o + 24] = spreadU || (f.u1 - f.u0) * 0.05; d[o + 25] = spreadV || (f.v1 - f.v0) * 0.05;
    d[o + 26] = dissolveT; d[o + 27] = revealT;
    d[o + 28] = fx.pixelate ? Math.max(2, w / Math.max(1, fx.pixelate.size ?? 4)) : 0;
    d[o + 29] = fx.wobble ? ((f.u1 - f.u0) * ((fx.wobble.size ?? 3) / Math.max(1, w))) : 0;
    d[o + 30] = fx.glitch ? ((fx.glitch.amount ?? 6) / Math.max(1, w)) : 0;
    d[o + 31] = seed;
    d.set(corners, o + 32); // cmodTL/TR/BL/BR
    this.count++;
  }

  private grow(): void {
    this.capacity *= 2;
    const next = new Float32Array(this.capacity * FLOATS);
    next.set(this.data);
    this.data = next;
    this.instances.destroy();
    this.instances = this.device.createBuffer({ size: this.capacity * FLOATS * 4, usage: BITS.STORAGE | BITS.COPY_DST });
    this.makeBind();
  }

  private upload(): boolean {
    if (this.count === 0 || !this.bind) return false;
    if (!this.uploaded) {
      this.device.queue.writeBuffer(this.uniforms, 0, this.uniformData);
      this.device.queue.writeBuffer(this.instances, 0, this.data.buffer, 0, this.count * FLOATS * 4);
      this.uploaded = true;
    }
    return true;
  }

  /** @internal Draw ONE contiguous span — the submission-order walk's unit. */
  drawRange(pass: GPURenderPassEncoder, first: number, n: number): void {
    if (n <= 0 || !this.upload()) return;
    pass.setPipeline(this.pipeline);
    pass.setBindGroup(0, this.bind!);
    pass.draw(4, n, 0, first);
  }

  flush(pass: GPURenderPassEncoder): number {
    if (!this.upload()) return 0;
    pass.setPipeline(this.pipeline);
    pass.setBindGroup(0, this.bind!);
    pass.draw(4, this.count);
    return this.count;
  }
}
