// GRID sprites — the §8.6 deformable layer. A sprite is ONE quad by default
// (QuadBatch, the hot path); pass `deform` and it renders here instead: a
// 24×24-cell subdivided quad whose vertices are displaced ENTIRELY in the
// vertex shader — zero CPU vertex writes, one instanced draw for all grid
// sprites. Prior art: Pixi MeshPlane/PerspectiveMesh; the deformers are
// data (kind + amount/speed/phase), not code.
//
// Deformers:
//   wave  — cloth/flag ripple; anchored LEFT edge, amplitude grows to the
//           right. amount = world units of ripple.
//   sway  — pendulum bend; anchored BOTTOM edge, the top swings.
//           amount = world units of top displacement.
//   flip  — card flip about the vertical centre axis with fake perspective.
//           speed = turns/sec; phase = start angle (rad). Past 90° the face
//           renders MIRRORED — swap to a back frame when facing() < 0 for a
//           real two-sided card.
//   jelly — squash/stretch wobble, volume-preserving, anchored at the
//           bottom. amount = fraction (0.15 = ±15%).
//
// wave/sway/jelly animate from the frame clock via `speed` (cycles/sec);
// set speed 0 and drive `phase` yourself for manual control.

import { BITS } from './gpu.js';
import { Z_RANGE, DEPTH_FORMAT, SRC_GRID, type DrawOrder } from './batch.js';
import type { Frame } from './atlas.js';

/** Vertex-stage deformation for one sprite (routes it to the grid batch). */
export interface Deform {
  /** Built-in kind, or the name of a registered custom DeformDef. */
  kind: 'wave' | 'sway' | 'flip' | 'jelly' | (string & {});
  /** Strength — world units (wave/sway) or fraction (jelly). Unused by flip. */
  amount?: number;
  /** Animation rate in cycles (flip: turns) per second. 0 = drive phase yourself. */
  speed?: number;
  /** Phase offset in radians (also the manual control when speed is 0). */
  phase?: number;
}

/**
 * A CUSTOM deformer as pure DATA — the same delivery shape as post-effect
 * EffectDefs (the MCP-block path): register with game.assets.deformer(def), then
 * use it by name: `deform: { kind: def.name }`. The `code` snippet runs in
 * the VERTEX stage with these in scope:
 *   p      vec2f  centred vertex position in WORLD units — mutate this
 *   shade  f32    brightness multiplier (1 = lit) — mutate for fake light
 *   uvn    vec2f  0..1 position across the sprite
 *   size   vec2f  sprite size in world units
 *   amount f32    Deform.amount
 *   t      f32    phase + speed*time*2pi (the animation clock)
 *   TAU    const  2pi
 *   d.uv   vec4f  the frame's atlas rect — with `tex`/`samp` you may
 *          textureSampleLevel(tex, samp, uv, 0.0) IN THE VERTEX STAGE
 *          (drive twists/wind from the sprite's own texture).
 * The optional `fragment` snippet runs per-pixel AFTER the base sample with:
 *   color  vec4f  straight-alpha output (base: tex × tint × shade) — mutate
 *   tint   vec4f  the instance color
 *   uvn    vec2f  0..1 across the sprite · uvRect vec4f the atlas rect
 *   t / amount / shade  as above; tex/samp via textureSampleLevel
 * Wrap-scroll inside the frame with: uvRect.xy + fract(uv) * (uvRect.zw -
 * uvRect.xy) — on a TILEABLE noise frame the wrap is seamless.
 * Agents request deformers by name and never write WGSL — snippets arrive
 * as data, like effect blocks.
 */
export interface DeformDef {
  name: string;
  /** The WGSL vertex-stage snippet (the WebGPU renderer's dialect). */
  code: string;
  /** Optional WGSL fragment-stage snippet. */
  fragment?: string;
  /** Optional GLSL ES 3.0 twin of `code` — same variable scope (`p`, `shade`,
   * `uvn`, `size`, `amount`, `t`, `TAU`), spliced by the WebGL fallback. A def
   * without one renders UNDEFORMED there (with a one-shot console warn), so
   * ship both dialects for anything that must degrade gracefully. */
  glsl?: string;
}

const BUILTIN_ID: Record<string, number> = { wave: 1, sway: 2, flip: 3, jelly: 4 };
const CUSTOM_BASE = 16;

/** The flip deformer's facing for frame-swapping: > 0 front, < 0 back (mirrored). */
export function facing(d: Deform, time: number): number {
  return Math.cos((d.phase ?? 0) + (d.speed ?? 0) * time * Math.PI * 2);
}

const SEGS = 24;
const VERTS = SEGS * SEGS * 6;
const FLOATS = 20; // posSize(4) rot/kind/flip/z(4) rgba(4) uvRect(4) deform(4)

/** Pure WGSL assembly (headless-testable): built-in kinds + spliced customs. */
export function buildGridWGSL(blocky: boolean, customs: ReadonlyArray<{ id: number; def: DeformDef }> = []): string {
  const custom = customs
    .map(({ id, def }) => ` else if (kind == ${id}u) {\n${def.code}\n  }`)
    .join('');
  const customFs = customs
    .filter(({ def }) => def.fragment)
    .map(({ id, def }) => `  if (kind == ${id}u) {\n${def.fragment}\n  }`)
    .join('\n');
  return /* wgsl */ `
const BLOCKY = ${blocky};
const SEGS = ${SEGS}.0;
const TAU = 6.28318530718;
struct U { view: vec4f, time: vec4f }
struct Inst { posSize: vec4f, misc: vec4f, color: vec4f, uv: vec4f, deform: vec4f }
struct VSOut {
  @builtin(position) pos: vec4f,
  @location(0) t01: vec2f,
  @location(1) color: vec4f,
  @location(2) uvRect: vec4f,
  @location(3) shade: f32,
  @location(4) dmeta: vec3f,  // t (anim clock), amount, kind — for fragment snippets
}

@group(0) @binding(0) var<uniform> u: U;
@group(0) @binding(1) var<storage, read> inst: array<Inst>;
@group(0) @binding(2) var samp: sampler;
@group(0) @binding(3) var tex: texture_2d<f32>;

@vertex
fn vs(@builtin(vertex_index) vi: u32, @builtin(instance_index) ii: u32) -> VSOut {
  let d = inst[ii];
  // cell + corner from the flat index; offsets packed as bit tables.
  let corner = vi % 6u;
  let cell = vi / 6u;
  let cx = f32(cell % ${SEGS}u);
  let cy = f32(cell / ${SEGS}u);
  let o = vec2f(f32((0x1Au >> corner) & 1u), f32((0x34u >> corner) & 1u));
  let uvn = vec2f((cx + o.x) / SEGS, (cy + o.y) / SEGS);   // 0..1 across the sprite

  let size = d.posSize.zw;
  let kind = u32(d.misc.y);
  let amount = d.deform.x;
  let t = d.deform.z + d.deform.y * u.time.x * TAU;        // phase + speed·time
  var p = (uvn - 0.5) * size;                              // centred, world units
  var shade = 1.0;

  if (kind == 1u) {                                        // wave — cloth ripple
    let k = uvn.x;                                         // anchored left edge
    let ph = uvn.x * 2.5 * TAU * 0.5 - t;
    p.y += sin(ph) * amount * k;
    shade = 1.0 - cos(ph) * 0.22 * k;                      // slope-lit folds
  } else if (kind == 2u) {                                 // sway — pendulum bend
    let k = 1.0 - uvn.y;                                   // anchored bottom
    p.x += sin(t) * amount * k * k;
  } else if (kind == 3u) {                                 // flip — fake-3D card
    let c = cos(t);
    let s = sin(t);
    p.x = p.x * c;
    p.y = p.y * (1.0 + (uvn.x - 0.5) * s * 0.55);          // perspective taper
    shade = 0.72 + 0.28 * abs(c);                          // edge-on darkening
  } else if (kind == 4u) {                                 // jelly — squash wobble
    let sq = sin(t) * amount;
    p.x *= 1.0 + sq * (1.0 - uvn.y);                       // top wobbles most
    let bottom = 0.5 * size.y;
    p.y = (p.y - bottom) * (1.0 - sq * 0.8) + bottom;      // volume-ish preserve
    p.x += sin(t * 2.0 + uvn.y * TAU * 0.5) * amount * size.x * 0.06 * (1.0 - uvn.y);
  }${custom}

  let sn = sin(d.misc.x);
  let cn = cos(d.misc.x);
  let centre = d.posSize.xy + size * 0.5;
  let world = centre + vec2f(p.x * cn - p.y * sn, p.x * sn + p.y * cn);
  let ndc = (world - u.view.xy) / u.view.zw * 2.0 - 1.0;

  var ux = uvn.x;
  if (d.misc.z > 0.5) { ux = 1.0 - ux; }                   // flipX
  var out: VSOut;
  out.pos = vec4f(ndc.x, -ndc.y, 1.0 - d.misc.w, 1.0);
  out.t01 = vec2f(ux, uvn.y);
  out.uvRect = d.uv;
  out.color = d.color;
  out.shade = shade;
  out.dmeta = vec3f(t, amount, f32(kind));
  return out;
}

@fragment
fn fs(in: VSOut) -> @location(0) vec4f {
  // Same atlas mapping as QuadBatch: un-inset extent, clamped back in.
  let texRes = vec2f(textureDimensions(tex));
  let ht = 0.5 / texRes;
  let lo = in.uvRect.xy - ht;
  let hi = in.uvRect.zw + ht;
  var uv = clamp(vec2f(mix(lo.x, hi.x, in.t01.x), mix(lo.y, hi.y, in.t01.y)), in.uvRect.xy, in.uvRect.zw);
  if (BLOCKY) {
    let cont = in.t01 * (hi - lo) * texRes;
    let dd = max(vec2f(
      length(vec2f(dpdx(cont.x), dpdy(cont.x))),
      length(vec2f(dpdx(cont.y), dpdy(cont.y)))), vec2f(1e-6));
    let tc = uv * texRes;
    let seam = floor(tc + 0.5);
    let snapped = clamp((tc - seam) / dd + seam, seam - 0.5, seam + 0.5);
    uv = clamp(snapped / texRes, in.uvRect.xy, in.uvRect.zw);
  }
  let base = textureSample(tex, samp, uv);
  // Straight-alpha working color — fragment snippets mutate this.
  var color = vec4f(base.rgb * in.color.rgb * in.shade, base.a * in.color.a);
  let tint = in.color;
  let uvn = in.t01;
  let uvRect = in.uvRect;
  let t = in.dmeta.x;
  let amount = in.dmeta.y;
  let shade = in.shade;
  let kind = u32(in.dmeta.z + 0.5);
${customFs}
  return vec4f(color.rgb * color.a, color.a);              // premultiplied
}
`;
}

export interface GridBatchOptions {
  /** Blocky pixel-art sampling (matches QuadBatch's flag). */
  blocky?: boolean;
  filter?: GPUFilterMode;
  capacity?: number;
}

/**
 * One pipeline + instance buffer for every deformed sprite this frame.
 * Flushed inside the scene pass after the blend batch (alpha, depth-tested,
 * push order). All deformation is vertex-stage — no CPU vertex writes.
 */
export class GridBatch {
  /** The surface's submission-order log — see batch.ts's DrawOrder. */
  private order: DrawOrder | null = null;
  private layer = 0;
  private uploaded = false;

  /** @internal Take part in a surface's submission order. */
  joinOrder(order: DrawOrder): void { this.order = order; }
  /** @see QuadBatch.setLayer */
  setLayer(n: number): void { this.layer = n; }
  private data: Float32Array;
  private count = 0;
  private capacity: number;
  private blocky: boolean;
  private filter: GPUFilterMode;
  private uniformData = new Float32Array(8);

  private customs: Array<{ id: number; def: DeformDef }> = [];
  private kinds: Record<string, number> = { ...BUILTIN_ID };

  private device!: GPUDevice;
  private pipeline!: GPURenderPipeline;
  private layout!: GPUBindGroupLayout;
  private sampler!: GPUSampler;
  private uniforms!: GPUBuffer;
  private instances!: GPUBuffer;
  private textureView: GPUTextureView | null = null;
  private bind: GPUBindGroup | null = null;

  constructor(device: GPUDevice, private format: GPUTextureFormat, opts: GridBatchOptions = {}) {
    this.capacity = opts.capacity ?? 256;
    this.blocky = opts.blocky ?? false;
    this.filter = this.blocky ? 'linear' : opts.filter ?? 'linear';
    this.data = new Float32Array(this.capacity * FLOATS);
    this.rebuild(device);
  }

  /**
   * Register a custom deformer (idempotent by name; re-registering replaces
   * the snippet). Recompiles the one pipeline — do it at load, not per frame.
   */
  register(def: DeformDef): void {
    const existing = this.customs.find((c) => c.def.name === def.name);
    if (existing) {
      existing.def = def;
    } else {
      const id = CUSTOM_BASE + this.customs.length;
      this.customs.push({ id, def });
      this.kinds[def.name] = id;
    }
    this.makePipeline();
  }

  rebuild(device: GPUDevice): void {
    this.device = device;
    this.layout = device.createBindGroupLayout({
      entries: [
        { binding: 0, visibility: BITS.STAGE_VERTEX, buffer: { type: 'uniform' } },
        { binding: 1, visibility: BITS.STAGE_VERTEX, buffer: { type: 'read-only-storage' } },
        // Vertex visibility too: deformer snippets may textureSampleLevel
        // in the vertex stage (texture-driven twist/wind).
        { binding: 2, visibility: BITS.STAGE_VERTEX | BITS.STAGE_FRAGMENT, sampler: {} },
        { binding: 3, visibility: BITS.STAGE_VERTEX | BITS.STAGE_FRAGMENT, texture: {} },
      ],
    });
    this.makePipeline();
    this.sampler = device.createSampler({ magFilter: this.filter, minFilter: this.filter });
    this.uniforms = device.createBuffer({ size: 32, usage: BITS.UNIFORM | BITS.COPY_DST });
    this.instances = device.createBuffer({ size: this.capacity * FLOATS * 4, usage: BITS.STORAGE | BITS.COPY_DST });
    this.bind = null;
    this.textureView = null;
  }

  private makePipeline(): void {
    const module = this.device.createShaderModule({ code: buildGridWGSL(this.blocky, this.customs) });
    void module.getCompilationInfo().then((info) => {
      for (const m of info.messages) {
        if (m.type === 'error') console.error(`GridBatch WGSL ${m.lineNum}:${m.linePos} ${m.message}`);
      }
    });
    this.pipeline = this.device.createRenderPipeline({
      layout: this.device.createPipelineLayout({ bindGroupLayouts: [this.layout] }),
      vertex: { module, entryPoint: 'vs' },
      fragment: {
        module,
        entryPoint: 'fs',
        targets: [{
          format: this.format,
          blend: {
            color: { srcFactor: 'one', dstFactor: 'one-minus-src-alpha' },
            alpha: { srcFactor: 'one', dstFactor: 'one-minus-src-alpha' },
          },
        }],
      },
      depthStencil: { format: DEPTH_FORMAT, depthWriteEnabled: false, depthCompare: 'less-equal' },
      primitive: { topology: 'triangle-list' },
    });
  }

  setTexture(view: GPUTextureView): void {
    this.textureView = view;
    this.makeBind();
  }

  private makeBind(): void {
    if (!this.textureView) return;
    this.bind = this.device.createBindGroup({
      layout: this.layout,
      entries: [
        { binding: 0, resource: { buffer: this.uniforms } },
        { binding: 1, resource: { buffer: this.instances } },
        { binding: 2, resource: this.sampler },
        { binding: 3, resource: this.textureView },
      ],
    });
  }

  begin(viewX: number, viewY: number, viewW: number, viewH: number, time: number): void {
    this.count = 0;
    this.layer = 0;
    this.uploaded = false;
    this.uniformData.set([viewX, viewY, viewW, viewH, time, 0, 0, 0]);
  }

  push(
    x: number, y: number, w: number, h: number,
    frame: Frame, rot: number, flipX: boolean, z: number,
    deform: Deform,
    r: number, g: number, b: number, a: number,
  ): void {
    this.order?.put(SRC_GRID, this.count, this.layer);
    if (this.count === this.capacity) this.grow();
    const o = this.count * FLOATS;
    const d = this.data;
    d[o] = x; d[o + 1] = y; d[o + 2] = w; d[o + 3] = h;
    d[o + 4] = rot; d[o + 5] = this.kinds[deform.kind] ?? 0; d[o + 6] = flipX ? 1 : 0; d[o + 7] = z / Z_RANGE;
    d[o + 8] = r; d[o + 9] = g; d[o + 10] = b; d[o + 11] = a;
    d[o + 12] = frame.u0; d[o + 13] = frame.v0; d[o + 14] = frame.u1; d[o + 15] = frame.v1;
    d[o + 16] = deform.amount ?? 8; d[o + 17] = deform.speed ?? 1; d[o + 18] = deform.phase ?? 0; d[o + 19] = 0;
    this.count++;
  }

  private grow(): void {
    this.capacity *= 2;
    const next = new Float32Array(this.capacity * FLOATS);
    next.set(this.data);
    this.data = next;
    this.instances.destroy();
    this.instances = this.device.createBuffer({ size: this.capacity * FLOATS * 4, usage: BITS.STORAGE | BITS.COPY_DST });
    this.makeBind();
  }

  private upload(): boolean {
    if (this.count === 0 || !this.bind) return false;
    if (!this.uploaded) {
      this.device.queue.writeBuffer(this.uniforms, 0, this.uniformData);
      this.device.queue.writeBuffer(this.instances, 0, this.data.buffer, 0, this.count * FLOATS * 4);
      this.uploaded = true;
    }
    return true;
  }

  /** @internal Draw ONE contiguous span — the submission-order walk's unit. */
  drawRange(pass: GPURenderPassEncoder, first: number, n: number): void {
    if (n <= 0 || !this.upload()) return;
    pass.setPipeline(this.pipeline);
    pass.setBindGroup(0, this.bind!);
    pass.draw(VERTS, n, 0, first);
  }

  flush(pass: GPURenderPassEncoder): number {
    if (!this.upload()) return 0;
    pass.setPipeline(this.pipeline);
    pass.setBindGroup(0, this.bind!);
    pass.draw(VERTS, this.count);
    return this.count;
  }
}
