// Runtime particle textures — the classic particle-pack shapes generated
// from canvas gradients at load time, no asset files. Register with
// game.assets.frames(particleCanvas({ ... })) and pass the frame to any particle
// emit (2D or 3D); everything is painted WHITE so per-particle colour/ramp
// tints do the colouring. The combination that makes particle systems read
// as beautiful instead of "emitting circles": a textured shape × colour
// tint × size variance × spin × fade.
//
// (Real PNG packs still work through game.assets.loadFrames() — this module covers
// the shapes every pack starts with.)

export type ParticleTexKind = 'soft' | 'flare' | 'ring' | 'star' | 'spark' | 'petal';

export interface ParticleTexOptions {
  /** Which classic: 'soft' (radial glow puff), 'flare' (glow + streak
   * cross), 'ring' (soft halo band), 'star' (5-point star in a glow),
   * 'spark' (a thin horizontal streak — pair with `spin` or velocity),
   * 'petal' (a flower petal with the sakura notch at the tip — pair with
   * `spin` + the GPU emitter's `flutter`/`tumble`). */
  kind?: ParticleTexKind;
  /** Texture size in px (default 64 — particles are small on screen). */
  size?: number;
  /** Star points (star only, default 5). */
  points?: number;
  /** Core-to-halo balance 0..1 (default 0.5): higher = a bigger hot core. */
  core?: number;
}

/** Paint a classic particle texture onto a fresh canvas (all white +
 * alpha — tint at emit time). */
export function particleCanvas(opts: ParticleTexOptions = {}): HTMLCanvasElement {
  const size = opts.size ?? 64;
  const kind = opts.kind ?? 'soft';
  const core = Math.min(1, Math.max(0, opts.core ?? 0.5));
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = size;
  const ctx = canvas.getContext('2d')!;
  const c = size / 2;

  // The shared radial glow (white.png): a hot core easing into a wide halo.
  const glow = (coreFrac: number, alpha = 1): void => {
    const g = ctx.createRadialGradient(c, c, 0, c, c, c);
    g.addColorStop(0, `rgba(255,255,255,${alpha})`);
    g.addColorStop(Math.max(0.01, coreFrac * 0.35), `rgba(255,255,255,${alpha * 0.9})`);
    g.addColorStop(0.55, `rgba(255,255,255,${alpha * 0.25})`);
    g.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, size, size);
  };

  // A soft streak through the centre (flare arms, sparks).
  const streak = (angle: number, len: number, width: number, alpha: number): void => {
    ctx.save();
    ctx.translate(c, c);
    ctx.rotate(angle);
    const g = ctx.createLinearGradient(-len, 0, len, 0);
    g.addColorStop(0, 'rgba(255,255,255,0)');
    g.addColorStop(0.5, `rgba(255,255,255,${alpha})`);
    g.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.ellipse(0, 0, len, width, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  };

  switch (kind) {
    case 'soft':
      glow(core);
      break;
    case 'flare':
      glow(core * 0.8, 0.9);
      streak(0, c * 0.98, c * 0.06, 0.9);
      streak(Math.PI / 2, c * 0.98, c * 0.06, 0.9);
      glow(0.1, 0.5);           // re-brighten the centre over the arms
      break;
    case 'ring': {
      const g = ctx.createRadialGradient(c, c, 0, c, c, c);
      const mid = 0.55 + core * 0.15;
      g.addColorStop(Math.max(0, mid - 0.28), 'rgba(255,255,255,0)');
      g.addColorStop(mid, 'rgba(255,255,255,1)');
      g.addColorStop(Math.min(1, mid + 0.28), 'rgba(255,255,255,0)');
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, size, size);
      break;
    }
    case 'star': {
      glow(0.15, 0.55);
      const points = opts.points ?? 5;
      const rOut = c * (0.5 + core * 0.3);
      const rIn = rOut * 0.45;
      ctx.beginPath();
      for (let i = 0; i < points * 2; i++) {
        const r = i % 2 === 0 ? rOut : rIn;
        const a = (i / (points * 2)) * Math.PI * 2 - Math.PI / 2;
        ctx[i === 0 ? 'moveTo' : 'lineTo'](c + Math.cos(a) * r, c + Math.sin(a) * r);
      }
      ctx.closePath();
      // A blurred pass then a crisp pass — soft edge, hot body.
      ctx.fillStyle = 'rgba(255,255,255,0.85)';
      ctx.filter = `blur(${Math.max(1, size / 32)}px)`;
      ctx.fill();
      ctx.filter = 'none';
      ctx.fill();
      break;
    }
    case 'spark':
      streak(0, c * 0.95, c * 0.14, 1);
      glow(0.1, 0.35);
      break;
    case 'petal': {
      // A sakura petal: obovate (wide at the tip, tapering to the base)
      // with the characteristic NOTCH cleft into the tip. Painted white
      // with a soft alpha falloff so per-particle tints make it any
      // blossom — pale pink over white is the sakura look. Base at the
      // bottom, tip (and notch) at the top.
      const w = c * 0.62;                 // half-width at the widest point
      const tip = c * 0.86;               // tip height above centre
      const base = c * 0.9;               // base depth below centre
      const notch = c * 0.22;             // how deep the tip cleft cuts
      ctx.save();
      ctx.translate(c, c);
      ctx.beginPath();
      ctx.moveTo(0, base);                                              // stem point
      ctx.bezierCurveTo(-w * 0.55, base * 0.55, -w, -tip * 0.15, -w * 0.72, -tip * 0.72);
      ctx.bezierCurveTo(-w * 0.55, -tip * 0.95, -w * 0.2, -tip, -w * 0.16, -tip * 0.98);
      // the notch: dip toward the centre between the two tip lobes
      ctx.quadraticCurveTo(0, -tip + notch, w * 0.16, -tip * 0.98);
      ctx.bezierCurveTo(w * 0.2, -tip, w * 0.55, -tip * 0.95, w * 0.72, -tip * 0.72);
      ctx.bezierCurveTo(w, -tip * 0.15, w * 0.55, base * 0.55, 0, base);
      ctx.closePath();
      // Soft body: brightest mid-petal, gently translucent rim + base.
      const g = ctx.createRadialGradient(0, -tip * 0.15, 0, 0, 0, c);
      g.addColorStop(0, 'rgba(255,255,255,1)');
      g.addColorStop(0.55, 'rgba(255,255,255,0.92)');
      g.addColorStop(1, 'rgba(255,255,255,0.55)');
      ctx.fillStyle = g;
      ctx.filter = `blur(${Math.max(1, size / 64)}px)`;                 // soften the cut edge
      ctx.fill();
      ctx.filter = 'none';
      ctx.fill();
      ctx.restore();
      break;
    }
  }
  return canvas;
}
