// CONSTRUCTIVE SOLID GEOMETRY for the 3D layer — boolean union / subtract /
// intersect over triangle-soup meshes, living ENTIRELY at the geometry layer
// (soup in → soup out). The result is one more unit-ish mesh you hand to
// world.custom(), so CSG needs zero renderer / shader / pipeline / physics
// work — it is bake-time geometry, never touched per frame.
//
// The core is a BSP-tree polygon boolean (Evan Wallace's csg.js recipe),
// adapted to the engine's interleaved vertex: [x,y,z, nx,ny,nz, u,v] (8
// floats — the same STRIDE as geometry3d). Cut edges INTERPOLATE the normal
// and uv, so a drilled dimple lights as a true concave bowl and textures stay
// sane. Pure math, DOM-free, headlessly testable.
//
// Robustness note: this is the classic csg.js algorithm — excellent for
// "convex tool minus a convex-ish body" (dimples, notches, engraving) and
// solid for general use, but it is NOT a bullet-proof CAD kernel over
// arbitrary self-intersecting meshes. Keep tools clean and closed.

const EPS = 1e-5;

/** A vertex: [x, y, z, nx, ny, nz, u, v]. */
type Vert = number[];

interface Plane { x: number; y: number; z: number; w: number; }
interface Poly { verts: Vert[]; plane: Plane; }

// ── Vertex / plane helpers ───────────────────────────────────────────────────
function cloneVert(v: Vert): Vert {
  return [v[0]!, v[1]!, v[2]!, v[3]!, v[4]!, v[5]!, v[6]!, v[7]!];
}

/** Linear blend of two verts at t — position + uv lerp, normal lerp+renormalise. */
function lerpVert(a: Vert, b: Vert, t: number): Vert {
  const x = a[0]! + (b[0]! - a[0]!) * t;
  const y = a[1]! + (b[1]! - a[1]!) * t;
  const z = a[2]! + (b[2]! - a[2]!) * t;
  let nx = a[3]! + (b[3]! - a[3]!) * t;
  let ny = a[4]! + (b[4]! - a[4]!) * t;
  let nz = a[5]! + (b[5]! - a[5]!) * t;
  const l = Math.hypot(nx, ny, nz) || 1;
  nx /= l; ny /= l; nz /= l;
  const u = a[6]! + (b[6]! - a[6]!) * t;
  const v = a[7]! + (b[7]! - a[7]!) * t;
  return [x, y, z, nx, ny, nz, u, v];
}

function planeFromVerts(a: Vert, b: Vert, c: Vert): Plane {
  const ux = b[0]! - a[0]!, uy = b[1]! - a[1]!, uz = b[2]! - a[2]!;
  const vx = c[0]! - a[0]!, vy = c[1]! - a[1]!, vz = c[2]! - a[2]!;
  let nx = uy * vz - uz * vy, ny = uz * vx - ux * vz, nz = ux * vy - uy * vx;
  const l = Math.hypot(nx, ny, nz) || 1;
  nx /= l; ny /= l; nz /= l;
  return { x: nx, y: ny, z: nz, w: nx * a[0]! + ny * a[1]! + nz * a[2]! };
}

function makePoly(verts: Vert[]): Poly {
  return { verts, plane: planeFromVerts(verts[0]!, verts[1]!, verts[2]!) };
}

function flipPoly(p: Poly): void {
  p.verts.reverse();
  for (const v of p.verts) { v[3] = -v[3]!; v[4] = -v[4]!; v[5] = -v[5]!; }
  p.plane = { x: -p.plane.x, y: -p.plane.y, z: -p.plane.z, w: -p.plane.w };
}

const COPLANAR = 0, FRONT = 1, BACK = 2, SPANNING = 3;

/** Split `poly` by `plane`, routing whole/fragment polys to the four buckets. */
function splitPoly(plane: Plane, poly: Poly, cf: Poly[], cb: Poly[], front: Poly[], back: Poly[]): void {
  let polyType = 0;
  const types: number[] = [];
  for (const v of poly.verts) {
    const t = plane.x * v[0]! + plane.y * v[1]! + plane.z * v[2]! - plane.w;
    const type = t < -EPS ? BACK : t > EPS ? FRONT : COPLANAR;
    polyType |= type;
    types.push(type);
  }
  switch (polyType) {
    case COPLANAR: {
      const dot = plane.x * poly.plane.x + plane.y * poly.plane.y + plane.z * poly.plane.z;
      (dot > 0 ? cf : cb).push(poly);
      break;
    }
    case FRONT: front.push(poly); break;
    case BACK: back.push(poly); break;
    default: {  // SPANNING — clip the polygon against the plane
      const f: Vert[] = [], b: Vert[] = [];
      const n = poly.verts.length;
      for (let i = 0; i < n; i++) {
        const j = (i + 1) % n;
        const ti = types[i]!, tj = types[j]!;
        const vi = poly.verts[i]!, vj = poly.verts[j]!;
        if (ti !== BACK) f.push(vi);
        if (ti !== FRONT) b.push(ti !== BACK ? cloneVert(vi) : vi);
        if ((ti | tj) === SPANNING) {
          const denom = plane.x * (vj[0]! - vi[0]!) + plane.y * (vj[1]! - vi[1]!) + plane.z * (vj[2]! - vi[2]!);
          const t = (plane.w - (plane.x * vi[0]! + plane.y * vi[1]! + plane.z * vi[2]!)) / denom;
          const mid = lerpVert(vi, vj, t);
          f.push(mid);
          b.push(cloneVert(mid));
        }
      }
      if (f.length >= 3) front.push(makePoly(f));
      if (b.length >= 3) back.push(makePoly(b));
    }
  }
}

// ── BSP node ─────────────────────────────────────────────────────────────────
// All tree walks are ITERATIVE (explicit work stacks) — a well-known csg.js
// failure is O(N)-deep recursion blowing the call stack on big polygon sets;
// iterative walks lift that ceiling.
class Node {
  plane: Plane | null = null;
  front: Node | null = null;
  back: Node | null = null;
  polygons: Poly[] = [];

  constructor(polygons?: Poly[]) { if (polygons) this.build(polygons); }

  invert(): void {
    const stack: Node[] = [this];
    while (stack.length) {
      const node = stack.pop()!;
      for (const p of node.polygons) flipPoly(p);
      if (node.plane) node.plane = { x: -node.plane.x, y: -node.plane.y, z: -node.plane.z, w: -node.plane.w };
      const t = node.front; node.front = node.back; node.back = t;
      if (node.front) stack.push(node.front);
      if (node.back) stack.push(node.back);
    }
  }

  clipPolygons(polygons: Poly[]): Poly[] {
    const result: Poly[] = [];
    const stack: Array<{ node: Node; polys: Poly[] }> = [{ node: this, polys: polygons }];
    while (stack.length) {
      const { node, polys } = stack.pop()!;
      if (!node.plane) { for (const p of polys) result.push(p); continue; }
      const front: Poly[] = [], back: Poly[] = [];
      for (const p of polys) splitPoly(node.plane, p, front, back, front, back);
      if (node.front) stack.push({ node: node.front, polys: front });
      else for (const p of front) result.push(p);
      if (node.back) stack.push({ node: node.back, polys: back });
      // No back child → those polygons are inside the solid → dropped.
    }
    return result;
  }

  clipTo(bsp: Node): void {
    const stack: Node[] = [this];
    while (stack.length) {
      const node = stack.pop()!;
      node.polygons = bsp.clipPolygons(node.polygons);
      if (node.front) stack.push(node.front);
      if (node.back) stack.push(node.back);
    }
  }

  allPolygons(): Poly[] {
    const out: Poly[] = [];
    const stack: Node[] = [this];
    while (stack.length) {
      const node = stack.pop()!;
      for (const p of node.polygons) out.push(p);
      if (node.front) stack.push(node.front);
      if (node.back) stack.push(node.back);
    }
    return out;
  }

  build(polygons: Poly[]): void {
    const stack: Array<{ node: Node; polys: Poly[] }> = [{ node: this, polys: polygons }];
    while (stack.length) {
      const { node, polys } = stack.pop()!;
      if (!polys.length) continue;
      if (!node.plane) node.plane = { ...polys[0]!.plane };
      const front: Poly[] = [], back: Poly[] = [];
      for (const p of polys) splitPoly(node.plane, p, node.polygons, node.polygons, front, back);
      if (front.length) stack.push({ node: (node.front ??= new Node()), polys: front });
      if (back.length) stack.push({ node: (node.back ??= new Node()), polys: back });
    }
  }
}

// ── Boolean ops over polygon arrays (inputs are consumed, so callers clone) ──
function op(a: Poly[], b: Poly[], kind: 'union' | 'subtract' | 'intersect'): Poly[] {
  const A = new Node(a), B = new Node(b);
  if (kind === 'union') {
    A.clipTo(B); B.clipTo(A); B.invert(); B.clipTo(A); B.invert();
    A.build(B.allPolygons());
    return A.allPolygons();
  }
  if (kind === 'subtract') {
    A.invert(); A.clipTo(B); B.clipTo(A); B.invert(); B.clipTo(A); B.invert();
    A.build(B.allPolygons()); A.invert();
    return A.allPolygons();
  }
  // intersect
  A.invert(); B.clipTo(A); B.invert(); A.clipTo(B); B.clipTo(A);
  A.build(B.allPolygons()); A.invert();
  return A.allPolygons();
}

// ── Soup ⇄ polygons ──────────────────────────────────────────────────────────
function vertsToPolys(v: Float32Array): Poly[] {
  const polys: Poly[] = [];
  for (let i = 0; i + 24 <= v.length; i += 24) {
    const tri: Vert[] = [
      [v[i]!, v[i + 1]!, v[i + 2]!, v[i + 3]!, v[i + 4]!, v[i + 5]!, v[i + 6]!, v[i + 7]!],
      [v[i + 8]!, v[i + 9]!, v[i + 10]!, v[i + 11]!, v[i + 12]!, v[i + 13]!, v[i + 14]!, v[i + 15]!],
      [v[i + 16]!, v[i + 17]!, v[i + 18]!, v[i + 19]!, v[i + 20]!, v[i + 21]!, v[i + 22]!, v[i + 23]!],
    ];
    polys.push(makePoly(tri));
  }
  return polys;
}

function clonePolys(polys: Poly[]): Poly[] {
  return polys.map((p) => ({ verts: p.verts.map(cloneVert), plane: { ...p.plane } }));
}

/** Triangulate the (convex) BSP fragments back to interleaved soup — RAW, so
 * CSG's deliberate winding/normals survive (never re-corrected outward). */
function polysToVerts(polys: Poly[]): Float32Array<ArrayBuffer> {
  const out: number[] = [];
  for (const p of polys) {
    for (let i = 2; i < p.verts.length; i++) {
      for (const v of [p.verts[0]!, p.verts[i - 1]!, p.verts[i]!]) {
        out.push(v[0]!, v[1]!, v[2]!, v[3]!, v[4]!, v[5]!, v[6]!, v[7]!);
      }
    }
  }
  return new Float32Array(out);
}

// ── Transform (bake a tool's placement into its soup before combining) ───────
/** Placement of one solid before it joins the shared CSG space. `scale` is
 * uniform or per-axis; rotation follows the shader's roll·pitch·yaw order. */
export interface Transform {
  pos?: [number, number, number];
  scale?: number | [number, number, number];
  yaw?: number; pitch?: number; roll?: number;
}

function rot3(x: number, y: number, z: number, yaw: number, pitch: number, roll: number): [number, number, number] {
  const cr = Math.cos(roll), sr = Math.sin(roll);
  const x1 = x * cr - y * sr, y1 = x * sr + y * cr, z1 = z;
  const cp = Math.cos(pitch), sp = Math.sin(pitch);
  const x2 = x1, y2 = y1 * cp - z1 * sp, z2 = y1 * sp + z1 * cp;
  const cy = Math.cos(yaw), sy = Math.sin(yaw);
  return [x2 * cy - z2 * sy, y2, x2 * sy + z2 * cy];   // right-hand-turn yaw (matches mesh shader)
}

/** Return a copy of `verts` with a placement baked in: scale → rotate → move.
 * Normals rotate too (divided by scale first for non-uniform, then renormalised). */
export function transformVerts(verts: Float32Array, xf: Transform): Float32Array<ArrayBuffer> {
  const [sx, sy, sz] = typeof xf.scale === 'number'
    ? [xf.scale, xf.scale, xf.scale]
    : xf.scale ?? [1, 1, 1];
  const [px, py, pz] = xf.pos ?? [0, 0, 0];
  const yaw = xf.yaw ?? 0, pitch = xf.pitch ?? 0, roll = xf.roll ?? 0;
  const out = new Float32Array(verts.length);
  for (let i = 0; i < verts.length; i += 8) {
    const p = rot3(verts[i]! * sx, verts[i + 1]! * sy, verts[i + 2]! * sz, yaw, pitch, roll);
    out[i] = p[0] + px; out[i + 1] = p[1] + py; out[i + 2] = p[2] + pz;
    let n = rot3(verts[i + 3]! / sx, verts[i + 4]! / sy, verts[i + 5]! / sz, yaw, pitch, roll);
    const l = Math.hypot(n[0], n[1], n[2]) || 1;
    out[i + 3] = n[0] / l; out[i + 4] = n[1] / l; out[i + 5] = n[2] / l;
    out[i + 6] = verts[i + 6]!; out[i + 7] = verts[i + 7]!;
  }
  return out;
}

// ── Public API ───────────────────────────────────────────────────────────────
/**
 * A solid you can boolean against another. Build from any triangle-soup
 * (a geometry3d generator's output), optionally with a placement, then chain
 * `.subtract()` / `.union()` / `.intersect()` and hand `.toVerts()` to
 * `world.custom(name, () => solid.toVerts(), cfg)` — one baked, instanced mesh.
 *
 * ```ts
 * const die = Solid.fromVerts(roundedBoxVerts(0.22, 3))
 *   .subtract(Solid.fromVerts(sphereVerts(16, 12), { pos: [0, 0.5, 0], scale: 0.2 }));
 * world.custom('die', () => die.toVerts(), { w: S, h: S, d: S, color });
 * ```
 * Bake-time only; keep tools clean/closed (see the robustness note up top).
 */
export class Solid {
  private constructor(private polys: Poly[]) {}

  /** Wrap a triangle-soup, optionally baking a placement into it. */
  static fromVerts(verts: Float32Array, xf?: Transform): Solid {
    return new Solid(vertsToPolys(xf ? transformVerts(verts, xf) : verts));
  }

  /** Merge many solids into one. USE THIS to combine cutting tools before a
   * single subtract — "union the tools, subtract once" keeps the polygon count
   * (and the bake time) an order of magnitude below N sequential subtracts. */
  static union(solids: Solid[]): Solid {
    if (!solids.length) return new Solid([]);
    let acc = solids[0]!;
    for (let i = 1; i < solids.length; i++) acc = acc.union(solids[i]!);
    return acc;
  }

  union(other: Solid): Solid { return new Solid(op(clonePolys(this.polys), clonePolys(other.polys), 'union')); }
  subtract(other: Solid): Solid { return new Solid(op(clonePolys(this.polys), clonePolys(other.polys), 'subtract')); }
  intersect(other: Solid): Solid { return new Solid(op(clonePolys(this.polys), clonePolys(other.polys), 'intersect')); }

  /** The result as interleaved (pos, normal, uv) soup for world.custom(). */
  toVerts(): Float32Array<ArrayBuffer> { return polysToVerts(this.polys); }
}

// Low-level soup-in/soup-out helpers (same engine as Solid, no wrapper).
export function unionVerts(a: Float32Array, b: Float32Array): Float32Array<ArrayBuffer> {
  return polysToVerts(op(vertsToPolys(a), vertsToPolys(b), 'union'));
}
export function subtractVerts(a: Float32Array, b: Float32Array): Float32Array<ArrayBuffer> {
  return polysToVerts(op(vertsToPolys(a), vertsToPolys(b), 'subtract'));
}
export function intersectVerts(a: Float32Array, b: Float32Array): Float32Array<ArrayBuffer> {
  return polysToVerts(op(vertsToPolys(a), vertsToPolys(b), 'intersect'));
}
