// The immediate-mode draw verbs — the engine's public drawing surface. No ctx
// argument, no Graphics object, no retained state: each call appends ONE
// instance to the frame's batches, so sprites and shapes interleave in call
// order and the whole frame is two draw calls (opaque cutout + blend).
//
// ROUTING (invisible to game code): fully opaque sprites go to the CUTOUT
// batch (depth write — overdraw is killed by early-Z); anything translucent —
// SDF shapes (their anti-aliased edges need partial alpha), alpha'd or
// blend-flagged sprites — goes to the BLEND batch, which depth-TESTS against
// the cutout content but keeps push order among itself. Every push takes the
// next z from a per-frame cursor, so plain call order still paints back-to-
// front; pass an explicit `z` to override.
//
// Colours are CSS hex strings ('#f80', '#ff8800', '#ff880080' — parses are
// cached). Positions/sizes are WORLD units (see Game: the world is
// `worldHeight` units tall, as wide as the window).

import type { QuadBatch } from './batch.js';
import { textOutline, type VecTextOptions } from './vecfont.js';
import type { Atlas } from './atlas.js';
import type { BitmapFont } from './font.js';
import { fxNeedsShader, type FxBatch, type SpriteFx } from './fxbatch.js';
import type { GlowPass } from './glowpass.js';
import type { GridBatch, Deform } from './gridbatch.js';
import { rgba, WHITE, type Rgba } from './color.js';
import { triangulate, type TriBatch } from './tribatch.js';
import type { MsdfText, MsdfDrawOptions } from './msdf-text.js';
import type { MsdfRenderer } from './msdf.js';
import type { UnicodeText, UnicodeDrawOptions, TextPointer } from './unicode-text.js';
import type { TextBounds } from './text-bounds.js';
import type { UiRenderer, ClipRect } from './ui.js';
import { resolveUiStyle, type UiStyle, type UiState } from './ui-style.js';
import { Ui, type UiDeps } from './ui-widgets.js';

/**
 * What a `d.panel()` call reports back about the pointer, this frame. A panel
 * only hit-tests when its style is interactive (it has a `hover`/`pressed` look
 * or sets `interactive: true`); an inert panel reports all-false for free.
 */
export interface PanelState {
  /** The pointer is over the panel. */
  hovered: boolean;
  /** The pointer is held down ON the panel — the look-pressed state. */
  pressed: boolean;
  /**
   * A press that STARTED on this panel is still held, wherever the pointer has
   * moved to since. This is the DRAG flag: a slider keeps tracking when the
   * pointer wanders off the track, where `pressed` would have gone false.
   */
  active: boolean;
  /** Released over the panel this frame, after pressing on it — the click. */
  clicked: boolean;
  /** The offset the panel's style actually applied this frame (a pressed button
   *  sinking). Move a label by these and it stays with its panel. */
  offsetX: number;
  offsetY: number;
}

const INERT: PanelState = Object.freeze({
  hovered: false, pressed: false, active: false, clicked: false, offsetX: 0, offsetY: 0,
});

/** Per-panel press bookkeeping — a click needs the press AND the release on the
 *  same panel, so a drag that began elsewhere can't trigger one. */
interface PanelMemory {
  /** The press that is currently live began on THIS panel. */
  armed: boolean;
  /** The `pressedAt` of the last press this panel has already accounted for. */
  lastPress: number;
  seen: number;
}

export interface SpriteOpts {
  /** Draw size in world units (default: the frame's pixel size). */
  w?: number; h?: number;
  /** Rotation about the sprite's centre, radians clockwise. */
  rot?: number;
  flipX?: boolean;
  /** Multiply-tint, hex. */
  tint?: string;
  alpha?: number;
  /** Depth override (bigger = in front); default: call order. */
  z?: number;
  /** Force the blend pass (e.g. additive-looking glows drawn as sprites). */
  blend?: boolean;
  /**
   * Tile the frame across the sprite: repeat counts per axis (default 1).
   * Combine with w/h for a tiled region — ground strips, walls, conveyors.
   */
  uvRepeat?: { x?: number; y?: number };
  /**
   * Scroll the texture inside the sprite, in FRAME fractions (1 = one full
   * frame). Animate per frame for parallax/conveyors/lava — the geometry
   * never moves, only the texture.
   */
  uvScroll?: { x?: number; y?: number };
  /** Per-OBJECT effects on THIS sprite only — a stacking bag (see effects.md). */
  fx?: SpriteFx;
  /**
   * Vertex-stage deformation: { kind: 'wave' | 'sway' | 'flip' | 'jelly',
   * amount?, speed?, phase? }. Subdivides the sprite into a grid deformed
   * entirely on the GPU — flags, hanging banners, card flips, jiggling
   * slimes. See draw.md's deformer entry.
   */
  deform?: Deform;
}

export class Draw {
  private zCursor = 0;
  private time = 0;

  /**
   * @internal Built by `Game` — reach a surface as `game.draw` / `game.hud` (or
   * the `d` handed to `run()` / `draw()` / `drawHud()`), never construct one.
   * (Also keeps the internal `TextPointer` out of the shipped `.d.ts`.)
   */
  constructor(
    private cutout: QuadBatch,
    private blend: QuadBatch,
    private atlas: Atlas,
    /** Additive batch (particles/glows); HUD surfaces reuse their blend batch. */
    private add: QuadBatch = blend,
    /** Per-object fx batch (outline/dissolve/…); absent on HUD surfaces. */
    private fxb: FxBatch | null = null,
    /** True blurred glow (bloom-style); absent on HUD surfaces. */
    private glow: GlowPass | null = null,
    /** Deformable grid sprites (wave/sway/flip/jelly); absent on HUD surfaces. */
    private grid: GridBatch | null = null,
    /** Filled-polygon batch (the `fill` verb); absent on HUD surfaces. */
    private tri: TriBatch | null = null,
    /**
     * The TEXT pass for THIS surface — world space for `game.draw`, screen space
     * for `game.hud`. `msdfText`/`unicodeText` submit into it, which is why the
     * same retained text object can be drawn in either space.
     */
    private textPass: MsdfRenderer | null = null,
    /**
     * The pointer in THIS surface's units (world for `game.draw`, CSS pixels for
     * `game.hud`), or null when there is none / input is in its transition
     * grace. Interactive text hit-tests against it.
     */
    private pointerIn: (() => TextPointer | null) | null = null,
    /**
     * The UI PANEL pass for THIS surface (see ui.ts). Panels paint over the 2D
     * layer and UNDER this surface's text, so a button's label sits on its
     * body without the game having to think about order.
     */
    private uiPass: UiRenderer | null = null,
    /**
     * The UI-LABEL batch for THIS surface. Bitmap labels that belong to UI
     * furniture go here rather than into `blend`, and it flushes per LAYER in
     * step with `uiPass` and `textPass` — panels, then their labels, then their
     * MSDF text, one layer at a time. That is what makes a control and its
     * caption one object, and what lets a window claim a layer and stack over
     * another window's text without a stencil.
     *
     * `d.text()` deliberately does NOT come here: it is a scene verb and keeps
     * its free z-ordering among sprites.
     */
    private textq: QuadBatch | null = null,
  ) {}

  /**
   * @internal Boxes of every text block drawn on this surface this frame —
   * collected only while the debug overlay's `textBounds` is on, so a shipped
   * game pays nothing. The overlay draws them and reddens the ones that clash.
   */
  textBoxes: TextBounds[] = [];
  /** @internal Set by Game from `game.debug`. */
  traceText = false;

  private viewX = 0;
  private viewY = 0;
  private viewW = 0;
  private viewH = 0;

  /**
   * The clip stack. Each entry is NORMALISED to the surface (0..1), already
   * intersected with its parent, so a nested clip can only ever shrink — the
   * same rule CSS overflow follows.
   */
  private clipStack: ClipRect[] = [];
  /** 0 = the normal UI, 1 = overlays (open dropdowns, tooltips). See ui.ts. */
  /**
   * The current LAYER. 0 is the frame's ordinary content — sprites, shapes,
   * text and panels alike, ordered purely by the order the game drew them. A
   * window or modal claims 1, 2, … and everything it draws goes wholly above
   * everything below, which is the only thing call order cannot express.
   */
  private uiLayer = 0;
  /** Deepest layer any window reached this frame — overlays go one above it. */
  private maxUiLayer = 0;
  /** How far down anything has been drawn while measuring is on (see
   *  {@link beginMeasure}); -Infinity when nothing has been drawn yet. */
  private measureBottom = -Infinity;
  private measuring = 0;

  /** This surface's width in its own units this frame (`game.view.w` for
   *  `game.draw`, the HUD reference for `game.hud`). */
  get w(): number { return this.viewW; }
  /** This surface's height in its own units this frame — see {@link w}. */
  get h(): number { return this.viewH; }

  private _ui: Ui | null = null;
  private uiDeps: UiDeps | null = null;

  /**
   * The WIDGET layer for this surface — `button`, `checkbox`, `toggle`,
   * `slider`, `progress`, `window`, `input`, `textarea`, `list` (see ui.md),
   * named after HTML's. Built on `panel()`,
   * so widgets inherit its size-independence and restyle from one theme.
   *
   * ```ts
   * if (d.ui.button(x, y, 180, 52, 'Start')) startGame();
   * ```
   */
  get ui(): Ui {
    return this._ui ?? (this._ui = new Ui(this, this.uiDeps));
  }

  /**
   * @internal Flush this surface's deferred UI overlays (open dropdowns).
   * Called by Game after the frame's own drawing, never by games.
   *
   * They draw on LAYER 1, which the renderers flush after the normal text pass.
   * Submission order alone is not enough: panels and text are separate passes,
   * so a popup drawn last still ends up under text drawn earlier.
   */
  flushUiOverlays(): void {
    if (!this._ui) return;
    const was = this.uiLayer;
    // Above every window opened this frame, whatever depth they reached.
    this.setUiLayer(this.maxUiLayer + 1);
    this._ui.flushOverlays();
    this.setUiLayer(was);
  }

  /**
   * @internal Point every UI pass at layer `n` — panels, their bitmap labels
   * and their MSDF text together. They are separate batches but ONE stack:
   * moving them in lockstep is what makes a window a single object.
   *
   * Driven by `d.ui.window()`; games do not call it.
   */
  setUiLayer(n: number): void {
    this.uiLayer = n;
    if (n > this.maxUiLayer) this.maxUiLayer = n;
    // Every pass moves together, so a window carries its sprites, its text and
    // its furniture up as one. Called mid-frame, after every begin().
    this.blend.setLayer(n);
    if (this.add !== this.blend) this.add.setLayer(n);
    this.textq?.setLayer(n);
    if (this.textPass) this.textPass.layer = n;
  }

  /** @internal The layer a window opened here would claim. */
  get currentUiLayer(): number { return this.uiLayer; }

  /** @internal Wired by Game after construction — input and the fallback font
   *  are both built later than the Draw surfaces themselves. */
  attachUi(deps: UiDeps): void {
    this.uiDeps = deps;
    if (this._ui) this._ui = new Ui(this, deps);
  }

  /**
   * @internal Start measuring how far down subsequent drawing reaches. Nests.
   * A container uses this to size itself to its content: it pushes its frame
   * first (the frame must paint UNDER the content), draws the content, then
   * corrects the frame's height from what came back.
   */
  beginMeasure(): void {
    if (this.measuring++ === 0) this.measureBottom = -Infinity;
  }

  /** @internal Stop measuring; returns the lowest Y drawn, or -Infinity. */
  endMeasure(): number {
    this.measuring = Math.max(0, this.measuring - 1);
    return this.measureBottom;
  }

  /**
   * @internal Note that something reached down to `bottom`.
   *
   * CLAMPED TO THE CLIP, which is the whole subtlety: a scroll region's rows are
   * laid out at their scrolled positions and most of them hang far below the box
   * they show through. Measuring where they were DRAWN rather than where they
   * are VISIBLE made an auto-sized window grow and shrink as you scrolled it —
   * tall while the rows hung out of the bottom, correct once you reached the
   * end. Nothing clipped away can make its container taller.
   */
  private mark(bottom: number): void {
    if (this.measuring <= 0) return;
    const c = this.clip;
    if (c) bottom = Math.min(bottom, this.viewY + c.y1 * this.viewH);
    if (bottom > this.measureBottom) this.measureBottom = bottom;
  }

  /** Centre `opts.label` on a panel that has just been pushed, on its layer. */
  private panelLabel(
    opts: { label?: string; labelColor?: string; labelSize?: number } | undefined,
    x: number, y: number, w: number, h: number,
  ): void {
    const str = opts?.label;
    if (!str) return;
    const bmp = this.uiDeps?.bitmapFont() ?? null;
    if (!bmp) return;
    const size = opts.labelSize ?? this._ui?.theme.fontSize ?? 16;
    const scale = size / bmp.lineHeight;
    this.uiLabel(bmp, str, x + w / 2, y + h / 2 - (bmp.lineHeight * scale) / 2, {
      scale, color: opts.labelColor ?? this._ui?.theme.text ?? '#ffffff', align: 'center',
    });
  }

  /** @internal Reserve a panel now and correct its rect later — the container
   *  auto-size path. Returns the instance index, or -1. */
  reservePanel(x: number, y: number, w: number, h: number, style?: string | UiStyle): number {
    if (!this.uiPass) return -1;
    return this.uiPass.push(x, y, w, h, resolveUiStyle(style), 0, this.clip, this.uiLayer);
  }

  /** @internal Rewrite a reserved panel's rectangle (see {@link reservePanel}). */
  patchPanel(index: number, x: number, y: number, w: number, h: number): void {
    this.uiPass?.patchRect(index, x, y, w, h);
  }

  /** @internal This surface's pointer, in its own units — widgets that DRAG
   *  (the slider) need the position, not just the panel's hit flags. */
  uiPointer(): { x: number; y: number; down: boolean } | null {
    return this.pointerIn?.() ?? null;
  }

  /** Press state per interactive panel, keyed by its id (explicit or implicit). */
  private panelMemory = new Map<string | number, PanelMemory>();
  /** The implicit-id cursor: which interactive panel this is, in call order. */
  private panelSeq = 0;
  private frameNo = 0;

  /**
   * Clip everything drawn until the matching {@link popClip} to this rectangle,
   * in the SURFACE's own units. Nested clips intersect, so a child can never
   * paint outside its parent.
   *
   * This is how a scrolling region, a masked panel, or a text field that must
   * not spill over its neighbours are built:
   * ```ts
   * d.pushClip(x, y, w, h);
   * for (const item of items) d.ui.button(x, y + item.top - scroll, w, 40, item.name);
   * d.popClip();
   * ```
   *
   * **Panels and text obey it; sprites, lines and shapes do not yet** — it is a
   * hardware scissor on the UI and text passes (see ui.md).
   */
  pushClip(x: number, y: number, w: number, h: number): void {
    const c: ClipRect = {
      x0: (x - this.viewX) / Math.max(1e-6, this.viewW),
      y0: (y - this.viewY) / Math.max(1e-6, this.viewH),
      x1: (x + w - this.viewX) / Math.max(1e-6, this.viewW),
      y1: (y + h - this.viewY) / Math.max(1e-6, this.viewH),
    };
    const parent = this.clipStack[this.clipStack.length - 1];
    if (parent) {
      c.x0 = Math.max(c.x0, parent.x0);
      c.y0 = Math.max(c.y0, parent.y0);
      c.x1 = Math.min(Math.max(c.x1, c.x0), parent.x1);
      c.y1 = Math.min(Math.max(c.y1, c.y0), parent.y1);
    }
    this.clipStack.push(c);
    this.syncClip();
  }

  /** Pop the innermost clip pushed by {@link pushClip}. */
  popClip(): void {
    this.clipStack.pop();
    this.syncClip();
  }

  /** The clip in force right now, or null. */
  private get clip(): ClipRect | null {
    return this.clipStack.length ? this.clipStack[this.clipStack.length - 1] : null;
  }

  /** Text submitters don't take a clip argument, so the text pass carries the
   *  current one and reads it inside alloc(). */
  private syncClip(): void {
    if (this.textPass) this.textPass.clip = this.clip;
  }

  /**
   * Is any of this rect visible through the current clip? Widgets use it to
   * skip work for rows scrolled out of view — clipping stops them DRAWING, this
   * stops them being built at all.
   */
  visible(x: number, y: number, w: number, h: number): boolean {
    const c = this.clip;
    if (!c) return true;
    const x0 = (x - this.viewX) / Math.max(1e-6, this.viewW);
    const y0 = (y - this.viewY) / Math.max(1e-6, this.viewH);
    const x1 = (x + w - this.viewX) / Math.max(1e-6, this.viewW);
    const y1 = (y + h - this.viewY) / Math.max(1e-6, this.viewH);
    return x1 > c.x0 && x0 < c.x1 && y1 > c.y0 && y0 < c.y1;
  }

  /** @internal Start a frame (called by Game). */
  begin(x: number, y: number, w: number, h: number, time = 0): void {
    this.zCursor = 0;
    this.clipStack.length = 0;
    this.uiLayer = 0;
    this.maxUiLayer = 0;
    // Layer cursors are NOT stamped here — each pass's own begin() runs after
    // this and resets them to 0, which is exactly where they should start.
    this.viewX = x;
    this.viewY = y;
    this.panelSeq = 0;
    this.frameNo++;
    this._ui?.begin(time);
    // Panels that stopped being drawn (a closed menu) would otherwise sit in the
    // map for the life of the game. Sweep rarely — this is a leak guard, not
    // bookkeeping the common case pays for.
    if (this.panelMemory.size > 256) {
      for (const [k, m] of this.panelMemory) {
        if (this.frameNo - m.seen > 120) this.panelMemory.delete(k);
      }
    }
    if (this.textBoxes.length) this.textBoxes.length = 0;
    this.time = time;
    this.viewW = w;
    this.viewH = h;
    this.cutout.begin(x, y, w, h);
    this.blend.begin(x, y, w, h);
    if (this.add !== this.blend) this.add.begin(x, y, w, h);
    if (this.textq && this.textq !== this.blend) this.textq.begin(x, y, w, h);
    this.fxb?.begin(x, y, w, h);
    this.glow?.begin(x, y, w, h);
    this.grid?.begin(x, y, w, h, time);
  }

  /** @internal Particle push: centred disc (frame -1) or sprite frame, float colour, premul-routed. */
  part(cx: number, cy: number, size: number, rot: number, frame: number, r: number, g: number, b: number, a: number, add: boolean): void {
    const batch = add ? this.add : this.blend;
    const z = this.nextZ();
    if (frame >= 0) {
      const f = this.atlas.frames[frame];
      if (!f) return;
      batch.push(cx - size, cy - size, size * 2, size * 2, f, 0, rot, 0, z, r, g, b, a);
    } else {
      batch.push(cx - size, cy - size, size * 2, size * 2, this.atlas.frames[0], 1, 0, 0, z, r, g, b, a);
    }
  }

  /** @internal The next auto-depth value (call order). */
  nextZ(): number {
    return ++this.zCursor;
  }

  /** A textured sprite: `frame` is an index from game.assets.frames()/game.assets.text(). */
  sprite(frame: number, x: number, y: number, opts?: SpriteOpts): void {
    const f = this.atlas.frames[frame];
    if (!f) return;
    const c: Rgba = opts?.tint ? rgba(opts.tint) : WHITE;
    const a = (opts?.alpha ?? 1) * c[3];
    let w = opts?.w ?? f.w;
    let h = opts?.h ?? f.h;
    if (opts?.deform && this.grid) {
      // Deformed sprites render on the subdivided grid batch instead.
      this.grid.push(x, y, w, h, f, opts.rot ?? 0, opts.flipX ?? false, opts.z ?? this.nextZ(), opts.deform, c[0], c[1], c[2], a);
      return;
    }
    const fx = opts?.fx;
    if (fx) {
      // Transform effects run on the CPU and ride whichever batch draws the sprite.
      if (fx.shake) {
        const k = fx.shake.duration && fx.shake._left !== undefined
          ? Math.max(0, fx.shake._left / fx.shake.duration) : 1;
        x += (Math.random() * 2 - 1) * fx.shake.amount * k;
        y += (Math.random() * 2 - 1) * fx.shake.amount * k;
      }
      if (fx.squash) {
        const ph = Math.sin((fx.squash._t ?? this.time) * (fx.squash.speed ?? 2) * Math.PI * 2);
        const am = fx.squash.amount ?? 0.15;
        const cx = x + w / 2, bottom = y + h;
        w *= 1 + ph * am;
        h *= 1 - ph * am;
        x = cx - w / 2;
        y = bottom - h;
      }
      // Glow is a separate blurred-silhouette pass — the sprite itself still
      // renders through whichever batch it would normally use.
      if (fx.glow && this.glow) {
        const gc = rgba(fx.glow.color ?? '#ffe08a');
        this.glow.stamp(
          x, y, w, h, f, opts?.rot ?? 0, opts?.flipX ?? false,
          gc[0], gc[1], gc[2], gc[3], fx.glow.size ?? 16,
        );
      }
      if (fxNeedsShader(fx) && this.fxb) {
        this.fxb.push(
          x, y, w, h, f,
          opts?.rot ?? 0, opts?.flipX ?? false, opts?.z ?? this.nextZ(), fx, this.time,
          c[0], c[1], c[2], a,
        );
        return;
      }
    }
    const batch = opts?.blend || a < 1 ? this.blend : this.cutout;
    batch.push(
      x, y, w, h, f,
      0, opts?.rot ?? 0, opts?.flipX ? 1 : 0, opts?.z ?? this.nextZ(),
      c[0], c[1], c[2], a,
      opts?.uvScroll?.x ?? 0, opts?.uvScroll?.y ?? 0,
      opts?.uvRepeat?.x ?? 1, opts?.uvRepeat?.y ?? 1,
    );
  }

  /** A solid rectangle (optionally rotated about its centre). */
  rect(x: number, y: number, w: number, h: number, color = '#ffffff', alpha = 1, rot = 0): void {
    const c = rgba(color);
    this.blend.push(x, y, w, h, this.atlas.frames[0], 3, rot, 0, this.nextZ(), c[0], c[1], c[2], alpha * c[3]);
  }

  /** A line segment with width — a rotated solid quad centred on the segment. */
  line(x0: number, y0: number, x1: number, y1: number, width: number, color = '#ffffff', alpha = 1): void {
    const dx = x1 - x0, dy = y1 - y0;
    const len = Math.hypot(dx, dy);
    if (len < 0.0001) return;
    const c = rgba(color);
    this.blend.push(
      (x0 + x1 - len) / 2, (y0 + y1 - width) / 2, len, width, this.atlas.frames[0],
      3, Math.atan2(dy, dx), 0, this.nextZ(), c[0], c[1], c[2], alpha * c[3],
    );
  }

  /** @internal VFX ribbon segment — a width'd line routed to blend or ADDITIVE. */
  trailSegment(x0: number, y0: number, x1: number, y1: number, width: number, color: string, alpha: number, add: boolean): void {
    const dx = x1 - x0, dy = y1 - y0;
    const len = Math.hypot(dx, dy);
    if (len < 0.0001) return;
    const c = rgba(color);
    const batch = add ? this.add : this.blend;
    batch.push(
      (x0 + x1 - len) / 2, (y0 + y1 - width) / 2, len, width, this.atlas.frames[0],
      3, Math.atan2(dy, dx), 0, this.nextZ(), c[0], c[1], c[2], alpha * c[3],
    );
  }

  /** A polyline: segments + round joints — smooth corners without miter maths. */
  poly(points: ReadonlyArray<{ x: number; y: number }>, width: number, color = '#ffffff', alpha = 1): void {
    for (let i = 1; i < points.length; i++) {
      this.line(points[i - 1].x, points[i - 1].y, points[i].x, points[i].y, width, color, alpha);
    }
    if (width > 2.5) {
      for (let i = 1; i < points.length - 1; i++) this.circle(points[i].x, points[i].y, width / 2, color, alpha);
    }
  }

  /**
   * The stroked VECTOR FACE as ordinary polylines — the same glyphs
   * `game.vector.text()` draws, but through the draw verbs, so it works on the
   * **HUD surface** where the vector layer cannot reach.
   *
   * ```ts
   * override drawHud(d: Draw): void {
   *   d.vectorText('SCORE 004200', 22, 18, { size: 22, color: '#cdd8ff' });
   * }
   * ```
   *
   * Why this exists: the vector layer is one world-space pass drawn BEFORE the
   * HUD, so a scrolling game's readouts would slide away with the camera. This
   * puts the letterforms on the HUD in screen space, correctly ordered with
   * every other HUD element.
   *
   * The trade is the BEAM: these are plain quads, so there is no phosphor halo
   * and no `dwell`. For glowing text inside the world, use `game.vector.text()`.
   */
  vectorText(
    str: string, x: number, y: number,
    opts: VecTextOptions & { width?: number; color?: string; alpha?: number } = {},
  ): void {
    const w = opts.width ?? 2;
    const color = opts.color ?? '#ffffff';
    const alpha = opts.alpha ?? 1;
    for (const pts of textOutline(str, x, y, opts)) this.poly(pts, w, color, alpha);
  }

  /**
   * A FILLED polygon of arbitrary shape (ear-clipped into triangles). Points in
   * world units, any simple polygon (convex or concave). Flat colour, alpha
   * blended — the fill counterpart to `poly()`'s stroke.
   */
  fill(points: ReadonlyArray<{ x: number; y: number }>, color = '#ffffff', alpha = 1): void {
    if (!this.tri || points.length < 3) return;
    const c = rgba(color);
    const a = alpha * c[3];
    const idx = triangulate(points);
    for (let i = 0; i < idx.length; i += 3) {
      const p0 = points[idx[i]], p1 = points[idx[i + 1]], p2 = points[idx[i + 2]];
      this.tri.push(p0.x, p0.y, p1.x, p1.y, p2.x, p2.y, c[0], c[1], c[2], a);
    }
  }

  /** An anti-aliased filled circle (analytic SDF — crisp at any radius). */
  circle(cx: number, cy: number, radius: number, color = '#ffffff', alpha = 1): void {
    const c = rgba(color);
    this.blend.push(cx - radius, cy - radius, radius * 2, radius * 2, this.atlas.frames[0], 1, 0, 0, this.nextZ(), c[0], c[1], c[2], alpha * c[3]);
  }

  /** An anti-aliased ring / circle outline with a stroke thickness in world units. */
  ring(cx: number, cy: number, radius: number, thickness: number, color = '#ffffff', alpha = 1): void {
    const frac = Math.min(1, Math.max(0.02, thickness / Math.max(1, radius)));
    const c = rgba(color);
    this.blend.push(cx - radius, cy - radius, radius * 2, radius * 2, this.atlas.frames[0], 2, 0, frac, this.nextZ(), c[0], c[1], c[2], alpha * c[3]);
  }

  /**
   * A UI PANEL — the procedural interface primitive: a rounded box whose rim,
   * bevel, gloss, inner shadow and drop shadow are all computed from the shape
   * itself (see ui.md). Buttons, frames, slots, bars, tooltips, dialogs.
   *
   * There is NO source art and nothing stretches: the same call gives a 40-unit
   * chip and a 900-unit dialog the same crisp 5-unit rim, at any zoom.
   *
   * ```ts
   * d.panel(x, y, 200, 64, 'glossy');                        // a named style
   * d.panel(x, y, 200, 64, { base: 'glossy', fill: '#e6408f', fillTo: '#a01f5e' });
   * ```
   *
   * Panels paint over the 2D scene and UNDER this surface's text, so a label
   * drawn after the panel lands on top of it whatever the call order.
   */
  panel(
    x: number, y: number, w: number, h: number,
    style?: string | UiStyle,
    opts?: {
      rot?: number;
      /**
       * Identity for the press/click machine. Defaults to the panel's position
       * among the INTERACTIVE panels drawn this frame, which is stable for a
       * fixed layout. Pass an explicit id when interactive panels appear and
       * disappear conditionally, or the ids after the gap shift by one.
       */
      id?: string | number;
      /**
       * A caption centred on the panel, drawn as PART OF IT — same layer, always
       * on top of the body, and it moves with the panel when a pressed style
       * sinks. This is the supported way to label a bespoke control.
       *
       * Do NOT reach for `d.text` here: that is a scene verb with its own
       * z-ordering among sprites, and nothing guarantees it lands on the panel.
       * Uses the zero-setup bitmap font; for styled or non-Latin captions build
       * the control from `d.ui.*` instead.
       */
      label?: string;
      /** Caption colour (default: the widget theme's text colour). */
      labelColor?: string;
      /** Caption size in surface units (default: the widget theme's fontSize). */
      labelSize?: number;
    },
  ): PanelState {
    if (!this.uiPass) return INERT;
    const base = resolveUiStyle(style);
    if (!base.interactive) {
      this.uiPass.push(x + base.offsetX, y + base.offsetY, w, h, base, opts?.rot ?? 0, this.clip, this.uiLayer);
      this.panelLabel(opts, x + base.offsetX, y + base.offsetY, w, h);
      this.mark(y + base.offsetY + h);
      return INERT;
    }

    // Reading the pointer is what makes the surface attach its DOM listeners, so
    // a screen of static panels never pays for input at all.
    // A panel clipped entirely out of view must not hit-test either — a row
    // scrolled off the top of a list is gone, not merely invisible.
    const pointer = this.visible(x, y, w, h) ? (this.pointerIn?.() ?? null) : null;
    const key = opts?.id ?? this.panelSeq++;
    let mem = this.panelMemory.get(key);
    if (!mem) this.panelMemory.set(key, mem = { armed: false, lastPress: 0, seen: this.frameNo });
    mem.seen = this.frameNo;

    let hovered = false, held = false, clicked = false, active = false;
    if (!pointer) {
      mem.armed = false;
    } else {
      // Hit-test the panel where it is DRAWN — a pressed button that sinks by
      // its offset stays under the pointer that is pressing it.
      const px = x + base.offsetX, py = y + base.offsetY;
      const inside = (hx: number, hy: number): boolean =>
        hx >= px && hx <= px + w && hy >= py && hy <= py + h;
      hovered = inside(pointer.x, pointer.y);

      // Press edges come from `pressedAt`, not from the polled `down` flag: a
      // tap that begins AND ends between two frames never shows up as down at
      // sample time, and would otherwise be dropped entirely. Arming uses the
      // point where the press LANDED, which for such a tap is the only place we
      // ever see it.
      const pressedAt = pointer.pressedAt ?? 0;
      if (pressedAt !== mem.lastPress) {
        mem.lastPress = pressedAt;
        mem.armed = inside(pointer.pressX ?? pointer.x, pointer.pressY ?? pointer.y);
      }
      if (!pointer.down && mem.armed) {
        // Released: it counts as a click if the release is over the panel too.
        if (hovered) clicked = true;
        mem.armed = false;
      }
      active = mem.armed && pointer.down;          // a drag, wherever it is now
      held = hovered && active;
      if (hovered && base.cursor) pointer.wantCursor?.();
    }

    const state: UiState = held && base.hasPressed ? 'pressed' : hovered && base.hasHover ? 'hover' : 'base';
    const look = state === 'base' ? base : resolveUiStyle(style, state);
    this.uiPass.push(x + look.offsetX, y + look.offsetY, w, h, look, opts?.rot ?? 0, this.clip, this.uiLayer);
    // The caption follows the panel's own sink, so button and label move as one.
    this.panelLabel(opts, x + look.offsetX, y + look.offsetY, w, h);
    this.mark(y + look.offsetY + h);
    return { hovered, pressed: held, active, clicked, offsetX: look.offsetX, offsetY: look.offsetY };
  }

  /**
   * A single line of bitmap-font text. Glyphs are pre-baked white quads —
   * per-frame changing strings cost nothing but pushes, and `color` tints
   * them per instance. x is the anchor per `align` (left edge by default).
   */
  text(
    font: BitmapFont, str: string, x: number, y: number,
    opts?: { scale?: number; color?: string; alpha?: number; align?: 'left' | 'center' | 'right'; z?: number },
  ): void {
    const scale = opts?.scale ?? 1;
    const c: Rgba = opts?.color ? rgba(opts.color) : WHITE;
    const a = (opts?.alpha ?? 1) * c[3];
    const align = opts?.align ?? 'left';
    let pen = x;
    if (align !== 'left') {
      const w = font.measure(str, scale);
      pen = align === 'center' ? x - w / 2 : x - w;
    }
    this.glyphs(this.blend, font, str, pen, y, scale, c, a, opts?.z ?? this.nextZ());
  }

  /**
   * @internal The label path for UI FURNITURE — the widget layer and `panel`'s
   * own `label`. Identical glyph work to `text()`, but into the UI-label batch
   * at the current UI layer, so the label belongs to the panel it names: drawn
   * with it, above it, and carried with it when a window claims a layer.
   *
   * Game code never needs this. A label on a control comes from the control.
   */
  uiLabel(font: BitmapFont, str: string, x: number, y: number, opts?: { scale?: number; color?: string; alpha?: number; align?: 'left' | 'center' | 'right' }): void {
    if (!this.textq) { this.text(font, str, x, y, opts); return; }
    const scale = opts?.scale ?? 1;
    const c: Rgba = opts?.color ? rgba(opts.color) : WHITE;
    const a = (opts?.alpha ?? 1) * c[3];
    const align = opts?.align ?? 'left';
    let pen = x;
    if (align !== 'left') {
      const w = font.measure(str, scale);
      pen = align === 'center' ? x - w / 2 : x - w;
    }
    this.glyphs(this.textq, font, str, pen, y, scale, c, a, this.nextZ());
  }

  /** Lay a string out as quads into `batch`, pen already positioned for align. */
  private glyphs(batch: QuadBatch, font: BitmapFont, str: string, startPen: number, y: number, scale: number, c: Rgba, a: number, z: number): void {
    let pen = startPen;
    for (const ch of str) {
      const g = font.glyphs.get(ch);
      if (!g) { pen += font.spaceAdvance * scale; continue; }
      const f = this.atlas.frames[g.frame];
      if (f) {
        // Glyph edges are canvas-antialiased → a blend batch keeps them clean.
        batch.push(pen, y, g.w * scale, g.h * scale, f, 0, 0, 0, z, c[0], c[1], c[2], a);
      }
      pen += g.advance * scale;
    }
  }

  /**
   * Submit a retained MSDF text block (from `game.assets.msdfText(...)`) at (x, y) —
   * crisp at any scale, with per-object/run weight, outline, shadow, gradients
   * and decorations. Lay it out once (set text/style on the object), then draw
   * it each frame here; changing strings only re-lays-out that object.
   */
  msdfText(text: MsdfText, x: number, y: number, opts?: MsdfDrawOptions): void {
    if (!this.textPass) return;
    text.submit(this.textPass, x, y, opts);
    if (this.measuring > 0) this.mark(y + text.height * (1 - (opts?.origin?.y ?? 0)));
    if (this.traceText) this.textBoxes.push(text.bounds(x, y, opts));
  }

  /**
   * Draw a retained UNICODE text block (from `game.assets.unicodeText(...)`) at
   * (x, y) — **the path for Chinese, Japanese, Korean, Arabic, Hebrew, Thai,
   * Devanagari, Cyrillic and emoji**, with correct shaping, right-to-left bidi
   * and system font fallback. Styles (gradient / stroke / shadow / glow /
   * background plate) are baked into the block, so a frame is one quad.
   *
   * Works on BOTH surfaces: `game.draw` (world space, scrolls with the camera)
   * and `game.hud` (screen space, CSS pixels). See unicode-text.md.
   *
   * Drawing is also what drives INTERACTION: a block with a `hover`/`pressed`
   * style (or `interactive: true`) hit-tests this surface's pointer here, so
   * `text.hovered` / `text.clicked` are current straight after this call.
   */
  unicodeText(text: UnicodeText, x: number, y: number, opts?: UnicodeDrawOptions): void {
    if (!this.textPass) return;
    text.submit(this.textPass, x, y, opts, this.pointerIn);
    if (this.measuring > 0) this.mark(y + text.height * (1 - (opts?.origin?.y ?? 0)));
    if (this.traceText) this.textBoxes.push(text.bounds(x, y, opts));
  }
}
