/**
 * Physics2d — OPTIONAL full-body rigid-body physics for the engine. A thin,
 * engine-vocabulary wrapper over a vendored Box2D v3 core that ships as a
 * SEPARATE chunk (`physics2d-core.mjs`, ~640 KB): games that never call
 * `Physics2d.create()` never load a byte of it. This is the 2D twin of
 * `Physics3d` — for physics-strenuous titles (stacks, ragdolls, ropes, vehicles,
 * dominoes) where the arcade `solid(A, B)` solver isn't enough.
 *
 *   // setup() — one await, then attach to the scene and it's hands-free:
 *   this.world = await Physics2d.create({ gravity: 900 });   // units/s² downward
 *   this.physics2d = this.world;                    // the scene steps + syncs
 *   this.world.bind(ground, { type: 'static' });    // immovable level geometry
 *   const crate = this.world.bind(crateSprite, { bounce: 0.2, friction: 0.6 });
 *   crate.impulse({ x: 0, y: -400 });               // units/s kick (screen-up)
 *
 * What the wrapper hides ON PURPOSE (never reach past it): the WASM module and
 * its manual memory rules (every Box2D getter returns a handle that must be
 * freed — the wrapper does this for you), the meters/world-units + y-up/y-down
 * coordinate bridge (you work in the sprite's world units; Box2D works in
 * meters, y-up), body/shape handle plumbing, collision bitmasks (use string
 * `group`/`hits` names), and the fixed-timestep accumulator.
 *
 * You steer dynamic bodies with `impulse`/`force`/`velocity` — NEVER by setting
 * `sprite.x/y` (the sim overwrites them every frame; use `teleport` for a hard
 * move). Bound sprites skip the arcade integrator automatically.
 */

import type { Sprite } from './sprite.js';
import type { Vec2 } from './util.js';
import type { VectorShape, VecPt } from './vector.js';
import { hullFor, convexPieces } from './vecshapes.js';

// ─── Internal core-module surface. The vendored chunk is the Box2D v3 C API
// exposed via embind; deliberately untyped beyond what we call. This wrapper is
// the contract — nothing outside this file touches `B2`.
type B2 = any;
/** A Box2D id (body/shape/joint) — a plain value object, cheap to copy, no free. */
type Id = { index1: number; world0?: number; generation: number };
const idKey = (id: Id): string => id.index1 + ':' + id.generation;

/** @internal Bodies that drive nothing visible (chains, loose capsules) still
 *  need a target object; this stands in so the sync loop stays branch-free. */
const CHAIN_TARGET = { x: 0, y: 0, rot: 0, scale: 1 } as unknown as VectorShape;

// Resolve the physics core: the shipped sibling chunk first (dist/ + sandbox
// layout), then the repo vendor file (dev + headless tests from src).
async function loadCore(explicit?: string): Promise<B2> {
  // NOTE: the URL argument must stay a VARIABLE — a literal lets vite
  // statically resolve the vendor path at build time and INLINE the ~1 MB
  // WASM core into the main bundle as a base64 data: URL, silently
  // defeating the lazy-chunk design (this shipped once).
  const candidates = (explicit
    ? [explicit]
    : [
        './physics2d-core.mjs',            // next to webgpu.js (shipped)
        '../physics2d-core.mjs',           // dist/webgpu/ types layout
        '../../vendor/physics2d-core.mjs', // dev: src/lib → vendor/
      ]).map((p) => new URL(p, import.meta.url).href);
  let lastErr: unknown = null;
  for (const url of candidates) {
    try {
      const mod = await import(/* @vite-ignore */ url);
      return await mod.default();
    } catch (e) {
      lastErr = e;
    }
  }
  throw new Error('Physics2d: physics core module not found (physics2d-core.mjs). ' + String(lastErr));
}

/** Options for `Physics2d.create`. */
export interface Physics2dOptions {
  /**
   * Gravity. A number is downward world-units/s² (screen-down positive) — `900`
   * default, a lively arcade weight. Or a full `{x, y}` vector (y positive = down).
   */
  gravity?: number | Vec2;
  /**
   * World units per simulated metre. Box2D is tuned for bodies roughly 0.1–10 m,
   * so the wrapper simulates in metres and scales by this. The default `32` makes
   * a 32-unit sprite a 1-m body — good for most games. Larger worlds with big
   * sprites can raise it; you rarely need to touch it. Fixed at create time.
   */
  pixelsPerMeter?: number;
  /**
   * Solver sub-steps per 60 Hz frame — how many times the constraint solver
   * refines each step. `4` (default) is right for most games. Raise (e.g. `8`)
   * for demanding contact chains — tall stacks, precise restitution (a Newton's
   * cradle), fast joints — at a proportional CPU cost. Lower is not advised.
   */
  substeps?: number;
  /** Override the physics core module URL (rarely needed — the default finds the shipped chunk). */
  module?: string;
}

/** Options for `world.bind`. */
export interface BindOptions {
  /**
   * `'dynamic'` (default) — fully simulated. `'static'` — immovable level
   * geometry (walls, floors). `'kinematic'` — YOU move the sprite
   * (`sprite.x/y` / `sprite.rot` as usual) and it pushes dynamic bodies
   * without being pushed back (moving platforms, doors, paddles).
   */
  type?: 'dynamic' | 'static' | 'kinematic';
  /**
   * Collision shape: `'auto'` (default — a `'box'` the size of the sprite's
   * hitbox), `'box'` (axis of `sprite.w/h`), or `'circle'` (radius from
   * `sprite.w/h`, or `radius`). Balls, wheels and round pickups want `'circle'`.
   */
  shape?: 'auto' | 'box' | 'circle';
  /** Circle radius in world units (circle shape only). Default: half the smaller of `sprite.w/h`. */
  radius?: number;
  /** Surface grip 0..1+. Default `0.6`. */
  friction?: number;
  /** Bounciness 0..1 (a ball at `1` never loses height). Default `0`. */
  bounce?: number;
  /**
   * Mass density (dynamic bodies): mass = density × area. With the default
   * `pixelsPerMeter`, a 32-unit box at density `1` weighs 1 unit. Default `1`.
   */
  density?: number;
  /** Collision group name (see `hits`). Bodies default to the `'default'` group. */
  group?: string;
  /** Group names this body collides with. Omit = collides with everything. */
  hits?: string[];
  /**
   * Family name: bodies sharing a family NEVER collide with each other while
   * still colliding with the rest of the world — the ragdoll / linked-creature
   * knob (limbs must overlap at the joints without shoving each other apart).
   */
  family?: string;
  /** Freeze rotation — the body slides and stacks but never spins (top-down pucks, upright characters, paddles). Default `false`. */
  fixedRotation?: boolean;
  /** Continuous collision for fast movers (bullets) — stops tunnelling through thin walls. Costs a little; set it only on the fast body. Default `false`. */
  bullet?: boolean;
  /** Linear drag (air resistance), 0 = none. Default `0`. */
  damping?: number;
  /** Angular drag. Default `0.05` (spins settle). */
  angularDamping?: number;
  /** Gravity multiplier for this body (`0` = floats, `2` = falls twice as hard). Default `1`. */
  gravityScale?: number;
  /**
   * Shift the centre of mass off the shape's centre, in world units relative to
   * the sprite centre (`+y` = down). A low centre of mass makes a body
   * bottom-heavy so it resists tipping — a car with `balance: { y: 16 }` stays
   * planted and won't wheelie/flip; a roly-poly toy uses a big `+y`. Default:
   * the geometric centre.
   */
  balance?: Vec2;
  /** Sensor mode: overlaps fire `onEnter`/`onExit` but apply NO contact forces (pickup zones, trigger plates, goal areas). */
  trigger?: boolean;
  /** A body entered this trigger (trigger bodies only). */
  onEnter?: (other: Body2d) => void;
  /** A body left this trigger (trigger bodies only). */
  onExit?: (other: Body2d) => void;
  /** Contact started (`speed` = approach speed in units/s — gate impact sounds/damage on it). */
  onHit?: (other: Body2d, speed: number) => void;
  /** Contact began (any speed — standing-on bookkeeping, "what am I touching"). */
  onTouch?: (other: Body2d) => void;
  /** Contact ended — the pair separated (left the platform, dropped the crate). */
  onRelease?: (other: Body2d) => void;
}

/** The bit of the vector layer `debugDraw` needs — `game.vector` satisfies it. */
export interface DebugDrawTarget {
  seg(x0: number, y0: number, x1: number, y1: number, style?: Record<string, unknown>): void;
  poly(points: readonly VecPt[], style?: Record<string, unknown>, closed?: boolean): void;
  arc(cx: number, cy: number, r: number, from: number, to: number, style?: Record<string, unknown>, steps?: number): void;
}

/** Options for `world.debugDraw`. */
export interface DebugDrawOptions {
  /** Awake dynamic/kinematic bodies (default '#39f0a0'). */
  color?: string;
  /** Bodies Box2D has put to sleep (default '#2b5da0') — seeing them go quiet
   *  is half the value of a debug view. */
  sleepColor?: string;
  /** Static geometry (default '#4a6fa5'). */
  staticColor?: string;
  width?: number;
  glow?: number;
  /** Segments per circle (default 16). */
  circleSteps?: number;
}

/** Options for `world.chain` — static line geometry has no mass or density. */
export interface ChainOptions {
  /** Join the last point back to the first (a rim, a closed arena). */
  loop?: boolean;
  friction?: number;
  bounce?: number;
  group?: string;
  hits?: string[];
  onHit?: (other: Body2d, speed: number) => void;
  onTouch?: (other: Body2d) => void;
  onRelease?: (other: Body2d) => void;
}

/** Options for `world.bindShape` — `BindOptions` with the shape modes a vector
 *  outline needs instead of a sprite's box/circle. */
export interface BindShapeOptions extends Omit<BindOptions, 'shape' | 'radius'> {
  /**
   * `'hull'` (default) — the convex hull of the outline, reduced to Box2D's
   * eight-vertex limit. `'box'` — the outline's bounding box. `'circle'` — a
   * disc covering it (or `radius`). `'decompose'` — split a CONCAVE outline
   * into convex pieces, all on this one body, so a ship's notch is a real
   * notch instead of being filled in by the hull.
   *
   * `'hull'` is the right default for line art and much the cheaper of the
   * two; reach for `'decompose'` when the dent matters to play.
   */
  shape?: 'hull' | 'box' | 'circle' | 'decompose';
  /** Circle radius in world units (circle shape only). Default: the outline's
   *  furthest point from its origin. */
  radius?: number;
  /** Cap the hull's vertex count (default 8, Box2D's own limit). */
  maxVertices?: number;
}

/** A physics joint. Call `destroy()` to break it (the bodies stay). */
export interface Joint2d {
  destroy(): void;
  /**
   * Drive (or brake) the joint's motor at runtime — the knob for powered wheels,
   * pinball flippers, elevators and gears. On a `pin` joint, `speed` is rad/s
   * (screen-clockwise) and `effort` a torque budget; on a `slider`, `speed` is
   * units/s along its axis and `effort` a force budget. `speed: 0` with a budget
   * holds position; omit `effort` to keep the previous budget. A no-op on
   * `rope`/`weld` joints (they have no motor). Enables the motor on first call.
   */
  motor(speed: number, effort?: number): void;
}

/** Options for `world.pin` (revolute joint — a hinge / pivot). */
export interface PinOptions {
  /** World-space pivot point. Default: the midpoint between the two bodies. */
  at?: Vec2;
  /** Swing limits in radians `[min, max]`. Omit for free spin. */
  limits?: [number, number];
  /** Drive the hinge at this angular speed (rad/s, screen-clockwise +) with `maxTorque` budget — a motor / powered wheel. */
  motorSpeed?: number;
  /** Torque budget for `motorSpeed`. Required if you set a motor. */
  maxTorque?: number;
}

/** Options for `world.rope` (distance joint — a rod / rope / spring). */
export interface RopeOptions {
  /** Rest length in world units. Default: the current distance between the anchor points. */
  length?: number;
  /** Min/max length — a rope that can go slack but not stretch (`[0, length]`), or a rigid rod (`[length, length]`, the default). */
  range?: [number, number];
  /** Springiness in Hz (0 = rigid rod, 4 = bouncy tether). Default `0`. */
  hertz?: number;
  /** Spring damping 0..1 (only with `hertz`). Default `0.5`. */
  damping?: number;
  /** Anchor point on body A (world space). Default: A's centre. */
  atA?: Vec2;
  /** Anchor point on body B (world space). Default: B's centre. */
  atB?: Vec2;
}

/** Options for `world.slider` (prismatic joint — motion along one axis only). */
export interface SliderOptions {
  /** World-space axis the body slides along (any length). Default `{x:1, y:0}` (horizontal). */
  axis?: Vec2;
  /** Travel limits along the axis `[min, max]`. Omit for free travel. */
  limits?: [number, number];
  /** Drive along the axis at this speed (units/s) with `maxForce` budget — a powered piston / elevator. */
  motorSpeed?: number;
  /** Force budget for `motorSpeed`. */
  maxForce?: number;
}

/** Options for `world.wheel` (a spring-suspension car axle). */
export interface WheelOptions {
  /** World-space attach point — the wheel's centre. */
  at: Vec2;
  /** Suspension direction the wheel travels along (any length). Default `{x:0, y:1}` (vertical). */
  axis?: Vec2;
  /** Suspension spring frequency in Hz (stiffness). Default `4`. */
  hertz?: number;
  /** Suspension damping ratio 0..1. Default `0.7`. */
  damping?: number;
  /** Suspension travel limits along the axis `[min, max]`. Omit for free travel. */
  travel?: [number, number];
  /** Drive the wheel at this angular speed (rad/s, screen-clockwise) — set with `maxTorque`, or drive live via the returned joint's `motor()`. */
  motorSpeed?: number;
  /** Drive torque budget for the motor. */
  maxTorque?: number;
}

/** Options for `world.grab`. */
export interface GrabOptions {
  /**
   * `true` (default) is a firm, responsive grab — the clicked point tracks the
   * pointer closely with little lag, and the body rotates naturally to follow
   * (it dangles from the grab point). `false` is a soft, springy rubber-band
   * pull — good for slingshots and tractor beams. Both cap their force so a
   * dragged jointed body (a ragdoll) never gets torn apart.
   */
  stiff?: boolean;
  /** Pull strength for the elastic (`stiff: false`) mode — higher snaps harder. Default `1`. */
  strength?: number;
}

/** A drag handle from `world.grab` — a mouse/touch joint. Move the target each frame, then release. */
export interface Grab2d {
  /** Move the grab target to a new world point (call each frame with the pointer). */
  moveTo(point: Vec2): void;
  /** Let go — the body keeps whatever velocity it had, so a moving release throws it. */
  release(): void;
}

/** A ray hit. */
export interface RayHit {
  /** The body the ray struck. */
  body: Body2d;
  /** World hit point. */
  point: Vec2;
  /** Surface normal at the hit (unit vector). */
  normal: Vec2;
  /** Distance from the ray origin in world units. */
  distance: number;
}

/**
 * A physics body driving (dynamic) or moved-by (kinematic/static) a sprite. Get
 * one from `world.bind(sprite, ...)`. Steer dynamic bodies with
 * `impulse`/`force`/`velocity`; read `velocity`/`mass`; break with `destroy()`.
 */
export class Body2d {
  /**
   * The sprite this body drives (dynamic) or follows (kinematic/static).
   *
   * `undefined` on a body bound to a VECTOR SHAPE — check `shape` instead, or
   * `target` for whichever it is.
   */
  readonly sprite!: Sprite;
  /** The vector shape this body drives, if it was bound with `bindShape`. */
  readonly shape?: VectorShape;
  /** Whichever of the two this body drives — `sprite` or `shape`. */
  readonly target: Sprite | VectorShape;
  /** `'sprite'` (top-left anchored, needs the half-size offset) or `'shape'`
   *  (origin-centred, the body pose maps straight on). */
  readonly kind: 'sprite' | 'shape';
  /** `'dynamic' | 'static' | 'kinematic'`. */
  readonly type: 'dynamic' | 'static' | 'kinematic';
  /** Contact started (approach speed in units/s). Assign any time. */
  onHit: ((other: Body2d, speed: number) => void) | null = null;
  /** Contact began / ended (any speed). */
  onTouch: ((other: Body2d) => void) | null = null;
  onRelease: ((other: Body2d) => void) | null = null;
  /** Trigger callbacks (trigger bodies). */
  onEnter: ((other: Body2d) => void) | null = null;
  onExit: ((other: Body2d) => void) | null = null;

  /** @internal */ _body: Id;
  /** @internal */ readonly _world: Physics2d;
  /** @internal Half the sprite hitbox at bind time — offsets centre↔top-left on sync. */
  readonly _halfW: number;
  /** @internal */ readonly _halfH: number;
  /** @internal Set once destroyed — every later call is a safe no-op. */
  _dead = false;
  /** @internal Pose history for render interpolation: [cx, cy, angle] at the previous and latest fixed step (screen units / screen radians). */
  _pose0 = new Float32Array(3);
  _pose1 = new Float32Array(3);

  /** @internal */
  constructor(w: Physics2d, body: Id, target: Sprite | VectorShape, type: 'dynamic' | 'static' | 'kinematic', kind: 'sprite' | 'shape' = 'sprite') {
    this._world = w;
    this._body = body;
    this.target = target;
    this.kind = kind;
    this.type = type;
    if (kind === 'sprite') {
      const sp = target as Sprite;
      this.sprite = sp;
      // A sprite is anchored top-LEFT, so every sync has to offset by half.
      this._halfW = sp.w / 2;
      this._halfH = sp.h / 2;
    } else {
      this.shape = target as VectorShape;
      // A vector shape is already origin-centred — no offset at all. That is
      // why line art is the easier of the two to bind.
      this._halfW = 0;
      this._halfH = 0;
    }
  }

  /** @internal Write a world pose onto whichever target this body drives. */
  _writePose(cx: number, cy: number, angle: number): void {
    if (this.kind === 'sprite') {
      this.sprite.x = cx - this._halfW;
      this.sprite.y = cy - this._halfH;
      this.sprite.rot = angle;
    } else {
      const sh = this.shape!;
      sh.x = cx;
      sh.y = cy;
      sh.rot = angle;
    }
  }

  /** Current velocity in units/s (screen space). */
  get velocity(): Vec2 {
    const b2 = this._world._b2;
    const v = b2.b2Body_GetLinearVelocity(this._body);
    const out = { x: this._world._fromBox(v.x), y: -this._world._fromBox(v.y) };
    v.delete();
    return out;
  }
  set velocity(v: Vec2) {
    const w = this._world, b2 = w._b2;
    w._scratch.Set(w._toBox(v.x), -w._toBox(v.y));
    b2.b2Body_SetLinearVelocity(this._body, w._scratch);
    b2.b2Body_SetAwake(this._body, true);
  }

  /** Angular velocity in rad/s (screen-clockwise positive). */
  get spin(): number {
    return -this._world._b2.b2Body_GetAngularVelocity(this._body);
  }
  set spin(v: number) {
    const b2 = this._world._b2;
    b2.b2Body_SetAngularVelocity(this._body, -v);
    b2.b2Body_SetAwake(this._body, true);
  }

  /** The body's mass. */
  get mass(): number {
    return this._world._b2.b2Body_GetMass(this._body);
  }

  /**
   * Instant kick in units/s (screen space): `impulse({y: -400})` pops the body
   * upward, scaled by mass so the same call gives the same launch speed whatever
   * the body weighs. Pass `at` (world point) to also spin it — off-centre hits
   * tumble.
   */
  impulse(v: Partial<Vec2>, at?: Vec2): void {
    const w = this._world, b2 = w._b2;
    const m = this.mass || 1;
    w._scratch.Set(w._toBox((v.x ?? 0) * m), -w._toBox((v.y ?? 0) * m));
    if (at) {
      w._scratch2.Set(w._toBox(at.x), -w._toBox(at.y));
      b2.b2Body_ApplyLinearImpulse(this._body, w._scratch, w._scratch2, true);
    } else {
      b2.b2Body_ApplyLinearImpulseToCenter(this._body, w._scratch, true);
    }
  }

  /** Continuous push in units/s² (accumulates until the next step) — thrusters, wind. Mass-scaled like `impulse`. */
  force(v: Partial<Vec2>): void {
    const w = this._world, b2 = w._b2;
    const m = this.mass || 1;
    w._scratch.Set(w._toBox((v.x ?? 0) * m), -w._toBox((v.y ?? 0) * m));
    b2.b2Body_ApplyForceToCenter(this._body, w._scratch, true);
  }

  /**
   * Spin the body: **angular acceleration in rad/s²**, screen-clockwise
   * positive, accumulating until the next step. Wakes the body.
   *
   * Scaled by the body's own rotational inertia, exactly as `force` is scaled
   * by its mass — so the number means the same thing on a pebble and on a
   * chassis, and `torque(4)` reaches 4 rad/s in a second (less whatever
   * `angularDamping` takes back). Raw Box2D torque is in kg·m² and a small
   * sprite's inertia is a fraction of one, so an unscaled value that looks
   * modest spins a light body into a blur.
   */
  torque(t: number): void {
    const b2 = this._world._b2;
    const i = b2.b2Body_GetRotationalInertia(this._body) || 1;
    b2.b2Body_ApplyTorque(this._body, -t * i, true);            // 3rd arg = wake
  }

  /** The body's rotational inertia — what `torque` scales by, as `mass` is what
   *  `force` scales by. */
  get inertia(): number {
    return this._world._b2.b2Body_GetRotationalInertia(this._body);
  }

  /** Instantly move the body (and its sprite) to a world position (its CENTRE) — respawns. Clears velocity. Optional `angle` in screen-clockwise radians. */
  teleport(position: Vec2, angle: number = 0): void {
    const w = this._world, b2 = w._b2;
    w._scratch.Set(w._toBox(position.x), -w._toBox(position.y));
    const rot = b2.b2MakeRot(-angle);
    b2.b2Body_SetTransform(this._body, w._scratch, rot);
    rot.delete();
    b2.b2Body_SetLinearVelocity(this._body, w._zeroVec);
    b2.b2Body_SetAngularVelocity(this._body, 0);
    b2.b2Body_SetAwake(this._body, true);
    // Write the target + reset interpolation history so a respawn never smears.
    this._writePose(position.x, position.y, angle);
    this._seedPose(position.x, position.y, angle);
  }

  /** @internal Seed both history slots (spawn/teleport — never smear across a jump). */
  _seedPose(cx: number, cy: number, angle: number): void {
    this._pose0[0] = this._pose1[0] = cx;
    this._pose0[1] = this._pose1[1] = cy;
    this._pose0[2] = this._pose1[2] = angle;
  }

  /**
   * Remove this body from the world (the sprite stays where it was — kill it
   * separately if you want it gone). Safe to call twice.
   */
  destroy(): void {
    if (this._dead) return;
    this._dead = true;
    this._world._removeBody(this);
  }
}

/**
 * The physics world. `await Physics2d.create()` once in an async `setup()`, bind
 * sprites, attach to the scene (`scene.physics2d = world`) and everything
 * else is hands-free — the scene steps and syncs it each frame. All shapes are
 * built from each sprite's CURRENT `x/y/w/h` at bind time — place the sprite
 * first, bind second.
 */
export class Physics2d {
  /** @internal The core module. */ _b2: B2;
  /** @internal */ private world: Id;
  /** @internal world units per simulated metre. */ private readonly ppm: number;
  /** @internal solver sub-steps per frame. */ private readonly substeps: number;
  /** @internal All live bodies by id key (event lookups). */
  private readonly bodies = new Map<string, Body2d>();
  /** @internal Sprite → body (rebind guards). */
  private readonly bySprite = new Map<Sprite, Body2d>();
  /** @internal Vector shape → body (rebind guards). */
  private readonly byShape = new Map<VectorShape, Body2d>();
  /** @internal Kinematic bodies (sprite drives body each step). */
  private readonly kinematics: Body2d[] = [];
  /** @internal Collision group name → category bit. */
  private readonly groups = new Map<string, number>();
  /** @internal Family name → negative filter-group index (self-collision off). */
  private readonly families = new Map<string, number>();
  /** @internal Active grabs (mouse joints). `lx`/`ly` = the clicked point in the body's local frame (box units). A force-capped velocity servo drives that point to `tx`/`ty`: `gain` sets responsiveness, `vmax` caps the follow speed, `maxAcc` caps the force so a jointed body can't be torn apart. */
  private readonly grabs: { body: Body2d; tx: number; ty: number; lx: number; ly: number; gain: number; vmax: number; maxAcc: number }[] = [];
  /** @internal Fixed-step accumulator. */ private acc = 0;
  /** @internal Reusable Box2D vectors (avoid per-call handle allocation). */
  _scratch: B2; _scratch2: B2; _zeroVec: B2;
  /** Diagnostic: bodies found stale during sync (should stay 0). */
  invalidBodies = 0;

  private constructor(b2: B2, world: Id, ppm: number, substeps: number) {
    this._b2 = b2;
    this.world = world;
    this.ppm = ppm;
    this.substeps = substeps;
    this._scratch = new b2.b2Vec2(0, 0);
    this._scratch2 = new b2.b2Vec2(0, 0);
    this._zeroVec = new b2.b2Vec2(0, 0);
  }

  /** @internal units → metres (lengths). */ _toBox(px: number): number { return px / this.ppm; }
  /** @internal metres → units (lengths). */ _fromBox(m: number): number { return m * this.ppm; }

  /**
   * Load the physics core (first call fetches the ~640 KB chunk; later calls are
   * instant) and create a world. One world per scene is the pattern.
   */
  static async create(opts: Physics2dOptions = {}): Promise<Physics2d> {
    const b2 = await loadCore(opts.module);
    const ppm = opts.pixelsPerMeter ?? 32;
    const def = b2.b2DefaultWorldDef();
    const g = opts.gravity ?? 900;
    // Screen-down (+y units) maps to Box2D-down (−y m). Scale units/s² → m/s².
    const gx = typeof g === 'number' ? 0 : g.x / ppm;
    const gy = typeof g === 'number' ? -g / ppm : -g.y / ppm;
    const gv = new b2.b2Vec2(gx, gy);
    def.gravity = gv;
    const world = b2.b2CreateWorld(def);
    gv.delete();
    def.delete();
    return new Physics2d(b2, world, ppm, Math.max(1, Math.round(opts.substeps ?? 4)));
  }

  /** @internal Category bit for a group name (created on first use, up to 32 groups). */
  private groupBit(name: string): number {
    let bit = this.groups.get(name);
    if (bit === undefined) {
      if (this.groups.size >= 31) throw new Error('Physics2d: too many collision groups (max 32).');
      bit = 1 << this.groups.size;
      this.groups.set(name, bit);
    }
    return bit;
  }

  /** @internal Negative filter-group index for a family (same index → never collide). */
  private familyIndex(family: string): number {
    let idx = this.families.get(family);
    if (idx === undefined) {
      idx = -(this.families.size + 1);
      this.families.set(family, idx);
    }
    return idx;
  }

  /**
   * Give a sprite a physics body. The shape is built from `sprite.w/h` and
   * `sprite.x/y` as they are RIGHT NOW — place the sprite first. Returns the
   * `Body2d`; dynamic bodies then own the sprite's `x/y` and `rot`.
   */
  bind(sprite: Sprite, opts: BindOptions = {}): Body2d {
    const existing = this.bySprite.get(sprite);
    if (existing) return existing;
    const b2 = this._b2;
    const type = opts.type ?? 'dynamic';

    const def = b2.b2DefaultBodyDef();
    const cx = sprite.x + sprite.w / 2;
    const cy = sprite.y + sprite.h / 2;
    const pos = new b2.b2Vec2(this._toBox(cx), -this._toBox(cy));
    def.position = pos;
    const rot = b2.b2MakeRot(-sprite.rot);
    def.rotation = rot;
    def.type = type === 'dynamic' ? b2.b2BodyType.b2_dynamicBody
      : type === 'kinematic' ? b2.b2BodyType.b2_kinematicBody
      : b2.b2BodyType.b2_staticBody;
    if (opts.bullet) def.isBullet = true;
    if (opts.damping !== undefined) def.linearDamping = opts.damping;
    def.angularDamping = opts.angularDamping ?? 0.05;
    if (opts.gravityScale !== undefined) def.gravityScale = opts.gravityScale;
    if (opts.fixedRotation) {
      const locks = def.motionLocks;
      locks.angularZ = true;
      def.motionLocks = locks;
    }
    const body = b2.b2CreateBody(this.world, def);
    pos.delete();
    rot.delete();
    def.delete();

    // Shape — the same definition builder the vector path uses, so material,
    // filters and event flags cannot drift between the two.
    const sd = this._shapeDef(opts);

    let shape = opts.shape ?? 'auto';
    if (shape === 'auto') shape = 'box';
    if (shape === 'circle') {
      const r = this._toBox(opts.radius ?? Math.min(sprite.w, sprite.h) / 2);
      const circle = new b2.b2Circle();
      circle.center = this._zeroVec;
      circle.radius = r;
      b2.b2CreateCircleShape(body, sd, circle);
      circle.delete();
    } else {
      const poly = b2.b2MakeBox(this._toBox(sprite.w / 2), this._toBox(sprite.h / 2));
      b2.b2CreatePolygonShape(body, sd, poly);
      poly.delete();
    }
    sd.delete();

    // Optional centre-of-mass shift (bottom-heavy = won't tip): move the local
    // CoM off the shape centre, keeping the shape-derived mass and inertia.
    if (opts.balance) {
      const md = b2.b2Body_GetMassData(body);
      const c = new b2.b2Vec2(this._toBox(opts.balance.x), -this._toBox(opts.balance.y));
      md.center = c;
      b2.b2Body_SetMassData(body, md);
      c.delete();
      md.delete?.();
    }

    const b = new Body2d(this, body, sprite, type);
    b.onHit = opts.onHit ?? null;
    b.onTouch = opts.onTouch ?? null;
    b.onRelease = opts.onRelease ?? null;
    b.onEnter = opts.onEnter ?? null;
    b.onExit = opts.onExit ?? null;
    b._seedPose(cx, cy, sprite.rot);
    this.bodies.set(idKey(body), b);
    this.bySprite.set(sprite, b);
    if (type === 'kinematic') this.kinematics.push(b);
    // Mark the sprite so the arcade integrator leaves it to Box2D.
    (sprite as unknown as { _body2d: Body2d | null })._body2d = b;
    return b;
  }

  /** The `Body2d` bound to a sprite, or `undefined`. */
  bodyFor(sprite: Sprite): Body2d | undefined {
    return this.bySprite.get(sprite);
  }

  /** The `Body2d` bound to a vector shape, or `undefined`. */
  bodyForShape(shape: VectorShape): Body2d | undefined {
    return this.byShape.get(shape);
  }

  /**
   * Give a VECTOR SHAPE a physics body — line art with real rigid-body
   * physics, which is the pairing the two were always going to make.
   *
   * ```ts
   * const rock = game.vector.shape(vectorKit.generatePolygon(40, 11), { x: 300, y: 120, glow: 0.9 });
   * world.bindShape(rock, { bounce: 0.4, friction: 0.3 });
   * ```
   *
   * A vector shape fits Box2D BETTER than a sprite does: it is already
   * origin-centred with live `x`/`y`/`rot`, so the body pose maps onto it with
   * no offset, where a sprite needs a half-size correction every sync.
   *
   * The outline is taken as it is RIGHT NOW, in the shape's own local frame,
   * with `scale` baked in — place and scale the shape first, bind second.
   * Changing `scale` afterwards moves the drawing and NOT the collision shape;
   * rebind if you need it to follow.
   *
   * Shapes are convex: `'hull'` (the default) takes the convex hull of the
   * outline and reduces it to Box2D's eight-vertex limit, so a jagged
   * eleven-point asteroid still collides as its own silhouette rather than
   * silently becoming a null shape.
   */
  bindShape(shape: VectorShape, opts: BindShapeOptions = {}): Body2d {
    const existing = this.byShape.get(shape);
    if (existing) return existing;
    const b2 = this._b2;
    const type = opts.type ?? 'dynamic';
    const scale = shape.scale ?? 1;

    // Local outline, scale baked in. NOT re-centred on its centroid — Box2D
    // works out centroid/mass/inertia in body-local space, and re-centring is
    // what makes a shape spin about a point it isn't drawn around.
    const local: VecPt[] = [];
    for (const [a, b] of shape.segs) {
      local.push({ x: a.x * scale, y: a.y * scale });
      local.push({ x: b.x * scale, y: b.y * scale });
    }

    const def = b2.b2DefaultBodyDef();
    const pos = new b2.b2Vec2(this._toBox(shape.x), -this._toBox(shape.y));
    def.position = pos;
    const rot = b2.b2MakeRot(-shape.rot);
    def.rotation = rot;
    def.type = type === 'dynamic' ? b2.b2BodyType.b2_dynamicBody
      : type === 'kinematic' ? b2.b2BodyType.b2_kinematicBody
      : b2.b2BodyType.b2_staticBody;
    if (opts.bullet) def.isBullet = true;
    if (opts.damping !== undefined) def.linearDamping = opts.damping;
    def.angularDamping = opts.angularDamping ?? 0.05;
    if (opts.gravityScale !== undefined) def.gravityScale = opts.gravityScale;
    if (opts.fixedRotation) {
      const locks = def.motionLocks;
      locks.angularZ = true;
      def.motionLocks = locks;
    }
    const body = b2.b2CreateBody(this.world, def);
    pos.delete();
    rot.delete();
    def.delete();

    const sd = this._shapeDef(opts);
    const kind = opts.shape ?? 'hull';
    if (kind === 'circle') {
      let r = opts.radius;
      if (r === undefined) {
        let m = 0;
        for (const p of local) m = Math.max(m, Math.hypot(p.x, p.y));
        r = m || 1;
      }
      const circle = new b2.b2Circle();
      circle.center = this._zeroVec;
      circle.radius = this._toBox(r);
      b2.b2CreateCircleShape(body, sd, circle);
      circle.delete();
    } else if (kind === 'box') {
      let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
      for (const p of local) {
        minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x);
        minY = Math.min(minY, p.y); maxY = Math.max(maxY, p.y);
      }
      const poly = b2.b2MakeOffsetBox(
        this._toBox((maxX - minX) / 2 || 1), this._toBox((maxY - minY) / 2 || 1),
        new b2.b2Vec2(this._toBox((minX + maxX) / 2), -this._toBox((minY + maxY) / 2)),
        b2.b2MakeRot(0),
      );
      b2.b2CreatePolygonShape(body, sd, poly);
      poly.delete();
    } else if (kind === 'decompose') {
      // One body, several convex fixtures. The outline is the shape's own
      // vertex ring, not the doubled-up segment endpoints.
      for (const piece of convexPieces(this._ringOf(shape, scale), opts.maxVertices)) {
        this._polygonShape(body, sd, piece);
      }
    } else {
      this._polygonShape(body, sd, hullFor(local, opts.maxVertices));
    }
    sd.delete();

    if (opts.balance) {
      const md = b2.b2Body_GetMassData(body);
      const c = new b2.b2Vec2(this._toBox(opts.balance.x), -this._toBox(opts.balance.y));
      md.center = c;
      b2.b2Body_SetMassData(body, md);
      c.delete();
      md.delete?.();
    }

    const b = new Body2d(this, body, shape, type, 'shape');
    b.onHit = opts.onHit ?? null;
    b.onTouch = opts.onTouch ?? null;
    b.onRelease = opts.onRelease ?? null;
    b.onEnter = opts.onEnter ?? null;
    b.onExit = opts.onExit ?? null;
    b._seedPose(shape.x, shape.y, shape.rot);
    this.bodies.set(idKey(body), b);
    this.byShape.set(shape, b);
    if (type === 'kinematic') this.kinematics.push(b);
    return b;
  }

  /**
   * A STATIC CHAIN body from a polyline — terrain, cave walls, a tube rim, a
   * ring of arcs. This is the shape Box2D wants for one-sided world geometry:
   * no thickness, no mass, and no internal edges for a fast body to catch on.
   *
   * ```ts
   * const ground = vectorKit.generateTerrain({ width: 1400, baseY: 600 });
   * game.vector.shape(ground, { closed: false, color: '#39f0a0' });
   * world.chain(ground, { friction: 0.9 });
   * ```
   *
   * `loop: true` closes it — which is exactly what `web.closed` and a closed
   * `ringSections` ring mean. Returns the body so you can `destroy()` it and
   * rebuild after deforming the line (a crater re-chains that stretch).
   *
   * A chain is ONE-SIDED. Points left-to-right along the top of your terrain
   * gives solid ground below, which is what a heightfield from
   * `generateTerrain` already is. Reverse the order (or the loop's winding) to
   * put the solid side on the other face — a ceiling, or a cave you are inside.
   */
  chain(points: readonly VecPt[], opts: ChainOptions = {}): Body2d {
    const b2 = this._b2;
    if (points.length < 2) throw new Error('Physics2d.chain: needs at least two points');
    if (!(opts.loop ?? false) && points.length < 2) throw new Error('Physics2d.chain: an open chain needs at least two points');
    const def = b2.b2DefaultBodyDef();
    def.type = b2.b2BodyType.b2_staticBody;
    const body = b2.b2CreateBody(this.world, def);
    def.delete();

    const loop = opts.loop ?? false;
    // GHOST VERTICES. An OPEN Box2D v3 chain treats its first and last points
    // as ghosts and builds only `count - 3` segments from the rest — hand it
    // your polyline raw and two thirds of a short one silently does not exist.
    // Extrapolating a ghost past each end gives every real edge a segment AND
    // gives Box2D the neighbour directions it wants for smooth end collisions.
    // A LOOP has no ends, so it needs none of this.
    const pts = loop ? points.slice() : [
      { x: points[0].x * 2 - points[1].x, y: points[0].y * 2 - points[1].y },
      ...points,
      {
        x: points[points.length - 1].x * 2 - points[points.length - 2].x,
        y: points[points.length - 1].y * 2 - points[points.length - 2].y,
      },
    ];
    // WINDING. A Box2D chain is ONE-SIDED: it only collides from the side its
    // normals face, which is the left of the direction of travel. Flipping y
    // into Box2D's y-up frame mirrors the polyline and so REVERSES that side —
    // terrain built left-to-right ends up solid from below and everything
    // falls straight through it. Reversing the order after the flip puts the
    // solid side back where the screen-space winding says it should be.
    const box = pts.map((p) => ({ x: this._toBox(p.x), y: -this._toBox(p.y) })).reverse();
    const cd = b2.b2DefaultChainDef();
    cd.SetPoints(box);
    cd.count = box.length;
    cd.isLoop = loop;
    const mats = b2.b2DefaultSurfaceMaterial ? [b2.b2DefaultSurfaceMaterial()] : null;
    if (mats) {
      mats[0].friction = opts.friction ?? 0.6;
      mats[0].restitution = opts.bounce ?? 0;
      cd.SetMaterials(mats);
      cd.materialCount = 1;
    }
    const filter = cd.filter;
    filter.categoryBits = this.groupBit(opts.group ?? 'default');
    if (opts.hits) {
      let mask = 0;
      for (const h of opts.hits) mask |= this.groupBit(h);
      filter.maskBits = mask;
    }
    cd.filter = filter;
    b2.b2CreateChain(body, cd);
    cd.delete?.();

    const b = new Body2d(this, body, CHAIN_TARGET, 'static', 'shape');
    b.onHit = opts.onHit ?? null;
    b.onTouch = opts.onTouch ?? null;
    b.onRelease = opts.onRelease ?? null;
    this.bodies.set(idKey(body), b);
    return b;
  }

  /**
   * A CAPSULE body for one thick stroke — a rod, a beam, a girder. The right
   * primitive for a line with width: a two-point polygon is degenerate, and a
   * box has corners a capsule does not.
   */
  capsule(x0: number, y0: number, x1: number, y1: number, radius: number, opts: BindShapeOptions = {}): Body2d {
    const b2 = this._b2;
    const cx = (x0 + x1) / 2, cy = (y0 + y1) / 2;
    const def = b2.b2DefaultBodyDef();
    const type = opts.type ?? 'dynamic';
    const pos = new b2.b2Vec2(this._toBox(cx), -this._toBox(cy));
    def.position = pos;
    def.type = type === 'dynamic' ? b2.b2BodyType.b2_dynamicBody
      : type === 'kinematic' ? b2.b2BodyType.b2_kinematicBody
      : b2.b2BodyType.b2_staticBody;
    def.angularDamping = opts.angularDamping ?? 0.05;
    const body = b2.b2CreateBody(this.world, def);
    pos.delete();
    def.delete();

    const sd = this._shapeDef(opts);
    const cap = new b2.b2Capsule();
    cap.center1 = new b2.b2Vec2(this._toBox(x0 - cx), -this._toBox(y0 - cy));
    cap.center2 = new b2.b2Vec2(this._toBox(x1 - cx), -this._toBox(y1 - cy));
    cap.radius = this._toBox(radius);
    b2.b2CreateCapsuleShape(body, sd, cap);
    cap.delete?.();
    sd.delete();

    const b = new Body2d(this, body, CHAIN_TARGET, type, 'shape');
    b.onHit = opts.onHit ?? null;
    b._seedPose(cx, cy, 0);
    this.bodies.set(idKey(body), b);
    if (type === 'kinematic') this.kinematics.push(b);
    return b;
  }

  /**
   * Draw the whole physics world as LINE ART, through the vector layer.
   *
   * ```ts
   * override draw(d: Draw): void {
   *   super.draw(d);
   *   this.world.debugDraw(this.game.vector);
   * }
   * ```
   *
   * Every shape Box2D is actually simulating, in its actual pose — the fastest
   * way to see that a hull came out the shape you meant, that a chain is on the
   * side you meant, or that a sensor is where you meant. It works for SPRITE
   * bodies too, so an ordinary sprite game gets a glowing collision overlay for
   * one line.
   *
   * Built on the typed shape API (`b2Body_GetShapes` + `b2Shape_GetPolygon` and
   * friends) rather than Box2D's own debug-draw command buffer: that buffer is
   * an undocumented 140-byte packed struct, and reading it means hard-coding
   * offsets that a Box2D bump would silently move.
   */
  debugDraw(layer: DebugDrawTarget, opts: DebugDrawOptions = {}): void {
    const b2 = this._b2;
    const width = opts.width ?? 1.6;
    const glow = opts.glow ?? 0.55;
    const awake = opts.color ?? '#39f0a0';
    const asleep = opts.sleepColor ?? '#2b5da0';
    const staticColor = opts.staticColor ?? '#4a6fa5';
    const sides = opts.circleSteps ?? 16;

    for (const body of this.bodies.values()) {
      if (body._dead || !b2.b2Body_IsValid(body._body)) continue;
      const xf = b2.b2Body_GetTransform(body._body);
      const px = this._fromBox(xf.p.x), py = -this._fromBox(xf.p.y);
      // Box2D's y-up rotation read back into screen space: the sine flips.
      const c = xf.q.c, sn = -xf.q.s;
      const style = {
        width, glow,
        color: body.type === 'static' ? staticColor
          : b2.b2Body_IsAwake(body._body) ? awake : asleep,
      };
      // Shape-local (already y-up-flipped) → world screen space.
      const at = (lx: number, ly: number): VecPt => {
        const x = this._fromBox(lx), y = -this._fromBox(ly);
        return { x: px + x * c - y * sn, y: py + x * sn + y * c };
      };
      const n = b2.b2Body_GetShapeCount(body._body);
      if (!n) continue;
      for (const sh of b2.b2Body_GetShapes(body._body, n) as B2[]) {
        const t = String(b2.b2Shape_GetType(sh)?.value ?? b2.b2Shape_GetType(sh));
        const T = b2.b2ShapeType;
        if (t === String(T.b2_polygonShape.value ?? 3)) {
          const poly = b2.b2Shape_GetPolygon(sh);
          const pts: VecPt[] = [];
          for (let i = 0; i < poly.count; i++) {
            const v = poly.GetVertex(i);
            pts.push(at(v.x, v.y));
          }
          if (pts.length > 1) layer.poly(pts, style, true);
        } else if (t === String(T.b2_circleShape.value ?? 0)) {
          const ci = b2.b2Shape_GetCircle(sh);
          const o = at(ci.center.x, ci.center.y);
          const r = this._fromBox(ci.radius);
          layer.arc(o.x, o.y, r, 0, Math.PI * 2, style, sides);
          // A spoke, so rotation is visible on a rolling disc.
          const a = Math.atan2(sn, c);
          layer.seg(o.x, o.y, o.x + Math.cos(a) * r, o.y + Math.sin(a) * r, style);
        } else if (t === String(T.b2_capsuleShape.value ?? 1)) {
          const cap = b2.b2Shape_GetCapsule(sh);
          const a = at(cap.center1.x, cap.center1.y);
          const b = at(cap.center2.x, cap.center2.y);
          const r = this._fromBox(cap.radius);
          const ang = Math.atan2(b.y - a.y, b.x - a.x);
          const nx = -Math.sin(ang) * r, ny = Math.cos(ang) * r;
          layer.seg(a.x + nx, a.y + ny, b.x + nx, b.y + ny, style);
          layer.seg(a.x - nx, a.y - ny, b.x - nx, b.y - ny, style);
          layer.arc(a.x, a.y, r, ang + Math.PI / 2, ang + Math.PI * 1.5, style, sides / 2);
          layer.arc(b.x, b.y, r, ang - Math.PI / 2, ang + Math.PI / 2, style, sides / 2);
        } else {
          // Segment and chain-segment both read back as two points.
          const seg = t === String(T.b2_chainSegmentShape.value ?? 4)
            ? b2.b2Shape_GetChainSegment(sh)?.segment
            : b2.b2Shape_GetSegment(sh);
          if (seg) {
            const a = at(seg.point1.x, seg.point1.y);
            const b = at(seg.point2.x, seg.point2.y);
            layer.seg(a.x, a.y, b.x, b.y, style);
          }
        }
      }
    }
  }

  /** @internal One convex polygon from LOCAL points (y flipped into Box2D's
   *  y-up frame). Silently does nothing if the hull degenerates. */
  private _polygonShape(body: Id, sd: B2, pts: readonly VecPt[]): void {
    const b2 = this._b2;
    if (pts.length < 3) return;
    const hull = b2.b2ComputeHull(pts.map((p) => ({ x: this._toBox(p.x), y: -this._toBox(p.y) })));
    if (!hull || hull.count < 3) { hull?.delete?.(); return; }
    const poly = b2.b2MakePolygon(hull, 0);
    b2.b2CreatePolygonShape(body, sd, poly);
    poly.delete?.();
    hull.delete?.();
  }

  /** @internal The shared shape definition — material, filters, events. */
  private _shapeDef(opts: Omit<BindOptions, 'shape' | 'radius'>): B2 {
    const b2 = this._b2;
    const sd = b2.b2DefaultShapeDef();
    sd.density = opts.density ?? 1;
    const mat = sd.material;
    mat.friction = opts.friction ?? 0.6;
    mat.restitution = opts.bounce ?? 0;
    sd.material = mat;
    sd.enableContactEvents = true;
    sd.enableHitEvents = true;
    sd.enableSensorEvents = true;
    if (opts.trigger) sd.isSensor = true;
    const filter = sd.filter;
    filter.categoryBits = this.groupBit(opts.group ?? 'default');
    if (opts.hits) {
      let mask = 0;
      for (const h of opts.hits) mask |= this.groupBit(h);
      filter.maskBits = mask;
    }
    if (opts.family) filter.groupIndex = this.familyIndex(opts.family);
    sd.filter = filter;
    return sd;
  }

  /**
   * Cast a ray from `from` to `to` (both world space); returns the nearest body
   * hit, or `null`. Line-of-sight, laser sights, ground probes.
   */
  raycast(from: Vec2, to: Vec2): RayHit | null {
    const b2 = this._b2;
    const origin = new b2.b2Vec2(this._toBox(from.x), -this._toBox(from.y));
    const translation = new b2.b2Vec2(this._toBox(to.x - from.x), -this._toBox(to.y - from.y));
    const filter = b2.b2DefaultQueryFilter();
    const res = b2.b2World_CastRayClosest(this.world, origin, translation, filter);
    let out: RayHit | null = null;
    if (res.hit) {
      const body = this.bodies.get(idKey(b2.b2Shape_GetBody(res.shapeId)));
      if (body) {
        const p = res.point, n = res.normal;
        const px = this._fromBox(p.x), py = -this._fromBox(p.y);
        out = {
          body,
          point: { x: px, y: py },
          normal: { x: n.x, y: -n.y },
          distance: Math.hypot(px - from.x, py - from.y),
        };
      }
    }
    origin.delete();
    translation.delete();
    filter.delete?.();
    res.delete?.();
    return out;
  }

  /**
   * A radial explosion at `at` (world space) within `radius` units, kicking every
   * dynamic body outward with `strength` (impulse per unit of overlap). Barrels,
   * bombs, shockwaves.
   */
  explosion(at: Vec2, radius: number, strength: number): void {
    const b2 = this._b2;
    const def = b2.b2DefaultExplosionDef();
    const p = new b2.b2Vec2(this._toBox(at.x), -this._toBox(at.y));
    def.position = p;
    def.radius = this._toBox(radius);
    def.falloff = this._toBox(radius) * 0.5;
    def.impulsePerLength = strength;
    b2.b2World_Explode(this.world, def);
    p.delete();
    def.delete();
  }

  /** A revolute joint (hinge / pivot) between two bodies — see-saws, ragdoll joints, powered wheels, doors. */
  pin(a: Body2d, b: Body2d, opts: PinOptions = {}): Joint2d {
    const b2 = this._b2;
    const def = b2.b2DefaultRevoluteJointDef();
    const base = def.base;
    base.bodyIdA = a._body;
    base.bodyIdB = b._body;
    const at = opts.at ?? this._midpoint(a, b);
    this._setLocalAnchors(base, a, b, at, at);
    def.base = base;
    if (opts.limits) {
      def.enableLimit = true;
      // Screen-clockwise → Box2D-CCW: negate and swap the ordering.
      def.lowerAngle = -opts.limits[1];
      def.upperAngle = -opts.limits[0];
    }
    if (opts.motorSpeed !== undefined && opts.maxTorque !== undefined) {
      def.enableMotor = true;
      def.motorSpeed = -opts.motorSpeed;
      def.maxMotorTorque = opts.maxTorque;
    }
    const id = b2.b2CreateRevoluteJoint(this.world, def);
    def.delete();
    return this._joint(id, 'revolute', a, b);
  }

  /** A distance joint (rigid rod by default, or a slack rope / bouncy spring) between two bodies. */
  rope(a: Body2d, b: Body2d, opts: RopeOptions = {}): Joint2d {
    const b2 = this._b2;
    const def = b2.b2DefaultDistanceJointDef();
    const base = def.base;
    base.bodyIdA = a._body;
    base.bodyIdB = b._body;
    const atA = opts.atA ?? this._center(a);
    const atB = opts.atB ?? this._center(b);
    this._setLocalAnchors(base, a, b, atA, atB);
    def.base = base;
    const len = opts.length !== undefined ? this._toBox(opts.length)
      : this._toBox(Math.hypot(atB.x - atA.x, atB.y - atA.y));
    def.length = Math.max(len, 0.005);
    if (opts.range) {
      def.enableLimit = true;
      def.minLength = Math.max(this._toBox(opts.range[0]), 0.005);
      def.maxLength = Math.max(this._toBox(opts.range[1]), def.minLength);
    }
    if (opts.hertz) {
      def.enableSpring = true;
      def.hertz = opts.hertz;
      def.dampingRatio = opts.damping ?? 0.5;
    }
    const id = b2.b2CreateDistanceJoint(this.world, def);
    def.delete();
    return this._joint(id);
  }

  /** A prismatic joint (slider): body B may only move along one axis relative to body A — pistons, elevators, sliding doors. */
  slider(a: Body2d, b: Body2d, opts: SliderOptions = {}): Joint2d {
    const b2 = this._b2;
    const def = b2.b2DefaultPrismaticJointDef();
    const base = def.base;
    base.bodyIdA = a._body;
    base.bodyIdB = b._body;
    const at = this._center(b);
    // v3.1 prismatic slides along localFrameA's x-axis — encode the axis as the
    // frame rotation (there is no separate axis field). Y-flip into Box2D space.
    const ax = opts.axis ?? { x: 1, y: 0 };
    const len = Math.hypot(ax.x, ax.y) || 1;
    const worldAngle = Math.atan2(-ax.y / len, ax.x / len);
    this._setLocalAnchors(base, a, b, at, at, worldAngle);
    def.base = base;
    if (opts.limits) {
      def.enableLimit = true;
      def.lowerTranslation = this._toBox(opts.limits[0]);
      def.upperTranslation = this._toBox(opts.limits[1]);
    }
    if (opts.motorSpeed !== undefined && opts.maxForce !== undefined) {
      def.enableMotor = true;
      def.motorSpeed = this._toBox(opts.motorSpeed);
      def.maxMotorForce = opts.maxForce;
    }
    const id = b2.b2CreatePrismaticJoint(this.world, def);
    def.delete();
    return this._joint(id, 'prismatic', a, b);
  }

  /** A weld joint: locks two bodies rigidly together (breakable structures, compound bodies). */
  weld(a: Body2d, b: Body2d, at?: Vec2): Joint2d {
    const b2 = this._b2;
    const def = b2.b2DefaultWeldJointDef();
    const base = def.base;
    base.bodyIdA = a._body;
    base.bodyIdB = b._body;
    const p = at ?? this._midpoint(a, b);
    this._setLocalAnchors(base, a, b, p, p);
    def.base = base;
    const id = b2.b2CreateWeldJoint(this.world, def);
    def.delete();
    return this._joint(id);
  }

  /**
   * A wheel joint — a spring-suspension axle for a vehicle. The wheel body
   * travels along `axis` (the suspension, default vertical) against a spring and
   * spins freely, with an optional drive motor. THE way to build a car: the
   * chassis floats on the springs above the wheels, so bumps are absorbed and the
   * body stays level — unlike a rigid `pin` axle, which fights every torque and
   * judders. Drive it live via the returned joint's `motor(speed, torque)`.
   */
  wheel(a: Body2d, b: Body2d, opts: WheelOptions): Joint2d {
    const b2 = this._b2;
    const def = b2.b2DefaultWheelJointDef();
    const base = def.base;
    base.bodyIdA = a._body;
    base.bodyIdB = b._body;
    const ax = opts.axis ?? { x: 0, y: 1 };
    const len = Math.hypot(ax.x, ax.y) || 1;
    const worldAngle = Math.atan2(-ax.y / len, ax.x / len);   // suspension axis = localFrameA x-axis
    this._setLocalAnchors(base, a, b, opts.at, opts.at, worldAngle);
    def.base = base;
    def.enableSpring = true;
    def.hertz = opts.hertz ?? 4;
    def.dampingRatio = opts.damping ?? 0.7;
    if (opts.travel) {
      def.enableLimit = true;
      def.lowerTranslation = this._toBox(opts.travel[0]);
      def.upperTranslation = this._toBox(opts.travel[1]);
    }
    if (opts.motorSpeed !== undefined && opts.maxTorque !== undefined) {
      def.enableMotor = true;
      def.motorSpeed = -opts.motorSpeed;   // screen-cw → Box2D-ccw
      def.maxMotorTorque = opts.maxTorque;
    }
    const id = b2.b2CreateWheelJoint(this.world, def);
    def.delete();
    return this._joint(id, 'wheel', a, b);
  }

  /**
   * Grab a body and drag it toward a moving target point — a mouse / touch joint.
   * Returns a handle: call `moveTo(point)` each frame with the pointer, and
   * `release()` to let go (the body keeps its velocity, so a moving release throws
   * it). Grab a ragdoll limb and the joints drag the rest along.
   */
  grab(body: Body2d, at: Vec2, opts: GrabOptions = {}): Grab2d {
    const b2 = this._b2;
    // The clicked point, resolved to the body's LOCAL frame, so that exact point
    // (not the centre) is what tracks the pointer.
    const wa = new b2.b2Vec2(this._toBox(at.x), -this._toBox(at.y));
    const la = b2.b2Body_GetLocalPoint(body._body, wa);
    const s = opts.strength ?? 1;
    const stiff = opts.stiff !== false;
    // Gains for a force-capped spring pulling the clicked point to the pointer.
    // `stiff` is snappy (a firm pin); the elastic mode is a softer rubber band.
    // The acceleration CAP is what stops the drag tearing joints apart.
    const g = {
      body, tx: at.x, ty: at.y, lx: la.x, ly: la.y,
      gain: stiff ? 18 : 9,          // 1/s — steady-state drag lag ≈ dragSpeed / gain
      vmax: stiff ? 3200 : 1500 * s, // units/s — caps the follow speed
      maxAcc: stiff ? 13000 : 5000 * s, // units/s² — caps the force (drags smoothly without whipping joints apart)
    };
    wa.delete(); la.delete?.();
    this.grabs.push(g);
    const self = this;
    return {
      moveTo(point: Vec2): void { g.tx = point.x; g.ty = point.y; },
      release(): void { const i = self.grabs.indexOf(g); if (i >= 0) self.grabs.splice(i, 1); },
    };
  }

  /**
   * @internal Drive each active grab (once per step). A mouse joint as a
   * force-capped VELOCITY SERVO: aim the clicked point's velocity straight at the
   * target (so it tracks with little lag and settles cleanly, no spring
   * oscillation), and apply the force AT THAT POINT (so the body rotates to
   * follow) with the acceleration capped so a jointed body is never torn apart.
   */
  private _applyGrabs(): void {
    const b2 = this._b2, ppm = this.ppm;
    for (const g of this.grabs) {
      const b = g.body;
      if (b._dead) continue;
      // World position + velocity of the clicked point on the body (screen units).
      this._scratch.Set(g.lx, g.ly);
      const wp = b2.b2Body_GetWorldPoint(b._body, this._scratch);
      const pv = b2.b2Body_GetWorldPointVelocity(b._body, wp);
      const ax = wp.x * ppm, ay = -wp.y * ppm;
      const pvx = pv.x * ppm, pvy = -pv.y * ppm;
      pv.delete();
      // Target velocity points at the cursor, magnitude ∝ distance (capped).
      let vdx = g.gain * (g.tx - ax), vdy = g.gain * (g.ty - ay);
      const vd = Math.hypot(vdx, vdy);
      if (vd > g.vmax) { vdx = (vdx / vd) * g.vmax; vdy = (vdy / vd) * g.vmax; }
      // Acceleration to reach that velocity this tick, force-capped.
      let accx = (vdx - pvx) * 60, accy = (vdy - pvy) * 60;
      const am = Math.hypot(accx, accy);
      if (am > g.maxAcc) { accx = (accx / am) * g.maxAcc; accy = (accy / am) * g.maxAcc; }
      const m = b.mass || 1;
      this._scratch2.Set((m * accx) / ppm, -(m * accy) / ppm);
      b2.b2Body_ApplyForce(b._body, this._scratch2, wp, true);
      wp.delete();
    }
  }

  /**
   * Step the world and sync every dynamic sprite. The scene calls this for you
   * once you set `scene.physics2d = world`; call it yourself only if you drive
   * the world outside a scene.
   */
  update(dt: number): void {
    const b2 = this._b2;
    // Kinematics: the SPRITE is the target — physics chases it.
    for (const k of this.kinematics) {
      if (k._dead) continue;
      const kp = this._readPose(k);
      this._scratch.Set(this._toBox(kp.x), -this._toBox(kp.y));
      const rot = b2.b2MakeRot(-kp.rot);
      const xf = new b2.b2Transform();
      xf.p = this._scratch;
      xf.q = rot;
      b2.b2Body_SetTargetTransform(k._body, xf, 1 / 60);
      xf.delete();
      rot.delete();
    }
    // Fixed 60 Hz steps (max 3/frame — a hitch must not spiral).
    this.acc = Math.min(this.acc + dt, 3 / 60);
    while (this.acc >= 1 / 60 - 1e-9) {
      this.acc -= 1 / 60;
      if (this.grabs.length) this._applyGrabs();
      b2.b2World_Step(this.world, 1 / 60, this.substeps);
      this.pumpEvents();
      for (const body of this.bodies.values()) {
        if (body.type !== 'dynamic' || body._dead) continue;
        if (!b2.b2Body_IsValid(body._body)) {
          this.invalidBodies++;
          body._dead = true;
          this.bodies.delete(idKey(body._body));
          this.bySprite.delete(body.sprite);
          continue;
        }
        body._pose0.set(body._pose1);
        const p = b2.b2Body_GetPosition(body._body);
        const r = b2.b2Body_GetRotation(body._body);
        body._pose1[0] = this._fromBox(p.x);
        body._pose1[1] = -this._fromBox(p.y);
        body._pose1[2] = -Math.atan2(r.s, r.c);   // Box2D-CCW → screen-CW
        p.delete();
        r.delete();
      }
    }
    // Sync sprites at the interpolated render pose (smooth on 120 Hz+ displays).
    const alpha = Math.max(0, Math.min(1, this.acc * 60));
    for (const body of this.bodies.values()) {
      if (body.type !== 'dynamic' || body._dead) continue;
      const a = body._pose0, b = body._pose1;
      const cx = a[0] + (b[0] - a[0]) * alpha;
      const cy = a[1] + (b[1] - a[1]) * alpha;
      // Angle: shortest-arc lerp so we never spin the long way round.
      let da = b[2] - a[2];
      while (da > Math.PI) da -= 2 * Math.PI;
      while (da < -Math.PI) da += 2 * Math.PI;
      body._writePose(cx, cy, a[2] + da * alpha);
    }
  }

  /** @internal Drain contact + sensor events into wrapper callbacks. */
  private pumpEvents(): void {
    const b2 = this._b2;
    const contacts = b2.b2World_GetContactEvents(this.world);
    const nHit = contacts.hitCount;
    for (let i = 0; i < nHit; i++) {
      const ev = contacts.GetHitEvent(i);
      const a = this.bodyOfShape(ev.shapeIdA);
      const bb = this.bodyOfShape(ev.shapeIdB);
      if (a && bb) {
        const speed = this._fromBox(ev.approachSpeed);
        a.onHit?.(bb, speed);
        bb.onHit?.(a, speed);
      }
      ev.delete?.();
    }
    const nBegin = contacts.beginCount;
    for (let i = 0; i < nBegin; i++) {
      const ev = contacts.GetBeginEvent(i);
      const a = this.bodyOfShape(ev.shapeIdA);
      const bb = this.bodyOfShape(ev.shapeIdB);
      if (a && bb) { a.onTouch?.(bb); bb.onTouch?.(a); }
      ev.delete?.();
    }
    const nEnd = contacts.endCount;
    for (let i = 0; i < nEnd; i++) {
      const ev = contacts.GetEndEvent(i);
      const a = this.bodyOfShape(ev.shapeIdA);
      const bb = this.bodyOfShape(ev.shapeIdB);
      if (a && bb) { a.onRelease?.(bb); bb.onRelease?.(a); }
      ev.delete?.();
    }
    contacts.delete?.();

    const sensors = b2.b2World_GetSensorEvents(this.world);
    const sBegin = sensors.beginCount;
    for (let i = 0; i < sBegin; i++) {
      const ev = sensors.GetBeginEvent(i);
      const sensor = this.bodyOfShape(ev.sensorShapeId);
      const visitor = this.bodyOfShape(ev.visitorShapeId);
      if (sensor && visitor) sensor.onEnter?.(visitor);
      ev.delete?.();
    }
    const sEnd = sensors.endCount;
    for (let i = 0; i < sEnd; i++) {
      const ev = sensors.GetEndEvent(i);
      const sensor = this.bodyOfShape(ev.sensorShapeId);
      const visitor = this.bodyOfShape(ev.visitorShapeId);
      if (sensor && visitor) sensor.onExit?.(visitor);
      ev.delete?.();
    }
    sensors.delete?.();
  }

  /** @internal Resolve an event shape id to a live Body2d (validate — shapes can belong to bodies destroyed this frame). */
  private bodyOfShape(shapeId: Id): Body2d | undefined {
    if (!this._b2.b2Shape_IsValid(shapeId)) return undefined;
    return this.bodies.get(idKey(this._b2.b2Shape_GetBody(shapeId)));
  }

  /** @internal Wrap a joint id in the public handle. `kind` enables `motor()`; `a`/`b` are woken when the motor is driven (a settled body sleeps and would otherwise ignore the command). */
  private _joint(id: Id, kind: 'revolute' | 'prismatic' | 'wheel' | 'none' = 'none', a?: Body2d, b?: Body2d): Joint2d {
    const b2 = this._b2, self = this;
    return {
      destroy(): void { if (b2.b2Joint_IsValid(id)) b2.b2DestroyJoint(id); },
      motor(speed: number, effort?: number): void {
        if (kind === 'revolute') {
          b2.b2RevoluteJoint_EnableMotor(id, true);
          b2.b2RevoluteJoint_SetMotorSpeed(id, -speed);   // screen-cw → Box2D-ccw
          if (effort !== undefined) b2.b2RevoluteJoint_SetMaxMotorTorque(id, effort);
        } else if (kind === 'prismatic') {
          b2.b2PrismaticJoint_EnableMotor(id, true);
          b2.b2PrismaticJoint_SetMotorSpeed(id, self._toBox(speed));
          if (effort !== undefined) b2.b2PrismaticJoint_SetMaxMotorForce(id, effort);
        } else if (kind === 'wheel') {
          b2.b2WheelJoint_EnableMotor(id, true);
          b2.b2WheelJoint_SetMotorSpeed(id, -speed);   // screen-cw → Box2D-ccw
          if (effort !== undefined) b2.b2WheelJoint_SetMaxMotorTorque(id, effort);
        }
        if (a && !a._dead) b2.b2Body_SetAwake(a._body, true);
        if (b && !b._dead) b2.b2Body_SetAwake(b._body, true);
      },
    };
  }

  /** @internal A shape's vertex RING (each segment's first point), scaled —
   *  what a decomposition needs, as opposed to the doubled-up endpoint list. */
  private _ringOf(shape: VectorShape, scale: number): VecPt[] {
    return shape.segs.map(([a]) => ({ x: a.x * scale, y: a.y * scale }));
  }

  /** @internal The target's CENTRE and angle in world space — a sprite is
   *  top-left anchored, a vector shape is already centred. */
  private _readPose(b: Body2d): { x: number; y: number; rot: number } {
    if (b.kind === 'sprite') {
      return { x: b.sprite.x + b._halfW, y: b.sprite.y + b._halfH, rot: b.sprite.rot };
    }
    const sh = b.shape!;
    return { x: sh.x, y: sh.y, rot: sh.rot };
  }

  /** @internal Body centre in world space. */
  private _center(b: Body2d): Vec2 {
    const p = this._readPose(b);
    return { x: p.x, y: p.y };
  }
  /** @internal Midpoint between two bodies in world space. */
  private _midpoint(a: Body2d, b: Body2d): Vec2 {
    const ca = this._center(a), cb = this._center(b);
    return { x: (ca.x + cb.x) / 2, y: (ca.y + cb.y) / 2 };
  }
  /**
   * @internal Set a joint's local anchor frames from world points. `worldAngle`
   * (Box2D-space radians) orients each frame's x-axis — identity for pin/rope/weld,
   * the slide direction for a slider.
   */
  private _setLocalAnchors(base: B2, a: Body2d, b: Body2d, atA: Vec2, atB: Vec2, worldAngle = 0): void {
    const b2 = this._b2;
    const wa = new b2.b2Vec2(this._toBox(atA.x), -this._toBox(atA.y));
    const wb = new b2.b2Vec2(this._toBox(atB.x), -this._toBox(atB.y));
    const la = b2.b2Body_GetLocalPoint(a._body, wa);
    const lb = b2.b2Body_GetLocalPoint(b._body, wb);
    const frameA = this._frameAt(la, worldAngle - this._bodyAngle(a));
    const frameB = this._frameAt(lb, worldAngle - this._bodyAngle(b));
    base.localFrameA = frameA;
    base.localFrameB = frameB;
    frameA.delete(); frameB.delete();
    wa.delete(); wb.delete(); la.delete?.(); lb.delete?.();
  }
  /** @internal A body's current world angle in Box2D-space radians. */
  private _bodyAngle(b: Body2d): number {
    const r = this._b2.b2Body_GetRotation(b._body);
    const a = this._b2.b2Rot_GetAngle(r);
    r.delete();
    return a;
  }
  /** @internal A b2Transform at a body-local point with the given local rotation. */
  private _frameAt(localPoint: B2, angle: number): B2 {
    const b2 = this._b2;
    const t = new b2.b2Transform();
    t.p = localPoint;
    const r = b2.b2MakeRot(angle);
    t.q = r;
    r.delete();
    return t;
  }

  /** @internal */
  _removeBody(body: Body2d): void {
    this.bodies.delete(idKey(body._body));
    if (body.kind === 'sprite') {
      this.bySprite.delete(body.sprite);
      (body.sprite as unknown as { _body2d: Body2d | null })._body2d = null;
    } else {
      this.byShape.delete(body.shape!);
    }
    const ki = this.kinematics.indexOf(body);
    if (ki >= 0) this.kinematics.splice(ki, 1);
    if (this._b2.b2Body_IsValid(body._body)) this._b2.b2DestroyBody(body._body);
  }

  /** Tear the world down (frees the WASM side). Sprites stay where they were. */
  destroy(): void {
    const b2 = this._b2;
    for (const body of this.bodies.values()) {
      if (body.kind === 'sprite') {
        (body.sprite as unknown as { _body2d: Body2d | null })._body2d = null;
      }
      body._dead = true;
    }
    this._scratch.delete();
    this._scratch2.delete();
    this._zeroVec.delete();
    b2.b2DestroyWorld(this.world);
    this.bodies.clear();
    this.bySprite.clear();
    this.kinematics.length = 0;
  }
}
